INSERT INTO verso(versao_id, livro_id, numero_capitulo, numero_verso, texto) VALUES (1, 2, 1, 1, "São estes, pois, os nomes dos filhos de Israel que entraram com Jacó no Egito, cada um com a sua respectiva família:"),  (2, 2, 1, 2, "Rúben, Simeão, Levi e Judá;"),  (3, 2, 1, 3, "Issacar, Zebulom e Benjamim;"),  (4, 2, 1, 4, "Dã, Naftali, Gade e Aser."),  (5, 2, 1, 5, "Ao todo, os descendentes de Jacó eram setenta; José, porém, já se encontrava no Egito."),  (6, 2, 1, 6, "Ora, morreram José, todos os seus irmãos e toda aquela geração."),  (7, 2, 1, 7, "Os israelitas, porém, eram férteis, proliferaram, tornaram-se numerosos e fortaleceram-se muito, tanto que encheram o país."),  (8, 2, 1, 8, "Então subiu ao trono do Egito um novo rei, que nada sabia sobre José."),  (9, 2, 1, 9, "Disse ele ao seu povo: Vejam! O povo israelita é agora numeroso e mais forte que nós."),  (10, 2, 1, 10, "Temos de agir com astúcia, para que não se tornem ainda mais numerosos e, no caso de guerra, aliem-se aos nossos inimigos, lutem contra nós e fujam do país."),  (11, 2, 1, 11, "Estabeleceram, pois, sobre eles chefes de trabalhos forçados, para os oprimir com tarefas pesadas. E assim os israelitas construíram para o faraó as cidades-celeiros de Pitom e Ramessés."),  (12, 2, 1, 12, "Todavia, quanto mais eram oprimidos, mais numerosos se tornavam e mais se espalhavam. Por isso os egípcios passaram a temer os israelitas,"),  (13, 2, 1, 13, "e os sujeitaram a cruel escravidão."),  (14, 2, 1, 14, "Tornaram-lhes a vida amarga, impondo-lhes a árdua tarefa de preparar o barro e fazer tijolos, e executar todo tipo de trabalho agrícola; em tudo os egípcios os sujeitavam a cruel escravidão."),  (15, 2, 1, 15, "O rei do Egito ordenou às parteiras dos hebreus, que se chamavam Sifrá e Puá:"),  (16, 2, 1, 16, "Quando vocês ajudarem as hebréias a dar à luz, verifiquem se é menino. Se for, matem-no; se for menina, deixem-na viver."),  (17, 2, 1, 17, "Todavia, as parteiras temeram a Deus e não obedeceram às ordens do rei do Egito; deixaram viver os meninos."),  (18, 2, 1, 18, "Então o rei do Egito convocou as parteiras e lhes perguntou: Por que vocês fizeram isso? Por que deixaram viver os meninos? "),  (19, 2, 1, 19, "Responderam as parteiras do faraó: As mulheres hebréias não são como as egípcias. São cheias de vigor e dão à luz antes de chegarem as parteiras."),  (20, 2, 1, 20, "Deus foi bondoso com as parteiras; e o povo ia se tornando ainda mais numeroso, cada vez mais forte."),  (21, 2, 1, 21, "Visto que as parteiras temeram a Deus, ele concedeu-lhes que tivessem suas próprias famílias."),  (22, 2, 1, 22, "Por isso o faraó ordenou a todo o seu povo: Lancem ao Nilo todo menino recém-nascido, mas deixem viver as meninas."),  (23, 2, 2, 1, "Um homem da tribo de Levi casou-se com uma mulher da mesma tribo,"),  (24, 2, 2, 2, "e ela engravidou e deu à luz um filho. Vendo que era bonito, ela o escondeu por três meses."),  (25, 2, 2, 3, "Quando já não podia mais escondê-lo, pegou um cesto feito de junco e o vedou com piche e betume. Colocou nele o menino e deixou o cesto entre os juncos, à margem do Nilo."),  (26, 2, 2, 4, "A irmã do menino ficou observando de longe para ver o que lhe aconteceria."),  (27, 2, 2, 5, "A filha do faraó descera ao Nilo para tomar banho. Enquanto isso as suas servas andavam pela margem do rio. Nisso viu o cesto entre os juncos e mandou sua criada apanhá-lo."),  (28, 2, 2, 6, "Ao abri-lo viu um bebê chorando. Ficou com pena dele e disse: Este menino é dos hebreus."),  (29, 2, 2, 7, "Então a irmã do menino aproximou-se e perguntou à filha do faraó: A senhora quer que eu vá chamar uma mulher dos hebreus para amamentar e criar o menino? "),  (30, 2, 2, 8, "Quero, respondeu ela. E a moça foi chamar a mãe do menino."),  (31, 2, 2, 9, "Então a filha do faraó disse à mulher: Leve este menino e amamente-o para mim, e eu lhe pagarei por isso. A mulher levou o menino e o amamentou."),  (32, 2, 2, 10, "Tendo o menino crescido, ela o levou à filha do faraó, que o adotou e lhe deu o nome de Moisés, dizendo: Porque eu o tirei das águas."),  (33, 2, 2, 11, "Certo dia, sendo Moisés já adulto, foi ao lugar onde estavam os seus irmãos hebreus e descobriu como era pesado o trabalho que realizavam. Viu também um egípcio espancar um dos hebreus."),  (34, 2, 2, 12, "Correu o olhar por todos os lados e, não vendo ninguém, matou o egípcio e o escondeu na areia."),  (35, 2, 2, 13, "No dia seguinte saiu e viu dois hebreus brigando. Então perguntou ao agressor: Por que você está espancando o seu companheiro? "),  (36, 2, 2, 14, "O homem respondeu: Quem o nomeou líder e juiz sobre nós? Quer matar-me como matou o egípcio?  Moisés teve medo e pensou: Com certeza tudo já foi descoberto! "),  (37, 2, 2, 15, "Quando o faraó soube disso, procurou matar Moisés, mas este fugiu e foi morar na terra de Midiã. Ali assentou-se à beira de um poço."),  (38, 2, 2, 16, "Ora, o sacerdote de Midiã tinha sete filhas. Elas foram buscar água para encher os bebedouros e dar de beber ao rebanho de seu pai."),  (39, 2, 2, 17, "Alguns pastores se aproximaram e começaram a expulsá-las dali; Moisés, porém, veio em auxílio delas e deu água ao rebanho."),  (40, 2, 2, 18, "Quando as moças voltaram a seu pai Reuel, este lhes perguntou: Por que voltaram tão cedo hoje? "),  (41, 2, 2, 19, "Elas responderam: Um egípcio defendeu-nos dos pastores e ainda tirou água do poço para nós e deu de beber ao rebanho."),  (42, 2, 2, 20, "Onde está ele? , perguntou o pai a elas. Por que o deixaram lá? Convidem-no para comer conosco. "),  (43, 2, 2, 21, "Moisés aceitou e concordou também em morar na casa daquele homem; este lhe deu por mulher sua filha Zípora."),  (44, 2, 2, 22, "Ela deu à luz um menino, a quem Moisés deu o nome de Gérson, dizendo: Sou imigrante em terra estrangeira."),  (45, 2, 2, 23, "Muito tempo depois, morreu o rei do Egito. Os israelitas gemiam e clamavam debaixo da escravidão; e o seu clamor subiu até Deus."),  (46, 2, 2, 24, "Ouviu Deus o lamento deles e lembrou-se da aliança que fizera com Abraão, Isaque e Jacó."),  (47, 2, 2, 25, "Deus olhou para os israelitas e viu qual era a situação deles."),  (48, 2, 3, 1, "Moisés pastoreava o rebanho de seu sogro Jetro, que era sacerdote de Midiã. Um dia levou o rebanho para o outro lado do deserto e chegou a Horebe, o monte de Deus."),  (49, 2, 3, 2, "Ali o Anjo do Senhor lhe apareceu numa chama de fogo que saía do meio de uma sarça. Moisés viu que, embora a sarça estivesse em chamas, esta não era consumida pelo fogo."),  (50, 2, 3, 3, "Que impressionante! , pensou. Por que a sarça não se queima? Vou ver isso de perto. "),  (51, 2, 3, 4, "O Senhor viu que ele se aproximava para observar. E então, do meio da sarça Deus o chamou: Moisés, Moisés!  Eis-me aqui, respondeu ele."),  (52, 2, 3, 5, "Então disse Deus: Não se aproxime. Tire as sandálias dos pés, pois o lugar em que você está é terra santa."),  (53, 2, 3, 6, "Disse ainda: Eu sou o Deus de seu pai, o Deus de Abraão, o Deus de Isaque, o Deus de Jacó. Então Moisés cobriu o rosto, pois teve medo de olhar para Deus."),  (54, 2, 3, 7, "Disse o Senhor: De fato tenho visto a opressão sobre o meu povo no Egito, e também tenho escutado o seu clamor, por causa dos seus feitores, e sei quanto eles estão sofrendo."),  (55, 2, 3, 8, "Por isso desci para livrá-lo das mãos dos egípcios e tirá-los daqui para uma terra boa e vasta, onde manam leite e mel: a terra dos cananeus, dos hititas, dos amorreus, dos ferezeus, dos heveus e dos jebuseus."),  (56, 2, 3, 9, "Pois agora o clamor dos israelitas chegou a mim, e tenho visto como os egípcios os oprimem."),  (57, 2, 3, 10, "Vá, pois, agora; eu o envio ao faraó para tirar do Egito o meu povo, os israelitas."),  (58, 2, 3, 11, "Moisés, porém, respondeu a Deus: Quem sou eu para apresentar-me ao faraó e tirar os israelitas do Egito? "),  (59, 2, 3, 12, "Deus afirmou: Eu estarei com você. Esta é a prova de que sou eu quem o envia: quando você tirar o povo do Egito, vocês prestarão culto a Deus neste monte."),  (60, 2, 3, 13, "Moisés perguntou: Quando eu chegar diante dos israelitas e lhes disser: O Deus dos seus antepassados me enviou a vocês, e eles me perguntarem: ‘Qual é o nome dele? ’ Que lhes direi? "),  (61, 2, 3, 14, "Disse Deus a Moisés: Eu Sou o que Sou. É isto que você dirá aos israelitas: Eu Sou me enviou a vocês."),  (62, 2, 3, 15, "Disse também Deus a Moisés: Diga aos israelitas: O Senhor, o Deus dos seus antepassados, o Deus de Abraão, o Deus de Isaque, o Deus de Jacó, enviou-me a vocês. Esse é o meu nome para sempre, nome pelo qual serei lembrado de geração em geração."),  (63, 2, 3, 16, "Vá, reúna as autoridades de Israel e diga-lhes: O Senhor, o Deus dos seus antepassados, o Deus de Abraão, de Isaque e de Jacó, apareceu a mim e disse: Eu virei em auxílio de vocês; pois vi o que lhes tem sido feito no Egito."),  (64, 2, 3, 17, "Prometi tirá-los da opressão do Egito para a terra dos cananeus, dos hititas, dos amorreus, dos ferezeus, dos heveus e dos jebuseus, terra onde manam leite e mel."),  (65, 2, 3, 18, "As autoridades de Israel o atenderão. Depois você irá com elas ao rei do Egito e lhe dirá: O Senhor, o Deus dos hebreus, veio ao nosso encontro. Agora, deixe-nos fazer uma caminhada de três dias, adentrando o deserto, para oferecermos sacrifícios ao Senhor nosso Deus."),  (66, 2, 3, 19, "Eu sei que o rei do Egito não os deixará sair, a não ser que uma poderosa mão o force."),  (67, 2, 3, 20, "Por isso estenderei a minha mão e ferirei os egípcios com todas as maravilhas que realizarei no meio deles. Depois disso ele os deixará sair."),  (68, 2, 3, 21, "E farei que os egípcios tenham boa-vontade para com o povo, de modo que, quando vocês saírem, não sairão de mãos vazias."),  (69, 2, 3, 22, "Todas as israelitas pedirão às suas vizinhas, e às mulheres que estiverem hospedando em casa, objetos de prata e de ouro, e roupas, que vocês porão em seus filhos e em suas filhas. Assim vocês despojarão os egípcios."),  (70, 2, 4, 1, "Moisés respondeu: E se eles não acreditarem em mim nem quiserem me ouvir e disserem: ‘O Senhor não lhe apareceu’? "),  (71, 2, 4, 2, "Então o Senhor lhe perguntou: Que é isso em sua mão?  Uma vara, respondeu ele."),  (72, 2, 4, 3, "Disse o Senhor: Jogue-a ao chão. Moisés jogou-a, e ela se transformou numa serpente. Moisés fugiu dela,"),  (73, 2, 4, 4, "mas o Senhor lhe disse: Estenda a mão e pegue-a pela cauda. Moisés estendeu a mão, pegou a serpente e esta se transformou numa vara em sua mão."),  (74, 2, 4, 5, "E disse o Senhor: Isso é para que eles acreditem que o Deus dos seus antepassados, o Deus de Abraão, o Deus de Isaque, o Deus de Jacó, apareceu a você."),  (75, 2, 4, 6, "Disse-lhe mais o Senhor: Coloque a mão no peito. Moisés obedeceu e, quando a retirou, ela estava leprosa; parecia neve."),  (76, 2, 4, 7, "Ordenou-lhe depois: Agora, coloque de novo a mão no peito. Moisés tornou a pôr a mão no peito e, quando a tirou, ela estava novamente como o restante da sua pele."),  (77, 2, 4, 8, "Prosseguiu o Senhor: Se eles não acreditarem em você nem derem atenção ao primeiro sinal miraculoso, acreditarão no segundo."),  (78, 2, 4, 9, "E se ainda assim não acreditarem nestes dois sinais nem lhe derem ouvidos, tire um pouco de água do Nilo e derrame-a em terra seca. Quando você derramar essa água em terra seca ela se transformará em sangue."),  (79, 2, 4, 10, "Disse, porém, Moisés ao Senhor: Ó Senhor! Nunca tive facilidade para falar, nem no passado nem agora que falaste a teu servo. Não consigo falar bem! "),  (80, 2, 4, 11, "Disse-lhe o Senhor: Quem deu boca ao homem? Quem o fez surdo ou mudo? Quem lhe concede vista ou o torna cego? Não sou eu, o Senhor?"),  (81, 2, 4, 12, "Agora, pois, vá; eu estarei com você, ensinando-lhe o que dizer."),  (82, 2, 4, 13, "Respondeu-lhe, porém, Moisés: Ah Senhor! Peço-te que envies outra pessoa."),  (83, 2, 4, 14, "Então o Senhor se irou com Moisés e lhe disse: Você não tem o seu irmão Arão, o levita? Eu sei que ele fala bem. Ele já está vindo ao seu encontro e se alegrará ao vê-lo."),  (84, 2, 4, 15, "Você falará com ele e lhe dirá o que ele deve dizer; eu estarei com vocês quando falarem, e lhes direi o que fazer."),  (85, 2, 4, 16, "Assim como Deus fala ao profeta, você falará a seu irmão, e ele será o seu porta-voz diante do povo."),  (86, 2, 4, 17, "E leve na mão esta vara; com ela você fará os sinais miraculosos."),  (87, 2, 4, 18, "Depois Moisés voltou a Jetro, seu sogro, e lhe disse: Preciso voltar ao Egito para ver se meus parentes ainda vivem. Jetro lhe respondeu: Vá em paz! "),  (88, 2, 4, 19, "Ora, o Senhor tinha dito a Moisés, em Midiã: Volte ao Egito, pois já morreram todos os que procuravam matá-lo."),  (89, 2, 4, 20, "Então Moisés levou sua mulher e seus filhos montados num jumento e partiu de volta ao Egito. Levava na mão a vara de Deus."),  (90, 2, 4, 21, "Disse mais o Senhor a Moisés: Quando você voltar ao Egito, tenha o cuidado de fazer diante do faraó todas as maravilhas que concedi a você o poder de realizar. Mas eu vou endurecer o coração dele, para não deixar o povo ir."),  (91, 2, 4, 22, "Depois diga ao faraó que assim diz o Senhor: Israel é o meu primeiro filho,"),  (92, 2, 4, 23, "e eu já lhe disse que deixe o meu filho ir para prestar-me culto. Mas você não quis deixá-lo ir; por isso matarei o seu primeiro filho! "),  (93, 2, 4, 24, "Numa hospedaria ao longo do caminho, o Senhor foi ao encontro de Moisés e procurou matá-lo."),  (94, 2, 4, 25, "Mas Zípora pegou uma pedra afiada, cortou o prepúcio de seu filho e tocou os pés de Moisés. E disse: Você é para mim um marido de sangue! "),  (95, 2, 4, 26, "Ela disse marido de sangue, referindo-se à circuncisão. Nessa ocasião o Senhor o deixou."),  (96, 2, 4, 27, "Então o Senhor disse a Arão: Vá ao deserto encontrar-se com Moisés. Ele foi, encontrou-se com Moisés no monte de Deus, e o saudou com um beijo."),  (97, 2, 4, 28, "Moisés contou a Arão tudo o que o Senhor lhe tinha mandado dizer, e também falou-lhe de todos os sinais miraculosos que lhe havia ordenado realizar."),  (98, 2, 4, 29, "Assim Moisés e Arão foram e reuniram todas as autoridades dos israelitas,"),  (99, 2, 4, 30, "e Arão lhes contou tudo o que o Senhor dissera a Moisés. Em seguida Moisés também realizou os sinais diante do povo,"),  (100, 2, 4, 31, "e eles creram. Quando o povo soube que o Senhor decidira vir em auxílio deles e tinha visto a sua opressão, curvou-se em adoração."),  (101, 2, 5, 1, "Depois disso Moisés e Arão foram falar com o faraó e disseram: Assim diz o Senhor, o Deus de Israel: ‘Deixe o meu povo ir para celebrar-me uma festa no deserto’ ."),  (102, 2, 5, 2, "O faraó respondeu: Quem é o Senhor, para que eu lhe obedeça e deixe Israel sair? Não conheço o Senhor, e não deixarei Israel sair."),  (103, 2, 5, 3, "Eles insistiram: O Deus dos hebreus veio ao nosso encontro. Agora, permite-nos caminhar três dias no deserto, para oferecer sacrifícios ao Senhor, o nosso Deus; caso contrário, ele nos atingirá com pragas ou com a espada."),  (104, 2, 5, 4, "Mas o rei do Egito respondeu: Moisés e Arão, por que vocês estão fazendo o povo interromper suas tarefas? Voltem ao trabalho! "),  (105, 2, 5, 5, "E acrescentou: Essa gente já é tão numerosa, e vocês ainda os fazem parar de trabalhar! "),  (106, 2, 5, 6, "No mesmo dia o faraó deu a seguinte ordem aos feitores e capatazes responsáveis pelo povo:"),  (107, 2, 5, 7, "Não forneçam mais palha ao povo para fazer tijolos, como faziam antes. Eles que tratem de ajuntar palha!"),  (108, 2, 5, 8, "Mas exijam que continuem a fazer a mesma quantidade de tijolos; não reduzam a cota. São preguiçosos, e por isso estão clamando: ‘Iremos oferecer sacrifícios ao nosso Deus’."),  (109, 2, 5, 9, "Aumentem a carga de trabalho dessa gente para que cumpram suas tarefas e não dêem atenção a mentiras."),  (110, 2, 5, 10, "Os feitores e os capatazes foram dizer ao povo: Assim diz o faraó: ‘Já não lhes darei palha."),  (111, 2, 5, 11, "Saiam e recolham-na onde puderem achá-la, pois o trabalho de vocês em nada será reduzido’ ."),  (112, 2, 5, 12, "O povo então espalhou-se por todo o Egito, a fim de ajuntar restolho em lugar da palha."),  (113, 2, 5, 13, "Enquanto isso, os feitores os pressionavam, dizendo: Completem a mesma tarefa diária que lhes foi exigida quando tinham palha."),  (114, 2, 5, 14, "Os capatazes israelitas indicados pelos feitores do faraó eram espancados e interrogados: Por que não completaram ontem e hoje a mesma cota de tijolos dos dias anteriores? "),  (115, 2, 5, 15, "Então os capatazes israelitas foram apelar para o faraó: Por que tratas os teus servos dessa maneira?"),  (116, 2, 5, 16, "Não se fornece a nós, teus servos, a palha, e contudo nos dizem: ‘Façam tijolos! ’ Os teus servos têm sido espancados, mas a culpa é do teu próprio povo."),  (117, 2, 5, 17, "Respondeu o faraó: Preguiçosos, é o que vocês são! Preguiçosos! Por isso andam dizendo: ‘Iremos oferecer sacrifícios ao Senhor’."),  (118, 2, 5, 18, "Agora, voltem ao trabalho. Vocês não receberão palha alguma! Continuem a produzir a cota integral de tijolos! "),  (119, 2, 5, 19, "Os capatazes israelitas se viram em dificuldade quando lhes disseram que não poderiam reduzir a quantidade de tijolos exigida a cada dia."),  (120, 2, 5, 20, "Ao saírem da presença do faraó, encontraram-se com Moisés e Arão, que estavam à espera deles,"),  (121, 2, 5, 21, "e lhes disseram: O Senhor os examine e os julgue! Vocês atraíram o ódio do faraó e dos seus conselheiros sobre nós, e lhes puseram nas mãos uma espada para que nos matem."),  (122, 2, 5, 22, "Moisés voltou-se para o Senhor e perguntou: Senhor, por que maltrataste a este povo? Afinal, por que me enviaste?"),  (123, 2, 5, 23, "Desde que me dirigi ao faraó para falar em teu nome, ele tem maltratado a este povo, e tu de modo algum libertaste o teu povo! "),  (124, 2, 6, 1, "Então o Senhor disse a Moisés: Agora você verá o que farei ao faraó: Por minha mão poderosa, ele os deixará ir; por minha mão poderosa, ele os expulsará do seu país."),  (125, 2, 6, 2, "Disse Deus ainda a Moisés: Eu sou o Senhor."),  (126, 2, 6, 3, "Apareci a Abraão, a Isaque e a Jacó como o Deus Todo-poderoso, mas pelo meu nome, o Senhor, não me revelei a eles."),  (127, 2, 6, 4, "Depois estabeleci com eles a minha aliança para dar-lhes a terra de Canaã, terra onde viveram como estrangeiros."),  (128, 2, 6, 5, "E agora ouvi o lamento dos israelitas, a quem os egípcios mantêm escravos, e lembrei-me da minha aliança."),  (129, 2, 6, 6, "Por isso, diga aos israelitas: Eu sou o Senhor. Eu os livrarei do trabalho imposto pelos egípcios. Eu os libertarei da escravidão e os resgatarei com braço forte e com poderosos atos de juízo."),  (130, 2, 6, 7, "Eu os farei meu povo e serei o Deus de vocês. Então vocês saberão que eu sou o Senhor, o Deus de vocês, que os livra do trabalho imposto pelos egípcios."),  (131, 2, 6, 8, "E os farei entrar na terra que, com mão levantada, jurei que daria a Abraão, a Isaque e a Jacó. Eu a darei a vocês como propriedade. Eu sou o Senhor."),  (132, 2, 6, 9, "Moisés declarou isso aos israelitas, mas eles não lhe deram ouvidos, por causa da angústia e da cruel escravidão que sofriam."),  (133, 2, 6, 10, "Então o Senhor ordenou a Moisés:"),  (134, 2, 6, 11, "Vá dizer ao faraó, rei do Egito, que deixe os israelitas saírem do país."),  (135, 2, 6, 12, "Moisés, porém, disse na presença do Senhor: Se os israelitas não me dão ouvidos, como me ouvirá o faraó? Ainda mais que não tenho facilidade para falar! "),  (136, 2, 6, 13, "Mas, o Senhor ordenou a Moisés e a Arão que dissessem aos israelitas e ao faraó, rei do Egito, que tinham ordem para tirar do Egito os israelitas."),  (137, 2, 6, 14, "Estes foram os chefes das famílias israelitas: Os filhos de Rúben, filho mais velho de Israel, foram: Enoque, Palu, Hezrom e Carmi. Esses foram os clãs de Rúben."),  (138, 2, 6, 15, "Os filhos de Simeão foram: Jemuel, Jamim, Oade, Jaquim, Zoar e Saul, filho de uma cananéia. Esses foram os clãs de Simeão."),  (139, 2, 6, 16, "Estes, pois, são os nomes dos filhos de Levi, por ordem de nascimento: Gérson, Coate e Merari. Levi viveu cento e trinta e sete anos."),  (140, 2, 6, 17, "Os filhos de Gérson, conforme seus clãs, foram Libni e Simei."),  (141, 2, 6, 18, "Os filhos de Coate foram Anrão, Isar, Hebrom e Uziel. Coate viveu cento e trinta e três anos."),  (142, 2, 6, 19, "Os filhos de Merari foram Mali e Musi. Esses foram os clãs de Levi, por ordem de nascimento."),  (143, 2, 6, 20, "Anrão tomou por mulher sua tia Joquebede, que lhe deu à luz Arão e Moisés. Anrão viveu cento e trinta e sete anos."),  (144, 2, 6, 21, "Os filhos de Isar foram Corá, Nefegue e Zicri."),  (145, 2, 6, 22, "Os filhos de Uziel foram Misael, Elzafã e Sitri."),  (146, 2, 6, 23, "Arão tomou por mulher a Eliseba, filha de Aminadabe, irmã de Naassom, e ela lhe deu à luz Nadabe, Abiú, Eleazar e Itamar."),  (147, 2, 6, 24, "Os filhos de Corá foram Assir, Elcana e Abiasafe. Esses foram os clãs dos coraítas."),  (148, 2, 6, 25, "Eleazar, filho de Arão, tomou por mulher uma das filhas de Futiel, e ela lhe deu à luz Finéias. Esses foram os chefes das famílias dos levitas, conforme seus clãs."),  (149, 2, 6, 26, "Foi a este Arão e a este Moisés que o Senhor disse: Tirem os israelitas do Egito, organizados segundo as suas divisões."),  (150, 2, 6, 27, "Foram eles, Moisés e Arão, que falaram ao faraó, rei do Egito, a fim de tirar os israelitas do Egito."),  (151, 2, 6, 28, "Ora, quando o Senhor falou com Moisés no Egito,"),  (152, 2, 6, 29, "disse-lhe: Eu sou o Senhor. Diga ao faraó, rei do Egito, tudo o que eu lhe disser."),  (153, 2, 6, 30, "Moisés, porém, perguntou ao Senhor: Como o faraó me dará ouvidos, se não tenho facilidade para falar? "),  (154, 2, 7, 1, "O Senhor lhe respondeu: Dou-lhe a minha autoridade perante o faraó, e seu irmão Arão será seu porta-voz."),  (155, 2, 7, 2, "Você falará tudo o que eu lhe ordenar, e o seu irmão Arão dirá ao faraó que deixe os israelitas saírem do país."),  (156, 2, 7, 3, "Eu, porém, farei o coração do faraó resistir; e, embora multiplique meus sinais e maravilhas no Egito,"),  (157, 2, 7, 4, "ele não os ouvirá. Então porei a minha mão sobre o Egito, e com poderosos atos de juízo tirarei do Egito os meus exércitos, o meu povo, os israelitas."),  (158, 2, 7, 5, "E os egípcios saberão que eu sou o Senhor, quando eu estender a minha mão contra o Egito e tirar de lá os israelitas."),  (159, 2, 7, 6, "Moisés e Arão fizeram como o Senhor lhes havia ordenado."),  (160, 2, 7, 7, "Moisés tinha oitenta anos de idade e Arão oitenta e três, quando falaram com o faraó."),  (161, 2, 7, 8, "Disse o Senhor a Moisés e a Arão:"),  (162, 2, 7, 9, "Quando o faraó lhes pedir que façam algum milagre, diga a Arão que tome a sua vara e a jogue diante do faraó; e ela se transformará numa serpente."),  (163, 2, 7, 10, "Moisés e Arão dirigiram-se ao faraó e fizeram como o Senhor tinha ordenado. Arão jogou a vara diante do faraó e seus conselheiros, e ela se transformou em serpente."),  (164, 2, 7, 11, "O faraó, porém, mandou chamar os sábios e feiticeiros; e também os magos do Egito fizeram a mesma coisa por meio das suas ciências ocultas."),  (165, 2, 7, 12, "Cada um deles jogou ao chão uma vara, e estas se transformaram em serpentes. Mas a vara de Arão engoliu as varas deles."),  (166, 2, 7, 13, "Contudo, o coração do faraó se endureceu e ele não quis dar ouvidos a Moisés e a Arão, como o Senhor tinha dito."),  (167, 2, 7, 14, "Disse o Senhor a Moisés: O coração do faraó está obstinado; ele não quer deixar o povo ir."),  (168, 2, 7, 15, "Vá ao faraó de manhã, quando ele estiver indo às águas. Espere-o na margem do rio para encontrá-lo e leve também a vara que se transformou em serpente."),  (169, 2, 7, 16, "Diga-lhe: O Senhor, o Deus dos hebreus, mandou-me dizer-lhe: Deixe ir o meu povo, para prestar-me culto no deserto. Mas até agora você não me atendeu."),  (170, 2, 7, 17, "Assim diz o Senhor: Nisto você saberá que eu sou o Senhor: com a vara que trago na mão ferirei as águas do Nilo, e elas se transformarão em sangue."),  (171, 2, 7, 18, "Os peixes do Nilo morrerão, o rio ficará cheirando mal, e os egípcios não suportarão beber das suas águas."),  (172, 2, 7, 19, "Disse o Senhor a Moisés: Diga a Arão que tome a sua vara e estenda a mão sobre as águas do Egito, dos rios, dos canais, dos açudes e de todos os reservatórios, e elas se transformarão em sangue. Haverá sangue por toda a terra do Egito, até nas vasilhas de madeira e nas vasilhas de pedra."),  (173, 2, 7, 20, "Moisés e Arão fizeram como o Senhor tinha ordenado. Arão levantou a vara e feriu as águas do Nilo na presença do faraó e dos seus conselheiros; e toda a água do rio transformou-se em sangue."),  (174, 2, 7, 21, "Os peixes morreram e o rio cheirava tão mal que os egípcios não conseguiam beber das suas águas. Havia sangue por toda a terra do Egito."),  (175, 2, 7, 22, "Mas os magos do Egito fizeram a mesma coisa por meio de suas ciências ocultas. O coração do faraó se endureceu, e ele não deu ouvidos a Moisés e a Arão, como o Senhor tinha dito."),  (176, 2, 7, 23, "Pelo contrário, deu-lhes as costas e voltou para o seu palácio. Nem assim o faraó levou isso a sério."),  (177, 2, 7, 24, "Todos os egípcios cavaram buracos às margens do Nilo para encontrar água potável, pois da água do rio não podiam mais beber."),  (178, 2, 7, 25, "Passaram-se sete dias depois que o Senhor feriu o Nilo."),  (179, 2, 8, 1, "O Senhor falou a Moisés: Vá ao faraó e diga-lhe que assim diz o Senhor: Deixe o meu povo ir para que me preste culto."),  (180, 2, 8, 2, "Se você não quiser deixá-lo ir, mandarei sobre todo o seu território uma praga de rãs."),  (181, 2, 8, 3, "O Nilo ficará infestado de rãs. Elas subirão e entrarão em seu palácio, em seu quarto, e até em sua cama; estarão também nas casas dos seus conselheiros e do seu povo, dentro dos seus fornos e nas suas amassadeiras."),  (182, 2, 8, 4, "As rãs subirão em você, em seus conselheiros e em seu povo."),  (183, 2, 8, 5, "Depois o Senhor disse a Moisés: Diga a Arão que estenda a mão com a vara sobre os rios, sobre os canais e sobre os açudes, e faça subir deles rãs sobre a terra do Egito."),  (184, 2, 8, 6, "Assim Arão estendeu a mão sobre as águas do Egito, e as rãs subiram e cobriram a terra do Egito."),  (185, 2, 8, 7, "Mas os magos fizeram a mesma coisa por meio das suas ciências ocultas: fizeram subir rãs sobre a terra do Egito."),  (186, 2, 8, 8, "O faraó mandou chamar Moisés e Arão e disse: Orem ao Senhor para que ele tire estas rãs de mim e do meu povo; então deixarei o povo ir e oferecer sacrifícios ao Senhor."),  (187, 2, 8, 9, "Moisés disse ao faraó: Tua é a honra de dizer-me quando devo orar por ti, por teus conselheiros e por teu povo para que tu e tuas casas fiquem livres das rãs e sobrem apenas as que estão no rio."),  (188, 2, 8, 10, "Amanhã, disse o faraó. Moisés respondeu: Será como tu dizes, para que saibas que não há ninguém como o Senhor nosso Deus."),  (189, 2, 8, 11, "As rãs deixarão a ti, às tuas casas, a teus conselheiros e a teu povo; sobrarão apenas as que estão no rio."),  (190, 2, 8, 12, "Depois que Moisés e Arão saíram da presença do faraó, Moisés clamou ao Senhor por causa das rãs que enviara sobre o faraó."),  (191, 2, 8, 13, "E o Senhor atendeu o pedido de Moisés; morreram as rãs que estavam nas casas, nos pátios e nos campos."),  (192, 2, 8, 14, "Foram ajuntadas em montões e, por isso, a terra cheirou mal."),  (193, 2, 8, 15, "Mas quando o faraó percebeu que houve alívio, obstinou-se em seu coração e não deu mais ouvidos a Moisés e a Arão, conforme o Senhor tinha dito."),  (194, 2, 8, 16, "Então o Senhor disse a Moisés: Diga a Arão que estenda a sua vara e fira o pó da terra, e o pó se transformará em piolhos por toda a terra do Egito."),  (195, 2, 8, 17, "Assim fizeram, e quando Arão estendeu a mão e com a vara feriu o pó da terra, surgiram piolhos nos homens e nos animais. Todo o pó de toda a terra do Egito transformou-se em piolhos."),  (196, 2, 8, 18, "Mas, quando os magos tentaram fazer surgir piolhos por meio das suas ciências ocultas, não conseguiram. E os piolhos infestavam os homens e os animais."),  (197, 2, 8, 19, "Os magos disseram ao faraó: Isso é o dedo de Deus. Mas o coração do faraó permaneceu endurecido, e ele não quis ouvi-los, conforme o Senhor tinha dito."),  (198, 2, 8, 20, "Depois o Senhor disse a Moisés: Levante-se bem cedo e apresente-se ao faraó, quando ele estiver indo às águas. Diga-lhe que assim diz o Senhor: Deixe o meu povo ir para que me preste culto."),  (199, 2, 8, 21, "Se você não deixar meu povo ir, enviarei enxames de moscas para atacar você, os seus conselheiros, o seu povo e as suas casas. As casas dos egípcios, bem como o chão em que pisam, se encherão de moscas."),  (200, 2, 8, 22, "Mas naquele dia tratarei de maneira diferente a terra de Gósen, onde habita o meu povo; nenhum enxame de moscas se achará ali, para que você saiba que eu, o Senhor, estou nesta terra."),  (201, 2, 8, 23, "Farei distinção entre o meu povo e o seu. Este sinal miraculoso acontecerá amanhã."),  (202, 2, 8, 24, "E assim fez o Senhor. Grandes enxames de moscas invadiram o palácio do faraó e as casas de seus conselheiros, e em todo o Egito a terra foi arruinada pelas moscas."),  (203, 2, 8, 25, "Então o faraó mandou chamar Moisés e Arão e disse: Vão oferecer sacrifícios ao seu Deus, mas não saiam do país."),  (204, 2, 8, 26, "Isso não seria sensato, respondeu Moisés; os sacrifícios que oferecemos ao nosso Deus são um sacrilégio para os egípcios. Se oferecermos sacrifícios que lhes pareçam sacrilégio, isso não os levará a nos apedrejar?"),  (205, 2, 8, 27, "Faremos três dias de viagem no deserto, e ofereceremos sacrifícios ao Senhor nosso Deus, como ele nos ordena. "),  (206, 2, 8, 28, "Disse o faraó: Eu os deixarei ir e oferecer sacrifícios ao Senhor seu Deus no deserto, mas não se afastem muito e orem por mim também."),  (207, 2, 8, 29, "Moisés respondeu: Assim que sair da tua presença, orarei ao Senhor, e amanhã os enxames de moscas deixarão o faraó, teus conselheiros e teu povo. Que somente o faraó não volte a agir com falsidade, impedindo que o povo vá oferecer sacrifícios ao Senhor."),  (208, 2, 8, 30, "Então Moisés saiu da presença do faraó e orou ao Senhor,"),  (209, 2, 8, 31, "e o Senhor atendeu o seu pedido: as moscas deixaram o faraó, seus conselheiros e seu povo; não restou uma só mosca."),  (210, 2, 8, 32, "Mas também dessa vez o faraó obstinou-se em seu coração e não deixou que o povo saísse."),  (211, 2, 9, 1, "Depois o Senhor disse a Moisés: Vá ao faraó e diga-lhe que assim diz o Senhor, o Deus dos hebreus: Deixe o meu povo ir para que me preste culto."),  (212, 2, 9, 2, "Se você ainda não quiser deixá-lo ir e continuar a impedi-lo,"),  (213, 2, 9, 3, "saiba que a mão do Senhor trará uma praga terrível sobre os rebanhos do faraó que estão nos campos: os cavalos, os jumentos, os camelos, os bois e as ovelhas."),  (214, 2, 9, 4, "Mas o Senhor fará distinção entre os rebanhos de Israel e os do Egito. Nenhum animal dos israelitas morrerá."),  (215, 2, 9, 5, "O Senhor estabeleceu um prazo: Amanhã o Senhor fará o que prometeu nesta terra."),  (216, 2, 9, 6, "No dia seguinte o Senhor o fez. Todos os rebanhos dos egípcios morreram, mas nenhum rebanho dos israelitas morreu."),  (217, 2, 9, 7, "O faraó mandou verificar e constatou que nenhum animal dos israelitas havia morrido. Mesmo assim, seu coração continuou obstinado e não deixou o povo ir."),  (218, 2, 9, 8, "Disse mais o Senhor a Moisés e a Arão: Tirem um punhado de cinza de uma fornalha, e Moisés a espalhará no ar, diante do faraó."),  (219, 2, 9, 9, "Ela se tornará como um pó fino sobre toda a terra do Egito, e feridas purulentas surgirão nos homens e nos animais em todo o Egito."),  (220, 2, 9, 10, "Eles tiraram cinza duma fornalha e se puseram diante do faraó. Moisés a espalhou pelo ar, e feridas purulentas começaram a estourar nos homens e nos animais."),  (221, 2, 9, 11, "Nem os magos podiam manter-se diante de Moisés, porque ficaram cobertos de feridas, como os demais egípcios."),  (222, 2, 9, 12, "Mas o Senhor endureceu o coração do faraó, e ele se recusou a atender Moisés e Arão, conforme o Senhor tinha dito a Moisés."),  (223, 2, 9, 13, "Disse o Senhor a Moisés: Levante-se logo cedo, apresente-se ao faraó e diga-lhe que assim diz o Senhor, o Deus dos hebreus: Deixe o meu povo ir para que me preste culto."),  (224, 2, 9, 14, "Caso contrário, mandarei desta vez todas as minhas pragas contra você, contra os seus conselheiros e contra o seu povo, para que você saiba que em toda a terra não há ninguém como eu."),  (225, 2, 9, 15, "Porque eu já poderia ter estendido a mão, ferindo você e o seu povo com uma praga que teria eliminado você da terra."),  (226, 2, 9, 16, "Mas eu o mantive de pé exatamente com este propósito: mostrar-lhe o meu poder e fazer que o meu nome seja proclamado em toda a terra."),  (227, 2, 9, 17, "Contudo você ainda insiste em colocar-se contra o meu povo e não o deixa ir."),  (228, 2, 9, 18, "Amanhã, a esta hora, enviarei a pior tempestade de granizo que já caiu sobre o Egito, desde o dia da sua fundação até hoje."),  (229, 2, 9, 19, "Agora, mande recolher os seus rebanhos e tudo o que você tem nos campos. Todos os homens e animais que estiverem nos campos, que não tiverem sido abrigados, serão atingidos pelo granizo e morrerão."),  (230, 2, 9, 20, "Os conselheiros do faraó que temiam a palavra do Senhor apressaram-se em recolher aos abrigos os seus rebanhos e os seus escravos."),  (231, 2, 9, 21, "Mas os que não se importaram com a palavra do Senhor deixaram os seus escravos e os seus rebanhos no campo."),  (232, 2, 9, 22, "Então o Senhor disse a Moisés: Estenda a mão para o céu, e cairá granizo sobre toda a terra do Egito: sobre homens, sobre animais e sobre toda a vegetação do Egito."),  (233, 2, 9, 23, "Quando Moisés estendeu a vara para o céu, o Senhor fez vir trovões e granizo, e raios caíam sobre a terra. Assim o Senhor fez chover granizo sobre a terra do Egito."),  (234, 2, 9, 24, "Caiu granizo, e raios cortavam o céu em todas as direções. Nunca houve uma tempestade de granizo como aquela em todo o Egito, desde que este se tornou uma nação."),  (235, 2, 9, 25, "Em todo o Egito o granizo atingiu tudo o que havia nos campos, tanto homens como animais; destruiu toda a vegetação, além de quebrar todas as árvores."),  (236, 2, 9, 26, "Somente na terra de Gósen, onde estavam os israelitas, não caiu granizo."),  (237, 2, 9, 27, "Então o faraó mandou chamar Moisés e Arão e disse-lhes: Desta vez eu pequei. O Senhor é justo; eu e o meu povo é que somos culpados."),  (238, 2, 9, 28, "Orem ao Senhor! Os trovões de Deus e o granizo já são demais. Eu os deixarei ir; não precisam mais ficar aqui."),  (239, 2, 9, 29, "Moisés respondeu: Assim que eu tiver saído da cidade, erguerei as mãos em oração ao Senhor. Os trovões cessarão e não cairá mais granizo, para que saibas que a terra pertence ao Senhor."),  (240, 2, 9, 30, "Mas eu bem sei que tu e os teus conselheiros ainda não sabem o que é tremer diante do Senhor Deus! "),  (241, 2, 9, 31, "( O linho e a cevada foram destruídos, pois a cevada já havia amadurecido e o linho estava em flor."),  (242, 2, 9, 32, "Todavia, o trigo e o centeio nada sofreram, pois só amadurecem mais tarde. )"),  (243, 2, 9, 33, "Assim Moisés deixou o faraó, saiu da cidade, e ergueu as mãos ao Senhor. Os trovões e o granizo cessaram, e a chuva parou."),  (244, 2, 9, 34, "Quando o faraó viu que a chuva, o granizo e os trovões haviam cessado, pecou novamente e obstinou-se em seu coração, ele e os seus conselheiros."),  (245, 2, 9, 35, "O coração do faraó continuou endurecido, e ele não deixou que os israelitas saíssem, como o Senhor tinha dito por meio de Moisés."),  (246, 2, 10, 1, "O Senhor disse a Moisés: Vá ao faraó, pois tornei obstinado o coração dele e o de seus conselheiros, a fim de realizar estes meus prodígios entre eles,"),  (247, 2, 10, 2, "para que você possa contar a seus filhos e netos como zombei dos egípcios e como realizei meus milagres entre eles. Assim vocês saberão que eu sou o Senhor."),  (248, 2, 10, 3, "Dirigiram-se, pois, Moisés e Arão ao faraó e lhe disseram: Assim diz o Senhor, o Deus dos hebreus: ‘Até quando você se recusará a humilhar-se perante mim? Deixe ir o meu povo, para que me preste culto."),  (249, 2, 10, 4, "Se você não quiser deixá-lo ir, farei vir gafanhotos sobre o seu território amanhã."),  (250, 2, 10, 5, "Eles cobrirão a face da terra até não se poder enxergar o solo. Devorarão tanto o pouco que ainda lhes restou da tempestade de granizo como todas as árvores que estiverem brotando nos campos."),  (251, 2, 10, 6, "Encherão os seus palácios e as casas de todos os seus conselheiros e de todos os egípcios: algo que nem os seus pais nem os seus antepassados jamais viram, desde o dia em que se fixaram nesta terra até o dia de hoje’ . A seguir Moisés virou as costas e saiu da presença do faraó."),  (252, 2, 10, 7, "Os conselheiros do faraó lhe disseram: Até quando este homem será uma ameaça para nós? Deixa os homens irem prestar culto ao Senhor Deus deles. Não percebes que o Egito está arruinado? "),  (253, 2, 10, 8, "Então Moisés e Arão foram trazidos de volta à presença do faraó, que lhes disse: Vão e prestem culto ao Senhor, ao seu Deus. Mas, digam-me, quem irá? "),  (254, 2, 10, 9, "Moisés respondeu: Temos que levar todos: os jovens e os velhos, os nossos filhos e as nossas filhas, as nossas ovelhas e os nossos bois, pois celebraremos uma festa ao Senhor."),  (255, 2, 10, 10, "Disse-lhes o faraó: Vocês vão mesmo precisar do Senhor quando eu deixá-los ir com as mulheres e crianças! É claro que vocês estão com más intenções."),  (256, 2, 10, 11, "De forma alguma! Só os homens podem ir prestar culto ao Senhor, como vocês têm pedido. E Moisés e Arão foram expulsos da presença do faraó."),  (257, 2, 10, 12, "Mas o Senhor disse a Moisés: Estenda a mão sobre o Egito para que os gafanhotos venham sobre a terra e devorem toda a vegetação, tudo o que foi deixado pelo granizo."),  (258, 2, 10, 13, "Moisés estendeu a vara sobre o Egito, e o Senhor fez soprar sobre a terra um vento oriental durante todo aquele dia e toda aquela noite. Pela manhã, o vento havia trazido os gafanhotos,"),  (259, 2, 10, 14, "os quais invadiram todo o Egito e desceram em grande número sobre toda a sua extensão. Nunca antes houve tantos gafanhotos, nem jamais haverá."),  (260, 2, 10, 15, "Eles cobriram toda a face da terra de tal forma que essa escureceu. Devoraram tudo o que o granizo tinha deixado: toda a vegetação e todos os frutos das árvores. Não restou nada verde nas árvores nem nas plantas do campo, em toda a terra do Egito."),  (261, 2, 10, 16, "O faraó mandou chamar Moisés e Arão imediatamente e disse-lhes: Pequei contra o Senhor seu Deus e contra vocês!"),  (262, 2, 10, 17, "Agora perdoem ainda esta vez o meu pecado e orem ao Senhor seu Deus para que leve esta praga mortal para longe de mim."),  (263, 2, 10, 18, "Moisés saiu da presença do faraó e orou ao Senhor."),  (264, 2, 10, 19, "E o Senhor fez soprar com muito mais força o vento ocidental, e este envolveu os gafanhotos e os lançou no mar Vermelho. Não restou um gafanhoto sequer em toda a extensão do Egito."),  (265, 2, 10, 20, "Mas o Senhor endureceu o coração do faraó, e ele não deixou que os israelitas saíssem."),  (266, 2, 10, 21, "O Senhor disse a Moisés: Estenda a mão para o céu, e trevas cobrirão o Egito, trevas tais que poderão ser apalpadas."),  (267, 2, 10, 22, "Moisés estendeu a mão para o céu, e por três dias houve densas trevas em todo o Egito."),  (268, 2, 10, 23, "Ninguém pôde ver ninguém, nem sair do seu lugar durante três dias. Todavia, todos os israelitas tinham luz nos locais em que habitavam."),  (269, 2, 10, 24, "Então o faraó mandou chamar Moisés e disse: Vão e prestem culto ao Senhor. Deixem somente as ovelhas e os bois; as mulheres e as crianças podem ir."),  (270, 2, 10, 25, "Mas Moisés contestou: Tu mesmo nos darás os animais para os nossos sacrifícios e holocaustos que ofereceremos ao Senhor."),  (271, 2, 10, 26, "Além disso, os nossos rebanhos também irão conosco; nem um casco de animal será deixado. Temos que escolher alguns deles para prestar culto ao Senhor nosso Deus e, enquanto não chegarmos ao local, não saberemos quais animais sacrificaremos."),  (272, 2, 10, 27, "Mas o Senhor endureceu o coração do faraó, e ele se recusou a deixá-los ir."),  (273, 2, 10, 28, "Disse o faraó a Moisés: Saia da minha presença! Trate de não aparecer nunca mais diante de mim! No dia em que vir a minha face, você morrerá."),  (274, 2, 10, 29, "Respondeu Moisés: Será como disseste; nunca mais verei a tua face."),  (275, 2, 11, 1, "Disse então o Senhor a Moisés: Enviarei ainda mais uma praga sobre o faraó e sobre o Egito. Somente depois desta ele os deixará sair daqui e até os expulsará totalmente."),  (276, 2, 11, 2, "Diga ao povo, tanto aos homens como às mulheres, que peça aos seus vizinhos objetos de prata e de ouro."),  (277, 2, 11, 3, "O Senhor tornou os egípcios favoráveis ao povo, e o próprio Moisés era tido em alta estima no Egito pelos conselheiros do faraó e pelo povo."),  (278, 2, 11, 4, "Disse, pois, Moisés ao faraó: Assim diz o Senhor: ‘Por volta da meia-noite, passarei por todo o Egito."),  (279, 2, 11, 5, "Todos os primogênitos do Egito morrerão, desde o filho mais velho do faraó, herdeiro do trono, até o filho mais velho da escrava que trabalha no moinho, e também todas as primeiras crias do gado."),  (280, 2, 11, 6, "Haverá grande pranto em todo o Egito, como nunca houve antes nem jamais haverá."),  (281, 2, 11, 7, "Entre os israelitas, porém, nem sequer um cão latirá contra homem ou animal’. Então vocês saberão que o Senhor faz distinção entre o Egito e Israel!"),  (282, 2, 11, 8, "Todos esses seus conselheiros virão a mim e se ajoelharão diante de mim, suplicando: ‘Saiam você e todo o povo que o segue! ’ Só então eu sairei. E, com grande ira, Moisés saiu da presença do faraó."),  (283, 2, 11, 9, "O Senhor tinha dito a Moisés: O faraó não lhes dará ouvidos, a fim de que os meus prodígios se multipliquem no Egito."),  (284, 2, 11, 10, "Moisés e Arão realizaram todos esses prodígios diante do faraó, mas o Senhor lhe endureceu o coração, e ele não quis deixar os israelitas saírem do país."),  (285, 2, 12, 1, "O Senhor disse a Moisés e a Arão, no Egito:"),  (286, 2, 12, 2, "Este deverá ser o primeiro mês do ano para vocês."),  (287, 2, 12, 3, "Digam a toda a comunidade de Israel que no décimo dia deste mês todo homem deverá separar um cordeiro ou um cabrito, para a sua família, um para cada casa."),  (288, 2, 12, 4, "Se uma família for pequena demais para um animal inteiro, deve dividi-lo com seu vizinho mais próximo, conforme o número de pessoas e conforme o que cada um puder comer."),  (289, 2, 12, 5, "O animal escolhido será macho de um ano, sem defeito, e pode ser cordeiro ou cabrito."),  (290, 2, 12, 6, "Guardem-no até o décimo quarto dia do mês, quando toda a comunidade de Israel irá sacrificá-lo, ao pôr-do-sol."),  (291, 2, 12, 7, "Passem, então, um pouco do sangue nas laterais e nas vigas superiores das portas das casas nas quais vocês comerão o animal."),  (292, 2, 12, 8, "Naquela mesma noite comerão a carne assada no fogo, juntamente com ervas amargas e pão sem fermento."),  (293, 2, 12, 9, "Não comam a carne crua, nem cozida em água, mas assada no fogo: cabeça, pernas e vísceras."),  (294, 2, 12, 10, "Não deixem sobrar nada até pela manhã; caso isso aconteça, queimem o que restar."),  (295, 2, 12, 11, "Ao comerem, estejam prontos para sair: cinto no lugar, sandálias nos pés e cajado na mão. Comam apressadamente. Esta é a Páscoa do Senhor."),  (296, 2, 12, 12, "Naquela mesma noite passarei pelo Egito e matarei todos os primogênitos, tanto dos homens como dos animais, e executarei juízo sobre todos os deuses do Egito. Eu sou o Senhor!"),  (297, 2, 12, 13, "O sangue será um sinal para indicar as casas em que vocês estiverem; quando eu vir o sangue, passarei adiante. A praga de destruição não os atingirá quando eu ferir o Egito."),  (298, 2, 12, 14, "Este dia será um memorial que vocês e todos os seus descendentes o comemorarão como festa ao Senhor. Comemorem-no como decreto perpétuo."),  (299, 2, 12, 15, "Durante sete dias comam pão sem fermento. No primeiro dia tirem de casa o fermento, porque quem comer qualquer coisa fermentada, do primeiro ao sétimo dia, será eliminado de Israel."),  (300, 2, 12, 16, "Convoquem uma reunião santa no primeiro dia e outra no sétimo. Não façam nenhum trabalho nesses dias, exceto o da preparação da comida para todos. É só o que poderão fazer."),  (301, 2, 12, 17, "Celebrem a festa dos pães sem fermento, porque foi nesse mesmo dia que eu tirei os exércitos de vocês do Egito. Celebrem esse dia como decreto perpétuo por todas as suas gerações."),  (302, 2, 12, 18, "No primeiro mês comam pão sem fermento, desde o entardecer do décimo quarto dia até o entardecer do vigésimo primeiro."),  (303, 2, 12, 19, "Durante sete dias vocês não deverão ter fermento em casa. Quem comer qualquer coisa fermentada será eliminado da comunidade de Israel, seja estrangeiro, seja natural da terra."),  (304, 2, 12, 20, "Não comam nada fermentado. Onde quer que morarem, comam apenas pão sem fermento."),  (305, 2, 12, 21, "Então Moisés convocou todas as autoridades de Israel e lhes disse: Escolham um cordeiro ou um cabrito para cada família. Sacrifiquem-no para celebrar a Páscoa!"),  (306, 2, 12, 22, "Molhem um feixe de hissopo no sangue que estiver na bacia e passem o sangue na viga superior e nas laterais das portas. Nenhum de vocês poderá sair de casa até o amanhecer."),  (307, 2, 12, 23, "Quando o Senhor passar pela terra para matar os egípcios, verá o sangue na viga superior e nas laterais da porta e passará sobre aquela porta; e não permitirá que o destruidor entre na casa de vocês para matá-los."),  (308, 2, 12, 24, "Obedeçam a estas instruções como decreto perpétuo para vocês e para os seus descendentes."),  (309, 2, 12, 25, "Quando entrarem na terra que o Senhor prometeu lhes dar, celebrem essa cerimônia."),  (310, 2, 12, 26, "Quando os seus filhos lhes perguntarem: ‘O que significa esta cerimônia? ’,"),  (311, 2, 12, 27, "respondam-lhes: É o sacrifício da Páscoa ao Senhor, que passou sobre as casas dos israelitas no Egito e poupou nossas casas quando matou os egípcios. Então o povo curvou-se em adoração."),  (312, 2, 12, 28, "Depois os israelitas se retiraram e fizeram conforme o Senhor tinha ordenado a Moisés e a Arão."),  (313, 2, 12, 29, "Então, à meia-noite, o Senhor matou todos os primogênitos do Egito, desde o filho mais velho do faraó, herdeiro do trono, até o filho mais velho do prisioneiro que estava no calabouço, e também todas as primeiras crias do gado."),  (314, 2, 12, 30, "No meio da noite o faraó, todos os seus conselheiros e todos os egípcios se levantaram. E houve grande pranto no Egito, pois não havia casa que não houvesse um morto."),  (315, 2, 12, 31, "Naquela mesma noite o faraó mandou chamar Moisés e Arão e lhes disse: Saiam imediatamente do meio do meu povo, vocês e os israelitas! Vão prestar culto ao Senhor, como vocês pediram."),  (316, 2, 12, 32, "Levem os seus rebanhos, como tinham dito, e abençoem a mim também."),  (317, 2, 12, 33, "Os egípcios pressionavam o povo para que se apressasse em sair do país, dizendo: Todos nós morreremos! "),  (318, 2, 12, 34, "Então o povo tomou a massa de pão ainda sem fermento e a carregou nos ombros, nas amassadeiras embrulhadas em suas roupas."),  (319, 2, 12, 35, "Os israelitas obedeceram à ordem de Moisés e pediram aos egípcios objetos de prata e de ouro, bem como roupas."),  (320, 2, 12, 36, "O Senhor concedeu ao povo uma disposição favorável da parte dos egípcios, de modo que lhes davam o que pediam; assim eles despojaram os egípcios."),  (321, 2, 12, 37, "Os israelitas foram de Ramessés até Sucote. Havia cerca de seiscentos mil homens a pé, além de mulheres e crianças."),  (322, 2, 12, 38, "Grande multidão de estrangeiros de todo tipo seguiu com eles, além de grandes rebanhos, tanto de bois como de ovelhas e cabras."),  (323, 2, 12, 39, "Com a massa que haviam trazido do Egito, fizeram pães sem fermento. A massa não tinha fermentado, pois eles foram expulsos do Egito e não tiveram tempo de preparar comida."),  (324, 2, 12, 40, "Ora, o período que os israelitas viveram no Egito foi de quatrocentos e trinta anos."),  (325, 2, 12, 41, "No dia quando se completaram os quatrocentos e trinta anos, todos os exércitos do Senhor saíram do Egito."),  (326, 2, 12, 42, "Assim como o Senhor passou em vigília aquela noite para tirar do Egito os israelitas, estes também devem passar em vigília essa mesma noite, para honrar ao Senhor, por todas as suas gerações."),  (327, 2, 12, 43, "Disse o Senhor a Moisés e a Arão: Estas são as leis da Páscoa: Nenhum estrangeiro poderá comê-la."),  (328, 2, 12, 44, "O escravo comprado poderá comer da Páscoa, depois de circuncidado,"),  (329, 2, 12, 45, "mas o residente temporário e o trabalhador contratado dela não comerão."),  (330, 2, 12, 46, "Vocês a comerão numa só casa; não levem nenhum pedaço de carne para fora da casa, nem quebrem nenhum dos ossos."),  (331, 2, 12, 47, "Toda a comunidade de Israel terá que celebrar a Páscoa."),  (332, 2, 12, 48, "Qualquer estrangeiro residente entre vocês que quiser celebrar a Páscoa do Senhor terá que circuncidar todos os do sexo masculino da sua família; então poderá participar como o natural da terra. Nenhum incircunciso poderá participar."),  (333, 2, 12, 49, "A mesma lei se aplicará ao natural da terra e ao estrangeiro residente."),  (334, 2, 12, 50, "Todos os israelitas fizeram como o Senhor tinha ordenado a Moisés e a Arão."),  (335, 2, 12, 51, "No mesmo dia o Senhor tirou os israelitas do Egito, organizados segundo as suas divisões."),  (336, 2, 13, 1, "E disse o Senhor a Moisés:"),  (337, 2, 13, 2, "Consagre a mim todos os primogênitos. O primeiro filho israelita me pertence, não somente entre os homens, mas também entre os animais."),  (338, 2, 13, 3, "Então disse Moisés ao povo: Comemorem esse dia em que vocês saíram do Egito, da terra da escravidão, porque o Senhor os tirou dali com mão poderosa. Não comam nada fermentado."),  (339, 2, 13, 4, "Neste dia do mês de abibe vocês estão saindo."),  (340, 2, 13, 5, "Quando o Senhor os fizer entrar na terra dos cananeus, dos hititas, dos amorreus, dos heveus e dos jebuseus — terra que ele jurou aos seus antepassados que daria a vocês, terra onde manam leite e mel — vocês deverão celebrar esta cerimônia neste mesmo mês."),  (341, 2, 13, 6, "Durante sete dias comam pão sem fermento e, no sétimo dia façam uma festa ao Senhor."),  (342, 2, 13, 7, "Comam pão sem fermento durante os sete dias; não haja nada fermentado entre vocês, nem fermento algum dentro do seu território."),  (343, 2, 13, 8, "Nesse dia cada um dirá a seu filho: Assim faço pelo que o Senhor fez por mim quando saí do Egito."),  (344, 2, 13, 9, "Isto lhe será como sinal em sua mão e memorial em sua testa, para que a lei do Senhor esteja em seus lábios, porque o Senhor o tirou do Egito com mão poderosa."),  (345, 2, 13, 10, "Cumpra esta determinação na época certa, de ano em ano."),  (346, 2, 13, 11, "Depois que o Senhor os fizer entrar na terra dos cananeus e entregá-la a vocês, como jurou a vocês e aos seus antepassados,"),  (347, 2, 13, 12, "separem para o Senhor o primeiro nascido de todo ventre. Todos os primeiros machos dos seus rebanhos pertencem ao Senhor."),  (348, 2, 13, 13, "Resgate com um cordeiro toda primeira cria dos jumentos, mas se não quiser resgatá-la, quebre-lhe o pescoço. Resgate também todo primogênito entre os seus filhos."),  (349, 2, 13, 14, "No futuro, quando os seus filhos lhes perguntarem: ‘Que significa isto? ’, digam-lhes: Com mão poderosa o Senhor nos tirou do Egito, da terra da escravidão."),  (350, 2, 13, 15, "Quando o faraó resistiu e recusou deixar-nos sair, o Senhor matou todos os primogênitos do Egito, tanto de homens como de animais. Por isso sacrificamos ao Senhor os primeiros machos de todo ventre e resgatamos os nossos primogênitos."),  (351, 2, 13, 16, "Isto será como sinal em sua mão e marca em sua testa de que o Senhor nos tirou do Egito com mão poderosa."),  (352, 2, 13, 17, "Quando o faraó deixou sair o povo, Deus não o guiou pela rota da terra dos filisteus, embora este fosse o caminho mais curto, pois disse: Se eles se defrontarem com a guerra, talvez se arrependam e voltem para o Egito."),  (353, 2, 13, 18, "Assim, o Senhor fez o povo dar a volta pelo deserto, seguindo o caminho que leva ao mar Vermelho. Os israelitas saíram do Egito preparados para lutar."),  (354, 2, 13, 19, "Moisés levou os ossos de José, porque José havia feito os filhos de Israel prestarem um juramento, quando disse: Deus certamente virá em auxílio de vocês; levem então os meus ossos daqui."),  (355, 2, 13, 20, "Os israelitas partiram de Sucote e acamparam em Etã, junto ao deserto."),  (356, 2, 13, 21, "Durante o dia o Senhor ia adiante deles, numa coluna de nuvem, para guiá-los no caminho, e de noite, numa coluna de fogo, para iluminá-los, e assim podiam caminhar de dia e de noite."),  (357, 2, 13, 22, "A coluna de nuvem não se afastava do povo de dia, nem a coluna de fogo, de noite."),  (358, 2, 14, 1, "Disse o Senhor a Moisés:"),  (359, 2, 14, 2, "Diga aos israelitas que mudem o rumo e acampem perto de Pi-Hairote, entre Migdol e o mar. Acampem à beira-mar, defronte de Baal-Zefom."),  (360, 2, 14, 3, "O faraó pensará que os israelitas estão vagando confusos, cercados pelo deserto."),  (361, 2, 14, 4, "Então endurecerei o coração do faraó, e ele os perseguirá. Todavia, eu serei glorificado por meio do faraó e de todo o seu exército; e os egípcios saberão que eu sou o Senhor. E assim fizeram os israelitas."),  (362, 2, 14, 5, "Contaram ao rei do Egito que o povo havia fugido. Então o faraó e os seus conselheiros mudaram de idéia e disseram: O que foi que fizemos? Deixamos os israelitas saírem e perdemos os nossos escravos! "),  (363, 2, 14, 6, "Então o faraó mandou aprontar a sua carruagem, e levou consigo o seu exército."),  (364, 2, 14, 7, "Levou todos os carros de guerra do Egito, inclusive seiscentos dos melhores desses carros, cada um com um oficial no seu comando."),  (365, 2, 14, 8, "O Senhor endureceu o coração do faraó, rei do Egito, e este perseguiu os israelitas, que marchavam triunfantemente."),  (366, 2, 14, 9, "Os egípcios, com todos os cavalos e carros de guerra do faraó, os cavaleiros e a infantaria, saíram em perseguição aos israelitas e os alcançaram quando estavam acampados à beira-mar, perto de Pi-Hairote, defronte de Baal-Zefom."),  (367, 2, 14, 10, "Ao aproximar-se o faraó, os israelitas olharam e avistaram os egípcios que marchavam na direção deles. E, aterrorizados, clamaram ao Senhor."),  (368, 2, 14, 11, "Disseram a Moisés: Foi por falta de túmulos no Egito que você nos trouxe para morrermos no deserto? O que você fez conosco, tirando-nos de lá?"),  (369, 2, 14, 12, "Já não lhe tínhamos dito no Egito: Deixe-nos em paz! Seremos escravos dos egípcios! Antes ser escravos dos egípcios do que morrer no deserto! "),  (370, 2, 14, 13, "Moisés respondeu ao povo: Não tenham medo. Fiquem firmes e vejam o livramento que o Senhor lhes trará hoje, porque vocês nunca mais verão os egípcios que hoje vêem."),  (371, 2, 14, 14, "O Senhor lutará por vocês; tão-somente acalmem-se."),  (372, 2, 14, 15, "Disse então o Senhor a Moisés: Por que você está clamando a mim? Diga aos israelitas que sigam avante."),  (373, 2, 14, 16, "Erga a sua vara e estenda a mão sobre o mar, e as águas se dividirão para que os israelitas atravessem o mar em terra seca."),  (374, 2, 14, 17, "Eu, porém, endurecerei o coração dos egípcios e eles os perseguirão. E serei glorificado com a derrota do faraó e de todo o seu exército, com seus carros de guerra e seus cavaleiros."),  (375, 2, 14, 18, "Os egípcios saberão que eu sou o Senhor quando eu for glorificado com a derrota do faraó, com seus carros de guerra e seus cavaleiros."),  (376, 2, 14, 19, "A seguir o anjo de Deus que ia à frente dos exércitos de Israel retirou-se, colocando-se atrás deles. A coluna de nuvem também saiu da frente deles e se pôs atrás,"),  (377, 2, 14, 20, "entre os egípcios e os israelitas. A nuvem trouxe trevas para um e luz para o outro, de modo que os egípcios não puderam aproximar-se dos israelitas durante toda a noite."),  (378, 2, 14, 21, "Então Moisés estendeu a mão sobre o mar, e o Senhor afastou o mar e o tornou em terra seca, com um forte vento oriental que soprou toda aquela noite. As águas se dividiram,"),  (379, 2, 14, 22, "e os israelitas atravessaram pelo meio do mar em terra seca, tendo uma parede de água à direita e outra à esquerda."),  (380, 2, 14, 23, "Os egípcios os perseguiram, e todos os cavalos, carros de guerra e cavaleiros do faraó foram atrás deles até o meio do mar."),  (381, 2, 14, 24, "No fim da madrugada, do alto da coluna de fogo e de nuvem, o Senhor viu o exército dos egípcios e o pôs em confusão."),  (382, 2, 14, 25, "Fez que as rodas dos seus carros começassem a soltar-se, de forma que tinham dificuldades em conduzi-los. E os egípcios gritaram: Vamos fugir dos israelitas! O Senhor está lutando por eles contra o Egito."),  (383, 2, 14, 26, "Mas o Senhor disse a Moisés: Estenda a mão sobre o mar para que as águas voltem sobre os egípcios, sobre os seus carros de guerra e sobre os seus cavaleiros."),  (384, 2, 14, 27, "Moisés estendeu a mão sobre o mar, e ao raiar do dia o mar voltou ao seu lugar. Quando os egípcios estavam fugindo, foram de encontro às águas, e o Senhor os lançou ao mar."),  (385, 2, 14, 28, "As águas voltaram e encobriram os seus carros de guerra e os seus cavaleiros, todo o exército do faraó que havia perseguido os israelitas mar adentro. Ninguém sobreviveu."),  (386, 2, 14, 29, "Mas os israelitas atravessaram o mar pisando em terra seca, tendo uma parede de água à direita e outra à esquerda."),  (387, 2, 14, 30, "Naquele dia o Senhor salvou Israel das mãos dos egípcios, e os israelitas viram os egípcios mortos na praia."),  (388, 2, 14, 31, "Israel viu o grande poder do Senhor contra os egípcios, temeu ao Senhor e pôs nele a sua confiança, como também em Moisés, seu servo."),  (389, 2, 15, 1, "Então Moisés e os israelitas entoaram este cântico ao Senhor: Cantarei ao Senhor, pois triunfou gloriosamente. Lançou ao mar o cavalo e o seu cavaleiro!"),  (390, 2, 15, 2, "O Senhor é a minha força e a minha canção; ele é a minha salvação! Ele é o meu Deus e eu o louvarei, é o Deus de meu pai, e eu o exaltarei!"),  (391, 2, 15, 3, "O Senhor é guerreiro, o seu nome é Senhor."),  (392, 2, 15, 4, "Ele lançou ao mar os carros de guerra e o exército do faraó. Os seus melhores oficiais afogaram-se no mar Vermelho."),  (393, 2, 15, 5, "Águas profundas os encobriram; como pedra desceram ao fundo."),  (394, 2, 15, 6, "Senhor, a tua mão direita foi majestosa em poder. Senhor, a tua mão direita despedaçou o inimigo."),  (395, 2, 15, 7, "Em teu triunfo grandioso, derrubaste os teus adversários. Enviaste o teu furor flamejante, que os consumiu como palha."),  (396, 2, 15, 8, "Pelo forte sopro das tuas narinas as águas se amontoaram. As águas turbulentas firmaram-se como muralha; as águas profundas congelaram-se no coração do mar."),  (397, 2, 15, 9, "O inimigo se gloriava: ‘Eu os perseguirei e os alcançarei, dividirei o despojo e os devorarei. Com a espada na mão, eu os destruirei. ’"),  (398, 2, 15, 10, "Mas enviaste o teu sopro, e o mar os encobriu. Afundaram como chumbo nas águas volumosas."),  (399, 2, 15, 11, "Quem entre os deuses é semelhante a ti, Senhor? Quem é semelhante a ti? Majestoso em santidade, terrível em feitos gloriosos, autor de maravilhas?"),  (400, 2, 15, 12, "Estendes a tua mão direita e a terra os engole."),  (401, 2, 15, 13, "Com o teu amor conduzes o povo que resgataste; com a tua força tu o levas à tua santa habitação."),  (402, 2, 15, 14, "As nações ouvem e estremecem; angústia se apodera do povo da Filístia."),  (403, 2, 15, 15, "Os chefes de Edom ficam aterrorizados, os poderosos de Moabe são tomados de tremor, o povo de Canaã esmorece;"),  (404, 2, 15, 16, "terror e medo caem sobre eles; pelo poder do teu braço ficam paralisados como pedra, até que passe o teu povo, ó Senhor, até que passe o povo que tu compraste."),  (405, 2, 15, 17, "Tu o farás entrar e o plantarás no monte da tua herança, no lugar, ó Senhor, que fizeste para a tua habitação, no santuário, ó Senhor, que as tuas mãos estabeleceram."),  (406, 2, 15, 18, "O Senhor reinará eternamente."),  (407, 2, 15, 19, "Quando os cavalos, os carros de guerra e os cavaleiros do faraó entraram no mar, o Senhor fez que as águas do mar se voltassem sobre eles, mas os israelitas atravessaram o mar pisando em terra seca."),  (408, 2, 15, 20, "Então Miriã, a profetisa, irmã de Arão, pegou um tamborim e todas as mulheres a seguiram, tocando tamborins e dançando."),  (409, 2, 15, 21, "E Miriã lhes respondia, cantando: Cantem ao Senhor, pois triunfou gloriosamente. Lançou ao mar o cavalo e o seu cavaleiro."),  (410, 2, 15, 22, "Depois Moisés conduziu Israel desde o mar Vermelho até o deserto de Sur. Durante três dias caminharam no deserto sem encontrar água."),  (411, 2, 15, 23, "Então chegaram a Mara, mas não puderam beber das águas de lá porque eram amargas. Esta é a razão porque o lugar chama-se Mara."),  (412, 2, 15, 24, "E o povo começou a reclamar a Moisés, dizendo: Que beberemos? "),  (413, 2, 15, 25, "Moisés clamou ao Senhor, e este lhe indicou um arbusto. Ele o lançou na água, e esta se tornou boa. Em Mara o Senhor lhes deu leis e ordenanças, e os colocou à prova,"),  (414, 2, 15, 26, "dizendo-lhes: Se vocês derem atenção ao Senhor, ao seu Deus e fizerem o que ele aprova, se derem ouvidos aos seus mandamentos e obedecerem a todos os seus decretos, não trarei sobre vocês nenhuma das doenças que eu trouxe sobre os egípcios, pois eu sou o Senhor que os cura."),  (415, 2, 15, 27, "Depois chegaram a Elim, onde havia doze fontes de água e setenta palmeiras; e acamparam junto àquelas águas."),  (416, 2, 16, 1, "Toda a comunidade de Israel partiu de Elim e chegou ao deserto de Sim, que fica entre Elim e o Sinai. Foi no décimo quinto dia do segundo mês, depois que saíram do Egito."),  (417, 2, 16, 2, "No deserto, toda a comunidade de Israel reclamou a Moisés e Arão."),  (418, 2, 16, 3, "Disseram-lhes os israelitas: Quem dera a mão do Senhor nos tivesse matado no Egito! Lá nos sentávamos ao redor das panelas de carne e comíamos pão à vontade, mas vocês nos trouxeram a este deserto para fazer morrer de fome toda esta multidão! "),  (419, 2, 16, 4, "Disse, porém, o Senhor a Moisés: Eu lhes farei chover pão do céu. O povo sairá e recolherá diariamente a porção necessária para aquele dia. Com isso os porei à prova para ver se seguem ou não as minhas instruções."),  (420, 2, 16, 5, "No sexto dia trarão para ser preparado o dobro do que recolhem nos outros dias."),  (421, 2, 16, 6, "Assim Moisés e Arão disseram a todos os israelitas: Ao entardecer, vocês saberão que foi o Senhor quem os tirou do Egito,"),  (422, 2, 16, 7, "e amanhã cedo verão a glória do Senhor, porque o Senhor ouviu a queixa de vocês contra ele. Quem somos nós para que vocês reclamem a nós? "),  (423, 2, 16, 8, "Disse ainda Moisés: O Senhor lhes dará carne para comer ao entardecer e pão à vontade pela manhã, porque ele ouviu as suas queixas contra ele. Quem somos nós? Vocês não estão reclamando de nós, mas do Senhor."),  (424, 2, 16, 9, "Disse Moisés a Arão: Diga a toda a comunidade de Israel que se apresente ao Senhor, pois ele ouviu as suas queixas."),  (425, 2, 16, 10, "Enquanto Arão falava a toda a comunidade, todos olharam em direção ao deserto, e a glória do Senhor apareceu na nuvem."),  (426, 2, 16, 11, "E o Senhor disse a Moisés:"),  (427, 2, 16, 12, "Ouvi as queixas dos israelitas. Responda-lhes que ao pôr-do-sol vocês comerão carne, e ao amanhecer se fartarão de pão. Assim saberão que eu sou o Senhor seu Deus."),  (428, 2, 16, 13, "No final da tarde, apareceram codornizes que cobriram o lugar onde estavam acampados; ao amanhecer havia uma camada de orvalho ao redor do acampamento."),  (429, 2, 16, 14, "Depois que o orvalho secou, flocos finos semelhantes a geada estavam sobre a superfície do deserto."),  (430, 2, 16, 15, "Quando os israelitas viram aquilo, começaram a perguntar uns aos outros: Que é isso? , pois não sabiam do que se tratava. Disse-lhes Moisés: Este é o pão que o Senhor lhes deu para comer."),  (431, 2, 16, 16, "Assim ordenou o Senhor: ‘Cada chefe de família recolha o quanto precisar: um jarro para cada pessoa da sua tenda’ ."),  (432, 2, 16, 17, "Os israelitas fizeram como lhes fora dito; alguns recolheram mais, outros menos."),  (433, 2, 16, 18, "Quando mediram com o jarro, quem tinha recolhido muito não teve demais, e não faltou a quem tinha recolhido pouco. Cada um recolheu tanto quanto precisava."),  (434, 2, 16, 19, "Ninguém deve guardar nada para a manhã seguinte, ordenou-lhes Moisés."),  (435, 2, 16, 20, "Todavia, alguns deles não deram atenção a Moisés e guardaram um pouco até a manhã seguinte, mas aquilo criou bicho e começou a cheirar mal. Por isso Moisés irou-se contra eles."),  (436, 2, 16, 21, "Cada manhã todos recolhiam o quanto precisavam, pois quando o sol esquentava, aquilo se derretia."),  (437, 2, 16, 22, "No sexto dia recolheram o dobro: dois jarros para cada pessoa; e os líderes da comunidade foram contar isso a Moisés,"),  (438, 2, 16, 23, "que lhes explicou: Foi isto que o Senhor ordenou: ‘Amanhã será dia de descanso, sábado consagrado ao Senhor. Assem e cozinhem o que quiserem. Guardem o que sobrar até a manhã seguinte’ ."),  (439, 2, 16, 24, "E eles o guardaram até a manhã seguinte, como Moisés tinha ordenado, e não cheirou mal nem criou bicho."),  (440, 2, 16, 25, "Comam-no hoje, disse Moisés, pois hoje é o sábado do Senhor. Hoje, vocês não o encontrarão no terreno."),  (441, 2, 16, 26, "Durante seis dias vocês podem recolhê-lo, mas, no sétimo dia, o sábado, nada acharão. "),  (442, 2, 16, 27, "Apesar disso, alguns deles saíram no sétimo dia para recolhê-lo, mas não encontraram nada."),  (443, 2, 16, 28, "Então o Senhor disse a Moisés: Até quando vocês se recusarão a obedecer aos meus mandamentos e às minhas instruções?"),  (444, 2, 16, 29, "Vejam que o Senhor lhes deu o sábado; e por isso, no sexto dia, ele lhes dá pão para dois dias. No sétimo dia, fiquem todos onde estiverem; ninguém deve sair."),  (445, 2, 16, 30, "Então o povo descansou no sétimo dia."),  (446, 2, 16, 31, "O povo de Israel chamou maná àquele pão. Era branco como semente de coentro e tinha gosto de bolo de mel."),  (447, 2, 16, 32, "Disse Moisés: O Senhor ordenou-lhes que recolham um jarro de maná e guardem-no para as futuras gerações, para que vejam o pão que lhes dei no deserto, quando os tirei do Egito."),  (448, 2, 16, 33, "Então Moisés disse a Arão: Ponha numa vasilha a medida de um jarro de maná, e coloque-a diante do Senhor, para que seja conservado para as futuras gerações."),  (449, 2, 16, 34, "Em obediência ao que o Senhor tinha ordenado a Moisés, Arão colocou o maná junto às tábuas da aliança, para ali ser guardado."),  (450, 2, 16, 35, "Os israelitas comeram maná durante quarenta anos, até chegarem a uma terra habitável; comeram maná até chegarem às fronteiras de Canaã."),  (451, 2, 16, 36, "( O jarro é a décima parte de uma arroba. )"),  (452, 2, 17, 1, "Toda a comunidade de Israel partiu do deserto de Sim, andando de um lugar para outro, conforme a ordem do Senhor. Acamparam em Refidim, mas lá não havia água para beber."),  (453, 2, 17, 2, "Por essa razão queixaram-se a Moisés e exigiram: Dê-nos água para beber. Ele respondeu: Por que se queixam a mim? Por que colocam o Senhor à prova? "),  (454, 2, 17, 3, "Mas o povo estava sedento e reclamou a Moisés: Por que você nos tirou do Egito? Foi para matar de sede a nós, aos nossos filhos e aos nossos rebanhos? "),  (455, 2, 17, 4, "Então Moisés clamou ao Senhor: Que farei com este povo? Estão a ponto de apedrejar-me! "),  (456, 2, 17, 5, "Respondeu-lhe o Senhor: Passe à frente do povo. Leve com você algumas das autoridades de Israel, tenha na mão a vara com a qual você feriu o Nilo e vá adiante."),  (457, 2, 17, 6, "Eu estarei à sua espera no alto da rocha que está em Horebe. Bata na rocha, e dela sairá água para o povo beber. Assim fez Moisés, à vista das autoridades de Israel."),  (458, 2, 17, 7, "E chamou aquele lugar Massá e Meribá, porque ali os israelitas reclamaram e puseram o Senhor à prova, dizendo: O Senhor está entre nós, ou não? "),  (459, 2, 17, 8, "Sucedeu que os amalequitas vieram atacar os israelitas em Refidim."),  (460, 2, 17, 9, "Então Moisés disse a Josué: Escolha alguns dos nossos homens e lute contra os amalequitas. Amanhã tomarei posição no alto da colina, com a vara de Deus em minhas mãos."),  (461, 2, 17, 10, "Josué foi então lutar contra os amalequitas, conforme Moisés tinha ordenado. Moisés, Arão e Hur, porém, subiram ao alto da colina."),  (462, 2, 17, 11, "Enquanto Moisés mantinha as mãos erguidas, os israelitas venciam; quando, porém, as abaixava, os amalequitas venciam."),  (463, 2, 17, 12, "Quando as mãos de Moisés já estavam cansadas, eles pegaram uma pedra e a colocaram debaixo dele, para que nela se assentasse. Arão e Hur mantinham erguidas as mãos de Moisés, um de cada lado, de modo que as mãos permaneceram firmes até o pôr-do-sol."),  (464, 2, 17, 13, "E Josué derrotou o exército amalequita ao fio da espada."),  (465, 2, 17, 14, "Depois o Senhor disse a Moisés: Escreva isto num rolo, como memorial, e declare a Josué que farei que os amalequitas sejam esquecidos para sempre debaixo do céu."),  (466, 2, 17, 15, "Moisés construiu um altar e chamou-lhe o Senhor é minha bandeira."),  (467, 2, 17, 16, "E jurou: Pelo trono do Senhor! O Senhor fará guerra contra os amalequitas de geração em geração."),  (468, 2, 18, 1, "Jetro, sacerdote de Midiã e sogro de Moisés, soube de tudo o que Deus tinha feito por Moisés e pelo povo de Israel, como o Senhor havia tirado Israel do Egito."),  (469, 2, 18, 2, "Moisés tinha mandado Zípora, sua mulher, para a casa de seu sogro Jetro, que a recebeu"),  (470, 2, 18, 3, "juntamente com os seus dois filhos. Um deles chamava-se Gérson, pois Moisés dissera: Tornei-me imigrante em terra estrangeira;"),  (471, 2, 18, 4, "e o outro chamava-se Eliézer, pois dissera: O Deus de meu pai foi o meu ajudador; livrou-me da espada do faraó."),  (472, 2, 18, 5, "Jetro, sogro de Moisés, veio com os filhos e a mulher de Moisés encontrá-lo no deserto, onde estava acampado, perto do monte de Deus."),  (473, 2, 18, 6, "E Jetro mandou dizer-lhe: Eu, seu sogro Jetro, estou indo encontrá-lo, e comigo vão sua mulher e seus dois filhos."),  (474, 2, 18, 7, "Então Moisés saiu ao encontro do sogro, curvou-se e beijou-o; trocaram saudações e depois entraram na tenda."),  (475, 2, 18, 8, "Então Moisés contou ao sogro tudo quanto o Senhor tinha feito ao faraó e aos egípcios por amor a Israel e também todas as dificuldades que tinham enfrentado pelo caminho e como o Senhor os livrara."),  (476, 2, 18, 9, "Jetro alegrou-se ao ouvir todas as coisas boas que o Senhor tinha feito a Israel, libertando-o das mãos dos egípcios."),  (477, 2, 18, 10, "Disse ele: Bendito seja o Senhor que os libertou das mãos dos egípcios e do faraó; que livrou o povo das mãos dos egípcios!"),  (478, 2, 18, 11, "Agora sei que o Senhor é maior do que todos os outros deuses, pois ele os superou exatamente naquilo de que se vangloriavam."),  (479, 2, 18, 12, "Então Jetro, sogro de Moisés, ofereceu um holocausto e sacrifícios a Deus, e Arão veio com todas as autoridades de Israel para comerem com o sogro de Moisés na presença de Deus."),  (480, 2, 18, 13, "No dia seguinte Moisés assentou-se para julgar as questões do povo, e este permaneceu de pé diante dele, desde a manhã até o cair da tarde."),  (481, 2, 18, 14, "Quando o seu sogro viu tudo o que ele estava fazendo pelo povo, disse: Que é que você está fazendo? Por que só você se assenta para julgar, e todo este povo o espera de pé, desde a manhã até o cair da tarde? "),  (482, 2, 18, 15, "Moisés lhe respondeu: O povo me procura para que eu consulte a Deus."),  (483, 2, 18, 16, "Toda vez que alguém tem uma questão, esta me é trazida, e eu decido entre as partes, e ensino-lhes os decretos e leis de Deus."),  (484, 2, 18, 17, "Respondeu o sogro de Moisés: O que você está fazendo não é bom."),  (485, 2, 18, 18, "Você e o seu povo ficarão esgotados, pois esta tarefa lhe é pesada demais. Você não pode executá-la sozinho."),  (486, 2, 18, 19, "Agora, ouça-me! Eu lhe darei um conselho, e que Deus esteja com você! Seja você o representante do povo diante de Deus e leve a Deus as suas questões."),  (487, 2, 18, 20, "Oriente-os quanto aos decretos e leis, mostrando-lhes como devem viver e o que devem fazer."),  (488, 2, 18, 21, "Mas escolha dentre todo o povo homens capazes, tementes a Deus, dignos de confiança e inimigos de ganho desonesto. Estabeleça-os como chefes de mil, de cem, de cinqüenta e de dez."),  (489, 2, 18, 22, "Eles estarão sempre à disposição do povo para julgar as questões. Trarão a você apenas as questões difíceis; as mais simples decidirão sozinhos. Isso tornará mais leve o seu fardo, porque eles o dividirão com você."),  (490, 2, 18, 23, "Se você assim fizer, e se assim Deus ordenar, você será capaz de suportar as dificuldades, e todo este povo voltará para casa satisfeito."),  (491, 2, 18, 24, "Moisés aceitou o conselho do sogro e fez tudo como ele tinha sugerido."),  (492, 2, 18, 25, "Escolheu homens capazes de todo o Israel e colocou-os como líderes do povo: chefes de mil, de cem, de cinqüenta e de dez."),  (493, 2, 18, 26, "Estes ficaram como juízes permanentes do povo. As questões difíceis levavam a Moisés; as mais simples, porém, eles mesmos resolviam."),  (494, 2, 18, 27, "Então Moisés e seu sogro se despediram, e este voltou para a sua terra."),  (495, 2, 19, 1, "No dia em que se completaram três meses que os israelitas haviam saído do Egito, chegaram ao deserto do Sinai."),  (496, 2, 19, 2, "Depois de saírem de Refidim, entraram no deserto do Sinai, e Israel acampou ali, diante do monte."),  (497, 2, 19, 3, "Logo Moisés subiu o monte para encontrar-se com Deus. E o Senhor o chamou do monte, dizendo: Diga o seguinte aos descendentes de Jacó e declare aos israelitas:"),  (498, 2, 19, 4, "‘Vocês viram o que fiz ao Egito e como os transportei sobre asas de águias e os trouxe para junto de mim."),  (499, 2, 19, 5, "Agora, se me obedecerem fielmente e guardarem a minha aliança, vocês serão o meu tesouro pessoal dentre todas as nações. Embora toda a terra seja minha,"),  (500, 2, 19, 6, "vocês serão para mim um reino de sacerdotes e uma nação santa’. Essas são as palavras que você dirá aos israelitas."),  (501, 2, 19, 7, "Moisés voltou, convocou as autoridades do povo e lhes expôs tudo o que o Senhor havia-lhe mandado falar."),  (502, 2, 19, 8, "O povo todo respondeu unânime: Faremos tudo o que o Senhor ordenou. E Moisés levou ao Senhor a resposta do povo."),  (503, 2, 19, 9, "Disse o Senhor a Moisés: Virei a você numa densa nuvem, a fim de que o povo, ouvindo-me falar-lhe, passe a confiar sempre em você. Então Moisés relatou ao Senhor o que o povo lhe dissera."),  (504, 2, 19, 10, "E o Senhor disse a Moisés: Vá ao povo e consagre-o hoje e amanhã. Eles deverão lavar as suas vestes"),  (505, 2, 19, 11, "e estar prontos no terceiro dia, porque nesse dia o Senhor descerá sobre o monte Sinai, à vista de todo o povo."),  (506, 2, 19, 12, "Estabeleça limites em torno do monte e diga ao povo: Tenham o cuidado de não subir ao monte e de não tocar na sua base. Quem tocar no monte certamente será morto;"),  (507, 2, 19, 13, "será apedrejado ou morto a flechadas. Ninguém deverá tocá-lo com a mão. Seja homem, seja animal, não viverá. Somente quando a corneta soar um toque longo eles poderão subir ao monte."),  (508, 2, 19, 14, "Tendo Moisés descido do monte, consagrou o povo; e eles lavaram as suas vestes."),  (509, 2, 19, 15, "Disse ele então ao povo: Preparem-se para o terceiro dia, e até lá não se acheguem a mulher."),  (510, 2, 19, 16, "Ao amanhecer do terceiro dia houve trovões e raios, uma densa nuvem cobriu o monte, e uma trombeta ressoou fortemente. Todos no acampamento tremeram de medo."),  (511, 2, 19, 17, "Moisés levou o povo para fora do acampamento, para encontrar-se com Deus, e eles ficaram ao pé do monte."),  (512, 2, 19, 18, "O monte Sinai estava coberto de fumaça, pois o Senhor tinha descido sobre ele em chamas de fogo. Dele subia fumaça como que de uma fornalha; todo o monte tremia violentamente,"),  (513, 2, 19, 19, "e o som da trombeta era cada vez mais forte. Então Moisés falou, e a voz de Deus lhe respondeu."),  (514, 2, 19, 20, "O Senhor desceu ao topo do monte Sinai e chamou Moisés para o alto do monte. Moisés subiu"),  (515, 2, 19, 21, "e o Senhor lhe disse: Desça e alerte o povo que não ultrapasse os limites, para ver o Senhor, e muitos deles pereçam."),  (516, 2, 19, 22, "Mesmo os sacerdotes que se aproximarem do Senhor devem consagrar-se; senão o Senhor os fulminará."),  (517, 2, 19, 23, "Moisés disse ao Senhor: O povo não pode subir ao monte Sinai, pois tu mesmo nos avisaste: ‘Estabeleça um limite em torno do monte e declare-o santo’ ."),  (518, 2, 19, 24, "O Senhor respondeu: Desça e depois torne a subir, acompanhado de Arão. Quanto aos sacerdotes e ao povo, não devem ultrapassar o limite para subir ao Senhor; senão, o Senhor os fulminará."),  (519, 2, 19, 25, "Então Moisés desceu e avisou o povo."),  (520, 2, 20, 1, "E Deus falou todas estas palavras:"),  (521, 2, 20, 2, "Eu sou o Senhor, o teu Deus, que te tirou do Egito, da terra da escravidão."),  (522, 2, 20, 3, "Não terás outros deuses além de mim."),  (523, 2, 20, 4, "Não farás para ti nenhum ídolo, nenhuma imagem de qualquer coisa no céu, na terra, ou nas águas debaixo da terra."),  (524, 2, 20, 5, "Não te prostrarás diante deles nem lhes prestarás culto, porque eu, o Senhor teu Deus, sou Deus zeloso, que castigo os filhos pelos pecados de seus pais até a terceira e quarta geração daqueles que me desprezam,"),  (525, 2, 20, 6, "mas trato com bondade até mil gerações aos que me amam e guardam os meus mandamentos."),  (526, 2, 20, 7, "Não tomarás em vão o nome do Senhor teu Deus, pois o Senhor não deixará impune quem tomar o seu nome em vão."),  (527, 2, 20, 8, "Lembra-te do dia de sábado, para santificá-lo."),  (528, 2, 20, 9, "Trabalharás seis dias e neles farás todos os teus trabalhos,"),  (529, 2, 20, 10, "mas o sétimo dia é o sábado dedicado ao Senhor teu Deus. Nesse dia não farás trabalho algum, nem tu, nem teus filhos ou filhas, nem teus servos ou servas, nem teus animais, nem os estrangeiros que morarem em tuas cidades."),  (530, 2, 20, 11, "Pois em seis dias o Senhor fez os céus e a terra, o mar e tudo o que neles existe, mas no sétimo dia descansou. Portanto, o Senhor abençoou o sétimo dia e o santificou."),  (531, 2, 20, 12, "Honra teu pai e tua mãe, a fim de que tenhas vida longa na terra que o Senhor teu Deus te dá."),  (532, 2, 20, 13, "Não matarás."),  (533, 2, 20, 14, "Não adulterarás."),  (534, 2, 20, 15, "Não furtarás."),  (535, 2, 20, 16, "Não darás falso testemunho contra o teu próximo."),  (536, 2, 20, 17, "Não cobiçarás a casa do teu próximo. Não cobiçarás a mulher do teu próximo, nem seus servos ou servas, nem seu boi ou jumento, nem coisa alguma que lhe pertença."),  (537, 2, 20, 18, "Vendo-se o povo diante dos trovões e dos relâmpagos, e do som da trombeta e do monte fumegando, todos tremeram assustados. Ficaram à distância"),  (538, 2, 20, 19, "e disseram a Moisés: Fala tu mesmo conosco, e ouviremos. Mas que Deus não fale conosco, para que não morramos."),  (539, 2, 20, 20, "Moisés disse ao povo: Não tenham medo! Deus veio prová-los, para que o temor de Deus esteja em vocês e os livre de pecar."),  (540, 2, 20, 21, "Mas o povo permaneceu à distância, ao passo que Moisés aproximou-se da nuvem escura em que Deus se encontrava."),  (541, 2, 20, 22, "O Senhor disse a Moisés: Diga o seguinte aos israelitas: Vocês viram por si mesmos que do céu lhes falei:"),  (542, 2, 20, 23, "não façam ídolos de prata nem de ouro para me representarem."),  (543, 2, 20, 24, "Façam-me um altar de terra e nele sacrifiquem-me os seus holocaustos e as suas ofertas de comunhão, as suas ovelhas e os seus bois. Onde quer que eu faça celebrar o meu nome, virei a vocês e os abençoarei."),  (544, 2, 20, 25, "Se me fizerem um altar de pedras, não o façam com pedras lavradas, porque o uso de ferramentas o profanaria."),  (545, 2, 20, 26, "Não subam por degraus ao meu altar, para que nele não seja exposta a sua nudez."),  (546, 2, 21, 1, "São estas as leis que você proclamará ao povo:"),  (547, 2, 21, 2, "Se você comprar um escravo hebreu, ele o servirá por seis anos. Mas no sétimo ano será liberto, sem precisar pagar nada."),  (548, 2, 21, 3, "Se chegou solteiro, solteiro receberá liberdade; mas se chegou casado, sua mulher irá com ele."),  (549, 2, 21, 4, "Se o seu senhor lhe tiver dado uma mulher, e esta lhe tiver dado filhos ou filhas, a mulher e os filhos pertencerão ao senhor; somente o homem sairá livre."),  (550, 2, 21, 5, "Se, porém, o escravo declarar: ‘Eu amo o meu senhor, a minha mulher e os meus filhos, e não quero sair livre’,"),  (551, 2, 21, 6, "o seu senhor o levará perante os juízes. Terá que levá-lo à porta ou à lateral da porta e furar a sua orelha. Assim, ele será seu escravo por toda a vida."),  (552, 2, 21, 7, "Se um homem vender sua filha como escrava, ela não será liberta como os escravos homens."),  (553, 2, 21, 8, "Se ela não agradar ao seu senhor que a escolheu, ele deverá permitir que ela seja resgatada. Não poderá vendê-la a estrangeiros, pois isso seria deslealdade para com ela."),  (554, 2, 21, 9, "Se o seu senhor a escolher para seu filho, lhe dará os direitos de uma filha."),  (555, 2, 21, 10, "Se o senhor tomar uma segunda mulher, não poderá privar a primeira de alimento, de roupas e dos direitos conjugais."),  (556, 2, 21, 11, "Se não lhe garantir essas três coisas, ela poderá ir embora sem precisar pagar nada."),  (557, 2, 21, 12, "Quem ferir um homem, vindo a matá-lo, terá que ser executado."),  (558, 2, 21, 13, "Todavia, se não o fez intencionalmente, mas Deus o permitiu, designei um lugar para onde poderá fugir."),  (559, 2, 21, 14, "Mas se alguém tiver planejado matar outro deliberadamente, tire-o até mesmo do meu altar e mate-o."),  (560, 2, 21, 15, "Quem agredir o próprio pai ou a própria mãe terá que ser executado."),  (561, 2, 21, 16, "Aquele que seqüestrar alguém e vendê-lo ou for apanhado com ele em seu poder, terá que ser executado."),  (562, 2, 21, 17, "Quem amaldiçoar seu pai ou sua mãe terá que ser executado."),  (563, 2, 21, 18, "Se dois homens brigarem e um deles ferir o outro com uma pedra ou com o punho e o outro não morrer, mas cair de cama,"),  (564, 2, 21, 19, "aquele que o feriu será absolvido, se o outro se levantar e caminhar com o auxílio de uma bengala; todavia ele terá que indenizar o homem ferido pelo tempo que este perdeu e responsabilizar-se por sua completa recuperação."),  (565, 2, 21, 20, "Se alguém ferir seu escravo ou escrava com um pedaço de pau, e como resultado o escravo morrer, será punido;"),  (566, 2, 21, 21, "mas se o escravo sobreviver um ou dois dias, não será punido, visto que é sua propriedade."),  (567, 2, 21, 22, "Se homens brigarem e ferirem uma mulher grávida, e ela der à luz prematuramente, não havendo, porém, nenhum dano sério, o ofensor pagará a indenização que o marido daquela mulher exigir, conforme a determinação dos juízes."),  (568, 2, 21, 23, "Mas, se houver danos graves, a pena será vida por vida,"),  (569, 2, 21, 24, "olho por olho, dente por dente, mão por mão, pé por pé,"),  (570, 2, 21, 25, "queimadura por queimadura, ferida por ferida, contusão por contusão."),  (571, 2, 21, 26, "Se alguém ferir o seu escravo ou sua escrava no olho e o cegar, terá que libertar o escravo como compensação pelo olho."),  (572, 2, 21, 27, "Se quebrar um dente de um escravo ou de uma escrava, terá que libertar o escravo como compensação pelo dente."),  (573, 2, 21, 28, "Se um boi chifrar um homem ou uma mulher, causando-lhe a morte, o boi terá que ser apedrejado até a morte, e a sua carne não poderá ser comida. Mas o dono do boi será absolvido."),  (574, 2, 21, 29, "Se, todavia, o boi costumava chifrar e o dono, ainda que alertado, não o manteve preso, e o boi matar um homem ou uma mulher, o boi será apedrejado e o dono também terá que ser morto."),  (575, 2, 21, 30, "Caso, porém, lhe pedirem um pagamento, poderá resgatar a sua vida pagando o que for exigido."),  (576, 2, 21, 31, "Esta sentença também se aplica no caso de um boi chifrar um menino ou uma menina."),  (577, 2, 21, 32, "Se o boi chifrar um escravo ou escrava, o dono do animal terá que pagar trezentos e sessenta gramas de prata ao dono do escravo, e o boi será apedrejado."),  (578, 2, 21, 33, "Se alguém abrir ou deixar aberta uma cisterna, não tendo o cuidado de tampá-la, e um jumento ou um boi nela cair,"),  (579, 2, 21, 34, "o dono da cisterna terá que pagar o prejuízo indenizando o dono do animal, e ficará com o animal morto."),  (580, 2, 21, 35, "Se o boi de alguém ferir o boi de outro e o matar, venderão o boi vivo e o dividirão em partes iguais, tanto o valor como o animal morto."),  (581, 2, 21, 36, "Contudo, se o boi costumava chifrar, e o dono não o manteve preso, este terá que pagar boi por boi, e ficará com o que morreu. "),  (582, 2, 22, 1, "Se alguém roubar um boi ou uma ovelha e abatê-lo ou vendê-lo, terá que restituir cinco bois pelo boi e quatro ovelhas pela ovelha."),  (583, 2, 22, 2, "Se o ladrão que for pego arrombando for ferido e morrer, quem o feriu não será culpado de homicídio,"),  (584, 2, 22, 3, "mas se isso acontecer depois do nascer do sol, será culpado de homicídio. Um ladrão terá que restituir o que roubou, mas se não tiver nada, será vendido para pagar o roubo."),  (585, 2, 22, 4, "Se o que foi roubado for encontrado vivo em seu poder, seja boi, seja jumento, seja ovelha, ele deverá restituí-lo em dobro."),  (586, 2, 22, 5, "Se alguém levar seu rebanho para pastar num campo ou numa vinha e soltá-lo de modo que venha a pastar no campo de outro homem, fará restituição com o melhor do seu campo ou da sua vinha."),  (587, 2, 22, 6, "Se um fogo se espalhar e alcançar os espinheiros, e queimar os feixes colhidos ou o trigo plantado ou até a lavoura toda, aquele que iniciou o incêndio restituirá o prejuízo."),  (588, 2, 22, 7, "Se alguém entregar ao seu próximo prata ou bens para serem guardados e estes forem roubados da casa deste, o ladrão, se for encontrado, terá que restituí-los em dobro."),  (589, 2, 22, 8, "Mas se o ladrão não for encontrado, o dono da casa terá que comparecer perante os juízes para que se determine se ele não lançou mão dos bens do outro."),  (590, 2, 22, 9, "Sempre que alguém se apossar de boi, jumento, ovelha, roupa ou qualquer outro bem perdido, mas alguém disser: ‘Isto me pertence’, as duas partes envolvidas levarão o caso aos juízes. Aquele a quem os juízes declararem culpado restituirá o dobro ao seu próximo."),  (591, 2, 22, 10, "Se alguém der ao seu próximo o seu jumento, ou boi, ou ovelha ou qualquer outro animal para ser guardado, e o animal morrer, for ferido ou for levado, sem que ninguém o veja,"),  (592, 2, 22, 11, "a questão entre eles será resolvida prestando-se um juramento diante do Senhor de que um não lançou mão da propriedade do outro. O dono terá que aceitar isso e nenhuma restituição será exigida."),  (593, 2, 22, 12, "Mas se o animal tiver sido roubado do seu próximo, este terá que fazer restituição ao dono."),  (594, 2, 22, 13, "Se tiver sido despedaçado por um animal selvagem, ele trará como prova o que restou dele; e não terá que fazer restituição."),  (595, 2, 22, 14, "Se alguém pedir emprestado ao seu próximo um animal, e este for ferido ou morrer na ausência do dono, terá que fazer restituição."),  (596, 2, 22, 15, "Mas se o dono estiver presente, o que tomou emprestado não terá que restituí-lo. Se o animal tiver sido alugado, o preço do aluguel cobrirá a perda."),  (597, 2, 22, 16, "Se um homem seduzir uma virgem que ainda não tenha compromisso de casamento e deitar-se com ela, terá que pagar o preço do seu dote, e ela será sua mulher."),  (598, 2, 22, 17, "Mas se o pai recusar-se a entregá-la, ainda assim o homem terá que pagar o equivalente ao dote das virgens."),  (599, 2, 22, 18, "Não deixem viver a feiticeira."),  (600, 2, 22, 19, "Todo aquele que tiver relações sexuais com animal terá que ser executado."),  (601, 2, 22, 20, "Quem oferecer sacrifício a qualquer outro deus, e não unicamente ao Senhor, será destruído."),  (602, 2, 22, 21, "Não maltratem nem oprimam o estrangeiro, pois vocês foram estrangeiros no Egito."),  (603, 2, 22, 22, "Não prejudiquem as viúvas nem os órfãos;"),  (604, 2, 22, 23, "porque se o fizerem, e eles clamarem a mim, eu certamente atenderei ao seu clamor."),  (605, 2, 22, 24, "Com grande ira matarei vocês à espada; suas mulheres ficarão viúvas e seus filhos, órfãos."),  (606, 2, 22, 25, "Se fizerem empréstimo a alguém do meu povo, a algum necessitado que viva entre vocês, não cobrem juros dele; não emprestem visando lucro."),  (607, 2, 22, 26, "Se tomarem como garantia o manto do seu próximo, devolvam-no até o pôr-do-sol,"),  (608, 2, 22, 27, "porque o manto é a única coberta que ele possui para o corpo. Em que mais se deitaria? Quando ele clamar a mim, eu o ouvirei, pois sou misericordioso."),  (609, 2, 22, 28, "Não blasfemem contra Deus nem amaldiçoem uma autoridade do seu povo."),  (610, 2, 22, 29, "Não retenham as ofertas de suas colheitas. Consagrem-me o primeiro filho de vocês"),  (611, 2, 22, 30, "e a primeira cria das vacas, das ovelhas e das cabras. Durante sete dias a cria ficará com a mãe, mas, no oitavo dia, entreguem-na a mim."),  (612, 2, 22, 31, "Vocês serão meu povo santo. Não comam a carne de nenhum animal despedaçado por feras no campo; joguem-na aos cães. "),  (613, 2, 23, 1, "Não faça declarações falsas e não seja cúmplice do ímpio, sendo-lhe testemunha mal-intencionada."),  (614, 2, 23, 2, "Não acompanhe a maioria para fazer o mal. Ao testemunhar num processo, não perverta a justiça para apoiar a maioria,"),  (615, 2, 23, 3, "nem para favorecer o pobre num processo."),  (616, 2, 23, 4, "Se você encontrar perdido o boi ou o jumento que pertence ao seu inimigo, leve-o de volta a ele."),  (617, 2, 23, 5, "Se você vir o jumento de alguém que o odeia caído sob o peso de sua carga, não o abandone, procure ajudá-lo."),  (618, 2, 23, 6, "Não perverta o direito dos pobres em seus processos."),  (619, 2, 23, 7, "Não se envolva em falsas acusações nem condene à morte o inocente e o justo, porque não absolverei o culpado."),  (620, 2, 23, 8, "Não aceite suborno, pois o suborno cega até os que têm discernimento e prejudica a causa do justo."),  (621, 2, 23, 9, "Não oprima o estrangeiro. Vocês sabem o que é ser estrangeiro, pois foram estrangeiros no Egito."),  (622, 2, 23, 10, "Plantem e colham em sua terra durante seis anos,"),  (623, 2, 23, 11, "mas no sétimo deixem-na descansar sem cultivá-la. Assim os pobres do povo poderão comer o que crescer por si, e o que restar ficará para os animais do campo. Façam o mesmo com as suas vinhas e com os seus olivais."),  (624, 2, 23, 12, "Em seis dias façam os seus trabalhos, mas no sétimo não trabalhem, para que o seu boi e o seu jumento possam descansar, e o seu escravo e o estrangeiro renovem as forças."),  (625, 2, 23, 13, "Tenham o cuidado de fazer tudo o que lhes ordenei. Não invoquem o nome de outros deuses; não se ouçam tais nomes dos seus lábios. "),  (626, 2, 23, 14, "Três vezes por ano vocês me celebrarão festa."),  (627, 2, 23, 15, "Celebrem a festa dos pães sem fermento; durante sete dias comam pão sem fermento, como eu lhes ordenei. Façam isto na época determinada do mês de abibe, pois nesse mês vocês saíram do Egito. Ninguém se apresentará a mim de mãos vazias."),  (628, 2, 23, 16, "Celebrem a festa da colheita dos primeiros frutos do seu trabalho de semeadura. Celebrem a festa do encerramento da colheita, quando, no final do ano, vocês armazenarem as colheitas."),  (629, 2, 23, 17, "Três vezes por ano todos os homens devem comparecer diante do Senhor soberano."),  (630, 2, 23, 18, "Não ofereçam o sangue de um sacrifício feito em minha honra com pão fermentado. A gordura das ofertas de minhas festas não deverá ser guardada até a manhã seguinte."),  (631, 2, 23, 19, "Tragam ao santuário do Senhor seu Deus o melhor dos primeiros frutos das suas colheitas. Não cozinhem o cabrito no leite da própria mãe."),  (632, 2, 23, 20, "Eis que envio um anjo à frente de vocês para protegê-los por todo o caminho e fazê-los chegar ao lugar que preparei."),  (633, 2, 23, 21, "Prestem atenção e ouçam o que ele diz. Não se rebelem contra ele, pois não perdoará as suas transgressões, pois nele está o meu nome."),  (634, 2, 23, 22, "Se vocês ouvirem atentamente o que ele disser e fizerem tudo o que lhes ordeno, serei inimigo dos seus inimigos, e adversário dos seus adversários."),  (635, 2, 23, 23, "O meu anjo irá à frente de vocês e os fará chegar à terra dos amorreus, dos hititas, dos ferezeus, dos cananeus, dos heveus e dos jebuseus, e eu os exterminarei."),  (636, 2, 23, 24, "Não se curvem diante dos deuses deles, nem lhes prestem culto, nem sigam as suas práticas. Destruam-nos totalmente e quebrem as suas colunas sagradas."),  (637, 2, 23, 25, "Prestem culto ao Senhor, o Deus de vocês, e ele os abençoará, dando-lhes alimento e água. Tirarei a doença do meio de vocês."),  (638, 2, 23, 26, "Em sua terra nenhuma grávida perderá o filho, nem haverá mulher estéril. Farei completar-se o tempo de duração da vida de vocês."),  (639, 2, 23, 27, "Mandarei adiante de vocês o meu terror, que porá em confusão todas as nações que vocês encontrarem. Farei que todos os seus inimigos virem as costas e fujam."),  (640, 2, 23, 28, "Causarei pânico entre os heveus, os cananeus e os hititas para expulsá-los de diante de vocês."),  (641, 2, 23, 29, "Não os expulsarei num só ano, pois a terra se tornaria desolada e os animais selvagens se multiplicariam, ameaçando vocês."),  (642, 2, 23, 30, "Eu os expulsarei aos poucos, até que vocês sejam numerosos o suficiente para tomar posse da terra."),  (643, 2, 23, 31, "Estabelecerei as suas fronteiras desde o mar Vermelho até o mar dos filisteus, e desde o deserto até o Rio. Entregarei em suas mãos os povos que vivem na terra, aos quais expulsarão de diante de vocês."),  (644, 2, 23, 32, "Não façam aliança com eles nem com os seus deuses."),  (645, 2, 23, 33, "Não deixem que esses povos morem na terra de vocês, senão eles os levarão a pecar contra mim, porque prestar culto aos deuses deles será uma armadilha para vocês. "),  (646, 2, 24, 1, "Depois Deus disse a Moisés: Subam o monte para encontrar-se com o Senhor, você e Arão, Nadabe e Abiú, e setenta autoridades de Israel. Adorem à distância."),  (647, 2, 24, 2, "Somente Moisés se aproximará do Senhor; os outros não. O povo também não subirá com ele."),  (648, 2, 24, 3, "Quando Moisés se dirigiu ao povo e transmitiu-lhes todas as palavras e ordenanças do Senhor, eles responderam em uníssono: Faremos tudo o que o Senhor ordenou."),  (649, 2, 24, 4, "Moisés, então, escreveu tudo o que o Senhor dissera. Na manhã seguinte Moisés levantou-se, construiu um altar ao pé do monte e ergueu doze colunas de pedra, representando as doze tribos de Israel."),  (650, 2, 24, 5, "Em seguida enviou jovens israelitas, que ofereceram holocaustos e novilhos como sacrifícios de comunhão ao Senhor."),  (651, 2, 24, 6, "Moisés colocou metade do sangue em tigelas e a outra metade derramou sobre o altar."),  (652, 2, 24, 7, "Em seguida, leu o Livro da Aliança para o povo, e eles disseram: Faremos fielmente tudo o que o Senhor ordenou."),  (653, 2, 24, 8, "Depois Moisés aspergiu o sangue sobre o povo, dizendo: Este é o sangue da aliança que o Senhor fez com vocês de acordo com todas essas palavras."),  (654, 2, 24, 9, "Moisés, Arão, Nadabe, Abiú e setenta autoridades de Israel subiram"),  (655, 2, 24, 10, "e viram o Deus de Israel, sob cujos pés havia algo semelhante a um pavimento de safira, como o céu em seu esplendor."),  (656, 2, 24, 11, "Deus, porém, não estendeu a mão para punir esses líderes do povo de Israel; eles viram a Deus, e depois comeram e beberam."),  (657, 2, 24, 12, "Disse o Senhor a Moisés: Suba a mim, ao monte, e fique aqui; e lhe darei as tábuas de pedra com a lei e os mandamentos que escrevi para a instrução do povo."),  (658, 2, 24, 13, "Moisés partiu com Josué, seu auxiliar, e subiu ao monte de Deus."),  (659, 2, 24, 14, "Disse ele às autoridades de Israel: Esperem-nos aqui, até que retornemos. Arão e Hur ficarão com vocês; quem tiver alguma questão para resolver, poderá procurá-los."),  (660, 2, 24, 15, "Quando Moisés subiu, a nuvem cobriu o monte,"),  (661, 2, 24, 16, "e a glória do Senhor permaneceu sobre o monte Sinai. Durante seis dias a nuvem cobriu o monte. No sétimo dia o Senhor chamou Moisés do interior da nuvem."),  (662, 2, 24, 17, "Aos olhos dos israelitas a glória do Senhor parecia um fogo consumidor no topo do monte."),  (663, 2, 24, 18, "Moisés entrou na nuvem e foi subindo o monte. E permaneceu no monte quarenta dias e quarenta noites."),  (664, 2, 25, 1, "Disse o Senhor a Moisés:"),  (665, 2, 25, 2, "Diga aos israelitas que me tragam uma oferta. Receba-a de todo aquele cujo coração o compelir a dar."),  (666, 2, 25, 3, "Estas são as ofertas que deverá receber deles: ouro, prata e bronze,"),  (667, 2, 25, 4, "fios de tecido azul, roxo e vermelho, linho fino, pêlos de cabra,"),  (668, 2, 25, 5, "peles de carneiro tingidas de vermelho, couro, madeira de acácia,"),  (669, 2, 25, 6, "azeite para iluminação; especiarias para o óleo da unção e para o incenso aromático;"),  (670, 2, 25, 7, "pedras de ônix e outras pedras preciosas para serem encravadas no colete sacerdotal e no peitoral."),  (671, 2, 25, 8, "E farão um santuário para mim, e eu habitarei no meio deles."),  (672, 2, 25, 9, "Façam tudo como eu lhe mostrar, conforme o modelo do tabernáculo e de cada utensílio."),  (673, 2, 25, 10, "Faça uma arca de madeira de acácia com um metro e dez centímetros de comprimento, setenta centímetros de largura e setenta centímetros de altura."),  (674, 2, 25, 11, "Revista-a de ouro puro, por dentro e por fora, e faça uma moldura de ouro ao seu redor."),  (675, 2, 25, 12, "Mande fundir quatro argolas de ouro para ela e prenda-as em seus quatro pés, com duas argolas de um lado e duas do outro."),  (676, 2, 25, 13, "Depois faça varas de madeira de acácia, revista-as de ouro"),  (677, 2, 25, 14, "e coloque-as nas argolas laterais da arca, para que possa ser carregada."),  (678, 2, 25, 15, "As varas permanecerão nas argolas da arca; não devem ser retiradas."),  (679, 2, 25, 16, "Então coloque dentro da arca as tábuas da aliança que lhe darei."),  (680, 2, 25, 17, "Faça uma tampa de ouro puro com um metro e dez centímetros de comprimento por setenta centímetros de largura,"),  (681, 2, 25, 18, "com dois querubins de ouro batido nas extremidades da tampa."),  (682, 2, 25, 19, "Faça um querubim numa extremidade e o segundo na outra, formando uma só peça com a tampa."),  (683, 2, 25, 20, "Os querubins devem ter suas asas estendidas para cima, cobrindo com elas a tampa. Ficarão de frente um para o outro, com o rosto voltado para a tampa."),  (684, 2, 25, 21, "Coloque a tampa sobre a arca, e dentro dela as tábuas da aliança que darei a você."),  (685, 2, 25, 22, "Ali, sobre a tampa, no meio dos dois querubins que se encontram sobre a arca da aliança, eu me encontrarei com você e lhe darei todos os meus mandamentos destinados aos israelitas."),  (686, 2, 25, 23, "Faça uma mesa de madeira de acácia com noventa centímetros de comprimento, quarenta e cinco centímetros de largura e setenta centímetros de altura."),  (687, 2, 25, 24, "Revista-a de ouro puro e faça uma moldura de ouro ao seu redor."),  (688, 2, 25, 25, "Faça também ao seu redor uma borda com a largura de quatro dedos e uma moldura de ouro para essa borda."),  (689, 2, 25, 26, "Faça quatro argolas de ouro para a mesa e prenda-as nos quatro cantos dela, onde estão os seus quatro pés."),  (690, 2, 25, 27, "As argolas devem ser presas próximas da borda para que sustentem as varas usadas para carregar a mesa."),  (691, 2, 25, 28, "Faça as varas de madeira de acácia, revestindo-as de ouro; com elas se carregará a mesa."),  (692, 2, 25, 29, "Faça de ouro puro os seus pratos e o recipiente para incenso, as suas tigelas e as bacias nas quais se derramam as ofertas de bebidas."),  (693, 2, 25, 30, "Coloque sobre a mesa os pães da Presença, para que estejam sempre diante de mim."),  (694, 2, 25, 31, "Faça um candelabro de ouro puro e batido. O pedestal, a haste, as taças, as flores e os botões do candelabro formarão com ele uma só peça."),  (695, 2, 25, 32, "Seis braços sairão do candelabro: três de um lado e três do outro."),  (696, 2, 25, 33, "Haverá três taças com formato de flor de amêndoa num dos braços, cada uma com botão e flor, e três taças com formato de flor de amêndoa no braço seguinte, cada uma com botão e flor. Assim será com os seis braços que saem do candelabro."),  (697, 2, 25, 34, "Na haste do candelabro haverá quatro taças com formato de flor de amêndoa, cada uma com botão e flor."),  (698, 2, 25, 35, "Haverá um botão debaixo de cada par dos seis braços que saem do candelabro."),  (699, 2, 25, 36, "Os braços com seus botões formarão uma só peça com o candelabro, tudo feito de ouro puro e batido."),  (700, 2, 25, 37, "Faça-lhe também sete lâmpadas e coloque-as nele para que iluminem a frente dele."),  (701, 2, 25, 38, "Seus cortadores de pavio e seus apagadores serão de ouro puro."),  (702, 2, 25, 39, "Com trinta e cinco quilos de ouro puro faça o candelabro e todos esses utensílios."),  (703, 2, 25, 40, "Tenha o cuidado de fazê-lo segundo o modelo que lhe foi mostrado no monte."),  (704, 2, 26, 1, "Faça o tabernáculo com dez cortinas internas de linho fino trançado e de fios de tecido azul, roxo e vermelho, e nelas mande bordar querubins."),  (705, 2, 26, 2, "Todas as cortinas internas terão a mesma medida: doze metros e sessenta centímetros de comprimento e um metro e oitenta centímetros de largura."),  (706, 2, 26, 3, "Prenda cinco dessas cortinas internas uma com a outra e faça o mesmo com as outra cinco."),  (707, 2, 26, 4, "Faça laçadas de tecido azul ao longo da borda da cortina interna, na extremidade do primeiro conjunto de cortinas internas; o mesmo será feito à cortina interna na extremidade do outro conjunto."),  (708, 2, 26, 5, "Faça cinqüenta laçadas numa cortina interna e cinqüenta laçadas na cortina interna que está na extremidade do outro conjunto, de modo que as laçadas estarão opostas umas às outras."),  (709, 2, 26, 6, "Faça também cinqüenta colchetes de ouro com os quais se prenderão as cortinas internas uma na outra, para que o tabernáculo seja um todo."),  (710, 2, 26, 7, "Com o total de onze cortinas internas de pêlos de cabra faça uma tenda para cobrir o tabernáculo."),  (711, 2, 26, 8, "As onze cortinas internas terão o mesmo tamanho: treze metros e meio de comprimento e um metro e oitenta centímetros de largura."),  (712, 2, 26, 9, "Prenda de um lado cinco cortinas internas e também as outras seis do outro lado. Dobre em duas partes a sexta cortina interna na frente da tenda."),  (713, 2, 26, 10, "Faça cinqüenta laçadas ao longo da borda da cortina interna na extremidade do primeiro conjunto de cortinas, e também ao longo da borda da cortina interna do outro conjunto."),  (714, 2, 26, 11, "Em seguida faça cinqüenta colchetes de bronze e ponha-os nas laçadas para unir a tenda como um todo."),  (715, 2, 26, 12, "Quanto à sobra no comprimento das cortinas internas da tenda, a meia cortina interna que sobrar será pendurada na parte de trás do tabernáculo."),  (716, 2, 26, 13, "As dez cortinas internas serão quarenta e cinco centímetros mais compridas de cada lado; e o que sobrar será pendurado nos dois lados do tabernáculo, para cobri-lo."),  (717, 2, 26, 14, "Faça também para a tenda uma cobertura de pele de carneiro tingida de vermelho, e por cima desta uma cobertura de couro."),  (718, 2, 26, 15, "Faça armações verticais de madeira de acácia para o tabernáculo."),  (719, 2, 26, 16, "Cada armação terá quatro metros e meio de comprimento por setenta centímetros de largura,"),  (720, 2, 26, 17, "com dois encaixes paralelos um ao outro. Todas as armações do tabernáculo devem ser feitas dessa maneira."),  (721, 2, 26, 18, "Faça vinte armações para o lado sul do tabernáculo"),  (722, 2, 26, 19, "e quarenta bases de prata debaixo delas: duas bases para cada armação, uma debaixo de cada encaixe."),  (723, 2, 26, 20, "Para o outro lado, o lado norte do tabernáculo, faça vinte armações"),  (724, 2, 26, 21, "e quarenta bases de prata, duas debaixo de cada armação."),  (725, 2, 26, 22, "Faça seis armações para o lado ocidental do tabernáculo,"),  (726, 2, 26, 23, "e duas armações na parte de trás, nos cantos."),  (727, 2, 26, 24, "As armações nesses dois cantos serão duplas, desde a parte inferior até a superior, colocadas numa única argola; ambas serão assim."),  (728, 2, 26, 25, "Desse modo, haverá oito armações e dezesseis bases de prata, duas debaixo de cada armação."),  (729, 2, 26, 26, "Faça também travessões de madeira de acácia: cinco para as armações de um lado do tabernáculo,"),  (730, 2, 26, 27, "cinco para as do outro lado e cinco para as do lado ocidental, na parte de trás do tabernáculo."),  (731, 2, 26, 28, "O travessão central se estenderá de uma extremidade à outra entre as armações."),  (732, 2, 26, 29, "Revista de ouro as armações e faça argolas de ouro para sustentar os travessões, os quais também terão que ser revestidos de ouro."),  (733, 2, 26, 30, "Faça o tabernáculo de acordo com o modelo que lhe foi mostrado no monte."),  (734, 2, 26, 31, "Faça um véu de linho fino trançado e de fios de tecido azul, roxo e vermelho, e mande bordar nele querubins."),  (735, 2, 26, 32, "Pendure-o com ganchos de ouro em quatro colunas de madeira de acácia revestidas de ouro e fincadas em quatro bases de prata."),  (736, 2, 26, 33, "Pendure o véu pelos colchetes e coloque atrás do véu a arca da aliança. O véu separará o Lugar Santo do Lugar Santíssimo."),  (737, 2, 26, 34, "Coloque a tampa sobre a arca da aliança no Lugar Santíssimo."),  (738, 2, 26, 35, "Coloque a mesa do lado de fora do véu, no lado norte do tabernáculo; e o candelabro em frente dela, no lado sul."),  (739, 2, 26, 36, "Para a entrada da tenda faça uma cortina de linho fino trançado e de fios de tecido azul, roxo e vermelho, obra de bordador."),  (740, 2, 26, 37, "Faça ganchos de ouro para essa cortina e cinco colunas de madeira de acácia revestidas de ouro. Mande fundir para eles cinco bases de bronze. "),  (741, 2, 27, 1, "Faça um altar de madeira de acácia. Será quadrado, com dois metros e vinte e cinco centímetros de largura e um metro e trinta e cinco centímetros de altura."),  (742, 2, 27, 2, "Faça uma ponta em forma de chifre em cada um dos quatro cantos, formando uma só peça com o altar, que será revestido de bronze."),  (743, 2, 27, 3, "Faça de bronze todos os seus utensílios: os recipientes para recolher cinzas, as pás, as bacias de aspersão, os garfos para carne e os braseiros."),  (744, 2, 27, 4, "Faça também para ele uma grelha de bronze em forma de rede e uma argola de bronze em cada um dos quatro cantos da grelha."),  (745, 2, 27, 5, "Coloque-a abaixo da beirada do altar, de maneira que fique a meia altura do altar."),  (746, 2, 27, 6, "Faça varas de madeira de acácia para o altar e revista-as de bronze."),  (747, 2, 27, 7, "Estas varas serão colocadas nas argolas, dos dois lados do altar, quando este for carregado."),  (748, 2, 27, 8, "Faça o altar oco e de tábuas, conforme lhe foi mostrado no monte."),  (749, 2, 27, 9, "Faça um pátio para o tabernáculo. O lado sul terá quarenta e cinco metros de comprimento, e cortinas externas de linho fino trançado,"),  (750, 2, 27, 10, "com vinte colunas e vinte bases de bronze, com ganchos e ligaduras de prata nas colunas."),  (751, 2, 27, 11, "O lado norte também terá quarenta e cinco metros de comprimento e cortinas externas, com vinte colunas e vinte bases de bronze, com ganchos e ligaduras de prata nas colunas."),  (752, 2, 27, 12, "O lado ocidental, com as suas cortinas externas, terá vinte e dois metros e meio de largura, com dez colunas e dez bases."),  (753, 2, 27, 13, "O lado oriental, que dá para o nascente, também terá vinte e dois metros e meio de largura."),  (754, 2, 27, 14, "Haverá cortinas de seis metros e setenta e cinco centímetros de comprimento num dos lados da entrada, com três colunas e três bases,"),  (755, 2, 27, 15, "e cortinas externas de seis metros e setenta e cinco centímetros de comprimento no outro lado, também com três colunas e três bases."),  (756, 2, 27, 16, "Na entrada do pátio, haverá uma cortina de nove metros de comprimento, de linho fino trançado e de fios de tecido azul, roxo e vermelho, obra de bordador, com quatro colunas e quatro bases."),  (757, 2, 27, 17, "Todas as colunas ao redor do pátio terão ligaduras e ganchos de prata e bases de bronze."),  (758, 2, 27, 18, "O pátio terá quarenta e cinco metros de comprimento e vinte e dois metros e meio de largura, com cortinas de linho fino trançado de dois metros e vinte e cinco centímetros de altura e bases de bronze."),  (759, 2, 27, 19, "Todos os utensílios para o serviço do tabernáculo, inclusive todas as estacas da tenda e as do pátio, serão feitos de bronze."),  (760, 2, 27, 20, "Ordene aos israelitas que lhe tragam azeite puro de oliva batida para a iluminação, para que as lâmpadas fiquem sempre acesas."),  (761, 2, 27, 21, "Na Tenda do Encontro, do lado de fora do véu que se encontra diante das tábuas da aliança, Arão e seus filhos manterão acesas as lâmpadas diante do Senhor, do entardecer até de manhã. Este será um decreto perpétuo entre os israelitas, geração após geração. "),  (762, 2, 28, 1, "Chame seu irmão Arão e separe-o dentre os israelitas, e também os seus filhos Nadabe e Abiú, Eleazar e Itamar, para que me sirvam como sacerdotes."),  (763, 2, 28, 2, "Para o seu irmão Arão, faça vestes sagradas que lhe confiram dignidade e honra."),  (764, 2, 28, 3, "Diga a todos os homens capazes, aos quais dei habilidade, que façam vestes para a consagração de Arão, para que me sirva como sacerdote."),  (765, 2, 28, 4, "São estas as vestes que farão: um peitoral, um colete sacerdotal, um manto, uma túnica bordada, um turbante e um cinturão. Para que o sacerdote Arão e seus filhos me sirvam como sacerdotes, eles farão essas vestes sagradas"),  (766, 2, 28, 5, "e usarão linho fino, fios de ouro e fios de tecido azul, roxo e vermelho."),  (767, 2, 28, 6, "Faça o colete sacerdotal de linho fino trançado e de fios de ouro e de fios de tecido azul, roxo e vermelho, trabalho artesanal."),  (768, 2, 28, 7, "Terá duas ombreiras atadas às suas duas extremidades para uni-lo bem."),  (769, 2, 28, 8, "O cinturão e o colete que por ele é preso serão feitos da mesma peça. O cinturão também será de linho fino trançado, de fios de ouro e de fios de tecido azul, roxo e vermelho."),  (770, 2, 28, 9, "Grave em duas pedras de ônix os nomes dos filhos de Israel,"),  (771, 2, 28, 10, "por ordem de nascimento: seis nomes numa pedra e seis na outra."),  (772, 2, 28, 11, "Grave os nomes dos filhos de Israel nas duas pedras como o lapidador grava um selo. Em seguida prenda-as com filigranas de ouro,"),  (773, 2, 28, 12, "costurando-as nas ombreiras do colete sacerdotal, como pedras memoriais para os filhos de Israel. Assim Arão levará os nomes em seus ombros como memorial diante do Senhor."),  (774, 2, 28, 13, "Faça filigranas de ouro"),  (775, 2, 28, 14, "e duas correntes de ouro puro, entrelaçadas como uma corda; e prenda as correntes às filigranas."),  (776, 2, 28, 15, "Faça um peitoral de decisões, trabalho artesanal. Faça-o como o colete sacerdotal: de linho fino trançado e de fios de ouro e de fios de tecido azul, roxo e vermelho."),  (777, 2, 28, 16, "Será quadrado, com um palmo de comprimento e um palmo de largura, e dobrado em dois."),  (778, 2, 28, 17, "Em seguida, fixe nele quatro fileiras de pedras preciosas. Na primeira fileira haverá um rubi, um topázio e um berilo;"),  (779, 2, 28, 18, "na segunda, uma turquesa, uma safira e um diamante;"),  (780, 2, 28, 19, "na terceira, um jacinto, uma ágata e uma ametista;"),  (781, 2, 28, 20, "na quarta, um crisólito, um ônix e um jaspe."),  (782, 2, 28, 21, "Serão doze pedras, uma para cada um dos nomes dos filhos de Israel, cada uma gravada como um selo, com o nome de uma das doze tribos."),  (783, 2, 28, 22, "Faça para o peitoral correntes de ouro puro trançadas como cordas."),  (784, 2, 28, 23, "Faça também duas argolas de ouro e prenda-as às duas extremidades do peitoral."),  (785, 2, 28, 24, "Prenda as duas correntes de ouro às argolas nas extremidades do peitoral,"),  (786, 2, 28, 25, "e as outras extremidades das correntes, às duas filigranas, unindo-as às peças das ombreiras do colete sacerdotal, na parte da frente."),  (787, 2, 28, 26, "Faça outras duas argolas de ouro e prenda-as às outras duas extremidades do peitoral, na borda interna, próxima ao colete sacerdotal."),  (788, 2, 28, 27, "Faça mais duas argolas de ouro e prenda-as na parte inferior das ombreiras, na frente do colete sacerdotal, próximas da costura, logo acima do cinturão do colete sacerdotal."),  (789, 2, 28, 28, "As argolas do peitoral serão amarradas às argolas do colete com um cordão azul, ligando-o ao cinturão, para que o peitoral não se separe do colete sacerdotal."),  (790, 2, 28, 29, "Toda vez que Arão entrar no Lugar Santo, levará os nomes dos filhos de Israel sobre o seu coração no peitoral de decisões, como memorial permanente perante o Senhor."),  (791, 2, 28, 30, "Ponha também o Urim e o Tumim no peitoral das decisões, para que estejam sobre o coração de Arão sempre que ele entrar na presença do Senhor. Assim, Arão levará sempre sobre o coração, na presença do Senhor, os meios para tomar decisões em Israel. "),  (792, 2, 28, 31, "Faça o manto do colete sacerdotal inteiramente de fios de tecido azul,"),  (793, 2, 28, 32, "com uma abertura para a cabeça no centro. Ao redor dessa abertura haverá uma dobra tecida, como uma gola, para que não se rasgue."),  (794, 2, 28, 33, "Faça romãs de fios de tecido azul, roxo e vermelho em volta da borda do manto, intercaladas com pequenos sinos de ouro."),  (795, 2, 28, 34, "Os sinos de ouro e as romãs se alternarão por toda a volta da borda do manto."),  (796, 2, 28, 35, "Arão o vestirá quando ministrar. O som dos sinos será ouvido quando ele entrar no Lugar Santo diante do Senhor e quando sair, para que não morra."),  (797, 2, 28, 36, "Faça um diadema de ouro puro e grave nele como se grava um selo: Consagrado ao Senhor."),  (798, 2, 28, 37, "Prenda-o na parte da frente do turbante com uma fita azul."),  (799, 2, 28, 38, "Estará sobre a testa de Arão; assim ele levará a culpa de qualquer pecado que os israelitas cometerem em relação às coisas sagradas, ao fazerem todas as suas ofertas. Estará sempre sobre a testa de Arão, para que as ofertas sejam aceitas pelo Senhor."),  (800, 2, 28, 39, "Teça a túnica e o turbante com linho fino. O cinturão será feito por um bordador."),  (801, 2, 28, 40, "Faça também túnicas, cinturões e gorros para os filhos de Arão, para conferir-lhes honra e dignidade."),  (802, 2, 28, 41, "Depois de vestir seu irmão Arão e os filhos dele, unja-os e consagre-os, para que me sirvam como sacerdotes."),  (803, 2, 28, 42, "Faça-lhes calções de linho que vão da cintura até a coxa, para cobrirem a sua nudez."),  (804, 2, 28, 43, "Arão e seus filhos terão que vesti-los sempre que entrarem na Tenda do Encontro ou quando se aproximarem do altar para ministrar no Lugar Santo, para que não incorram em culpa e morram. Este é um decreto perpétuo para Arão e para os seus descendentes. "),  (805, 2, 29, 1, "Assim você os consagrará, para que me sirvam como sacerdotes: separe um novilho e dois cordeiros sem defeito."),  (806, 2, 29, 2, "Com a melhor farinha de trigo, sem fermento, faça pães e bolos amassados com azeite, e pães finos, untados com azeite."),  (807, 2, 29, 3, "Coloque-os numa cesta e ofereça-os dentro dela; também ofereça o novilho e os dois cordeiros."),  (808, 2, 29, 4, "Depois traga Arão e seus filhos à entrada da Tenda do Encontro e mande-os se lavar."),  (809, 2, 29, 5, "Pegue as vestes e vista Arão com a túnica e o peitoral. Prenda o colete sacerdotal sobre ele com o cinturão."),  (810, 2, 29, 6, "Ponha-lhe o turbante na cabeça e prenda a coroa sagrada ao turbante."),  (811, 2, 29, 7, "Unja-o com o óleo da unção, derramando-o sobre a cabeça de Arão."),  (812, 2, 29, 8, "Traga os filhos dele, vista a cada um com uma túnica"),  (813, 2, 29, 9, "e um gorro na cabeça. Ponha também os cinturões em Arão e em seus filhos. O sacerdócio lhes pertence como ordenança perpétua. Assim você dedicará Arão e seus filhos."),  (814, 2, 29, 10, "Traga o novilho para a frente da Tenda do Encontro. Arão e seus filhos colocarão as mãos sobre a cabeça do novilho,"),  (815, 2, 29, 11, "e você o sacrificará na presença do Senhor, defronte da Tenda do Encontro."),  (816, 2, 29, 12, "Com o dedo, coloque um pouco do sangue do novilho nas pontas do altar e derrame o resto do sangue na base do altar."),  (817, 2, 29, 13, "Depois tire toda a gordura que cobre as vísceras, o lóbulo do fígado, e os dois rins com a gordura que os envolve, e queime-os no altar."),  (818, 2, 29, 14, "Mas queime a carne, o couro e o excremento do novilho fora do acampamento; é oferta pelo pecado."),  (819, 2, 29, 15, "Separe um dos cordeiros sobre cuja cabeça Arão e seus filhos terão que colocar as mãos."),  (820, 2, 29, 16, "Sacrifique-o, pegue o sangue e jogue-o nos lados do altar."),  (821, 2, 29, 17, "Corte o cordeiro em pedaços, lave as vísceras e as pernas e coloque-as ao lado da cabeça e das outras partes."),  (822, 2, 29, 18, "Depois queime o cordeiro inteiro sobre o altar; é holocausto dedicado ao Senhor; é oferta de aroma agradável dedicada ao Senhor, preparada no fogo."),  (823, 2, 29, 19, "Pegue depois o outro cordeiro. Arão e seus filhos colocarão as mãos sobre a cabeça do animal,"),  (824, 2, 29, 20, "e você o sacrificará. Pegue do sangue e coloque-o na ponta da orelha direita de Arão e dos seus filhos, no polegar da mão direita e do pé direito de cada um deles. Depois derrame o resto do sangue nos lados do altar."),  (825, 2, 29, 21, "Pegue, então, um pouco do sangue do altar e um pouco do óleo da unção, e faça aspersão com eles sobre Arão e suas vestes, sobre seus filhos e as vestes deles. Assim serão consagrados, ele e suas vestes, seus filhos e as vestes deles."),  (826, 2, 29, 22, "Tire desse cordeiro a gordura, a parte gorda da cauda, a gordura que cobre as vísceras, o lóbulo do fígado, os dois rins e a gordura que os envolve, e a coxa direita. Este é o cordeiro da oferta de ordenação."),  (827, 2, 29, 23, "Tire da cesta de pães sem fermento um pão, um bolo assado com azeite e um pão fino."),  (828, 2, 29, 24, "Coloque tudo nas mãos de Arão e de seus filhos, e apresente-os como oferta ritualmente movida perante o Senhor."),  (829, 2, 29, 25, "Em seguida retome-o das mãos deles e queime os pães no altar com o holocausto de aroma agradável ao Senhor; é oferta dedicada ao Senhor, preparada no fogo."),  (830, 2, 29, 26, "Tire o peito do cordeiro para a ordenação de Arão e mova-o perante o Senhor, como gesto ritual de apresentação; essa parte pertencerá a você."),  (831, 2, 29, 27, "Consagre aquelas partes do cordeiro da ordenação que pertencem a Arão e a seus filhos: o peito e a coxa movidos como oferta."),  (832, 2, 29, 28, "Essas partes sempre serão dadas pelos israelitas a Arão e a seus filhos. É a contribuição obrigatória que lhes farão, das suas ofertas de comunhão ao Senhor."),  (833, 2, 29, 29, "As vestes sagradas de Arão passarão aos seus descendentes, que, com elas serão ungidos e consagrados."),  (834, 2, 29, 30, "O filho que o suceder como sacerdote e vier à Tenda do Encontro para ministrar no Lugar Santo terá que usá-las durante sete dias."),  (835, 2, 29, 31, "Pegue o cordeiro da ordenação e cozinhe a sua carne num lugar sagrado."),  (836, 2, 29, 32, "À entrada da Tenda do Encontro, Arão e seus filhos deverão comer a carne do cordeiro e o pão que está na cesta."),  (837, 2, 29, 33, "Eles comerão dessas ofertas com as quais se fez propiciação para sua ordenação e consagração; somente os sacerdotes poderão comê-las, pois são sagradas."),  (838, 2, 29, 34, "Se sobrar da carne do cordeiro da ordenação ou do pão até a manhã seguinte, queime a sobra. Não se deve comê-la, visto que é sagrada."),  (839, 2, 29, 35, "Para a ordenação de Arão e seus filhos, faça durante sete dias tudo o que lhe mandei."),  (840, 2, 29, 36, "Sacrifique um novilho por dia como oferta pelo pecado para fazer propiciação. Purifique o altar, fazendo propiciação por ele, e unja-o para consagrá-lo."),  (841, 2, 29, 37, "Durante sete dias faça propiciação pelo altar, consagrando-o. Então o altar será santíssimo, e tudo o que nele tocar será santo."),  (842, 2, 29, 38, "Eis o que você terá que sacrificar regularmente sobre o altar: a cada dia dois cordeiros de um ano."),  (843, 2, 29, 39, "Ofereça um de manhã e o outro ao entardecer."),  (844, 2, 29, 40, "Com o primeiro cordeiro ofereça um jarro da melhor farinha misturada com um litro de azeite de olivas moídas, e um litro de vinho como oferta derramada."),  (845, 2, 29, 41, "Ofereça o outro cordeiro ao entardecer com uma oferta de cereal e uma oferta derramada, como de manhã. É oferta de aroma agradável ao Senhor, preparada no fogo."),  (846, 2, 29, 42, "De geração em geração esse holocausto deverá ser feito regularmente à entrada da Tenda do Encontro, diante do Senhor. Nesse local eu os encontrarei e falarei com você;"),  (847, 2, 29, 43, "ali me encontrarei com os israelitas, e o lugar será consagrado pela minha glória."),  (848, 2, 29, 44, "Assim consagrarei a Tenda do Encontro e o altar, e consagrarei também Arão e seus filhos para me servirem como sacerdotes."),  (849, 2, 29, 45, "E habitarei no meio dos israelitas e lhes serei o seu Deus."),  (850, 2, 29, 46, "Saberão que eu sou o Senhor, o seu Deus, que os tirou do Egito para habitar no meio deles. Eu sou o Senhor, o seu Deus. "),  (851, 2, 30, 1, "Faça um altar de madeira de acácia para queimar incenso."),  (852, 2, 30, 2, "Será quadrado, com quarenta e cinco centímetros de cada lado e noventa centímetros de altura; suas pontas formarão com ele uma só peça."),  (853, 2, 30, 3, "Revista de ouro puro a parte superior, todos os lados e as pontas, e faça uma moldura de ouro ao seu redor."),  (854, 2, 30, 4, "Faça duas argolas de ouro de cada lado do altar, abaixo da moldura, que sustentem as varas utilizadas para carregá-lo,"),  (855, 2, 30, 5, "e use madeira de acácia para fazer as varas e revista-as de ouro."),  (856, 2, 30, 6, "Coloque o altar em frente do véu que se encontra diante da arca da aliança, diante da tampa que está sobre ele, onde me encontrarei com você."),  (857, 2, 30, 7, "Arão queimará incenso aromático sobre o altar todas as manhãs, quando vier cuidar das lâmpadas,"),  (858, 2, 30, 8, "e também quando acendê-las ao entardecer. Será queimado incenso continuamente perante o Senhor, pelas suas gerações."),  (859, 2, 30, 9, "Não ofereçam nesse altar nenhum outro tipo de incenso nem holocausto nem oferta de cereal nem derramem sobre ele ofertas de bebidas."),  (860, 2, 30, 10, "Uma vez por ano, Arão fará propiciação sobre as pontas do altar. Essa propiciação anual será realizada com o sangue da oferta para propiciação pelo pecado, geração após geração. Esse altar é santíssimo ao Senhor. "),  (861, 2, 30, 11, "Disse então o Senhor a Moisés:"),  (862, 2, 30, 12, "Quando você fizer o recenseamento dos israelitas, cada um deles terá que pagar ao Senhor um preço pelo resgate por sua vida quando for contado. Dessa forma nenhuma praga virá sobre eles quando você os contar."),  (863, 2, 30, 13, "Cada recenseado contribuirá com seis gramas, com base no peso padrão do santuário, que tem doze gramas. As seis gramas são uma oferta ao Senhor."),  (864, 2, 30, 14, "Todos os alistados, da idade de vinte anos para cima, darão ao Senhor essa oferta."),  (865, 2, 30, 15, "Os ricos não contribuirão com mais, nem os pobres darão menos que seis gramas, quando apresentarem a oferta ao Senhor como propiciação por suas vidas."),  (866, 2, 30, 16, "Receba dos israelitas o preço da propiciação e use-o para o serviço da Tenda do Encontro. Será um memorial perante o Senhor em favor dos israelitas, para fazerem propiciação por suas vidas."),  (867, 2, 30, 17, "Disse então o Senhor a Moisés:"),  (868, 2, 30, 18, "Faça uma bacia de bronze com uma base de bronze, para se lavarem. Coloque-a entre a Tenda do Encontro e o altar, e mande enchê-la de água."),  (869, 2, 30, 19, "Arão e seus filhos lavarão as mãos e os pés com a água da bacia."),  (870, 2, 30, 20, "Toda vez que entrarem na Tenda do Encontro, terão que lavar-se com água, para que não morram. Quando também se aproximarem do altar para ministrar ao Senhor, apresentando uma oferta preparada no fogo,"),  (871, 2, 30, 21, "lavarão as mãos e os pés para que não morram. Esse é um decreto perpétuo, para Arão e os seus descendentes, geração após geração."),  (872, 2, 30, 22, "Em seguida o Senhor disse a Moisés:"),  (873, 2, 30, 23, "Junte as seguintes especiarias: seis quilos de mirra líquida, a metade disso, ou seja, três quilos de canela, três quilos de cana aromática,"),  (874, 2, 30, 24, "seis quilos de cássia, com base no peso padrão do santuário, e um galão de azeite de oliva."),  (875, 2, 30, 25, "Faça com eles o óleo sagrado para as unções, uma mistura de aromas, obra de perfumista. Este será o óleo sagrado para as unções."),  (876, 2, 30, 26, "Use-o para ungir a Tenda do Encontro, a arca da aliança,"),  (877, 2, 30, 27, "a mesa e todos os seus utensílios, o candelabro e os seus utensílios, o altar do incenso,"),  (878, 2, 30, 28, "o altar do holocausto e todos os seus utensílios, e a bacia com a sua base."),  (879, 2, 30, 29, "Você os consagrará e serão santíssimos, e tudo o que neles tocar se tornará santo."),  (880, 2, 30, 30, "Unja Arão e seus filhos e consagre-os para que me sirvam como sacerdotes."),  (881, 2, 30, 31, "Diga aos israelitas: Este será o meu óleo sagrado para as unções, geração após geração."),  (882, 2, 30, 32, "Não o derramem sobre nenhum outro homem, e não façam nenhum outro óleo com a mesma composição. É óleo sagrado, e assim vocês devem considerá-lo."),  (883, 2, 30, 33, "Quem fizer óleo como esse ou usá-lo em alguém que não seja sacerdote, será eliminado do meio do seu povo."),  (884, 2, 30, 34, "Disse ainda o Senhor a Moisés: Junte as seguintes essências: bálsamo, ônica, gálbano e incenso puro, todos em quantidades iguais,"),  (885, 2, 30, 35, "e faça um incenso de mistura aromática, obra de perfumista. Levará sal, será puro e santo."),  (886, 2, 30, 36, "Moa parte dele, até virar pó, e coloque-o diante das tábuas da aliança, na Tenda do Encontro, onde me encontrarei com você. O incenso lhes será santíssimo."),  (887, 2, 30, 37, "Não façam nenhum outro incenso com a mesma composição para uso pessoal; considerem-no sagrado, reservado para o Senhor."),  (888, 2, 30, 38, "Quem fizer um incenso semelhante, para usufruir sua fragrância, será eliminado do seu povo."),  (889, 2, 31, 1, "Disse então o Senhor a Moisés:"),  (890, 2, 31, 2, "Eu escolhi a Bezalel, filho de Uri, filho de Hur, da tribo de Judá,"),  (891, 2, 31, 3, "e o enchi do Espírito de Deus, dando-lhes destreza, habilidade e plena capacidade artística"),  (892, 2, 31, 4, "para desenhar e executar trabalhos em ouro, prata e bronze,"),  (893, 2, 31, 5, "para talhar e esculpir pedras, para entalhar madeira e executar todo tipo de obra artesanal."),  (894, 2, 31, 6, "Além disso, designei Aoliabe, filho de Aisamaque, da tribo de Dã, para auxiliá-lo. Também capacitei a todos os artesãos para que executem tudo o que lhe ordenei:"),  (895, 2, 31, 7, "A Tenda do Encontro, a arca da aliança e a tampa que está sobre ela, e todos os outros utensílios da tenda —"),  (896, 2, 31, 8, "a mesa com os seus utensílios, o candelabro de ouro puro e os seus utensílios, o altar do incenso,"),  (897, 2, 31, 9, "o altar do holocausto com os seus utensílios, a bacia com a sua base —"),  (898, 2, 31, 10, "assim como as vestes litúrgicas, tanto as vestes sagradas para Arão, o sacerdote, como as vestes para os seus filhos, quando servirem como sacerdotes,"),  (899, 2, 31, 11, "bem como o óleo para as unções e o incenso aromático para o Lugar Santo. Tudo deve ser feito exatamente como eu lhe ordenei."),  (900, 2, 31, 12, "Disse ainda o Senhor a Moisés:"),  (901, 2, 31, 13, "Diga aos israelitas que guardem os meus sábados. Isso será um sinal entre mim e vocês, geração após geração, a fim de que saibam que eu sou o Senhor, que os santifica."),  (902, 2, 31, 14, "Guardem o sábado, pois para vocês é santo. Aquele que o profanar terá que ser executado; quem fizer algum trabalho nesse dia será eliminado do meio do seu povo."),  (903, 2, 31, 15, "Em seis dias qualquer trabalho poderá ser feito, mas o sétimo dia é o sábado, o dia de descanso, consagrado ao Senhor. Quem fizer algum trabalho no sábado terá que ser executado."),  (904, 2, 31, 16, "Os israelitas terão que guardar o sábado, eles e os seus descendentes, como uma aliança perpétua."),  (905, 2, 31, 17, "Isso será um sinal perpétuo entre mim e os israelitas, pois em seis dias o Senhor fez os céus e a terra, e no sétimo dia ele não trabalhou e descansou."),  (906, 2, 31, 18, "Quando o Senhor terminou de falar com Moisés no monte Sinai, deu-lhe as duas tábuas da aliança, tábuas de pedra, escritas pelo dedo de Deus."),  (907, 2, 32, 1, "O povo, ao ver que Moisés demorava a descer do monte, juntou-se ao redor de Arão e lhe disse: Venha, faça para nós deuses que nos conduzam, pois a esse Moisés, o homem que nos tirou do Egito, não sabemos o que lhe aconteceu."),  (908, 2, 32, 2, "Respondeu-lhes Arão: Tirem os brincos de ouro de suas mulheres, de seus filhos e de suas filhas e tragam-nos a mim."),  (909, 2, 32, 3, "Todos tiraram os seus brincos de ouro e os levaram a Arão."),  (910, 2, 32, 4, "Ele os recebeu e os fundiu, transformando tudo num ídolo, que modelou com uma ferramenta própria, dando-lhe a forma de um bezerro. Então disseram: Eis aí os seus deuses, ó Israel, que tiraram vocês do Egito! "),  (911, 2, 32, 5, "Vendo isso, Arão edificou um altar diante do bezerro e anunciou: Amanhã haverá uma festa dedicada ao Senhor."),  (912, 2, 32, 6, "Na manhã seguinte, ofereceram holocaustos e sacrifícios de comunhão. O povo se assentou para comer e beber, e levantou-se para se entregar à farra."),  (913, 2, 32, 7, "Então o Senhor disse a Moisés: Desça, porque o seu povo, que você tirou do Egito, corrompeu-se."),  (914, 2, 32, 8, "Muito depressa se desviaram daquilo que lhes ordenei e fizeram um ídolo em forma de bezerro, curvaram-se diante dele, ofereceram-lhe sacrifícios, e disseram: ‘Eis aí, ó Israel, os seus deuses que tiraram vocês do Egito’ ."),  (915, 2, 32, 9, "Disse o Senhor a Moisés: Tenho visto que este povo é um povo obstinado."),  (916, 2, 32, 10, "Deixe-me agora, para que a minha ira se acenda contra eles, e eu os destrua. Depois farei de você uma grande nação."),  (917, 2, 32, 11, "Moisés, porém, suplicou ao Senhor, o seu Deus, clamando: Ó Senhor, por que se acenderia a tua ira contra o teu povo, que tiraste do Egito com grande poder e forte mão?"),  (918, 2, 32, 12, "Por que diriam os egípcios: ‘Foi com intenção maligna que ele os libertou, para matá-los nos montes e bani-los da face da terra’? Arrepende-te do fogo da tua ira! Tem piedade, e não tragas este mal sobre o teu povo!"),  (919, 2, 32, 13, "Lembra-te dos teus servos Abraão, Isaque e Israel, aos quais juraste por ti mesmo: ‘Farei que os seus descendentes sejam numerosos como as estrelas do céu e lhes darei toda esta terra que lhes prometi, que será a sua herança para sempre’ ."),  (920, 2, 32, 14, "E sucedeu que o Senhor arrependeu-se do mal que ameaçara trazer sobre o povo."),  (921, 2, 32, 15, "Então Moisés desceu do monte, levando nas mãos as duas tábuas da aliança; estavam escritas em ambos os lados, frente e verso."),  (922, 2, 32, 16, "As tábuas tinham sido feitas por Deus; o que nelas estava gravado fora escrito por Deus."),  (923, 2, 32, 17, "Quando Josué ouviu o barulho do povo gritando, disse a Moisés: Há barulho de guerra no acampamento."),  (924, 2, 32, 18, "Respondeu Moisés: Não é canto de vitória, nem canto de derrota; mas ouço o som de canções! "),  (925, 2, 32, 19, "Quando Moisés aproximou-se do acampamento e viu o bezerro e as danças, irou-se e jogou as tábuas no chão, ao pé do monte, quebrando-as."),  (926, 2, 32, 20, "Pegou o bezerro que eles tinham feito e o destruiu no fogo; depois de moê-lo até virar pó, espalhou-o na água e fez com que os israelitas a bebessem."),  (927, 2, 32, 21, "E perguntou a Arão: Que lhe fez esse povo para que você o levasse a tão grande pecado? "),  (928, 2, 32, 22, "Respondeu Arão: Não te enfureças, meu senhor; tu bem sabes como esse povo é propenso para o mal."),  (929, 2, 32, 23, "Eles me disseram: ‘Faça para nós deuses que nos conduzam, pois esse Moisés, o homem que nos tirou do Egito, não sabemos o que lhe aconteceu’."),  (930, 2, 32, 24, "Então eu lhes disse: Quem tiver enfeites de ouro, traga-os para mim. O povo trouxe-me o ouro, eu o joguei no fogo e surgiu esse bezerro! "),  (931, 2, 32, 25, "Moisés viu que o povo estava desenfreado e que Arão o tinha deixado fora de controle, tendo se tornado motivo de riso para os seus inimigos."),  (932, 2, 32, 26, "Então ficou em pé, à entrada do acampamento, e disse: Quem é pelo Senhor, junte-se a mim. Todos os levitas se juntaram a ele."),  (933, 2, 32, 27, "Declarou-lhes também: Assim diz o Senhor, o Deus de Israel: ‘Pegue cada um sua espada, percorra o acampamento, de tenda em tenda, e mate o seu irmão, o seu amigo e o seu vizinho’ ."),  (934, 2, 32, 28, "Fizeram os levitas conforme Moisés ordenou, e naquele dia morreram cerca de três mil dentre o povo."),  (935, 2, 32, 29, "Disse então Moisés: Hoje vocês se consagraram ao Senhor, pois nenhum de vocês poupou o seu filho e o seu irmão, de modo que o Senhor os abençoou neste dia."),  (936, 2, 32, 30, "No dia seguinte Moisés disse ao povo: Vocês cometeram um grande pecado. Mas agora subirei ao Senhor, e talvez possa oferecer propiciação pelo pecado de vocês."),  (937, 2, 32, 31, "Assim, Moisés voltou ao Senhor e disse: Ah, que grande pecado cometeu este povo! Fizeram para si um deus de ouro."),  (938, 2, 32, 32, "Mas agora, eu te rogo, perdoa-lhes o pecado; se não, risca-me do teu livro que escreveste."),  (939, 2, 32, 33, "Respondeu o Senhor a Moisés: Riscarei do meu livro todo aquele que pecar contra mim."),  (940, 2, 32, 34, "Agora vá, guie o povo ao lugar de que lhe falei, e meu anjo irá à sua frente. Todavia, quando chegar a hora de puni-los, eu os punirei pelos pecados deles."),  (941, 2, 32, 35, "E o Senhor feriu o povo com uma praga porque quiseram que Arão fizesse o bezerro."),  (942, 2, 33, 1, "Depois ordenou o Senhor a Moisés: Saia deste lugar, com o povo que você tirou do Egito, e vá para a terra que prometi com juramento a Abraão, a Isaque e a Jacó, dizendo: Eu a darei a seus descendentes."),  (943, 2, 33, 2, "Mandarei à sua frente um anjo e expulsarei os cananeus, os amorreus, os hititas, os ferezeus, os heveus e os jebuseus."),  (944, 2, 33, 3, "Vão para a terra onde manam leite e mel. Mas eu não irei com vocês, pois vocês são um povo obstinado, e eu poderia destruí-los no caminho."),  (945, 2, 33, 4, "Quando o povo ouviu essas palavras terríveis, começou a chorar, e ninguém usou enfeite algum."),  (946, 2, 33, 5, "Isso porque o Senhor ordenara que Moisés dissesse aos israelitas: Vocês são um povo obstinado. Se eu fosse com vocês, ainda que por um só momento, eu os destruiria. Agora tirem os seus enfeites, e eu decidirei o que fazer com vocês."),  (947, 2, 33, 6, "Por isso, do monte Horebe em diante, os israelitas não usaram mais nenhum enfeite."),  (948, 2, 33, 7, "Moisés costumava montar uma tenda do lado de fora do acampamento; ele a chamava Tenda do Encontro. Quem quisesse consultar a Deus ia à tenda, fora do acampamento."),  (949, 2, 33, 8, "Sempre que Moisés ia até lá, todo o povo se levantava e ficava de pé à entrada de suas tendas, observando-o, até que ele entrasse na tenda."),  (950, 2, 33, 9, "Assim que Moisés entrava, a coluna de nuvem descia e ficava à entrada da tenda, enquanto o Senhor falava com Moisés."),  (951, 2, 33, 10, "Quando o povo via a coluna de nuvem parada à entrada da tenda, todos prestavam adoração de pé, cada qual na entrada de sua própria tenda."),  (952, 2, 33, 11, "O Senhor falava com Moisés face a face, como quem fala com seu amigo. Depois Moisés voltava ao acampamento; mas Josué, filho de Num, que lhe servia como auxiliar, não se afastava da tenda."),  (953, 2, 33, 12, "Disse Moisés ao Senhor: Tu me ordenaste: ‘Conduza este povo’, mas não me permites saber quem enviarás comigo. Disseste: ‘Eu o conheço pelo nome e de você tenho me agradado’."),  (954, 2, 33, 13, "Se me vês com agrado, revela-me os teus propósitos, para que eu te conheça e continue sendo aceito por ti. Lembra-te de que esta nação é o teu povo."),  (955, 2, 33, 14, "Respondeu o Senhor: Eu mesmo o acompanharei, e lhe darei descanso."),  (956, 2, 33, 15, "Então Moisés lhe declarou: Se não fores conosco não nos envies."),  (957, 2, 33, 16, "Como se saberá que eu e o teu povo podemos contar com o teu favor, se não nos acompanhares? Que mais poderá distinguir a mim e a teu povo de todos os demais povos da face da terra? "),  (958, 2, 33, 17, "O Senhor disse a Moisés: Farei o que me pede, porque tenho me agradado de você e o conheço pelo nome."),  (959, 2, 33, 18, "Então disse Moisés: Peço-te que me mostres a tua glória."),  (960, 2, 33, 19, "E Deus respondeu: Diante de você farei passar toda a minha bondade, e diante de você proclamarei o meu nome: o Senhor. Terei misericórdia de quem eu quiser ter misericórdia, e terei compaixão de quem eu quiser ter compaixão."),  (961, 2, 33, 20, "E acrescentou: Você não poderá ver a minha face, porque ninguém poderá ver-me e continuar vivo."),  (962, 2, 33, 21, "E prosseguiu o Senhor: Há aqui um lugar perto de mim, onde você ficará, em cima de uma rocha."),  (963, 2, 33, 22, "Quando a minha glória passar, eu o colocarei numa fenda da rocha e o cobrirei com a minha mão até que eu tenha acabado de passar."),  (964, 2, 33, 23, "Então tirarei a minha mão e você verá as minhas costas; mas a minha face ninguém poderá ver."),  (965, 2, 34, 1, "Disse o Senhor a Moisés: Talhe duas tábuas de pedra semelhantes às primeiras, e nelas escreverei as palavras que estavam nas primeiras tábuas que você quebrou."),  (966, 2, 34, 2, "Esteja pronto pela manhã para subir ao monte Sinai. E lá mesmo, no alto do monte, apresente-se a mim."),  (967, 2, 34, 3, "Ninguém poderá ir com você nem ficar em lugar algum do monte; nem mesmo ovelhas e bois deverão pastar diante do monte."),  (968, 2, 34, 4, "Assim Moisés lavrou duas tábuas de pedra semelhantes às primeiras e subiu ao monte Sinai, logo de manhã, como o Senhor lhe havia ordenado, levando nas mãos as duas tábuas de pedra."),  (969, 2, 34, 5, "Então o Senhor desceu na nuvem, permaneceu ali com ele e proclamou o seu nome: o Senhor."),  (970, 2, 34, 6, "E passou diante de Moisés, proclamando: Senhor, Senhor, Deus compassivo e misericordioso, paciente, cheio de amor e de fidelidade,"),  (971, 2, 34, 7, "que mantém o seu amor a milhares e perdoa a maldade, a rebelião e o pecado. Contudo, não deixa de punir o culpado; castiga os filhos e os netos pelo pecado de seus pais, até a terceira e a quarta gerações."),  (972, 2, 34, 8, "Imediatamente Moisés prostrou-se, rosto em terra, e o adorou, dizendo:"),  (973, 2, 34, 9, "Senhor, se de fato me aceitas com agrado, acompanha-nos o Senhor. Mesmo sendo esse um povo obstinado, perdoa a nossa maldade e o nosso pecado e faze de nós a tua herança."),  (974, 2, 34, 10, "Faço com vocês uma aliança, disse o Senhor. Diante de todo o seu povo farei maravilhas jamais realizadas na presença de nenhum outro povo do mundo. O povo no meio do qual você habita verá a obra maravilhosa que eu, o Senhor, farei."),  (975, 2, 34, 11, "Obedeça às ordens que hoje lhe dou. Expulsarei de diante de você os amorreus, os cananeus, os hititas, os ferezeus, os heveus e os jebuseus."),  (976, 2, 34, 12, "Acautele-se para não fazer acordo com aqueles que vivem na terra para a qual você está indo, pois eles se tornariam uma armadilha."),  (977, 2, 34, 13, "Pelo contrário, derrube os altares deles, quebre as suas colunas sagradas e corte os seus postes sagrados."),  (978, 2, 34, 14, "Nunca adore nenhum outro deus, porque o Senhor, cujo nome é Zeloso, é de fato Deus zeloso."),  (979, 2, 34, 15, "Acautele-se para não fazer acordo com aqueles que já vivem na terra; pois quando eles se prostituírem, seguindo aos seus deuses e lhes oferecerem sacrifícios, convidarão você e poderão levá-lo a comer dos seus sacrifícios"),  (980, 2, 34, 16, "e escolher para os seus filhos mulheres dentre as filhas deles. Quando elas se prostituírem, seguindo aos seus deuses, poderão levar os seus filhos a se prostituírem também."),  (981, 2, 34, 17, "Não faça ídolos de metal para você."),  (982, 2, 34, 18, "Celebre a festa dos pães sem fermento. Durante sete dias coma pão sem fermento, como lhe ordenei. Faça isso no tempo certo, no mês de abibe, porquanto naquele mês você saiu do Egito."),  (983, 2, 34, 19, "O primeiro a nascer de cada ventre me pertence, todos os machos dentre as primeiras crias dos seus rebanhos: bezerros, cordeiros e cabritos."),  (984, 2, 34, 20, "Resgate com um cordeiro cada primeiro jumentinho que nascer; mas se não o resgatar, quebre-lhe o pescoço. Resgate todos os seus primogênitos. Ninguém compareça perante mim de mãos vazias."),  (985, 2, 34, 21, "Trabalhe seis dias, mas descanse no sétimo; tanto na época de arar como na da colheita."),  (986, 2, 34, 22, "Celebre a festa das semanas, na ocasião dos primeiros frutos da colheita do trigo, e a festa do encerramento da colheita, no fim do ano."),  (987, 2, 34, 23, "Três vezes por ano todos os homens do seu povo comparecerão diante do Soberano Senhor, o Deus de Israel."),  (988, 2, 34, 24, "Expulsarei nações de diante de você e ampliarei o seu território. Quando você subir três vezes por ano para apresentar-se ao Senhor, o seu Deus, ninguém cobiçará a sua terra."),  (989, 2, 34, 25, "Não me ofereça o sangue de nenhum sacrifício misturado com algo fermentado, e não deixe sobra alguma do sacrifício da festa da Páscoa até a manhã seguinte."),  (990, 2, 34, 26, "Traga o melhor dos primeiros frutos da terra ao santuário do Senhor, o seu Deus. Não cozinhe o cabrito no leite da própria mãe. "),  (991, 2, 34, 27, "Disse o Senhor a Moisés: Escreva essas palavras; porque é de acordo com elas que faço aliança com você e com Israel."),  (992, 2, 34, 28, "Moisés ficou ali com o Senhor quarenta dias e quarenta noites, sem comer pão e sem beber água. E escreveu nas tábuas as palavras da aliança: os Dez Mandamentos."),  (993, 2, 34, 29, "Ao descer do monte Sinai com as duas tábuas da aliança nas mãos, Moisés não sabia que o seu rosto resplandecia por ter conversado com o Senhor."),  (994, 2, 34, 30, "Quando Arão e todos os israelitas viram Moisés, com o rosto resplandecente, tiveram medo de aproximar-se dele."),  (995, 2, 34, 31, "Ele, porém, os chamou; Arão e os líderes da comunidade atenderam, e Moisés falou com eles."),  (996, 2, 34, 32, "Depois, todos os israelitas se aproximaram, e ele lhes transmitiu todos os mandamentos que o Senhor lhe tinha dado no monte Sinai."),  (997, 2, 34, 33, "Quando acabou de falar com eles, cobriu o rosto com um véu."),  (998, 2, 34, 34, "Mas toda vez que entrava para estar na presença do Senhor e falar com ele, tirava o véu até sair. Sempre que saía e contava aos israelitas tudo o que lhe havia sido ordenado,"),  (999, 2, 34, 35, "eles viam que o seu rosto resplandecia. Então, de novo Moisés cobria o rosto com o véu até entrar de novo para falar com o Senhor."),  (1000, 2, 35, 1, "Moisés reuniu toda a comunidade de Israel e lhes disse: Estas são as coisas que o Senhor os mandou fazer:"),  (1001, 2, 35, 2, "Em seis dias qualquer trabalho poderá ser feito, mas o sétimo dia lhes será santo, um sábado de descanso consagrado ao Senhor. Todo aquele que trabalhar nesse dia terá que ser morto."),  (1002, 2, 35, 3, "Nem sequer acendam fogo em nenhuma de suas casas no dia de sábado! "),  (1003, 2, 35, 4, "Disse Moisés a toda a comunidade de Israel: Foi isto que o Senhor ordenou:"),  (1004, 2, 35, 5, "Separem dentre os seus bens uma oferta para o Senhor. Todo aquele que, de coração, estiver disposto, trará como oferta ao Senhor ouro, prata e bronze;"),  (1005, 2, 35, 6, "fios de tecido azul, roxo e vermelho; linho fino e pêlos de cabra;"),  (1006, 2, 35, 7, "peles de carneiro tingidas de vermelho e couro; madeira de acácia;"),  (1007, 2, 35, 8, "óleo para a iluminação; especiarias para o óleo da unção e para o incenso aromático;"),  (1008, 2, 35, 9, "pedras de ônix e outras pedras preciosas para serem encravadas no colete sacerdotal e no peitoral."),  (1009, 2, 35, 10, "Todos os que dentre vocês forem capazes virão fazer tudo quanto o Senhor ordenou:"),  (1010, 2, 35, 11, "o tabernáculo com sua tenda e sua cobertura, os ganchos, as armações, os travessões, as colunas e as bases;"),  (1011, 2, 35, 12, "a arca com suas varas, a tampa e o véu que a protege;"),  (1012, 2, 35, 13, "a mesa com suas varas e todos os seus utensílios, e os pães da Presença;"),  (1013, 2, 35, 14, "o candelabro com seus utensílios, as lâmpadas e o óleo para iluminação;"),  (1014, 2, 35, 15, "o altar do incenso com suas varas, o óleo da unção e o incenso aromático; a cortina divisória à entrada do tabernáculo;"),  (1015, 2, 35, 16, "o altar de holocaustos com sua grelha de bronze, suas varas e todos os seus utensílios; a bacia de bronze e sua base;"),  (1016, 2, 35, 17, "as cortinas externas do pátio com suas colunas e bases, e a cortina da entrada para o pátio;"),  (1017, 2, 35, 18, "as estacas do tabernáculo e do pátio e suas cordas;"),  (1018, 2, 35, 19, "as vestes litúrgicas para ministrar no Lugar Santo, tanto as vestes sagradas de Arão, o sacerdote, como as vestes de seus filhos, para quando servirem como sacerdotes."),  (1019, 2, 35, 20, "Então toda a comunidade de Israel saiu da presença de Moisés,"),  (1020, 2, 35, 21, "e todos os que estavam dispostos, cujo coração os impeliu a isso, trouxeram uma oferta ao Senhor para a obra na Tenda do Encontro, para todos os seus serviços e para as vestes sagradas."),  (1021, 2, 35, 22, "Todos os que se dispuseram, tanto homens como mulheres, trouxeram jóias de ouro de todos os tipos: broches, brincos, anéis e ornamentos; e apresentaram seus objetos de ouro como oferta ritualmente movida perante o Senhor."),  (1022, 2, 35, 23, "Todos os que possuíam fios de tecido azul, roxo e vermelho, ou linho fino, ou pêlos de cabra, peles de carneiro tingidas de vermelho ou couro, trouxeram-nos."),  (1023, 2, 35, 24, "Aqueles que apresentaram oferta de prata ou de bronze trouxeram-na como oferta ao Senhor, e todo aquele que possuía madeira de acácia para qualquer das partes da obra, também a trouxe."),  (1024, 2, 35, 25, "Todas as mulheres capazes teceram com suas mãos e trouxeram o que haviam feito: tecidos azul, roxo e vermelho e linho fino."),  (1025, 2, 35, 26, "Todas as mulheres que se dispuseram e que tinham habilidade teceram os pêlos de cabra."),  (1026, 2, 35, 27, "Os líderes trouxeram pedras de ônix e outras pedras preciosas para serem encravadas no colete sacerdotal e no peitoral."),  (1027, 2, 35, 28, "Trouxeram também especiarias e azeite de oliva para iluminação, para o óleo da unção e para o incenso aromático."),  (1028, 2, 35, 29, "Todos os israelitas que se dispuseram, tanto homens como mulheres, trouxeram ao Senhor ofertas voluntárias para toda a obra que o Senhor, por meio de Moisés, ordenou-lhes que fizessem."),  (1029, 2, 35, 30, "Disse então Moisés aos israelitas: O Senhor escolheu Bezalel, filho de Uri, neto de Hur, da tribo de Judá,"),  (1030, 2, 35, 31, "e o encheu do Espírito de Deus, dando-lhe destreza, habilidade e plena capacidade artística,"),  (1031, 2, 35, 32, "para desenhar e executar trabalhos em ouro, prata e bronze,"),  (1032, 2, 35, 33, "para talhar e lapidar pedras, entalhar madeira para todo tipo de obra artesanal."),  (1033, 2, 35, 34, "E concedeu tanto a ele como a Aoliabe, filho de Aisamaque, da tribo de Dã, a habilidade de ensinar os outros."),  (1034, 2, 35, 35, "A todos esses deu capacidade para realizar todo tipo de obra como artesãos, projetistas, bordadores de linho fino e de fios de tecido azul, roxo e vermelho, e como tecelões. Eram capazes para projetar e executar qualquer trabalho artesanal."),  (1035, 2, 36, 1, "Assim farão Bezalel, Aoliabe e todos os homens capazes, a quem o Senhor concedeu destreza e habilidade para fazerem toda a obra de construção do santuário, realizarão a obra como o Senhor ordenou. "),  (1036, 2, 36, 2, "Então Moisés chamou Bezalel e Aoliabe e todos os homens capazes a quem o Senhor dera habilidade e que estavam dispostos a vir realizar a obra."),  (1037, 2, 36, 3, "Receberam de Moisés todas as ofertas que os israelitas tinham trazido para a obra de construção do santuário. E o povo continuava a trazer voluntariamente ofertas, manhã após manhã."),  (1038, 2, 36, 4, "Por isso, todos os artesãos habilidosos que trabalhavam no santuário interromperam o trabalho"),  (1039, 2, 36, 5, "e disseram a Moisés: O povo está trazendo mais do que o suficiente para realizar a obra que o Senhor ordenou."),  (1040, 2, 36, 6, "Então Moisés ordenou que fosse feita esta proclamação em todo o acampamento: Nenhum homem ou mulher deverá fazer mais nada para ser oferecido ao santuário. Assim, o povo foi impedido de trazer mais,"),  (1041, 2, 36, 7, "pois o que já haviam recebido era mais que suficiente para realizar toda a obra."),  (1042, 2, 36, 8, "Todos os homens capazes dentre os trabalhadores fizeram o tabernáculo com dez cortinas internas de linho fino trançado e de fios de tecido azul, roxo e vermelho, com os querubins bordados sobre eles."),  (1043, 2, 36, 9, "Todas as cortinas internas tinham o mesmo tamanho: doze metros e sessenta centímetros de comprimento por um metro e oitenta centímetros de largura."),  (1044, 2, 36, 10, "Prendeu cinco cortinas internas, e fez o mesmo com as outras cinco."),  (1045, 2, 36, 11, "Em seguida fez laçadas de tecido azul ao longo da borda da última cortina interna do primeiro conjunto de cortinas internas, fazendo o mesmo com o segundo conjunto."),  (1046, 2, 36, 12, "Fez também cinqüenta laçadas na primeira cortina interna e cinqüenta laçadas na última cortina interna do segundo conjunto; as laçadas estavam opostas umas às outras."),  (1047, 2, 36, 13, "Depois fez cinqüenta ganchos de ouro e com eles prendeu um conjunto de cortinas internas ao outro, para que o tabernáculo formasse um todo."),  (1048, 2, 36, 14, "Com o total de onze cortinas internas de pêlos de cabra fez uma tenda para cobrir o tabernáculo."),  (1049, 2, 36, 15, "As onze cortinas internas tinham a mesma medida: treze metros e meio de comprimento por um metro e oitenta centímetros de largura."),  (1050, 2, 36, 16, "Prendeu cinco cortinas internas num conjunto e as outras seis noutro conjunto."),  (1051, 2, 36, 17, "Depois fez cinqüenta laçadas em volta da borda da última cortina interna de um dos conjuntos e também na borda da última cortina interna do outro conjunto."),  (1052, 2, 36, 18, "Fez também cinqüenta ganchos de bronze para unir a tenda, formando um todo."),  (1053, 2, 36, 19, "Em seguida fez para a tenda uma cobertura de pele de carneiro tingida de vermelho, e por cima desta uma cobertura de couro."),  (1054, 2, 36, 20, "Fez ainda armações verticais de madeira de acácia para o tabernáculo."),  (1055, 2, 36, 21, "Cada armação tinha quatro metros e meio de comprimento por setenta centímetros de largura,"),  (1056, 2, 36, 22, "com dois encaixes paralelos um ao outro. E fez todas as armações do tabernáculo dessa madeira."),  (1057, 2, 36, 23, "Fez também vinte armações para o lado sul do tabernáculo"),  (1058, 2, 36, 24, "e quarenta bases de prata para serem colocadas debaixo delas; duas bases para cada armação, uma debaixo de cada encaixe."),  (1059, 2, 36, 25, "Para o outro lado, o lado norte do tabernáculo, fez vinte armações"),  (1060, 2, 36, 26, "e quarenta bases de prata, duas debaixo de cada armação."),  (1061, 2, 36, 27, "Fez ainda seis armações na parte de trás do tabernáculo, isto é, para o lado ocidental,"),  (1062, 2, 36, 28, "e duas armações foram montadas nos cantos, na parte de trás do tabernáculo."),  (1063, 2, 36, 29, "Nesses dois cantos as armações eram duplas, desde a parte inferior até a mais alta, colocadas numa só argola, ambas feitas do mesmo modo."),  (1064, 2, 36, 30, "Havia, pois, oito armações e dezesseis bases de prata, duas debaixo de cada armação."),  (1065, 2, 36, 31, "Também fez travessões de madeira de acácia: cinco para as armações de um lado do tabernáculo,"),  (1066, 2, 36, 32, "cinco para as do outro lado e cinco para as do lado ocidental, na parte de trás do tabernáculo."),  (1067, 2, 36, 33, "Fez o travessão central de uma extremidade à outra, passando pelo meio das armações."),  (1068, 2, 36, 34, "Revestiu de ouro as armações e fez argolas de ouro para sustentar os travessões, os quais também revestiu de ouro."),  (1069, 2, 36, 35, "Fez o véu de linho fino trançado e de fios de tecido azul, roxo e vermelho, e mandou bordar nele querubins."),  (1070, 2, 36, 36, "Fez-lhe quatro colunas de madeira de acácia e as revestiu de ouro. Fez-lhe ainda ganchos de ouro e fundiu as suas bases de prata."),  (1071, 2, 36, 37, "Para a entrada da tenda fez uma cortina de linho fino trançado e de fios de tecido azul, roxo e vermelho, obra de bordador;"),  (1072, 2, 36, 38, "e fez-lhe cinco colunas com ganchos. Revestiu de ouro as partes superior e lateral das colunas e fez de bronze as suas cinco bases."),  (1073, 2, 37, 1, "Bezalel fez a arca com madeira de acácia, com um metro e dez centímetros de comprimento, setenta centímetros de largura e setenta centímetros de altura."),  (1074, 2, 37, 2, "Revestiu-a de ouro puro, por dentro e por fora, e fez uma moldura de ouro ao seu redor."),  (1075, 2, 37, 3, "Fundiu quatro argolas de ouro para ela, prendendo-as a seus quatro pés, com duas argolas de um lado e duas do outro."),  (1076, 2, 37, 4, "Depois fez varas de madeira de acácia e revestiu-as de ouro"),  (1077, 2, 37, 5, "e colocou-as nas argolas laterais da arca para que pudesse ser carregada."),  (1078, 2, 37, 6, "Fez a tampa de ouro puro com um metro e dez centímetros de comprimento por setenta centímetros de largura."),  (1079, 2, 37, 7, "Fez também dois querubins de ouro batido nas extremidades da tampa."),  (1080, 2, 37, 8, "Fez ainda um querubim numa extremidade e o segundo na outra, formando uma só peça com a tampa."),  (1081, 2, 37, 9, "Os querubins tinham as asas estendidas para cima, cobrindo com elas a tampa. Estavam de frente um para o outro, com o rosto voltado para a tampa."),  (1082, 2, 37, 10, "Fez a mesa com madeira de acácia com noventa centímetros de comprimento, quarenta e cinco centímetros de largura e setenta centímetros de altura."),  (1083, 2, 37, 11, "Revestiu-a de ouro puro e fez uma moldura de ouro ao seu redor."),  (1084, 2, 37, 12, "Fez também ao seu redor uma borda com a largura de quatro dedos e uma moldura de ouro para essa borda."),  (1085, 2, 37, 13, "Fundiu quatro argolas de ouro para a mesa e prendeu-as nos quatro cantos, onde estavam os seus quatro pés."),  (1086, 2, 37, 14, "As argolas foram presas próximas da borda, para que sustentassem as varas usadas para carregar a mesa."),  (1087, 2, 37, 15, "Fez as varas para carregar a mesa de madeira de acácia, revestidas de ouro."),  (1088, 2, 37, 16, "E de ouro puro fez os utensílios para a mesa: seus pratos e recipientes para incenso, tigelas e as bacias nas quais se derramam as ofertas de bebidas."),  (1089, 2, 37, 17, "Fez o candelabro de ouro puro e batido. O pedestal, a haste, as taças, as flores e os botões formavam com ele uma só peça."),  (1090, 2, 37, 18, "Seis braços saíam do candelabro: três de um lado e três do outro."),  (1091, 2, 37, 19, "Havia três taças com formato de flor de amêndoa, num dos braços, cada uma com botão e flor, e três taças com formato de flor de amêndoa no braço seguinte, cada uma com botão e flor. Assim será com os seis braços que saem do candelabro."),  (1092, 2, 37, 20, "Na haste do candelabro havia quatro taças com formato de flor de amêndoa, cada uma com flor e botão."),  (1093, 2, 37, 21, "Havia um botão debaixo de cada par dos seis braços que saíam do candelabro."),  (1094, 2, 37, 22, "Os braços com seus botões formavam uma só peça com o candelabro, tudo feito de ouro puro e batido."),  (1095, 2, 37, 23, "Fez de ouro puro suas sete lâmpadas, seus cortadores de pavio e seus apagadores."),  (1096, 2, 37, 24, "Com trinta e cinco quilos de ouro puro fez o candelabro com seus botões e todos esses utensílios."),  (1097, 2, 37, 25, "Fez ainda o altar de incenso de madeira de acácia. Era quadrado, com quarenta e cinco centímetros de cada lado e noventa centímetros de altura; suas pontas formavam com ele uma só peça."),  (1098, 2, 37, 26, "Revestiu de ouro puro a parte superior, todos os lados e as pontas, e fez uma moldura de ouro ao seu redor."),  (1099, 2, 37, 27, "Fez também duas argolas de ouro de cada lado do altar, abaixo da moldura, para sustentar as varas utilizadas para carregá-lo,"),  (1100, 2, 37, 28, "e usou madeira de acácia para fazer as varas e revestiu-as de ouro."),  (1101, 2, 37, 29, "Fez ainda o óleo sagrado para as unções e o incenso puro e aromático, obra de perfumista."),  (1102, 2, 38, 1, "Fez um altar de madeira de acácia para os holocaustos, com um metro e trinta e cinco centímetros de altura; era quadrado, com dois metros e vinte e cinco centímetros de cada lado."),  (1103, 2, 38, 2, "E fez uma ponta em forma de chifre em cada um dos quatro cantos, formando uma só peça com o altar, o qual revestiu de bronze."),  (1104, 2, 38, 3, "De bronze fez todos os seus utensílios: os recipientes para recolher cinzas, as pás, as bacias de aspersão, os garfos para carne e os braseiros."),  (1105, 2, 38, 4, "Fez uma grelha de bronze para o altar em forma de rede, abaixo da sua beirada, a meia altura do altar."),  (1106, 2, 38, 5, "Fundiu quatro argolas de bronze para sustentar as varas nos quatro cantos da grelha de bronze."),  (1107, 2, 38, 6, "Fez as varas de madeira de acácia, revestiu-as de bronze"),  (1108, 2, 38, 7, "e colocou-as nas argolas, nos dois lados do altar, para que o pudessem carregar. O altar era oco, feito de tábuas."),  (1109, 2, 38, 8, "Fez a bacia de bronze e a sua base com os espelhos das mulheres que serviam à entrada da Tenda do Encontro."),  (1110, 2, 38, 9, "Fez também o pátio. O lado sul tinha quarenta e cinco metros de comprimento e cortinas externas de linho fino trançado,"),  (1111, 2, 38, 10, "com vinte colunas e vinte bases de bronze, com ganchos e ligaduras de prata nas colunas."),  (1112, 2, 38, 11, "O lado norte também tinha quarenta e cinco metros de comprimento, com vinte colunas e vinte bases de bronze. Os ganchos e as ligaduras das colunas eram de prata."),  (1113, 2, 38, 12, "O lado ocidental, com suas cortinas externas, tinha vinte e dois metros e meio de largura, com dez colunas e dez bases, com ganchos e ligaduras de prata nas colunas."),  (1114, 2, 38, 13, "O lado oriental, que dá para o nascente, também tinha vinte e dois metros e meio de largura."),  (1115, 2, 38, 14, "Havia cortinas de seis metros e setenta e cinco centímetros de comprimento num dos lados da entrada, com três colunas e três bases,"),  (1116, 2, 38, 15, "e cortinas de seis metros e setenta e cinco centímetros de comprimento no outro lado da entrada do pátio, também com três colunas e três bases."),  (1117, 2, 38, 16, "Todas as cortinas ao redor do pátio eram feitas de linho fino trançado."),  (1118, 2, 38, 17, "As bases das colunas eram de bronze. Os ganchos e as ligaduras das colunas eram de prata, e o topo das colunas também eram revestidos de prata; de modo que todas as colunas do pátio tinham ligaduras de prata."),  (1119, 2, 38, 18, "Na entrada do pátio havia uma cortina de linho fino trançado e de fios de tecidos azul, roxo e vermelho, obra de bordador. Tinha nove metros de comprimento e, à semelhança das cortinas do pátio, tinha dois metros e vinte e cinco centímetros de altura,"),  (1120, 2, 38, 19, "com quatro colunas e quatro bases de bronze. Seus ganchos e ligaduras eram de prata, e o topo das colunas também era revestido de prata."),  (1121, 2, 38, 20, "Todas as estacas da tenda do tabernáculo e do pátio que o rodeava eram de bronze."),  (1122, 2, 38, 21, "Esta é a relação do material usado para o tabernáculo, o tabernáculo da aliança, registrada por ordem de Moisés pelos levitas, sob a direção de Itamar, filho de Arão, o sacerdote."),  (1123, 2, 38, 22, "Bezalel, filho de Uri, neto de Hur, da tribo de Judá, fez tudo o que o Senhor tinha ordenado a Moisés."),  (1124, 2, 38, 23, "Com ele estava Aoliabe, filho de Aisamaque, da tribo de Dã, artesão e projetista, e também bordador em linho fino e de fios de tecido azul, roxo e vermelho."),  (1125, 2, 38, 24, "O peso total do ouro recebido na oferta movida e utilizado para a obra do santuário foi de uma tonelada, com base no peso padrão do santuário."),  (1126, 2, 38, 25, "O peso da prata recebida dos que foram contados no recenseamento da comunidade foi superior a três toneladas e meia, com base no peso padrão do santuário:"),  (1127, 2, 38, 26, "seis gramas para cada um dos recenseados, seiscentos e três mil, quinhentos e cinqüenta homens de vinte anos de idade para cima."),  (1128, 2, 38, 27, "As três toneladas e meia de prata foram usadas para fundir as bases do santuário e do véu: cem bases feitas das três toneladas e meia, trinta e cinco quilos para cada base."),  (1129, 2, 38, 28, "Vinte quilos e trezentos gramas foram usados para fazer os ganchos para as colunas, para revestir a parte superior das colunas e para fazer as suas ligaduras."),  (1130, 2, 38, 29, "O peso do bronze da oferta movida foi de duas toneladas e meia."),  (1131, 2, 38, 30, "Ele o utilizou para fazer as bases da entrada da Tenda do Encontro, o altar de bronze, a sua grelha e todos os seus utensílios,"),  (1132, 2, 38, 31, "as bases do pátio ao redor e da sua entrada, e todas as estacas do tabernáculo e do pátio em derredor."),  (1133, 2, 39, 1, "Com fios de tecido azul, roxo e vermelho fizeram as vestes litúrgicas para ministrar no Lugar Santo. Também fizeram as vestes sagradas de Arão, como o Senhor tinha ordenado a Moisés."),  (1134, 2, 39, 2, "Fez o colete sacerdotal de linho fino trançado e de fios de ouro e de fios de tecidos azul, roxo e vermelho."),  (1135, 2, 39, 3, "E bateu o ouro em finas placas das quais cortaram fios de ouro para serem bordados no linho fino com os fios de tecido azul, roxo e vermelho, obra artesanal."),  (1136, 2, 39, 4, "Fizeram as ombreiras para o colete sacerdotal, atadas às suas duas extremidades, para que pudessem ser amarradas."),  (1137, 2, 39, 5, "O cinturão e o colete por ele preso foram feitos da mesma peça. O cinturão também foi feito de linho fino trançado e de fios de ouro e de fios de tecido azul, roxo e vermelho, como o Senhor tinha ordenado a Moisés."),  (1138, 2, 39, 6, "Prenderam as pedras de ônix em filigranas de ouro e nelas gravaram os nomes dos filhos de Israel, como um lapidador grava um selo."),  (1139, 2, 39, 7, "Então as costuraram nas ombreiras do colete sacerdotal, como pedras memoriais para os filhos de Israel, como o Senhor tinha ordenado a Moisés."),  (1140, 2, 39, 8, "Fez o peitoral, trabalho artesanal, como o colete sacerdotal: de linho fino trançado, de fios de ouro e de fios de tecidos azul, roxo e vermelho."),  (1141, 2, 39, 9, "Era quadrado, com um palmo de comprimento e um palmo de largura, e dobrado em dois."),  (1142, 2, 39, 10, "Em seguida fixaram nele quatro fileiras de pedras preciosas. Na primeira fileira havia um rubi, um topázio e um berilo;"),  (1143, 2, 39, 11, "na segunda, uma turquesa, uma safira e um diamante;"),  (1144, 2, 39, 12, "na terceira, um jacinto, uma ágata e uma ametista;"),  (1145, 2, 39, 13, "na quarta, um crisólito, um ônix e um jaspe, todas fixadas em filigranas de ouro."),  (1146, 2, 39, 14, "Havia doze pedras, uma para cada nome dos filhos de Israel, cada uma gravada como um lapidador grava um selo, com o nome de uma das doze tribos."),  (1147, 2, 39, 15, "Para o peitoral fizeram correntes trançadas de ouro puro, como cordas."),  (1148, 2, 39, 16, "De ouro fizeram duas filigranas e duas argolas, as quais prenderam às duas extremidades do peitoral."),  (1149, 2, 39, 17, "Prenderam as duas correntes de ouro às duas argolas nas extremidades do peitoral,"),  (1150, 2, 39, 18, "e as outras extremidades das correntes, às duas filigranas, unindo-as às peças das ombreiras do colete sacerdotal, na parte da frente."),  (1151, 2, 39, 19, "Fizeram outras duas argolas de ouro e as prenderam às duas extremidades do peitoral na borda interna, próxima ao colete sacerdotal."),  (1152, 2, 39, 20, "Depois fizeram mais duas argolas de ouro e as prenderam na parte inferior das ombreiras, na frente do colete sacerdotal, próximas da costura, logo acima do cinturão do colete sacerdotal."),  (1153, 2, 39, 21, "Amarraram as argolas do peitoral às argolas do colete com um cordão azul, ligando-o ao cinturão, para que o peitoral não se separasse do colete sacerdotal, como o Senhor tinha ordenado a Moisés."),  (1154, 2, 39, 22, "Fizeram o manto do colete sacerdotal inteiramente de fios de tecido azul, obra de tecelão,"),  (1155, 2, 39, 23, "com uma abertura no centro. Ao redor dessa abertura havia uma dobra tecida, como uma gola, para que não se rasgasse."),  (1156, 2, 39, 24, "Fizeram romãs de linho fino trançado e de fios de tecido azul, roxo e vermelho em volta da borda do manto."),  (1157, 2, 39, 25, "Fizeram ainda pequenos sinos de ouro puro, atando-os em volta da borda, entre as romãs."),  (1158, 2, 39, 26, "Os sinos e as romãs se alternavam por toda a borda do manto. Tudo feito para ser usado ao se ministrar, como o Senhor tinha ordenado a Moisés."),  (1159, 2, 39, 27, "Para Arão e seus filhos fizeram de linho fino as túnicas, obra de tecelão,"),  (1160, 2, 39, 28, "o turbante, os gorros e os calções, de linho fino trançado."),  (1161, 2, 39, 29, "O cinturão também era de linho fino trançado e de fios de tecido azul, roxo e vermelho, obra de bordador, como o Senhor tinha ordenado a Moisés."),  (1162, 2, 39, 30, "Fizeram de ouro puro o diadema sagrado, e gravaram nele como se grava um selo: Consagrado ao Senhor."),  (1163, 2, 39, 31, "Depois usaram um cordão azul para prendê-lo na parte de cima do turbante, como o Senhor tinha ordenado a Moisés."),  (1164, 2, 39, 32, "Assim foi encerrada toda a obra do tabernáculo, a Tenda do Encontro. Os israelitas fizeram tudo conforme o Senhor tinha ordenado a Moisés."),  (1165, 2, 39, 33, "Então trouxeram o tabernáculo a Moisés; a tenda e todos os seus utensílios, os ganchos, as molduras, os travessões, as colunas e as bases,"),  (1166, 2, 39, 34, "a cobertura de pele de carneiro tingida de vermelho, a cobertura de couro e o véu protetor,"),  (1167, 2, 39, 35, "a arca da aliança com as suas varas e a tampa,"),  (1168, 2, 39, 36, "a mesa com todos os seus utensílios e os pães da Presença,"),  (1169, 2, 39, 37, "o candelabro de ouro puro com a sua fileira de lâmpadas e todos os seus utensílios e o óleo para iluminação,"),  (1170, 2, 39, 38, "o altar de ouro, o óleo da unção, o incenso aromático e a cortina de entrada para a tenda,"),  (1171, 2, 39, 39, "o altar de bronze com a sua grelha, as suas varas e todos os seus utensílios, a bacia e a sua base,"),  (1172, 2, 39, 40, "as cortinas externas do pátio com as suas colunas e bases e a cortina para a entrada do pátio, as cordas e estacas da tenda do pátio, todos os utensílios para o tabernáculo, a Tenda do Encontro,"),  (1173, 2, 39, 41, "e as vestes litúrgicas para ministrar no Lugar Santo, tanto as vestes sagradas para Arão, o sacerdote, como as vestes de seus filhos, para quando servissem como sacerdotes."),  (1174, 2, 39, 42, "Os israelitas fizeram todo o trabalho conforme o Senhor tinha ordenado a Moisés."),  (1175, 2, 39, 43, "Moisés inspecionou a obra e viu que tinham feito tudo como o Senhor tinha ordenado. Então Moisés os abençoou."),  (1176, 2, 40, 1, "Disse o Senhor a Moisés:"),  (1177, 2, 40, 2, "Arme o tabernáculo, a Tenda do Encontro, no primeiro dia do primeiro mês."),  (1178, 2, 40, 3, "Coloque nele a arca da aliança e proteja-a com o véu."),  (1179, 2, 40, 4, "Traga a mesa e arrume sobre ela tudo o que lhe pertence. Depois traga o candelabro e coloque as suas lâmpadas."),  (1180, 2, 40, 5, "Ponha o altar de ouro para o incenso diante da arca da aliança e pendure a cortina na entrada do tabernáculo."),  (1181, 2, 40, 6, "Coloque o altar dos holocaustos em frente da entrada do tabernáculo, da Tenda do Encontro;"),  (1182, 2, 40, 7, "ponha a bacia entre a Tenda do Encontro e o altar, e encha-a de água."),  (1183, 2, 40, 8, "Arme ao seu redor o pátio e coloque a cortina na entrada do pátio."),  (1184, 2, 40, 9, "Unja com o óleo da unção o tabernáculo e tudo o que nele há; consagre-o juntamente com tudo o que lhe pertence, e ele será sagrado."),  (1185, 2, 40, 10, "Depois unja o altar dos holocaustos e todos os seus utensílios; consagre o altar, e ele será santíssimo."),  (1186, 2, 40, 11, "Unja também a bacia com a sua base e consagre-a."),  (1187, 2, 40, 12, "Traga Arão e seus filhos à entrada da Tenda do Encontro e mande-os se lavar."),  (1188, 2, 40, 13, "Vista depois Arão com as vestes sagradas, unja-o e consagre-o para que me sirva como sacerdote."),  (1189, 2, 40, 14, "Traga os filhos dele e vista-os com túnicas."),  (1190, 2, 40, 15, "Unja-os como você ungiu o pai deles, para que me sirvam como sacerdotes. A unção deles será para um sacerdócio perpétuo, geração após geração."),  (1191, 2, 40, 16, "Moisés fez tudo conforme o Senhor lhe havia ordenado."),  (1192, 2, 40, 17, "Assim, o tabernáculo foi armado no primeiro dia do primeiro mês do segundo ano."),  (1193, 2, 40, 18, "Moisés armou o tabernáculo, colocou as bases em seus lugares, armou as molduras, colocou as vigas e levantou as colunas."),  (1194, 2, 40, 19, "Depois estendeu a tenda sobre o tabernáculo e colocou a cobertura sobre ela, como o Senhor tinha ordenado."),  (1195, 2, 40, 20, "Colocou também as tábuas da aliança na arca, fixou nela as varas, e pôs sobre ela a tampa."),  (1196, 2, 40, 21, "Em seguida trouxe a arca para dentro do tabernáculo e pendurou o véu protetor, cobrindo a arca da aliança, como o Senhor tinha ordenado."),  (1197, 2, 40, 22, "Moisés colocou a mesa na Tenda do Encontro, no lado norte do tabernáculo, do lado de fora do véu,"),  (1198, 2, 40, 23, "e sobre ela colocou os pães da Presença, diante do Senhor, como o Senhor tinha ordenado."),  (1199, 2, 40, 24, "Pôs o candelabro na Tenda do Encontro, em frente da mesa, no lado sul do tabernáculo,"),  (1200, 2, 40, 25, "e colocou as lâmpadas diante do Senhor, como o Senhor tinha ordenado."),  (1201, 2, 40, 26, "Moisés também pôs o altar de ouro na Tenda do Encontro, diante do véu,"),  (1202, 2, 40, 27, "e nele queimou incenso aromático, como o Senhor tinha ordenado."),  (1203, 2, 40, 28, "Pôs também a cortina à entrada do tabernáculo."),  (1204, 2, 40, 29, "Montou o altar de holocaustos à entrada do tabernáculo, a Tenda do Encontro, e sobre ele ofereceu holocaustos e ofertas de cereal, como o Senhor tinha ordenado."),  (1205, 2, 40, 30, "Colocou a bacia entre a Tenda do Encontro e o altar, e encheu-a de água;"),  (1206, 2, 40, 31, "Moisés, Arão e os filhos deste usavam-na para lavar as mãos e os pés."),  (1207, 2, 40, 32, "Sempre que entravam na Tenda do Encontro e se aproximavam do altar, eles se lavavam, como o Senhor tinha ordenado a Moisés."),  (1208, 2, 40, 33, "Finalmente, Moisés armou o pátio ao redor do tabernáculo e colocou a cortina à entrada do pátio. Assim, Moisés terminou a obra."),  (1209, 2, 40, 34, "Então a nuvem cobriu a Tenda do Encontro, e a glória do Senhor encheu o tabernáculo."),  (1210, 2, 40, 35, "Moisés não podia entrar na Tenda do Encontro, porque a nuvem estava sobre ela, e a glória do Senhor enchia o tabernáculo."),  (1211, 2, 40, 36, "Sempre que a nuvem se erguia sobre o tabernáculo os israelitas seguiam viagem;"),  (1212, 2, 40, 37, "mas se a nuvem não se erguia, eles não prosseguiam; só partiam no dia em que ela se erguesse."),  (1213, 2, 40, 38, "De dia a nuvem do Senhor ficava sobre o tabernáculo, e de noite havia fogo na nuvem, à vista de toda a nação de Israel, em todas as suas viagens."),  (1214, 3, 1, 1, "Da Tenda do Encontro o Senhor chamou Moisés e lhe ordenou:"),  (1215, 3, 1, 2, "Diga o seguinte aos israelitas: Quando alguém trouxer um animal como oferta ao Senhor, que seja do gado ou do rebanho de ovelhas."),  (1216, 3, 1, 3, "Se o holocausto for de gado, oferecerá um macho sem defeito. Ele o apresentará à entrada da Tenda do Encontro para que seja aceito pelo Senhor,"),  (1217, 3, 1, 4, "e porá a mão sobre a cabeça do animal do holocausto para que seja aceito como propiciação em seu lugar."),  (1218, 3, 1, 5, "Então o novilho será morto perante o Senhor, e os sacerdotes, descendentes de Arão, trarão o sangue e o derramarão nos lados do altar, que está na entrada da Tenda do Encontro."),  (1219, 3, 1, 6, "Depois se tirará a pele do animal, que será cortado em pedaços."),  (1220, 3, 1, 7, "Então os descendentes do sacerdote Arão acenderão o fogo do altar e arrumarão a lenha sobre o fogo."),  (1221, 3, 1, 8, "Em seguida arrumarão os pedaços, inclusive a cabeça e a gordura, sobre a lenha que está no fogo do altar."),  (1222, 3, 1, 9, "As vísceras e as pernas serão lavadas com água. E o sacerdote queimará tudo isso no altar. É um holocausto, oferta preparada no fogo, de aroma agradável ao Senhor."),  (1223, 3, 1, 10, "Se a oferta for um holocausto do rebanho, quer de cordeiros quer de cabritos, oferecerá um macho sem defeito."),  (1224, 3, 1, 11, "O animal será morto no lado norte do altar, perante o Senhor; os sacerdotes, descendentes de Arão, derramarão o sangue nos lados do altar."),  (1225, 3, 1, 12, "Então o animal será cortado em pedaços. O sacerdote arrumará os pedaços, inclusive a cabeça e a gordura, sobre a lenha que está no fogo do altar."),  (1226, 3, 1, 13, "As vísceras e as pernas serão lavadas com água. O sacerdote trará tudo isso como oferta e o queimará no altar. É um holocausto, oferta preparada no fogo, de aroma agradável ao Senhor."),  (1227, 3, 1, 14, "Se a sua oferta ao Senhor for um holocausto de aves, traga uma rolinha ou um pombinho."),  (1228, 3, 1, 15, "O sacerdote trará a ave ao altar, destroncará o pescoço dela e a queimará, e deixará escorrer o sangue da ave na parede do altar."),  (1229, 3, 1, 16, "Ele retirará o papo com o seu conteúdo e o jogará ao lado leste do altar, onde ficam as cinzas."),  (1230, 3, 1, 17, "Rasgará a ave pelas asas, sem dividi-la totalmente, e então o sacerdote a queimará sobre a lenha acesa no altar. É um holocausto, oferta preparada no fogo, de aroma agradável ao Senhor."),  (1231, 3, 2, 1, "Quando alguém trouxer uma oferta de cereal ao Senhor, terá que ser da melhor farinha. Sobre ela derramará óleo, colocará incenso"),  (1232, 3, 2, 2, "e a levará aos descendentes de Arão, os sacerdotes. Um deles apanhará um punhado da melhor farinha com óleo, juntamente com todo o incenso, e o queimará no altar como porção memorial. É oferta preparada no fogo, de aroma agradável ao Senhor."),  (1233, 3, 2, 3, "O que restar da oferta de cereal pertence a Arão e a seus descendentes; é parte santíssima das ofertas dedicadas ao Senhor preparadas no fogo."),  (1234, 3, 2, 4, "Se um de vocês trouxer uma oferta de cereal assada no forno, seja da melhor farinha: bolos feitos sem fermento, amassados com óleo, ou pães finos sem fermento e untados com óleo."),  (1235, 3, 2, 5, "Se a sua oferta de cereal for preparada numa assadeira, seja da melhor farinha, amassada com óleo e sem fermento."),  (1236, 3, 2, 6, "Divida-as em pedaços e derrame óleo sobre ela; é uma oferta de cereal."),  (1237, 3, 2, 7, "Se a sua oferta de cereal for cozida numa panela, seja da melhor farinha com óleo."),  (1238, 3, 2, 8, "Traga ao Senhor a oferta de cereal feita desses ingredientes, apresente-a ao sacerdote, que a levará ao altar."),  (1239, 3, 2, 9, "Ele apanhará a porção memorial da oferta de cereal e a queimará no altar; é oferta preparada no fogo, de aroma agradável ao Senhor."),  (1240, 3, 2, 10, "O restante da oferta de cereal pertence a Arão e a seus descendentes; é parte santíssima das ofertas dedicadas ao Senhor preparadas no fogo."),  (1241, 3, 2, 11, "Nenhuma oferta de cereal que vocês trouxerem ao Senhor será feita com fermento, pois vocês não queimarão fermento nem mel como oferta preparada no fogo ao Senhor."),  (1242, 3, 2, 12, "Podem trazê-los como oferta dos primeiros frutos ao Senhor, mas não poderão oferecê-los no altar como aroma agradável."),  (1243, 3, 2, 13, "Tempere com sal todas as suas ofertas de cereal. Não exclua de suas ofertas de cereal o sal da aliança do seu Deus; acrescente sal a todas as suas ofertas."),  (1244, 3, 2, 14, "Se você trouxer ao Senhor uma oferta de cereal dos primeiros frutos, ofereça grãos esmagados de cereal novo, tostados no fogo."),  (1245, 3, 2, 15, "Sobre ela derrame óleo e coloque incenso; é oferta de cereal."),  (1246, 3, 2, 16, "O sacerdote queimará a porção memorial do cereal esmagado e do óleo, juntamente com todo o incenso, como uma oferta ao Senhor, preparada no fogo. "),  (1247, 3, 3, 1, "Quando a oferta de alguém for sacrifício de comunhão, assim se fará: se oferecer um animal do gado, seja macho ou fêmea, apresentará ao Senhor um animal sem defeito."),  (1248, 3, 3, 2, "Porá a mão sobre a cabeça do animal, que será morto na entrada da Tenda do Encontro. Os descendentes de Arão, os sacerdotes, derramarão o sangue nos lados do altar."),  (1249, 3, 3, 3, "Desse sacrifício de comunhão, oferta preparada no fogo, ele trará ao Senhor toda a gordura que cobre as vísceras e está ligada a elas,"),  (1250, 3, 3, 4, "os dois rins com a gordura que os cobre e que está perto dos lombos, e o lóbulo do fígado, que ele removerá junto com os rins."),  (1251, 3, 3, 5, "Os descendentes de Arão queimarão tudo isso em cima do holocausto que está sobre a lenha acesa no altar como oferta preparada no fogo, de aroma agradável ao Senhor."),  (1252, 3, 3, 6, "Se oferecer um animal do rebanho como sacrifício de comunhão ao Senhor, traga um macho ou fêmea sem defeito."),  (1253, 3, 3, 7, "Se oferecer um cordeiro, apresente-o ao Senhor."),  (1254, 3, 3, 8, "Porá a mão sobre a cabeça do animal, que será morto diante da Tenda do Encontro. Então os descendentes de Arão derramarão o sangue nos lados do altar."),  (1255, 3, 3, 9, "Desse sacrifício de comunhão, oferta preparada no fogo, ele trará ao Senhor a gordura, tanto a da cauda gorda cortada rente à espinha, como toda a gordura que cobre as vísceras e está ligada a elas,"),  (1256, 3, 3, 10, "os dois rins com a gordura que os cobre e que está perto dos lombos, e o lóbulo do fígado, que ele removerá junto com os rins."),  (1257, 3, 3, 11, "O sacerdote os queimará no altar como alimento oferecido ao Senhor, preparado no fogo."),  (1258, 3, 3, 12, "Se a sua oferta for um cabrito, ele o apresentará ao Senhor."),  (1259, 3, 3, 13, "Porá a mão sobre a cabeça do animal, que será morto diante da Tenda do Encontro. Então os descendentes de Arão derramarão o sangue nos lados do altar."),  (1260, 3, 3, 14, "Desse animal, que é uma oferta preparada no fogo, trará ao Senhor a gordura que cobre as vísceras e está ligada a elas,"),  (1261, 3, 3, 15, "os dois rins com a gordura que os cobre e que está perto dos lombos, e o lóbulo do fígado, que ele removerá junto com os rins."),  (1262, 3, 3, 16, "O sacerdote os queimará no altar como alimento, como oferta feita com fogo, de aroma agradável. Toda a gordura será do Senhor."),  (1263, 3, 3, 17, "Este é um decreto perpétuo para as suas gerações, onde quer que vivam: Não comam gordura alguma, nem sangue algum."),  (1264, 3, 4, 1, "O Senhor ordenou a Moisés:"),  (1265, 3, 4, 2, "Diga aos israelitas: Quando alguém pecar sem intenção, fazendo o que é proibido em qualquer dos mandamentos do Senhor, assim se fará:"),  (1266, 3, 4, 3, "Se for o sacerdote ungido que pecar, trazendo culpa sobre o povo, trará ao Senhor um novilho sem defeito como oferta pelo pecado que cometeu."),  (1267, 3, 4, 4, "Apresentará ao Senhor o novilho na entrada da Tenda do Encontro. Porá a mão sobre a cabeça do novilho que será morto perante o Senhor."),  (1268, 3, 4, 5, "Então o sacerdote ungido pegará um pouco do sangue do novilho e o levará à Tenda do Encontro;"),  (1269, 3, 4, 6, "molhará o dedo no sangue e o aspergirá sete vezes perante o Senhor, diante do véu do santuário."),  (1270, 3, 4, 7, "O sacerdote porá um pouco do sangue nas pontas do altar do incenso aromático que está perante o Senhor na Tenda do Encontro. Derramará todo o restante do sangue do novilho na base do altar do holocausto, na entrada da Tenda do Encontro."),  (1271, 3, 4, 8, "Então retirará toda a gordura do novilho da oferta pelo pecado: a gordura que cobre as vísceras e está ligada a elas,"),  (1272, 3, 4, 9, "os dois rins com a gordura que os cobre e que está perto dos lombos, e o lóbulo do fígado, que ele removerá junto com os rins,"),  (1273, 3, 4, 10, "como se retira a gordura do boi sacrificado como oferta de comunhão. Então o sacerdote os queimará no altar dos holocaustos."),  (1274, 3, 4, 11, "Mas o couro do novilho e toda a sua carne, bem como a cabeça e as pernas, as vísceras e os excrementos,"),  (1275, 3, 4, 12, "isto é, tudo o que restar do novilho, ele os levará para fora do acampamento, a um local cerimonialmente puro, onde se lançam as cinzas. Ali os queimará sobre a lenha de uma fogueira, sobre o monte de cinzas."),  (1276, 3, 4, 13, "Se for toda a comunidade de Israel que pecar sem intenção, fazendo o que é proibido em qualquer dos mandamentos do Senhor, ainda que não tenha consciência disso, a comunidade será culpada."),  (1277, 3, 4, 14, "Quando tiver consciência do pecado que cometeu, a comunidade trará um novilho como oferta pelo pecado e o apresentará diante da Tenda do Encontro."),  (1278, 3, 4, 15, "As autoridades da comunidade porão as mãos sobre a cabeça do novilho perante o Senhor. E o novilho será morto perante o Senhor."),  (1279, 3, 4, 16, "Então o sacerdote ungido levará um pouco do sangue do novilho para a Tenda do Encontro;"),  (1280, 3, 4, 17, "molhará o dedo no sangue e o aspergirá sete vezes perante o Senhor, diante do véu."),  (1281, 3, 4, 18, "Porá o sangue nas pontas do altar que está perante o Senhor na Tenda do Encontro e derramará todo o restante do sangue na base do altar dos holocaustos, na entrada da Tenda do Encontro."),  (1282, 3, 4, 19, "Então retirará toda a gordura do animal e a queimará no altar,"),  (1283, 3, 4, 20, "e fará com este novilho como fez com o novilho da oferta pelo pecado. Assim o sacerdote fará propiciação por eles, e eles serão perdoados."),  (1284, 3, 4, 21, "Depois levará o novilho para fora do acampamento e o queimará como queimou o primeiro. É oferta pelo pecado da comunidade."),  (1285, 3, 4, 22, "Quando for um líder que pecar sem intenção, fazendo o que é proibido em qualquer dos mandamentos do Senhor seu Deus, será culpado."),  (1286, 3, 4, 23, "Quando o conscientizarem do seu pecado, trará como oferta um bode sem defeito."),  (1287, 3, 4, 24, "Porá a mão sobre a cabeça do bode, que será morto no local onde o holocausto é sacrificado, perante o Senhor. Esta é a oferta pelo pecado."),  (1288, 3, 4, 25, "Então o sacerdote pegará com o dedo um pouco do sangue da oferta pelo pecado, o porá nas pontas do altar dos holocaustos e derramará o restante do sangue na base do altar do holocausto."),  (1289, 3, 4, 26, "Queimará toda a gordura no altar, como queimou a gordura do sacrifício de comunhão. Assim o sacerdote fará propiciação pelo pecado do líder, e ele será perdoado."),  (1290, 3, 4, 27, "Se for alguém da comunidade que pecar sem intenção, fazendo o que é proibido em qualquer dos mandamentos do Senhor seu Deus, será culpado."),  (1291, 3, 4, 28, "Quando o conscientizarem do seu pecado, trará como oferta pelo pecado que cometeu uma cabra sem defeito."),  (1292, 3, 4, 29, "Porá a mão sobre a cabeça do animal da oferta pelo pecado, que será morto no lugar dos holocaustos."),  (1293, 3, 4, 30, "Então o sacerdote pegará com o dedo um pouco do sangue, o porá nas pontas do altar dos holocaustos e derramará o restante do sangue na base do altar."),  (1294, 3, 4, 31, "Então retirará toda a gordura, como se retira a gordura do sacrifício de comunhão; o sacerdote a queimará no altar como aroma agradável ao Senhor. Assim o sacerdote fará propiciação por esse homem, e ele será perdoado."),  (1295, 3, 4, 32, "Se trouxer uma ovelha como oferta pelo pecado, terá que ser sem defeito."),  (1296, 3, 4, 33, "Porá a mão sobre a cabeça do animal, que será morto como oferta pelo pecado no lugar onde é sacrificado o holocausto."),  (1297, 3, 4, 34, "Então o sacerdote pegará com o dedo um pouco do sangue da oferta pelo pecado e o porá nas pontas do altar dos holocaustos, e derramará o restante do sangue na base do altar."),  (1298, 3, 4, 35, "Retirará toda a gordura, como se retira a gordura do cordeiro do sacrifício de comunhão; o sacerdote a queimará no altar, em cima das ofertas dedicadas ao Senhor, preparadas no fogo. Assim o sacerdote fará em favor dele propiciação pelo pecado que cometeu, e ele será perdoado."),  (1299, 3, 5, 1, "Se alguém pecar porque, tendo sido testemunha de algo que viu ou soube, não o declarou, sofrerá as conseqüências da sua iniqüidade."),  (1300, 3, 5, 2, "Se alguém tocar qualquer coisa impura, seja um cadáver de animal selvagem ou de animal do rebanho ou de uma das pequenas criaturas que povoam a terra, ainda que não tenha consciência disso, ele se tornará impuro e será culpado."),  (1301, 3, 5, 3, "Se alguém tocar impureza humana, qualquer coisa que o torne impuro, sem ter consciência disso, quando o souber será culpado."),  (1302, 3, 5, 4, "Se alguém impensadamente jurar fazer algo bom ou mau, em qualquer assunto que alguém possa jurar descuidadamente, ainda que não tenha consciência disso, quando o souber será culpado."),  (1303, 3, 5, 5, "Quando alguém for culpado de qualquer dessas coisas, confessará em que pecou"),  (1304, 3, 5, 6, "e, pelo pecado que cometeu, trará ao Senhor uma ovelha ou uma cabra do rebanho como oferta de reparação; e em favor dele o sacerdote fará propiciação pelo pecado."),  (1305, 3, 5, 7, "Se não tiver recursos para oferecer uma ovelha, trará pela culpa do seu pecado duas rolinhas ou dois pombinhos ao Senhor: um como oferta pelo pecado e o outro como holocausto."),  (1306, 3, 5, 8, "Ele os trará ao sacerdote, que oferecerá primeiro o que for oferecido como sacrifício pelo pecado. E destroncará o pescoço da ave, sem arrancar-lhe a cabeça totalmente,"),  (1307, 3, 5, 9, "e aspergirá no lado do altar o sangue da oferta pelo pecado e deixará escorrer o restante do sangue na base do altar. É oferta pelo pecado."),  (1308, 3, 5, 10, "O sacerdote então oferecerá a outra ave como holocausto, de acordo com a forma prescrita, e fará propiciação em favor dele pelo pecado que cometeu, e ele será perdoado."),  (1309, 3, 5, 11, "Se, contudo, não tiver recursos para oferecer duas rolinhas ou dois pombinhos, trará como oferta pelo pecado um jarro da melhor farinha como oferta pelo pecado. Mas sobre ela não derramará óleo nem colocará incenso, porquanto é oferta pelo pecado."),  (1310, 3, 5, 12, "Ele a trará ao sacerdote, que apanhará um punhado dela como porção memorial e queimará essa porção no altar, em cima das ofertas dedicadas ao Senhor, preparadas no fogo. É oferta pelo pecado."),  (1311, 3, 5, 13, "Assim o sacerdote fará propiciação em favor dele por qualquer desses pecados que tiver cometido, e ele será perdoado. O restante da oferta pertence ao sacerdote, como no caso da oferta de cereal."),  (1312, 3, 5, 14, "O Senhor disse a Moisés:"),  (1313, 3, 5, 15, "Quando alguém cometer uma ofensa, pecando sem intenção em qualquer coisa consagrada ao Senhor, trará ao Senhor um carneiro do rebanho, sem defeito, avaliado em prata com base no peso padrão do santuário, como oferta pela culpa."),  (1314, 3, 5, 16, "Fará restituição pelo que deixou de fazer em relação às coisas consagradas, acrescentará um quinto do valor e o entregará ao sacerdote. Este fará propiciação por ele com o carneiro da oferta pela culpa, e ele será perdoado."),  (1315, 3, 5, 17, "Se alguém pecar, fazendo o que é proibido em qualquer dos mandamentos do Senhor, ainda que não o saiba, será culpado e sofrerá as conseqüências da sua iniqüidade."),  (1316, 3, 5, 18, "Do rebanho ele trará ao sacerdote um carneiro, sem defeito e devidamente avaliado, como oferta pela culpa. Assim o sacerdote fará propiciação em favor dele pelo erro que cometeu sem intenção, e ele será perdoado."),  (1317, 3, 5, 19, "É oferta pela culpa, pois com certeza tornou-se culpado perante o Senhor."),  (1318, 3, 6, 1, "E disse o Senhor a Moisés:"),  (1319, 3, 6, 2, "Se alguém pecar, cometendo uma ofensa contra o Senhor, enganando o seu próximo no que diz respeito a algo que lhe foi confiado ou deixado como penhor ou roubado, ou se lhe extorquir algo,"),  (1320, 3, 6, 3, "ou se achar algum bem perdido e mentir a respeito disso, ou se jurar falsamente a respeito de qualquer coisa, cometendo pecado;"),  (1321, 3, 6, 4, "quando assim pecar, tornando-se por isso culpado, terá que devolver o que roubou ou tomou mediante extorsão, ou o que lhe foi confiado, ou os bens perdidos que achou,"),  (1322, 3, 6, 5, "ou qualquer coisa sobre a qual tenha jurado falsamente. Fará restituição plena, acrescentará a isso um quinto do valor e dará tudo ao proprietário no dia em que apresentar a sua oferta pela culpa."),  (1323, 3, 6, 6, "E por sua culpa trará ao sacerdote uma oferta dedicada ao Senhor: um carneiro do rebanho, sem defeito e devidamente avaliado."),  (1324, 3, 6, 7, "Dessa forma o sacerdote fará propiciação por ele perante o Senhor, e ele será perdoado de qualquer dessas coisas que fez e que o tornou culpado."),  (1325, 3, 6, 8, "O Senhor disse a Moisés:"),  (1326, 3, 6, 9, "Dê este mandamento a Arão e a seus filhos: Esta é a regulamentação acerca do holocausto: ele terá que ficar queimando até de manhã sobre as brasas do altar, onde o fogo terá que ser mantido aceso."),  (1327, 3, 6, 10, "O sacerdote vestirá suas roupas de linho e os calções de linho por baixo, retirará as cinzas do holocausto que o fogo consumiu no altar e as colocará ao lado do altar."),  (1328, 3, 6, 11, "Depois trocará de roupa, e levará as cinzas para fora do acampamento, a um lugar cerimonialmente puro."),  (1329, 3, 6, 12, "Mantenha-se aceso o fogo no altar; não deve ser apagado. Toda manhã o sacerdote acrescentará lenha, arrumará o holocausto sobre o fogo e queimará sobre ele a gordura das ofertas de comunhão."),  (1330, 3, 6, 13, "Mantenha-se o fogo continuamente aceso no altar; não deve ser apagado."),  (1331, 3, 6, 14, "Esta é a regulamentação da oferta de cereal: os filhos de Arão a apresentarão ao Senhor, em frente do altar."),  (1332, 3, 6, 15, "O sacerdote apanhará um punhado da melhor farinha com óleo, juntamente com todo o incenso que está sobre a oferta de cereal, e queimará no altar a porção memorial como aroma agradável ao Senhor."),  (1333, 3, 6, 16, "Arão e seus filhos comerão o restante da oferta, mas deverão comê-lo sem fermento e em lugar sagrado, no pátio da Tenda do Encontro."),  (1334, 3, 6, 17, "Essa oferta não será assada com fermento; eu a dei a eles como porção das ofertas feitas a mim com fogo. É santíssima, como a oferta pelo pecado e como a oferta pela culpa."),  (1335, 3, 6, 18, "Somente os homens descendentes de Arão poderão comer da porção das ofertas dedicadas ao Senhor, preparadas no fogo. É um decreto perpétuo para as suas gerações. Tudo o que nelas tocar se tornará santo."),  (1336, 3, 6, 19, "O Senhor disse também a Moisés:"),  (1337, 3, 6, 20, "Esta é a oferta que Arão e os seus descendentes terão que trazer ao Senhor no dia em que ele for ungido: um jarro da melhor farinha, como na oferta regular de cereal, metade pela manhã e metade à tarde."),  (1338, 3, 6, 21, "Prepare-a com óleo numa assadeira; traga-a bem misturada e apresente a oferta de cereal partida em pedaços, como aroma agradável ao Senhor."),  (1339, 3, 6, 22, "Todo sacerdote ungido, descendentes de Arão, também preparará essa oferta. É a porção do Senhor por decreto perpétuo e será totalmente queimada."),  (1340, 3, 6, 23, "Toda oferta de cereal do sacerdote será totalmente queimada; não será comida."),  (1341, 3, 6, 24, "O Senhor disse a Moisés:"),  (1342, 3, 6, 25, "Diga a Arão e aos seus filhos: Esta é a regulamentação da oferta pelo pecado: O animal da oferta pelo pecado será morto perante o Senhor no local onde é sacrificado o holocausto; é uma oferta santíssima."),  (1343, 3, 6, 26, "O sacerdote que oferecer o animal, o comerá em lugar sagrado, no pátio da Tenda do Encontro."),  (1344, 3, 6, 27, "Tudo o que tocar na carne se tornará santo, e se o sangue respingar na roupa, será lavada em lugar sagrado."),  (1345, 3, 6, 28, "A vasilha de barro em que a carne for cozida deverá ser quebrada; mas, se for cozida numa vasilha de bronze, a vasilha deverá ser esfregada e enxaguada com água."),  (1346, 3, 6, 29, "Somente os homens da família dos sacerdotes poderão comê-la; é uma oferta santíssima."),  (1347, 3, 6, 30, "Mas toda oferta pelo pecado, cujo sangue for trazido para a Tenda do Encontro para propiciação no Lugar Santo, não será comida; terá que ser queimada."),  (1348, 3, 7, 1, "Esta é a regulamentação da oferta pela culpa, que é oferta santíssima:"),  (1349, 3, 7, 2, "O animal da oferta pela culpa será morto no local onde são sacrificados os holocaustos, e seu sangue será derramado nos lados do altar."),  (1350, 3, 7, 3, "Toda a sua gordura será oferecida: a parte gorda da cauda e a gordura que cobre as vísceras,"),  (1351, 3, 7, 4, "os dois rins com a gordura que os cobre e que está perto dos lombos, e o lóbulo do fígado, que será removido juntamente com os rins."),  (1352, 3, 7, 5, "O sacerdote os queimará no altar como oferta dedicada ao Senhor, preparada no fogo. É oferta pela culpa."),  (1353, 3, 7, 6, "Somente os homens da família dos sacerdotes poderão comê-la, mas deve ser comida em lugar sagrado; é oferta santíssima."),  (1354, 3, 7, 7, "A mesma regulamentação aplica-se tanto à oferta pelo pecado quanto à oferta pela culpa: a carne pertence ao sacerdote que faz propiciação pela culpa."),  (1355, 3, 7, 8, "O sacerdote que oferecer um holocausto por alguém ficará com o couro do animal."),  (1356, 3, 7, 9, "Toda oferta de cereal, assada num forno ou cozida numa panela ou numa assadeira, pertence ao sacerdote que a oferecer,"),  (1357, 3, 7, 10, "e toda oferta de cereal, amassada com óleo ou não, pertence igualmente aos descendentes de Arão."),  (1358, 3, 7, 11, "Esta é a regulamentação da oferta de comunhão que pode ser apresentada ao Senhor:"),  (1359, 3, 7, 12, "Se alguém a fizer por gratidão, então, junto com sua oferta de gratidão, terá que oferecer bolos sem fermento e amassados com óleo, pães finos sem fermento e untados com óleo, e bolos da melhor farinha bem amassados e misturados com óleo."),  (1360, 3, 7, 13, "Juntamente com sua oferta de comunhão por gratidão, apresentará uma oferta que inclua bolos com fermento."),  (1361, 3, 7, 14, "De cada oferta trará uma contribuição ao Senhor que será dada ao sacerdote que asperge o sangue das ofertas de comunhão."),  (1362, 3, 7, 15, "A carne da sua oferta de comunhão por gratidão será comida no dia em que for oferecida; nada poderá sobrar até o amanhecer."),  (1363, 3, 7, 16, "Se, contudo, sua oferta for resultado de um voto ou for uma oferta voluntária, a carne do sacrifício será comida no dia em que for oferecida, e o que sobrar poderá ser comido no dia seguinte."),  (1364, 3, 7, 17, "Mas a carne que sobrar do sacrifício até o terceiro dia será queimada no fogo."),  (1365, 3, 7, 18, "Se a carne da oferta de comunhão for comida ao terceiro dia, ela não será aceita. A oferta não será atribuída àquele que a ofereceu, pois a carne estará estragada; e quem dela comer sofrerá as conseqüências da sua iniqüidade."),  (1366, 3, 7, 19, "A carne que tocar em qualquer coisa impura não será comida; será queimada no fogo. A carne do sacrifício, porém, poderá ser comida por quem estiver puro."),  (1367, 3, 7, 20, "Mas se alguém que está impuro comer da carne da oferta de comunhão que pertence ao Senhor, será eliminado do meio do seu povo."),  (1368, 3, 7, 21, "Se alguém tocar em alguma coisa impura, seja impureza humana, seja de animal, seja qualquer outra coisa impura e proibida, e comer da carne da oferta de comunhão que pertence ao Senhor, será eliminado do meio do seu povo. "),  (1369, 3, 7, 22, "E disse o Senhor a Moisés:"),  (1370, 3, 7, 23, "Diga aos israelitas: Não comam gordura alguma de boi, carneiro ou cabrito."),  (1371, 3, 7, 24, "A gordura de um animal encontrado morto ou despedaçado por animais selvagens pode ser usada para qualquer outra finalidade, mas nunca poderá ser comida."),  (1372, 3, 7, 25, "Quem comer a gordura de um animal, dedicado ao Senhor numa oferta preparada no fogo, será eliminado do meio do seu povo."),  (1373, 3, 7, 26, "Onde quer que vocês vivam, não comam o sangue de nenhuma ave nem de animal."),  (1374, 3, 7, 27, "Quem comer sangue será eliminado do meio do seu povo."),  (1375, 3, 7, 28, "Disse mais o Senhor a Moisés:"),  (1376, 3, 7, 29, "Diga aos israelitas: Todo aquele que trouxer sacrifício de comunhão ao Senhor terá que dedicar parte dele ao Senhor."),  (1377, 3, 7, 30, "Com suas próprias mãos trará ao Senhor as ofertas preparadas no fogo; trará a gordura juntamente com o peito, e o moverá perante o Senhor como gesto ritual de apresentação."),  (1378, 3, 7, 31, "O sacerdote queimará a gordura no altar, mas o peito pertence a Arão e a seus descendentes."),  (1379, 3, 7, 32, "Vocês deverão dar a coxa direita das ofertas de comunhão ao sacerdote como contribuição."),  (1380, 3, 7, 33, "O descendente de Arão que oferecer o sangue e a gordura da oferta de comunhão receberá a coxa direita como porção."),  (1381, 3, 7, 34, "Das ofertas de comunhão dos israelitas, tomei o peito que é movido ritualmente e a coxa que é ofertada, e os dei ao sacerdote Arão e a seus descendentes por decreto perpétuo para os israelitas."),  (1382, 3, 7, 35, "Essa é a parte das ofertas dedicadas ao Senhor, preparadas no fogo, designada a Arão e a seus filhos no dia em que foram apresentados para servirem ao Senhor como sacerdotes."),  (1383, 3, 7, 36, "Foi isso que o Senhor ordenou dar a eles, no dia em que foram ungidos dentre os israelitas. É um decreto perpétuo para as suas gerações."),  (1384, 3, 7, 37, "Essa é a regulamentação acerca do holocausto, da oferta de cereal, da oferta pelo pecado, da oferta pela culpa, da oferta de ordenação e da oferta de comunhão."),  (1385, 3, 7, 38, "O Senhor entregou-a a Moisés no monte Sinai, no dia em que ordenou aos israelitas que trouxessem suas ofertas ao Senhor, no deserto do Sinai."),  (1386, 3, 8, 1, "O Senhor disse a Moisés:"),  (1387, 3, 8, 2, "Traga Arão e seus filhos, suas vestes, o óleo da unção, o novilho para a oferta pelo pecado, os dois carneiros e o cesto de pães sem fermento;"),  (1388, 3, 8, 3, "e reúna toda a comunidade à entrada da Tenda do Encontro."),  (1389, 3, 8, 4, "Moisés fez como o Senhor lhe ordenou, e a comunidade reuniu-se à entrada da Tenda do Encontro."),  (1390, 3, 8, 5, "Então Moisés disse à comunidade: Foi isto que o Senhor mandou fazer;"),  (1391, 3, 8, 6, "e levou Arão e seus filhos à frente e mandou-os banhar-se com água;"),  (1392, 3, 8, 7, "pôs a túnica em Arão, colocou-lhe o cinto e o manto, e pôs sobre ele o colete sacerdotal; depois a ele prendeu o manto sacerdotal com o cinturão;"),  (1393, 3, 8, 8, "colocou também o peitoral, e nele pôs o Urim e o Tumim;"),  (1394, 3, 8, 9, "e colocou o turbante na cabeça de Arão com a lâmina de ouro, isto é, a coroa sagrada, na frente do turbante, conforme o Senhor tinha ordenado a Moisés."),  (1395, 3, 8, 10, "Depois Moisés pegou o óleo da unção e ungiu o tabernáculo e tudo o que nele havia, e assim os consagrou."),  (1396, 3, 8, 11, "Aspergiu sete vezes o óleo sobre o altar, ungindo o altar e todos os seus utensílios e a bacia com o seu suporte, para consagrá-los."),  (1397, 3, 8, 12, "Derramou o óleo da unção sobre a cabeça de Arão para ungi-lo e consagrá-lo."),  (1398, 3, 8, 13, "Trouxe então os filhos de Arão à frente, vestiu-os com suas túnicas e cintos, e colocou-lhes gorros, conforme o Senhor lhe havia ordenado."),  (1399, 3, 8, 14, "Em seguida trouxe o novilho para a oferta pelo pecado, e Arão e seus filhos puseram-lhe as mãos sobre a cabeça."),  (1400, 3, 8, 15, "Moisés sacrificou o novilho, e com o dedo pôs um pouco do sangue em todas as pontas do altar para purificá-lo. Derramou o restante do sangue na base do altar e assim o consagrou para fazer propiciação por ele."),  (1401, 3, 8, 16, "Moisés pegou também toda a gordura que cobre as vísceras, o lóbulo do fígado e os dois rins com a gordura que os cobre, e os queimou no altar."),  (1402, 3, 8, 17, "Mas o novilho com o seu couro, a sua carne e o seu excremento, ele os queimou fora do acampamento, conforme o Senhor lhe havia ordenado."),  (1403, 3, 8, 18, "Mandou trazer então o carneiro para o holocausto, e Arão e seus filhos puseram as mãos sobre a cabeça do carneiro."),  (1404, 3, 8, 19, "A seguir Moisés sacrificou o carneiro e derramou o sangue nos lados do altar."),  (1405, 3, 8, 20, "Depois, cortou o carneiro em pedaços; queimou a cabeça, os pedaços e a gordura."),  (1406, 3, 8, 21, "Lavou as vísceras e as pernas, e queimou o carneiro inteiro sobre o altar, como holocausto, oferta de aroma agradável ao Senhor, preparado no fogo, conforme o Senhor lhe havia ordenado."),  (1407, 3, 8, 22, "Depois mandou trazer o outro carneiro, o carneiro para a oferta de ordenação, e Arão e seus filhos colocaram as mãos sobre a cabeça do carneiro."),  (1408, 3, 8, 23, "Moisés sacrificou o carneiro e pôs um pouco do sangue na ponta da orelha direita de Arão, no polegar da sua mão direita e no polegar do seu pé direito."),  (1409, 3, 8, 24, "Moisés também mandou que os filhos de Arão se aproximassem, e sobre cada um pôs um pouco do sangue na ponta da orelha direita, no polegar da mão direita e no polegar do pé direito; e derramou o restante do sangue nos lados do altar."),  (1410, 3, 8, 25, "Apanhou a gordura, a cauda gorda, toda a gordura que cobre as vísceras, o lóbulo do fígado, os dois rins e a gordura que os cobre e a coxa direita."),  (1411, 3, 8, 26, "Então, do cesto de pães sem fermento, que estava perante o Senhor, apanhou um pão comum, outro feito com óleo e um pão fino, colocando-os sobre as porções de gordura e sobre a coxa direita."),  (1412, 3, 8, 27, "Pôs tudo nas mãos de Arão e de seus filhos e os moveu perante o Senhor como gesto ritual de apresentação."),  (1413, 3, 8, 28, "Depois Moisés pegou de volta das mãos deles e queimou tudo no altar, em cima do holocausto, como uma oferta de ordenação, preparada no fogo, de aroma agradável ao Senhor."),  (1414, 3, 8, 29, "Moisés também pegou o peito e a sua própria porção do carneiro da ordenação, e o moveu perante o Senhor como gesto ritual de apresentação, como o Senhor lhe havia ordenado."),  (1415, 3, 8, 30, "Então pegou um pouco do óleo da unção e um pouco do sangue que estava no altar e os aspergiu sobre Arão e suas vestes, bem como sobre seus filhos e suas vestes. Assim consagrou Arão e suas vestes, e seus filhos e suas vestes."),  (1416, 3, 8, 31, "Moisés então disse a Arão e a seus filhos: Cozinhem a carne na entrada da Tenda do Encontro, onde a deverão comer com o pão do cesto das ofertas de ordenação, conforme me foi ordenado: ‘Arão e seus filhos deverão comê-la’."),  (1417, 3, 8, 32, "Depois queimem o restante da carne e do pão."),  (1418, 3, 8, 33, "Não saiam da entrada da Tenda do Encontro por sete dias, até que se completem os dias da ordenação de vocês, pois essa cerimônia de ordenação durará sete dias."),  (1419, 3, 8, 34, "O que se fez hoje foi ordenado pelo Senhor para fazer propiciação por vocês."),  (1420, 3, 8, 35, "Vocês terão que permanecer dia e noite à entrada da Tenda do Encontro por sete dias e obedecer às exigências do Senhor, para que não morram; pois isso me foi ordenado."),  (1421, 3, 8, 36, "Arão e seus filhos fizeram tudo o que o Senhor tinha ordenado por meio de Moisés."),  (1422, 3, 9, 1, "Oito dias depois Moisés convocou Arão e seus filhos e as autoridades de Israel."),  (1423, 3, 9, 2, "E disse a Arão: Traga um bezerro para a oferta pelo pecado e um carneiro para o holocausto, ambos sem defeito, e apresente-os ao Senhor."),  (1424, 3, 9, 3, "Depois diga aos israelitas: Tragam um bode para oferta pelo pecado, um bezerro e um cordeiro, ambos de um ano de idade e sem defeito, para holocausto;"),  (1425, 3, 9, 4, "e um boi e um carneiro para oferta de comunhão, para os sacrificar perante o Senhor, juntamente com a oferta de cereal amassada com óleo; pois hoje o Senhor aparecerá a vocês."),  (1426, 3, 9, 5, "Levaram então tudo o que Moisés determinou para a frente da Tenda do Encontro, e a comunidade inteira aproximou-se e ficou de pé perante o Senhor."),  (1427, 3, 9, 6, "Disse-lhes Moisés: Foi isso que o Senhor ordenou que façam, para que a glória do Senhor apareça a vocês."),  (1428, 3, 9, 7, "Disse Moisés a Arão: Venha até o altar e ofereça o seu sacrifício pelo pecado e o seu holocausto, e faça propiciação por você mesmo e pelo povo; ofereça o sacrifício pelo povo e faça propiciação por ele, conforme o Senhor ordenou."),  (1429, 3, 9, 8, "Arão foi até o altar e ofereceu o bezerro como sacrifício pelo pecado por si mesmo."),  (1430, 3, 9, 9, "Seus filhos levaram-lhe o sangue, e ele molhou o dedo no sangue e o pôs nas pontas do altar; então derramou o restante do sangue na base do altar,"),  (1431, 3, 9, 10, "onde queimou a gordura, os rins e o lóbulo do fígado da oferta pelo pecado, conforme o Senhor tinha ordenado a Moisés;"),  (1432, 3, 9, 11, "a carne e o couro, porém, queimou fora do acampamento."),  (1433, 3, 9, 12, "Depois sacrificou o holocausto. Seus filhos lhe entregaram o sangue, e ele o derramou nos lados do altar."),  (1434, 3, 9, 13, "Entregaram-lhe em seguida o holocausto pedaço por pedaço, inclusive a cabeça, e ele os queimou no altar."),  (1435, 3, 9, 14, "Lavou as vísceras e as pernas e as queimou em cima do holocausto sobre o altar."),  (1436, 3, 9, 15, "Depois Arão apresentou a oferta pelo povo. Pegou o bode para a oferta pelo pecado do povo e o ofereceu como sacrifício pelo pecado, como fizera com o primeiro."),  (1437, 3, 9, 16, "Apresentou o holocausto e ofereceu-o conforme fora prescrito."),  (1438, 3, 9, 17, "Também apresentou a oferta de cereal, pegou um punhado dela e a queimou no altar, além do holocausto da manhã."),  (1439, 3, 9, 18, "Matou o boi e o carneiro como sacrifício de comunhão pelo povo. Seus filhos levaram-lhe o sangue, e ele o derramou nos lados do altar."),  (1440, 3, 9, 19, "Mas as porções de gordura do boi e do carneiro, a cauda gorda, a gordura que cobre as vísceras, os rins e o lóbulo do fígado,"),  (1441, 3, 9, 20, "puseram em cima do peito; e Arão as queimou no altar."),  (1442, 3, 9, 21, "Em seguida, Arão moveu o peito e a coxa direita do animal perante o Senhor como gesto ritual de apresentação, conforme Moisés tinha ordenado."),  (1443, 3, 9, 22, "Depois Arão ergueu as mãos em direção ao povo e o abençoou. E, tendo oferecido o sacrifício pelo pecado, o holocausto e o sacrifício de comunhão, desceu."),  (1444, 3, 9, 23, "Assim Moisés e Arão entraram na Tenda do Encontro. Quando saíram, abençoaram o povo; e a glória do Senhor apareceu a todo o povo."),  (1445, 3, 9, 24, "Saiu fogo da presença do Senhor e consumiu o holocausto e as porções de gordura sobre o altar. E, quando todo o povo viu isso, gritou de alegria e prostrou-se rosto em terra."),  (1446, 3, 10, 1, "Nadabe e Abiú, filhos de Arão, pegaram cada um o seu incensário, nos quais acenderam fogo, acrescentaram incenso, e trouxeram fogo profano perante o Senhor, sem que tivessem sido autorizados."),  (1447, 3, 10, 2, "Então saiu fogo da presença do Senhor e os consumiu. Morreram perante o Senhor."),  (1448, 3, 10, 3, "Moisés então disse a Arão: Foi isto que o Senhor disse: ‘Aos que de mim se aproximam santo me mostrarei; à vista de todo o povo glorificado serei’ . Arão, porém, ficou em silêncio."),  (1449, 3, 10, 4, "Então Moisés chamou Misael e Elzafã, filhos de Uziel, tio de Arão, e lhes disse: Venham cá; tirem os seus primos da frente do santuário e levem-nos para fora do acampamento."),  (1450, 3, 10, 5, "Eles foram e os puxaram pelas túnicas, para fora do acampamento, conforme Moisés tinha ordenado."),  (1451, 3, 10, 6, "Então Moisés disse a Arão e a seus filhos Eleazar e Itamar: Não andem descabelados, nem rasguem as roupas em sinal de luto, senão vocês morrerão e a ira do Senhor cairá sobre toda a comunidade. Mas os seus parentes, e toda a nação de Israel, poderão chorar por aqueles que o Senhor destruiu pelo fogo."),  (1452, 3, 10, 7, "Não saiam da entrada da Tenda do Encontro, senão vocês morrerão, porquanto o óleo da unção do Senhor está sobre vocês. E eles fizeram conforme Moisés tinha ordenado."),  (1453, 3, 10, 8, "Depois o Senhor disse a Arão:"),  (1454, 3, 10, 9, "Você e seus filhos não devem beber vinho nem outra bebida fermentada antes de entrar na Tenda do Encontro, senão vocês morrerão. É um decreto perpétuo para as suas gerações."),  (1455, 3, 10, 10, "Vocês têm que fazer separação entre o santo e o profano, entre o puro e o impuro,"),  (1456, 3, 10, 11, "e ensinar aos israelitas todos os decretos que o Senhor lhes deu por meio de Moisés."),  (1457, 3, 10, 12, "Então Moisés disse a Arão e aos seus filhos que ficaram vivos, Eleazar e Itamar: Peguem a oferta de cereal que sobrou das ofertas dedicadas ao Senhor, preparadas no fogo, e comam-na sem fermento junto ao altar, pois é santíssima."),  (1458, 3, 10, 13, "Comam-na em lugar sagrado, porquanto é a porção que lhes cabe por decreto, a você e a seus filhos, das ofertas dedicadas ao Senhor, preparadas no fogo; pois assim me foi ordenado."),  (1459, 3, 10, 14, "O peito ritualmente movido e a coxa ofertada, você, seus filhos e suas filhas poderão comer num lugar cerimonialmente puro; foi dado a você e a seus filhos como porção das ofertas de comunhão dos israelitas."),  (1460, 3, 10, 15, "A coxa ofertada e o peito ritualmente movido devem ser trazidos junto com as porções de gordura das ofertas preparadas no fogo, para serem movidos perante o Senhor como gesto ritual de apresentação. Esta será a porção por decreto perpétuo para você e seus descendentes, conforme o Senhor tinha ordenado."),  (1461, 3, 10, 16, "Quando Moisés procurou por toda parte o bode da oferta pelo pecado e soube que já fora queimado, irou-se contra Eleazar e Itamar, os filhos de Arão que ficaram vivos, e perguntou:"),  (1462, 3, 10, 17, "Por que vocês não comeram a carne da oferta pelo pecado no Lugar Santo? É santíssima; foi-lhes dada para retirar a culpa da comunidade e fazer propiciação por ela perante o Senhor."),  (1463, 3, 10, 18, "Como o sangue do animal não foi levado para dentro do Lugar Santo, vocês deviam tê-lo comido no Lugar Santo, conforme ordenei."),  (1464, 3, 10, 19, "Arão respondeu a Moisés: Hoje eles ofereceram o seu sacrifício pelo pecado e o seu holocausto perante o Senhor; mesmo assim coisas como essas aconteceram comigo. Será que teria agradado ao Senhor se eu tivesse comido a oferta pelo pecado hoje? "),  (1465, 3, 10, 20, "Quando Moisés ouviu isso, ficou satisfeito."),  (1466, 3, 11, 1, "Disse o Senhor a Moisés e a Arão:"),  (1467, 3, 11, 2, "Digam aos israelitas: De todos os animais que vivem na terra, estes são os que vocês poderão comer:"),  (1468, 3, 11, 3, "Qualquer animal que tem casco fendido e dividido em duas unhas, e que rumina."),  (1469, 3, 11, 4, "Vocês não poderão comer aqueles que só ruminam nem os que só têm o casco fendido. O camelo, embora rumine, não tem casco fendido; considerem-no impuro."),  (1470, 3, 11, 5, "O coelho, embora rumine, não tem casco fendido; é impuro para vocês."),  (1471, 3, 11, 6, "A lebre, embora rumine, não tem casco fendido; considerem-na impura."),  (1472, 3, 11, 7, "E o porco, embora tenha casco fendido e dividido em duas unhas, não rumina; considerem-no impuro."),  (1473, 3, 11, 8, "Vocês não comerão a carne desses animais nem tocarão em seus cadáveres; considerem-nos impuros."),  (1474, 3, 11, 9, "De todas as criaturas que vivem nas águas do mar e dos rios, vocês poderão comer todas as que possuem barbatanas e escamas."),  (1475, 3, 11, 10, "Mas todas as criaturas que vivem nos mares ou nos rios, que não possuem barbatanas e escamas, quer dentre todas as pequenas criaturas que povoam as águas quer dentre todos os outros animais das águas, serão proibidas para vocês."),  (1476, 3, 11, 11, "Por isso, não poderão comer sua carne e considerarão impuros os seus cadáveres."),  (1477, 3, 11, 12, "Tudo o que vive na água e não possui barbatanas e escamas será proibido para vocês."),  (1478, 3, 11, 13, "Estas são as aves que vocês considerarão impuras, das quais não poderão comer porque são proibidas: a águia, o urubu, a águia-marinha,"),  (1479, 3, 11, 14, "o milhafre, o falcão,"),  (1480, 3, 11, 15, "qualquer espécie de corvo,"),  (1481, 3, 11, 16, "a coruja-de-chifre, a coruja-de-orelha-pequena, a coruja-orelhuda, qualquer espécie de gavião,"),  (1482, 3, 11, 17, "o mocho, a coruja-pescadora e o corujão,"),  (1483, 3, 11, 18, "a coruja-branca, a coruja-do-deserto, o abutre,"),  (1484, 3, 11, 19, "a cegonha, qualquer tipo de garça, a poupa e o morcego."),  (1485, 3, 11, 20, "Todas as pequenas criaturas que enxameiam, que têm asas, mas que se movem pelo chão serão proibidas para vocês."),  (1486, 3, 11, 21, "Dentre estas, porém, vocês poderão comer aquelas que têm pernas articuladas para saltar no chão."),  (1487, 3, 11, 22, "Dessas vocês poderão comer os diversos tipos de gafanhotos."),  (1488, 3, 11, 23, "Mas considerarão impuras todas as outras criaturas que enxameiam, que têm asas e que se movem pelo chão."),  (1489, 3, 11, 24, "Por meio deles vocês ficarão impuros; todo aquele que tocar em seus cadáveres estará impuro até à tarde."),  (1490, 3, 11, 25, "Todo o que carregar o cadáver de algum deles lavará as suas roupas e estará impuro até à tarde."),  (1491, 3, 11, 26, "Todo animal de casco não dividido em duas unhas ou que não rumina é impuro para vocês; quem tocar qualquer um deles ficará impuro."),  (1492, 3, 11, 27, "Todos os animais de quatro pés, que andam sobre a planta dos pés são impuros para vocês; todo o que tocar os seus cadáveres ficará impuro até à tarde."),  (1493, 3, 11, 28, "Quem carregar o cadáver de algum deles lavará suas roupas, e estará impuro até à tarde. São impuros para vocês."),  (1494, 3, 11, 29, "Dos animais que se movem rente ao chão, estes vocês considerarão impuros: a doninha, o rato, qualquer espécie de lagarto grande,"),  (1495, 3, 11, 30, "a lagartixa, o lagarto-pintado, o lagarto, o lagarto da areia e o camaleão."),  (1496, 3, 11, 31, "De todos os que se movem rente ao chão, esses vocês considerarão impuros. Quem neles tocar depois de mortos estará impuro até à tarde."),  (1497, 3, 11, 32, "E tudo sobre o que um deles cair depois de morto, qualquer que seja o seu uso, ficará impuro, seja objeto feito de madeira, de pano, de couro ou de pano de saco. Deverá ser posto em água e estará impuro até a tarde, e então ficará puro."),  (1498, 3, 11, 33, "Se um deles cair dentro de uma vasilha de barro, tudo o que nela houver ficará impuro, e vocês quebrarão a vasilha."),  (1499, 3, 11, 34, "Qualquer alimento sobre o qual cair essa água, ficará impuro, e qualquer bebida que estiver dentro da vasilha, ficará impura."),  (1500, 3, 11, 35, "Tudo aquilo sobre o que o cadáver de um desses animais cair ficará impuro; se for um forno ou um fogão de barro vocês o quebrarão. Estão impuros, e vocês os considerarão como tais."),  (1501, 3, 11, 36, "Mas, se cair numa fonte ou numa cisterna onde se recolhe água, ela permanece pura; mas quem tocar no cadáver ficará impuro."),  (1502, 3, 11, 37, "Se um cadáver cair sobre alguma semente a ser plantada, ela permanece pura;"),  (1503, 3, 11, 38, "mas se foi derramada água sobre a semente, vocês a considerarão impura."),  (1504, 3, 11, 39, "Quando morrer um animal que vocês têm permissão para comer, quem tocar no seu cadáver ficará impuro até à tarde."),  (1505, 3, 11, 40, "Quem comer da carne do animal morto terá que lavar as suas roupas e ficará impuro até à tarde. Quem carregar o cadáver do animal terá que lavar as suas roupas, e ficará impuro até à tarde."),  (1506, 3, 11, 41, "Todo animal que se move rente ao chão lhes será proibido e não poderá ser comido."),  (1507, 3, 11, 42, "Vocês não poderão comer animal algum que se move rente ao chão, quer se arraste sobre o ventre quer ande de quatro ou com o auxílio de muitos pés; eles lhes são proibidos."),  (1508, 3, 11, 43, "Não se contaminem com qualquer desses animais. Não se tornem impuros com eles nem deixem que eles os tornem impuros."),  (1509, 3, 11, 44, "Pois eu sou o Senhor Deus de vocês; consagrem-se e sejam santos, porque eu sou santo. Não se tornem impuros com qualquer animal que se move rente ao chão."),  (1510, 3, 11, 45, "Eu sou o Senhor que os tirou da terra do Egito para ser o seu Deus; por isso, sejam santos, porque eu sou santo."),  (1511, 3, 11, 46, "Essa é a regulamentação acerca dos animais, das aves, de todos os seres vivos que se movem na água e de todo animal que se move rente ao chão."),  (1512, 3, 11, 47, "Vocês farão separação entre o impuro e o puro, entre animais que podem e os que não podem ser comidos."),  (1513, 3, 12, 1, "Disse o Senhor a Moisés:"),  (1514, 3, 12, 2, "Diga aos israelitas: Quando uma mulher engravidar e der à luz um menino, estará impura por sete dias, assim como está impura durante o seu período menstrual."),  (1515, 3, 12, 3, "No oitavo dia o menino terá que ser circuncidado."),  (1516, 3, 12, 4, "Então a mulher aguardará trinta e três dias para ser purificada do seu sangramento. Não poderá tocar em nenhuma coisa sagrada e não poderá ir ao santuário, até que se completem os dias da sua purificação."),  (1517, 3, 12, 5, "Se der à luz uma menina, estará impura por duas semanas, como durante o seu período menstrual. Nesse caso aguardará sessenta e seis dias para ser purificada do seu sangramento."),  (1518, 3, 12, 6, "Quando se completarem os dias da sua purificação pelo nascimento de um menino ou de uma menina, ela trará ao sacerdote, à entrada da Tenda do Encontro, um cordeiro de um ano para o holocausto e um pombinho ou uma rolinha como oferta pelo pecado."),  (1519, 3, 12, 7, "Ele os oferecerá ao Senhor para fazer propiciação por ela, que ficará pura do fluxo do seu sangramento. Essa é a regulamentação para a mulher que der à luz um menino ou uma menina."),  (1520, 3, 12, 8, "Se ela não tiver recursos para oferecer um cordeiro, poderá trazer duas rolinhas ou dois pombinhos, um para o holocausto e o outro para a oferta pelo pecado. Assim o sacerdote fará propiciação por ela, e ela ficará pura."),  (1521, 3, 13, 1, "Disse o Senhor a Moisés e a Arão:"),  (1522, 3, 13, 2, "Quando alguém tiver um inchaço, uma erupção ou uma mancha brilhante na pele que possa ser sinal de lepra, será levado ao sacerdote Arão ou a um dos seus filhos que seja sacerdote."),  (1523, 3, 13, 3, "Este examinará a parte afetada da pele, e, se naquela parte o pêlo tiver se tornado branco e o lugar parecer mais profundo do que a pele, é sinal de lepra. Depois de examiná-lo, o sacerdote o declarará impuro."),  (1524, 3, 13, 4, "Se a mancha na pele for branca, mas não parecer mais profunda do que a pele e sobre ela o pêlo não tiver se tornado branco, o sacerdote o porá em isolamento por sete dias."),  (1525, 3, 13, 5, "No sétimo dia o sacerdote o examinará, e, se verificar que a parte afetada não se alterou nem se espalhou pela pele, o manterá em isolamento por mais sete dias."),  (1526, 3, 13, 6, "Ao sétimo dia o sacerdote o examinará de novo, e, se a parte afetada diminuiu e não se espalhou pela pele, o sacerdote o declarará puro; é apenas uma erupção. Então ele lavará as suas roupas, e estará puro."),  (1527, 3, 13, 7, "Mas, se depois que se apresentou ao sacerdote para ser declarado puro a erupção se espalhar pela pele, ele terá que se apresentar novamente ao sacerdote."),  (1528, 3, 13, 8, "O sacerdote o examinará, e, se a erupção espalhou-se pela pele, ele o declarará impuro; trata-se de lepra."),  (1529, 3, 13, 9, "Quando alguém apresentar sinal de lepra, será levado ao sacerdote."),  (1530, 3, 13, 10, "Este o examinará, e, se houver inchaço branco na pele, o qual tornou branco o pêlo, e se houver carne viva no inchaço,"),  (1531, 3, 13, 11, "é lepra crônica na pele, e o sacerdote o declarará impuro. Não o porá em isolamento, porquanto já está impuro."),  (1532, 3, 13, 12, "Se a doença se alastrar por toda a pele e cobrir toda a pele da pessoa infectada, da cabeça aos pés, até onde é possível ao sacerdote verificar,"),  (1533, 3, 13, 13, "este o examinará e, se observar que a lepra cobriu todo o corpo, ele a declarará pura. Visto que tudo ficou branco, ela está pura."),  (1534, 3, 13, 14, "Mas quando nela aparecer carne viva, ficará impura."),  (1535, 3, 13, 15, "Quando o sacerdote vir a carne viva, ele a declarará impura. A carne viva é impura; trata-se de lepra."),  (1536, 3, 13, 16, "Se a carne viva retroceder e a pele se tornar branca, a pessoa voltará ao sacerdote."),  (1537, 3, 13, 17, "Este a examinará, e, se a parte afetada se tornou branca, o sacerdote declarará pura a pessoa infectada, que então estará pura."),  (1538, 3, 13, 18, "Quando alguém tiver uma ferida purulenta em sua pele e ela sarar,"),  (1539, 3, 13, 19, "e no lugar da ferida aparecer um inchaço branco ou uma mancha avermelhada, ele se apresentará ao sacerdote."),  (1540, 3, 13, 20, "Este examinará o local, e, se parecer mais profundo do que a pele e o pêlo ali tiver se tornado branco, o sacerdote o declarará impuro. É sinal de lepra que se alastrou onde estava a ferida."),  (1541, 3, 13, 21, "Mas se, quando o sacerdote o examinar não houver nenhum pêlo branco e o lugar não estiver mais profundo do que a pele e tiver diminuído, então o sacerdote o porá em isolamento por sete dias."),  (1542, 3, 13, 22, "Se de fato estiver se espalhando pela pele, o sacerdote o declarará impuro; é sinal de lepra."),  (1543, 3, 13, 23, "Mas, se a mancha não tiver se alterado nem se espalhado, é apenas a cicatriz da ferida, e o sacerdote o declarará puro."),  (1544, 3, 13, 24, "Quando alguém tiver uma queimadura na pele, e uma mancha avermelhada ou branca aparecer na carne viva da queimadura,"),  (1545, 3, 13, 25, "o sacerdote examinará a mancha, e, se o pêlo sobre ela tiver se tornado branco e ela parecer mais profunda do que a pele, é lepra que surgiu na queimadura. O sacerdote o declarará impuro; é sinal de lepra na pele."),  (1546, 3, 13, 26, "Mas, se o sacerdote examinar a mancha e nela não houver pêlo branco e esta não estiver mais profunda do que a pele e tiver diminuído, então o sacerdote o porá em isolamento por sete dias."),  (1547, 3, 13, 27, "No sétimo dia o sacerdote o examinará, e, se a mancha estiver se espalhado pela pele, o sacerdote o declarará impuro; é sinal de lepra."),  (1548, 3, 13, 28, "Se, todavia, a mancha não tiver se alterado nem se espalhado pela pele, mas tiver diminuído, é um inchaço da queimadura, e o sacerdote o declarará puro; é apenas a cicatriz da queimadura."),  (1549, 3, 13, 29, "Quando um homem ou uma mulher tiver uma ferida na cabeça ou no queixo,"),  (1550, 3, 13, 30, "o sacerdote examinará a ferida, e, se ela parecer mais profunda do que a pele e o pêlo nela for amarelado e fino, o sacerdote declarará impura aquela pessoa; é sarna, isto é, lepra da cabeça ou do queixo."),  (1551, 3, 13, 31, "Mas, se quando o sacerdote examinar o sinal de sarna, este não parecer mais profundo do que a pele e não houver pêlo escuro nela, então o sacerdote porá a pessoa infectada em isolamento por sete dias."),  (1552, 3, 13, 32, "No sétimo dia o sacerdote examinará a parte afetada, e, se a sarna não tiver se espalhado e não houver pêlo amarelado nela e não parecer mais profunda do que a pele,"),  (1553, 3, 13, 33, "a pessoa rapará os pêlos, exceto na parte afetada, e o sacerdote a porá em isolamento por mais sete dias."),  (1554, 3, 13, 34, "No sétimo dia o sacerdote examinará a sarna, e, se não tiver se espalhado mais e não parecer mais profunda do que a pele, o sacerdote declarará pura a pessoa. Esta lavará suas roupas e estará pura."),  (1555, 3, 13, 35, "Mas, se a sarna se espalhar pela pele depois que a pessoa for declarada pura,"),  (1556, 3, 13, 36, "o sacerdote a examinará, e, se a sarna tiver se espalhado pela pele, o sacerdote não precisará procurar pêlo amarelado; a pessoa está impura."),  (1557, 3, 13, 37, "Se, entretanto, verificar que não houve alteração e cresceu pêlo escuro, a sarna está curada. Ela está pura, e o sacerdote a declarará pura."),  (1558, 3, 13, 38, "Quando um homem ou uma mulher tiver manchas brancas na pele,"),  (1559, 3, 13, 39, "o sacerdote examinará as manchas; se forem brancas e sem brilho, é um eczema que se alastrou; essa pessoa está pura."),  (1560, 3, 13, 40, "Quando os cabelos de um homem caírem, ele está calvo, todavia puro."),  (1561, 3, 13, 41, "Se lhe caírem os cabelos da frente da cabeça, ele está meio-calvo, porém puro."),  (1562, 3, 13, 42, "Mas, se tiver uma ferida avermelhada na parte calva da frente ou de trás da cabeça, é lepra que se alastra pela calva da frente ou de trás da cabeça."),  (1563, 3, 13, 43, "O sacerdote o examinará, e, se a ferida inchada na parte da frente ou de trás da calva for avermelhada como a lepra de pele,"),  (1564, 3, 13, 44, "o homem está leproso e impuro. O sacerdote terá que declará-lo impuro devido à ferida na cabeça."),  (1565, 3, 13, 45, "Quem ficar leproso, apresentando quaisquer desses sintomas, usará roupas rasgadas, andará descabelado, cobrirá a parte inferior do rosto e gritará: ‘Impuro! Impuro! ’"),  (1566, 3, 13, 46, "Enquanto tiver a doença, estará impuro. Viverá separado, fora do acampamento."),  (1567, 3, 13, 47, "Quando aparecer mancha de mofo em alguma roupa, seja roupa de lã, seja de linho,"),  (1568, 3, 13, 48, "ou em qualquer peça tecida ou entrelaçada de linho ou de lã, ou em algum pedaço ou objeto de couro,"),  (1569, 3, 13, 49, "se a mancha na roupa, ou no pedaço de couro, ou na peça tecida ou entrelaçada, ou em qualquer objeto de couro, for esverdeada ou avermelhada, é mancha de mofo que deverá ser mostrada ao sacerdote."),  (1570, 3, 13, 50, "O sacerdote examinará a mancha e isolará o objeto afetado por sete dias."),  (1571, 3, 13, 51, "No sétimo dia examinará a mancha, e, se ela tiver se espalhado pela roupa, ou pela peça tecida ou entrelaçada, ou pelo pedaço de couro, qualquer que seja o seu uso, é mofo corrosivo; o objeto está impuro."),  (1572, 3, 13, 52, "Ele queimará a roupa, ou a peça tecida ou entrelaçada, ou qualquer objeto de couro que tiver a mancha, pois é mofo corrosivo; o objeto será queimado."),  (1573, 3, 13, 53, "Mas se, quando o sacerdote o examinar, a mancha não tiver se espalhado pela roupa, ou pela peça tecida ou entrelaçada, ou pelo objeto de couro,"),  (1574, 3, 13, 54, "ordenará que o objeto afetado seja lavado. Então ele o isolará por mais sete dias."),  (1575, 3, 13, 55, "Depois de lavado o objeto afetado, o sacerdote o examinará, e, se a mancha não tiver alterado sua cor, ainda que não tenha se espalhado, o objeto estará impuro. Queime-o com fogo, quer o mofo corrosivo tenha afetado um lado, quer o outro do objeto."),  (1576, 3, 13, 56, "Se quando o sacerdote o examinar, a mancha tiver diminuído depois de lavado o objeto, ele cortará a parte afetada da roupa, ou do pedaço de couro, ou da peça tecida ou entrelaçada."),  (1577, 3, 13, 57, "Mas, se a mancha ainda aparecer na roupa, ou na peça tecida ou entrelaçada, ou no objeto de couro, é mofo que se alastra, e tudo o que tiver o mofo será queimado com fogo."),  (1578, 3, 13, 58, "Mas se, depois de lavada, a mancha desaparecer da roupa, ou da peça tecida ou entrelaçada, ou do objeto de couro, será lavado de novo, e então estará puro."),  (1579, 3, 13, 59, "Essa é a regulamentação acerca da mancha de mofo nas roupas de lã ou de linho, nas peças tecidas ou entrelaçadas, ou nos objetos de couro, para declará-los puros ou impuros."),  (1580, 3, 14, 1, "Disse também o Senhor a Moisés:"),  (1581, 3, 14, 2, "Esta é a regulamentação acerca da purificação de um leproso: ele será levado ao sacerdote,"),  (1582, 3, 14, 3, "que sairá do acampamento e o examinará. Se a pessoa foi curada da lepra,"),  (1583, 3, 14, 4, "o sacerdote ordenará que duas aves puras, vivas, um pedaço de madeira de cedro, um pano vermelho e um ramo de hissopo sejam trazidos em favor daquele que será purificado."),  (1584, 3, 14, 5, "Então o sacerdote ordenará que uma das aves seja morta numa vasilha de barro com água da fonte."),  (1585, 3, 14, 6, "Então pegará a ave viva e a molhará, juntamente com o pedaço de madeira de cedro, com o pano vermelho e com o ramo de hissopo, no sangue da ave morta em água corrente."),  (1586, 3, 14, 7, "Sete vezes ele aspergirá aquele que está sendo purificado da lepra e o declarará puro. Depois soltará a ave viva em campo aberto."),  (1587, 3, 14, 8, "Aquele que estiver sendo purificado lavará as suas roupas, rapará todos os seus pêlos e se banhará com água; e assim estará puro. Depois disso poderá entrar no acampamento, mas ficará fora da sua tenda por sete dias."),  (1588, 3, 14, 9, "No sétimo dia rapará todos os seus pêlos: o cabelo, a barba, as sobrancelhas e o restante dos pêlos. Lavará suas roupas e banhará o corpo com água; então ficará puro."),  (1589, 3, 14, 10, "No oitavo dia pegará dois cordeiros sem defeito e uma cordeira de um ano sem defeito, juntamente com três jarros da melhor farinha amassada com óleo, como oferta de cereal, e uma caneca de óleo."),  (1590, 3, 14, 11, "O sacerdote que faz a purificação apresentará ao Senhor, à entrada da Tenda do Encontro, tanto aquele que estiver para ser purificado como as suas ofertas."),  (1591, 3, 14, 12, "Então o sacerdote pegará um dos cordeiros e o sacrificará como oferta pela culpa, juntamente com a caneca de óleo; ele os moverá perante o Senhor como gesto ritual de apresentação e"),  (1592, 3, 14, 13, "matará o cordeiro no Lugar Santo, onde são sacrificados a oferta pelo pecado e o holocausto. Como se dá com a oferta pelo pecado, também a oferta pela culpa pertence ao sacerdote; é santíssima."),  (1593, 3, 14, 14, "O sacerdote porá um pouco do sangue da oferta pela culpa na ponta da orelha direita daquele que será purificado, no polegar da sua mão direita e no polegar do seu pé direito."),  (1594, 3, 14, 15, "Então o sacerdote pegará um pouco de óleo da caneca e o derramará na palma da sua própria mão esquerda,"),  (1595, 3, 14, 16, "molhará o dedo direito no óleo que está na palma da mão esquerda, e com o dedo o aspergirá sete vezes perante o Senhor."),  (1596, 3, 14, 17, "O sacerdote ainda porá um pouco do óleo restante na palma da sua mão, na ponta da orelha direita daquele que está sendo purificado, no polegar da sua mão direita e no polegar do seu pé direito, em cima do sangue da oferta pela culpa."),  (1597, 3, 14, 18, "O óleo que restar na palma da sua mão, o sacerdote derramará sobre a cabeça daquele que está sendo purificado e fará propiciação por ele perante o Senhor."),  (1598, 3, 14, 19, "Então o sacerdote sacrificará a oferta pelo pecado e fará propiciação em favor daquele que está sendo purificado da sua impureza. Depois disso, o sacerdote matará o animal do holocausto"),  (1599, 3, 14, 20, "e o oferecerá sobre o altar, juntamente com a oferta de cereal; e assim fará propiciação pelo ofertante, o qual estará puro."),  (1600, 3, 14, 21, "Se, todavia, for alguém pobre, sem recursos para isso, pegará um cordeiro como oferta pela culpa para ser movido para fazer propiciação por ele, juntamente com um jarro da melhor farinha, amassada com óleo, como oferta de cereal; uma caneca de óleo"),  (1601, 3, 14, 22, "e duas rolinhas ou dois pombinhos, os quais ele tenha condições de ofertar, um como oferta pelo pecado e o outro como holocausto."),  (1602, 3, 14, 23, "No oitavo dia ele os trará ao sacerdote, para a sua purificação, à entrada da Tenda do Encontro, perante o Senhor."),  (1603, 3, 14, 24, "O sacerdote pegará o cordeiro da oferta pela culpa, juntamente com uma caneca de óleo, e os moverá perante o Senhor como gesto ritual de apresentação."),  (1604, 3, 14, 25, "Matará o cordeiro da oferta pela culpa e pegará um pouco do sangue e o porá na ponta da orelha direita daquele que está sendo purificado, no polegar da sua mão direita e no polegar do seu pé direito."),  (1605, 3, 14, 26, "O sacerdote derramará um pouco do óleo na palma da sua mão esquerda,"),  (1606, 3, 14, 27, "e com o dedo indicador direito aspergirá um pouco do óleo da palma da sua mão esquerda sete vezes perante o Senhor."),  (1607, 3, 14, 28, "Ele porá o óleo da palma da sua mão nos mesmos lugares em que pôs o sangue da oferta pela culpa: na ponta da orelha direita daquele que está sendo purificado, no polegar da sua mão direita e no polegar do seu pé direito."),  (1608, 3, 14, 29, "O que restar do óleo na palma da sua mão, o sacerdote derramará sobre a cabeça daquele que está sendo purificado, para fazer propiciação por ele perante o Senhor."),  (1609, 3, 14, 30, "Depois sacrificará uma das rolinhas ou um dos pombinhos, os quais a pessoa tem condições de ofertar,"),  (1610, 3, 14, 31, "um como oferta pelo pecado e o outro como holocausto, juntamente com a oferta de cereal. Assim o sacerdote fará propiciação perante o Senhor em favor daquele que está sendo purificado."),  (1611, 3, 14, 32, "Essa é a regulamentação para todo aquele que tem lepra e não tem recursos para fazer a oferta da sua purificação."),  (1612, 3, 14, 33, "O Senhor disse a Moisés e a Arão:"),  (1613, 3, 14, 34, "Quando vocês entrarem na terra de Canaã, que lhes dou como propriedade, e eu puser mancha de mofo numa casa, na terra que lhes pertence,"),  (1614, 3, 14, 35, "o dono da casa irá ao sacerdote e dirá: ‘Parece-me que há mancha de mofo em minha casa’."),  (1615, 3, 14, 36, "Antes de examinar o mofo, o sacerdote ordenará que desocupem a casa para que nada que houver na casa se torne impuro. Depois disso, o sacerdote irá examinar a casa."),  (1616, 3, 14, 37, "Examinará as manchas nas paredes, e, se elas forem esverdeadas ou avermelhadas e parecerem mais profundas do que a superfície da parede,"),  (1617, 3, 14, 38, "o sacerdote sairá da casa e a deixará fechada por sete dias."),  (1618, 3, 14, 39, "No sétimo dia voltará para examinar a casa. Se as manchas se houverem espalhado pelas paredes da casa,"),  (1619, 3, 14, 40, "ordenará que as pedras contaminadas pelas manchas sejam retiradas e jogadas num local impuro, fora da cidade."),  (1620, 3, 14, 41, "Fará que a casa seja raspada por dentro e que o reboco raspado seja jogado num local impuro, fora da cidade."),  (1621, 3, 14, 42, "Depois colocarão outras pedras no lugar das primeiras, e rebocarão a casa com barro novo."),  (1622, 3, 14, 43, "Se as manchas tornarem a alastrar-se na casa depois de retiradas as pedras e de raspada e rebocada a casa,"),  (1623, 3, 14, 44, "o sacerdote irá examiná-la, e, se as manchas se espalharam pela casa, é mofo corrosivo; a casa está impura."),  (1624, 3, 14, 45, "Ela terá que ser demolida: as pedras, as madeiras e todo o reboco da casa; tudo será levado para um local impuro, fora da cidade."),  (1625, 3, 14, 46, "Quem entrar na casa enquanto estiver fechada estará impuro até à tarde."),  (1626, 3, 14, 47, "Aquele que dormir ou comer na casa terá que lavar as suas roupas."),  (1627, 3, 14, 48, "Mas, se o sacerdote for examiná-la e as manchas não se houverem espalhado depois de rebocada a casa, declarará pura a casa, pois as manchas de mofo desapareceram."),  (1628, 3, 14, 49, "Para purificar a casa, ele pegará duas aves, um pedaço de madeira de cedro, um pano vermelho e hissopo."),  (1629, 3, 14, 50, "Depois matará uma das aves numa vasilha de barro com água da fonte."),  (1630, 3, 14, 51, "Então pegará o pedaço de madeira de cedro, o hissopo, o pano vermelho e a ave viva, e os molhará no sangue da ave morta e na água da fonte, e aspergirá a casa sete vezes."),  (1631, 3, 14, 52, "Ele purificará a casa com o sangue da ave, com a água da fonte, com a ave viva, com o pedaço de madeira de cedro, com o hissopo e com o pano vermelho."),  (1632, 3, 14, 53, "Depois soltará a ave viva em campo aberto, fora da cidade. Assim fará propiciação pela casa, que ficará pura."),  (1633, 3, 14, 54, "Essa é a regulamentação acerca de qualquer tipo de lepra, de sarna,"),  (1634, 3, 14, 55, "de mofo nas roupas ou numa casa"),  (1635, 3, 14, 56, "e de inchaço, erupção ou mancha brilhante,"),  (1636, 3, 14, 57, "para se determinar quando uma coisa é pura ou impura. Essa é a regulamentação acerca de qualquer tipo de lepra e de mofo."),  (1637, 3, 15, 1, "O Senhor disse a Moisés e a Arão:"),  (1638, 3, 15, 2, "Digam o seguinte aos israelitas: Quando um homem tiver um fluxo que sai do corpo, o fluxo é impuro."),  (1639, 3, 15, 3, "Ele ficará impuro por causa do seu fluxo, quer continue, quer fique retido."),  (1640, 3, 15, 4, "A cama em que um homem com fluxo se deitar ficará impura, e qualquer coisa em que se sentar ficará impura."),  (1641, 3, 15, 5, "Quem tocar na cama dele, lavará as suas roupas e se banhará com água, e ficará impuro até à tarde."),  (1642, 3, 15, 6, "Todo aquele que se sentar sobre qualquer coisa na qual esse homem se sentou, lavará suas roupas e se banhará com água, e estará impuro até à tarde."),  (1643, 3, 15, 7, "Quem tocar no homem que tiver um fluxo lavará as suas roupas e se banhará com água, e ficará impuro até à tarde."),  (1644, 3, 15, 8, "Se o homem cuspir em alguém que está puro, este lavará as suas roupas e se banhará com água, e ficará impuro até à tarde."),  (1645, 3, 15, 9, "Tudo aquilo em que o homem se sentar quando montar um animal estará impuro,"),  (1646, 3, 15, 10, "e todo aquele que tocar em qualquer coisa que tenha estado debaixo dele ficará impuro até à tarde; quem pegar essas coisas lavará as suas roupas e se banhará com água, e ficará impuro até à tarde."),  (1647, 3, 15, 11, "Qualquer pessoa em quem o homem com fluxo tocar sem lavar as mãos, lavará as suas roupas e se banhará com água, e ficará impura até à tarde."),  (1648, 3, 15, 12, "A vasilha de barro na qual ele tocar será quebrada; se tocar numa vasilha de madeira, ela será lavada."),  (1649, 3, 15, 13, "Quando um homem sarar de seu fluxo, contará sete dias para a sua purificação; lavará as suas roupas e se banhará em água corrente, e ficará puro."),  (1650, 3, 15, 14, "No oitavo dia pegará duas rolinhas ou dois pombinhos e irá perante o Senhor, à entrada da Tenda do Encontro, e os dará ao sacerdote."),  (1651, 3, 15, 15, "O sacerdote os sacrificará, um como oferta pelo pecado e o outro como holocausto, e assim fará propiciação perante o Senhor em favor do homem por causa do fluxo."),  (1652, 3, 15, 16, "Quando de um homem sair o sêmen, banhará todo o seu corpo com água, e ficará impuro até à tarde."),  (1653, 3, 15, 17, "Qualquer peça de roupa ou de couro em que houver sêmen será lavada com água, e ficará impura até à tarde."),  (1654, 3, 15, 18, "Quando um homem se deitar com uma mulher e lhe sair o sêmen, ambos terão que se banhar com água, e estarão impuros até à tarde."),  (1655, 3, 15, 19, "Quando uma mulher tiver fluxo de sangue que sai do corpo, a impureza da sua menstruação durará sete dias, e quem nela tocar ficará impuro até à tarde."),  (1656, 3, 15, 20, "Tudo sobre o que ela se deitar durante a sua menstruação ficará impuro, e tudo sobre o que ela se sentar ficará impuro."),  (1657, 3, 15, 21, "Todo aquele que tocar em sua cama lavará as suas roupas e se banhará com água, e ficará impuro até à tarde."),  (1658, 3, 15, 22, "Quem tocar em alguma coisa sobre a qual ela se sentar lavará as suas roupas e se banhará com água, e estará impuro até à tarde."),  (1659, 3, 15, 23, "Quer seja a cama, quer seja qualquer coisa sobre a qual ela esteve sentada, quando alguém nisso tocar estará impuro até à tarde."),  (1660, 3, 15, 24, "Se um homem se deitar com ela e a menstruação dela nele tocar, estará impuro por sete dias; qualquer cama sobre a qual ele se deitar estará impura."),  (1661, 3, 15, 25, "Quando uma mulher tiver um fluxo de sangue por muitos dias fora da sua menstruação normal, ou um fluxo que continue além desse período, ela ficará impura enquanto durar o corrimento, como nos dias da sua menstruação."),  (1662, 3, 15, 26, "Qualquer cama em que ela se deitar enquanto continuar o seu fluxo estará impura, como acontece com a sua cama durante a sua menstruação, e tudo sobre o que ela se sentar estará impuro, como durante a sua menstruação."),  (1663, 3, 15, 27, "Quem tocar em alguma dessas coisas ficará impuro; lavará as suas roupas e se banhará com água, e ficará impuro até à tarde."),  (1664, 3, 15, 28, "Quando sarar do seu fluxo, contará sete dias, e depois disso estará pura."),  (1665, 3, 15, 29, "No oitavo dia pegará duas rolinhas ou dois pombinhos e os levará ao sacerdote, à entrada da Tenda do Encontro."),  (1666, 3, 15, 30, "O sacerdote sacrificará um como oferta pelo pecado e o outro como holocausto, e assim fará propiciação em favor dela, perante o Senhor, devido à impureza do seu fluxo."),  (1667, 3, 15, 31, "Mantenham os israelitas separados das coisas que os tornam impuros, para que não morram por contaminar com sua impureza o meu tabernáculo, que está entre eles."),  (1668, 3, 15, 32, "Essa é a regulamentação acerca do homem que tem fluxo e daquele de quem sai o sêmen, tornando-se impuro,"),  (1669, 3, 15, 33, "da mulher em sua menstruação, do homem ou da mulher que têm fluxo e do homem que se deita com uma mulher que está impura."),  (1670, 3, 16, 1, "O Senhor falou com Moisés depois que morreram os dois filhos de Arão, por haverem se aproximado do Senhor."),  (1671, 3, 16, 2, "O Senhor disse a Moisés: Diga a seu irmão Arão que não entre a toda hora no Lugar Santíssimo, atrás do véu, diante da tampa da arca, para que não morra; pois aparecerei na nuvem, acima da tampa."),  (1672, 3, 16, 3, "Arão deverá entrar no Lugar Santo com um novilho como oferta pelo pecado e com um carneiro como holocausto."),  (1673, 3, 16, 4, "Ele vestirá a túnica sagrada de linho, com calções também de linho por baixo; porá o cinto de linho na cintura e também o turbante de linho. Essas vestes são sagradas; por isso ele se banhará com água antes de vesti-las."),  (1674, 3, 16, 5, "Receberá da comunidade de Israel dois bodes como oferta pelo pecado e um carneiro como holocausto."),  (1675, 3, 16, 6, "Arão sacrificará o novilho como oferta pelo seu próprio pecado para fazer propiciação por si mesmo e por sua família."),  (1676, 3, 16, 7, "Depois pegará os dois bodes e os apresentará ao Senhor, à entrada da Tenda do Encontro."),  (1677, 3, 16, 8, "E tirará sortes quanto aos dois bodes: uma para o Senhor e a outra para Azazel."),  (1678, 3, 16, 9, "Arão trará o bode cuja sorte caiu para o Senhor e o sacrificará como oferta pelo pecado."),  (1679, 3, 16, 10, "Mas o bode sobre o qual caiu a sorte para Azazel será apresentado vivo ao Senhor para se fazer propiciação e será enviado para Azazel no deserto."),  (1680, 3, 16, 11, "Arão trará o novilho como oferta por seu próprio pecado para fazer propiciação por si mesmo e por sua família, e ele o oferecerá como sacrifício pelo seu próprio pecado."),  (1681, 3, 16, 12, "Pegará o incensário cheio de brasas do altar que está perante o Senhor e dois punhados de incenso aromático em pó, e os levará para trás do véu."),  (1682, 3, 16, 13, "Porá o incenso no fogo perante o Senhor, e a fumaça do incenso cobrirá a tampa que está acima das tábuas da aliança, a fim de que não morra."),  (1683, 3, 16, 14, "Pegará um pouco do sangue do novilho e com o dedo o aspergirá sobre a parte da frente da tampa; depois, com o dedo aspergirá o sangue sete vezes, diante da tampa."),  (1684, 3, 16, 15, "Então sacrificará o bode da oferta pelo pecado, em favor do povo, e trará o sangue para trás do véu; fará com o sangue o que fez com o sangue do novilho; ele o aspergirá sobre a tampa e na frente dela."),  (1685, 3, 16, 16, "Assim fará propiciação pelo Lugar Santíssimo por causa das impurezas e das rebeliões dos israelitas, quaisquer que tenham sido os seus pecados. Fará o mesmo em favor da Tenda do Encontro, que está entre eles no meio das suas impurezas."),  (1686, 3, 16, 17, "Ninguém estará na Tenda do Encontro quando ele entrar para fazer propiciação no Lugar Santíssimo, até a saída de Arão, depois que fizer propiciação por si mesmo, por sua família e por toda a assembléia de Israel."),  (1687, 3, 16, 18, "Depois irá ao altar que está perante o Senhor e pelo altar fará propiciação. Pegará um pouco do sangue do novilho e do sangue do bode e o porá em todas as pontas do altar."),  (1688, 3, 16, 19, "Com o dedo aspergirá o sangue sete vezes sobre o altar para purificá-lo e santificá-lo das impurezas dos israelitas."),  (1689, 3, 16, 20, "Quando Arão terminar de fazer propiciação pelo Lugar Santíssimo, pela Tenda do Encontro e pelo altar, trará para a frente o bode vivo."),  (1690, 3, 16, 21, "Então colocará as duas mãos sobre a cabeça do bode vivo e confessará todas as iniqüidades e rebeliões dos israelitas, todos os seus pecados, e os porá sobre a cabeça do bode. Em seguida enviará o bode para o deserto aos cuidados de um homem designado para isso."),  (1691, 3, 16, 22, "O bode levará consigo todas as iniqüidades deles para um lugar solitário. E o homem soltará o bode no deserto."),  (1692, 3, 16, 23, "Depois Arão entrará na Tenda do Encontro, tirará as vestes de linho que usou para entrar no Lugar Santíssimo e as deixará ali."),  (1693, 3, 16, 24, "Ele se banhará com água num lugar sagrado e vestirá as suas próprias roupas. Então sairá e sacrificará o holocausto por si mesmo e o holocausto pelo povo, para fazer propiciação por si mesmo e pelo povo."),  (1694, 3, 16, 25, "Também queimará sobre o altar a gordura da oferta pelo pecado."),  (1695, 3, 16, 26, "Aquele que soltar o bode para Azazel lavará as suas roupas e se banhará com água, e depois poderá entrar no acampamento."),  (1696, 3, 16, 27, "O novilho e o bode da oferta pelo pecado, cujo sangue foi trazido ao Lugar Santíssimo para fazer propiciação, serão levados para fora do acampamento; o couro, a carne e o excremento deles serão queimados com fogo."),  (1697, 3, 16, 28, "Aquele que os queimar lavará as suas roupas e se banhará com água; depois poderá entrar no acampamento."),  (1698, 3, 16, 29, "Este é um decreto perpétuo para vocês: No décimo dia do sétimo mês vocês se humilharão a si mesmos e não poderão realizar trabalho algum, nem o natural da terra, nem o estrangeiro residente."),  (1699, 3, 16, 30, "Porquanto nesse dia se fará propiciação por vocês, para purificá-los. Então, perante o Senhor, vocês estarão puros de todos os seus pecados."),  (1700, 3, 16, 31, "Este lhes será um sábado de descanso, quando vocês se humilharão; é um decreto perpétuo."),  (1701, 3, 16, 32, "O sacerdote que for ungido e ordenado para suceder seu pai como sumo sacerdote fará a propiciação. Porá as vestes sagradas de linho"),  (1702, 3, 16, 33, "e fará propiciação pelo Lugar Santíssimo, pela Tenda do Encontro, pelo altar, por todos os sacerdotes e por todo o povo da assembléia."),  (1703, 3, 16, 34, "Este é um decreto perpétuo para vocês: A propiciação será feita uma vez por ano, por todos os pecados dos israelitas. E tudo foi feito conforme o Senhor tinha ordenado a Moisés."),  (1704, 3, 17, 1, "O Senhor disse a Moisés:"),  (1705, 3, 17, 2, "Diga o seguinte a Arão e seus filhos e a todos os israelitas: Foi isto o que o Senhor ordenou:"),  (1706, 3, 17, 3, "Qualquer israelita que sacrificar um boi, um cordeiro ou um cabrito dentro ou fora do acampamento,"),  (1707, 3, 17, 4, "e não o trouxer à entrada da Tenda do Encontro para apresentá-lo como oferta ao Senhor, diante do tabernáculo do Senhor, será considerado culpado de sangue; derramou sangue e será eliminado do meio do seu povo."),  (1708, 3, 17, 5, "Os sacrifícios, que os israelitas agora fazem em campo aberto, passarão a trazer ao Senhor, entregando-os ao sacerdote, para oferecê-los ao Senhor, à entrada da Tenda do Encontro, e os sacrificarão como ofertas de comunhão."),  (1709, 3, 17, 6, "O sacerdote aspergirá o sangue no altar do Senhor, à entrada da Tenda do Encontro, e queimará a gordura como aroma agradável ao Senhor."),  (1710, 3, 17, 7, "Não oferecerão mais sacrifícios aos ídolos em forma de bode, aos quais prestam culto imoral. Este é um decreto perpétuo para eles e para as suas gerações."),  (1711, 3, 17, 8, "Diga-lhes: Todo israelita ou estrangeiro residente que oferecer holocausto ou sacrifício,"),  (1712, 3, 17, 9, "e não o trouxer à entrada da Tenda do Encontro para oferecê-lo ao Senhor, será eliminado do meio do seu povo."),  (1713, 3, 17, 10, "Todo israelita ou estrangeiro residente que comer sangue de qualquer animal eu me voltarei contra esse que comeu sangue, e o eliminarei do meio do seu povo."),  (1714, 3, 17, 11, "Pois a vida da carne está no sangue, e eu o dei a vocês para fazerem propiciação por si mesmos no altar; é o sangue que faz propiciação pela vida."),  (1715, 3, 17, 12, "Por isso digo aos israelitas: nenhum de vocês poderá comer sangue, nem também o estrangeiro residente."),  (1716, 3, 17, 13, "Qualquer israelita ou estrangeiro residente que caçar um animal ou ave que se pode comer, derramará o sangue e o cobrirá com terra,"),  (1717, 3, 17, 14, "porque a vida de toda carne é o seu sangue. Por isso eu disse aos israelitas: vocês não poderão comer o sangue de nenhum animal, porque a vida de toda carne é o seu sangue; todo aquele que o comer será eliminado."),  (1718, 3, 17, 15, "Todo aquele que, natural da terra ou estrangeiro, comer um animal encontrado morto ou despedaçado por animais selvagens, lavará suas roupas e se banhará com água, e ficará impuro até à tarde; então estará puro."),  (1719, 3, 17, 16, "Mas, se não lavar as suas roupas nem se banhar, sofrerá as conseqüências da sua iniqüidade."),  (1720, 3, 18, 1, "Disse o Senhor a Moisés:"),  (1721, 3, 18, 2, "Diga o seguinte aos israelitas: Eu sou o Senhor, o Deus de vocês."),  (1722, 3, 18, 3, "Não procedam como se procede no Egito, onde vocês moraram, nem como se procede na terra de Canaã, para onde os estou levando. Não sigam as suas práticas."),  (1723, 3, 18, 4, "Pratiquem as minhas ordenanças, obedeçam aos meus decretos e sigam-nos. Eu sou o Senhor, o Deus de vocês."),  (1724, 3, 18, 5, "Obedeçam aos meus decretos e ordenanças, pois o homem que os praticar viverá por eles. Eu sou o Senhor."),  (1725, 3, 18, 6, "Ninguém poderá se aproximar de uma parenta próxima para se envolver sexualmente com ela. Eu sou o Senhor."),  (1726, 3, 18, 7, "Não desonre o seu pai, envolvendo-se sexualmente com a sua mãe. Ela é sua mãe; não se envolva sexualmente com ela."),  (1727, 3, 18, 8, "Não se envolva sexualmente com a mulher do seu pai; isso desonraria seu pai."),  (1728, 3, 18, 9, "Não se envolva sexualmente com a sua irmã, filha do seu pai ou da sua mãe, tenha ela nascido na mesma casa ou em outro lugar."),  (1729, 3, 18, 10, "Não se envolva sexualmente com a filha do seu filho ou com a filha da sua filha; isso desonraria você."),  (1730, 3, 18, 11, "Não se envolva sexualmente com a filha da mulher do seu pai, gerada por seu pai; ela é sua irmã."),  (1731, 3, 18, 12, "Não se envolva sexualmente com a irmã do seu pai; ela é parenta próxima do seu pai."),  (1732, 3, 18, 13, "Não se envolva sexualmente com a irmã da sua mãe; ela é parenta próxima da sua mãe."),  (1733, 3, 18, 14, "Não desonre o irmão do seu pai aproximando-se da sua mulher para com ela se envolver sexualmente; ela é sua tia."),  (1734, 3, 18, 15, "Não se envolva sexualmente com a sua nora. Ela é mulher do seu filho; não se envolva sexualmente com ela."),  (1735, 3, 18, 16, "Não se envolva sexualmente com a mulher do seu irmão; isso desonraria seu irmão."),  (1736, 3, 18, 17, "Não se envolva sexualmente com uma mulher e sua filha. Não se envolva sexualmente com a filha do seu filho ou com a filha da sua filha; são parentes próximos. É perversidade."),  (1737, 3, 18, 18, "Não tome por mulher a irmã da sua mulher, tornando-a rival, envolvendo-se sexualmente com ela, estando a sua mulher ainda viva."),  (1738, 3, 18, 19, "Não se aproxime de uma mulher para se envolver sexualmente com ela quando ela estiver na impureza da sua menstruação."),  (1739, 3, 18, 20, "Não se deite com a mulher do seu próximo, contaminando-se com ela."),  (1740, 3, 18, 21, "Não entregue os seus filhos para serem sacrificados a Moloque. Não profanem o nome do seu Deus. Eu sou o Senhor."),  (1741, 3, 18, 22, "Não se deite com um homem como quem se deita com uma mulher; é repugnante."),  (1742, 3, 18, 23, "Não tenha relações sexuais com um animal, contaminando-se com ele. Mulher nenhuma se porá diante de um animal para ajuntar-se com ele; é depravação."),  (1743, 3, 18, 24, "Não se contaminem com nenhuma dessas coisas, porque assim se contaminaram as nações que vou expulsar da presença de vocês."),  (1744, 3, 18, 25, "Até a terra ficou contaminada; e eu castiguei a sua iniqüidade, e a terra vomitou os seus habitantes."),  (1745, 3, 18, 26, "Mas vocês obedecerão aos meus decretos e às minhas leis. Nem o natural da terra nem o estrangeiro residente entre vocês farão nenhuma dessas abominações,"),  (1746, 3, 18, 27, "pois todas estas abominações foram praticadas pelos que habitaram essa terra antes de vocês; por isso a terra ficou contaminada."),  (1747, 3, 18, 28, "E, se vocês contaminarem a terra, ela os vomitará, como vomitou os povos que ali estavam antes de vocês."),  (1748, 3, 18, 29, "Todo aquele que fizer alguma destas abominações, aqueles que assim procederem serão eliminados do meio do seu povo."),  (1749, 3, 18, 30, "Obedeçam aos meus preceitos, e não pratiquem os costumes repugnantes praticados antes de vocês, nem se contaminem com eles. Eu sou o Senhor, o Deus de vocês."),  (1750, 3, 19, 1, "Disse ainda o Senhor a Moisés:"),  (1751, 3, 19, 2, "Diga o seguinte a toda comunidade de Israel: Sejam santos porque eu, o Senhor, o Deus de vocês, sou santo."),  (1752, 3, 19, 3, "Respeite cada um de vocês a sua mãe e o seu pai, e guarde os meus sábados. Eu sou o Senhor, o Deus de vocês."),  (1753, 3, 19, 4, "Não se voltem para os ídolos, nem façam para si deuses de metal. Eu sou o Senhor, o Deus de vocês."),  (1754, 3, 19, 5, "Quando vocês oferecerem um sacrifício de comunhão ao Senhor, ofereçam-no de modo que seja aceito em favor de vocês."),  (1755, 3, 19, 6, "Terá que ser comido no dia em que o oferecerem, ou no dia seguinte; o que sobrar até ao terceiro dia será queimado."),  (1756, 3, 19, 7, "Se alguma coisa for comida no terceiro dia, estará estragada e não será aceita."),  (1757, 3, 19, 8, "Quem comer sofrerá as conseqüências da sua iniqüidade, porque profanou o que é santo ao Senhor; será eliminado do meio do seu povo."),  (1758, 3, 19, 9, "Quando fizerem a colheita da sua terra, não colham até às extremidades da sua lavoura, nem ajuntem as espigas caídas de sua colheita."),  (1759, 3, 19, 10, "Não passem duas vezes pela sua vinha, nem apanhem as uvas que tiverem caído. Deixem-nas para o necessitado e para o estrangeiro. Eu sou o Senhor, o Deus de vocês."),  (1760, 3, 19, 11, "Não furtem. Não mintam. Não enganem uns aos outros."),  (1761, 3, 19, 12, "Não jurem falsamente pelo meu nome, profanando assim o nome do seu Deus. Eu sou o Senhor."),  (1762, 3, 19, 13, "Não oprimam nem roubem o seu próximo. Não retenham até a manhã do dia seguinte o pagamento de um diarista."),  (1763, 3, 19, 14, "Não amaldiçoem o surdo nem ponham pedra de tropeço à frente do cego, mas tema o seu Deus. Eu sou o Senhor."),  (1764, 3, 19, 15, "Não cometam injustiça num julgamento; não favoreçam os pobres, nem procurem agradar os grandes, mas julguem o seu próximo com justiça."),  (1765, 3, 19, 16, "Não espalhem calúnias entre o seu povo. Não se levantem contra a vida do seu próximo. Eu sou o Senhor."),  (1766, 3, 19, 17, "Não guardem ódio contra o seu irmão no coração; antes repreendam com franqueza o seu próximo para que, por causa dele, não sofram as conseqüências de um pecado."),  (1767, 3, 19, 18, "Não procurem vingança, nem guardem rancor contra alguém do seu povo, mas ame cada um o seu próximo como a si mesmo. Eu sou o Senhor."),  (1768, 3, 19, 19, "Obedeçam às minhas leis. Não cruzem diferentes espécies de animais. Não plantem duas espécies de sementes na sua lavoura. Não usem roupas feitas com dois tipos de tecido."),  (1769, 3, 19, 20, "Se um homem deitar-se com uma escrava prometida a outro homem, mas que não tenha sido resgatada nem recebido sua liberdade, aplique-se a devida punição. Contudo não serão mortos, porquanto ela não havia sido libertada."),  (1770, 3, 19, 21, "O homem, porém, trará ao Senhor, à entrada da Tenda do Encontro, um carneiro como oferta pela culpa."),  (1771, 3, 19, 22, "Com o carneiro da oferta pela culpa o sacerdote fará propiciação por ele perante o Senhor, pelo pecado que cometeu; assim o pecado que ele cometeu será perdoado."),  (1772, 3, 19, 23, "Quando vocês entrarem na terra e plantarem qualquer tipo de árvore frutífera, considerem proibidas as suas frutas. Durante três anos vocês as considerarão proibidas; não poderão comê-las."),  (1773, 3, 19, 24, "No quarto ano todas as suas frutas serão santas; será uma oferta de louvor ao Senhor."),  (1774, 3, 19, 25, "No quinto ano, porém, vocês poderão comer as suas frutas. Assim a sua colheita aumentará. Eu sou o Senhor, o Deus de vocês."),  (1775, 3, 19, 26, "Não comam nada com sangue. Não pratiquem adivinhação nem feitiçaria."),  (1776, 3, 19, 27, "Não cortem o cabelo dos lados da cabeça, nem aparem as pontas da barba."),  (1777, 3, 19, 28, "Não façam cortes em seus corpos por causa dos mortos, nem tatuagem em si mesmos. Eu sou o Senhor."),  (1778, 3, 19, 29, "Ninguém desonre a sua filha tornando-a uma prostituta, se não a terra se entregará à prostituição e se encherá de perversidade."),  (1779, 3, 19, 30, "Guardem os meus sábados e reverenciem o meu santuário. Eu sou o Senhor."),  (1780, 3, 19, 31, "Não recorram aos médiuns, nem busquem os espíritas, pois vocês serão contaminados por eles. Eu sou o Senhor, o Deus de vocês."),  (1781, 3, 19, 32, "Levantem-se na presença dos idosos, honrem os anciãos, tema o seu Deus. Eu sou o Senhor."),  (1782, 3, 19, 33, "Quando um estrangeiro viver na terra de vocês, não o maltratem."),  (1783, 3, 19, 34, "O estrangeiro residente que viver com vocês será tratado como o natural da terra. Amem-no como a si mesmos, pois vocês foram estrangeiros no Egito. Eu sou o Senhor, o Deus de vocês."),  (1784, 3, 19, 35, "Não usem medidas desonestas quando medirem comprimento, peso ou quantidade."),  (1785, 3, 19, 36, "Usem balanças de pesos honestos, tanto para cereais quanto para líquidos. Eu sou o Senhor, o Deus de vocês, que os tirei da terra do Egito."),  (1786, 3, 19, 37, "Obedeçam a todos os meus decretos e a todas as minhas leis e pratiquem-nos. Eu sou o Senhor."),  (1787, 3, 20, 1, "Disse o Senhor a Moisés:"),  (1788, 3, 20, 2, "Diga aos israelitas: Qualquer israelita ou estrangeiro residente em Israel que entregar um dos seus filhos a Moloque, terá que ser executado. O povo da terra o apedrejará."),  (1789, 3, 20, 3, "Voltarei o meu rosto contra ele e o eliminarei do meio do seu povo; pois deu os seus filhos a Moloque, contaminando assim o meu santuário e profanando o meu santo nome."),  (1790, 3, 20, 4, "Se o povo deliberadamente fechar os olhos quando alguém entregar um dos seus filhos a Moloque, e deixar de executá-lo,"),  (1791, 3, 20, 5, "voltarei o meu rosto contra aquele homem e contra o seu clã e eliminarei do meio do seu povo tanto ele quanto todos os que o seguem, prostituindo-se com Moloque."),  (1792, 3, 20, 6, "Voltarei o meu rosto contra aquele que procurar médiuns e espíritas para segui-los, prostituindo-se com eles. Eu o eliminarei do meio do seu povo."),  (1793, 3, 20, 7, "Consagrem-se, porém, e sejam santos, porque eu sou o Senhor, o Deus de vocês."),  (1794, 3, 20, 8, "Obedeçam aos meus decretos e pratiquem-nos. Eu sou o Senhor que os santifica."),  (1795, 3, 20, 9, "Se alguém amaldiçoar seu pai ou sua mãe, terá que ser executado. Por ter amaldiçoado o seu pai ou a sua mãe, merece a morte."),  (1796, 3, 20, 10, "Se um homem cometer adultério com a mulher de outro homem, com a mulher do seu próximo, tanto o adúltero quanto a adúltera terão que ser executados."),  (1797, 3, 20, 11, "Se um homem se deitar com a mulher do seu pai, desonrou seu pai. Tanto o homem quanto a mulher terão que ser executados, pois merecem a morte."),  (1798, 3, 20, 12, "Se um homem se deitar com a sua nora, ambos terão que ser executados. O que fizeram é depravação; merecem a morte."),  (1799, 3, 20, 13, "Se um homem se deitar com outro homem como quem se deita com uma mulher, ambos praticaram um ato repugnante. Terão que ser executados, pois merecem a morte."),  (1800, 3, 20, 14, "Se um homem tomar uma mulher e a mãe dela, comete perversidade. Tanto ele quanto elas serão queimados com fogo, para que não haja perversidade entre vocês."),  (1801, 3, 20, 15, "Se um homem tiver relações sexuais com um animal, terá que ser executado, e vocês matarão também o animal."),  (1802, 3, 20, 16, "Se uma mulher se aproximar de algum animal para ajuntar-se com ele, vocês matarão a mulher e o animal. Ambos terão que ser executados, pois merecem a morte."),  (1803, 3, 20, 17, "Se um homem tomar por mulher sua irmã, filha de seu pai ou de sua mãe, e se envolver sexualmente com ela, pratica um ato vergonhoso. Serão eliminados à vista de todo o povo. Desonrou sua irmã e sofrerá as conseqüências da sua iniqüidade."),  (1804, 3, 20, 18, "Se um homem se deitar com uma mulher durante a menstruação e com ela se envolver sexualmente, ambos serão eliminados do meio do seu povo, pois expuseram o sangramento dela."),  (1805, 3, 20, 19, "Não se envolva sexualmente com a irmã de sua mãe, nem com a irmã de seu pai; pois quem se envolver sexualmente com uma parenta próxima sofrerá as conseqüências da sua iniqüidade."),  (1806, 3, 20, 20, "Se um homem se deitar com a mulher do seu tio, desonrou seu tio. Eles sofrerão as conseqüências do seu pecado; morrerão sem filhos."),  (1807, 3, 20, 21, "Se um homem tomar por mulher a mulher do seu irmão, comete impureza; desonrou seu irmão. Ficarão sem filhos."),  (1808, 3, 20, 22, "Obedeçam a todos os meus decretos e leis e pratiquem-nos, para que a terra para onde os estou levando para habitarem não os vomite."),  (1809, 3, 20, 23, "Não sigam os costumes dos povos que vou expulsar de diante de vocês. Por terem feito todas essas coisas, causam-me repugnância."),  (1810, 3, 20, 24, "Mas a vocês prometi que herdarão a terra deles; eu a darei a vocês como herança, terra que mana leite e mel. Eu sou o Senhor, o Deus de vocês, que os separou dentre os povos."),  (1811, 3, 20, 25, "Portanto, façam separação entre animais puros e impuros e entre aves puras e impuras. Não se contaminem com animal, ou ave, ou com qualquer criatura que se move rente ao chão, os quais separei de vocês por serem eles impuros."),  (1812, 3, 20, 26, "Vocês serão santos para mim, porque eu, o Senhor, sou santo, e os separei dentre os povos para serem meus."),  (1813, 3, 20, 27, "Os homens ou mulheres que, entre vocês, forem médiuns ou espíritas, terão que ser executados. Serão apedrejados, pois merecem a morte."),  (1814, 3, 21, 1, "Disse ainda o Senhor a Moisés: Diga o seguinte aos sacerdotes, os filhos de Arão: Um sacerdote não poderá tornar-se impuro por causa de alguém do seu povo que venha a morrer,"),  (1815, 3, 21, 2, "a não ser por um parente próximo, como mãe ou pai, filho ou filha, irmão,"),  (1816, 3, 21, 3, "ou irmã virgem dependente dele por ainda não ter marido; por causa dela, poderá tornar-se impuro."),  (1817, 3, 21, 4, "Não poderá tornar-se impuro e contaminar-se por causa de parentes por casamento."),  (1818, 3, 21, 5, "Os sacerdotes não raparão a cabeça, nem apararão as pontas da barba, nem farão cortes no corpo."),  (1819, 3, 21, 6, "Serão santos ao seu Deus, e não profanarão o nome do seu Deus. Pelo fato de apresentarem ao Senhor as ofertas preparadas no fogo, ofertas de alimento do seu Deus, serão santos."),  (1820, 3, 21, 7, "Não poderão tomar por mulher uma prostituta, uma moça que tenha perdido a virgindade, ou uma mulher divorciada do seu marido, porque o sacerdote é santo ao seu Deus."),  (1821, 3, 21, 8, "Considerem-no santo, porque ele oferece o alimento do seu Deus. Considerem-no santo, porque eu, o Senhor, que os santifico, sou santo."),  (1822, 3, 21, 9, "Se a filha de um sacerdote se corromper, tornando-se prostituta, desonra seu pai; será queimada com fogo."),  (1823, 3, 21, 10, "O sumo sacerdote, aquele entre seus irmãos sobre cuja cabeça tiver sido derramado o óleo da unção, e que tiver sido consagrado para usar as vestes sacerdotais, não andará descabelado, nem rasgará as roupas em sinal de luto."),  (1824, 3, 21, 11, "Não entrará onde houver um cadáver. Não se tornará impuro, nem mesmo por causa do seu pai ou da sua mãe;"),  (1825, 3, 21, 12, "e não deixará o santuário do seu Deus, nem o profanará, porquanto foi consagrado pelo óleo da unção do seu Deus. Eu sou o Senhor."),  (1826, 3, 21, 13, "A mulher que ele tomar terá que ser virgem."),  (1827, 3, 21, 14, "Não poderá ser viúva, nem divorciada, nem moça que perdeu a virgindade, nem prostituta, mas terá que ser uma virgem do seu próprio povo,"),  (1828, 3, 21, 15, "assim ele não profanará a sua descendência entre o seu povo. Eu sou o Senhor, que o santifico."),  (1829, 3, 21, 16, "Disse ainda o Senhor a Moisés:"),  (1830, 3, 21, 17, "Diga a Arão: Pelas suas gerações, nenhum dos seus descendentes que tenha algum defeito poderá aproximar-se para trazer ao seu Deus ofertas de alimento."),  (1831, 3, 21, 18, "Nenhum homem que tenha algum defeito poderá aproximar-se: ninguém que seja cego ou aleijado, que tenha o rosto defeituoso ou o corpo deformado;"),  (1832, 3, 21, 19, "ninguém que tenha o pé ou a mão defeituosos,"),  (1833, 3, 21, 20, "ou que seja corcunda ou anão, ou que tenha qualquer defeito na vista, ou que esteja com feridas purulentas ou com fluxo, ou que tenha testículos defeituosos."),  (1834, 3, 21, 21, "Nenhum descendente do sacerdote Arão que tenha qualquer defeito poderá aproximar-se para apresentar ao Senhor ofertas preparadas no fogo. Tem defeito; não poderá aproximar-se para trazê-las ao seu Deus."),  (1835, 3, 21, 22, "Poderá comer o alimento santíssimo de seu Deus, e também o alimento santo;"),  (1836, 3, 21, 23, "contudo, por causa do seu defeito, não se aproximará do véu nem do altar, para que não profane o meu santuário. Eu sou o Senhor, que os santifico."),  (1837, 3, 21, 24, "Foi isso que Moisés falou a Arão e a seus filhos e a todos os israelitas."),  (1838, 3, 22, 1, "Disse o Senhor a Moisés:"),  (1839, 3, 22, 2, "Diga a Arão e a seus filhos que tratem com respeito as ofertas sagradas que os israelitas me consagrarem, para que não profanem o meu santo nome. Eu sou o Senhor."),  (1840, 3, 22, 3, "Avise-lhes que se, em suas futuras gerações, algum dos seus descendentes estiver impuro quando se aproximar das ofertas sagradas que os israelitas consagrarem ao Senhor, será eliminado da minha presença. Eu sou o Senhor."),  (1841, 3, 22, 4, "Nenhum descendente de Arão que tenha lepra ou fluxo no corpo poderá comer das ofertas sagradas até que esteja purificado. Também estará impuro se tocar em algo contaminado por um cadáver, ou se lhe sair o sêmen,"),  (1842, 3, 22, 5, "ou se tocar em alguma criatura, ou em alguém que o torne impuro, seja qual for a impureza."),  (1843, 3, 22, 6, "Aquele que neles tocar ficará impuro até à tarde. Não poderá comer das ofertas sagradas, a menos que se tenha banhado com água."),  (1844, 3, 22, 7, "Depois do pôr do sol estará puro, e então poderá comer as ofertas sagradas, pois são o seu alimento."),  (1845, 3, 22, 8, "Também não poderá comer animal encontrado morto ou despedaçado por animais selvagens, pois se tornaria impuro por causa deles. Eu sou o Senhor."),  (1846, 3, 22, 9, "Os sacerdotes obedecerão aos meus preceitos, para que não sofram as conseqüências do seu pecado nem sejam executados por tê-los profanado. Eu sou o Senhor, que os santifico."),  (1847, 3, 22, 10, "Somente o sacerdote e a sua família poderão comer da oferta sagrada; não poderá comê-la o seu hóspede, nem o seu empregado."),  (1848, 3, 22, 11, "Mas, se um sacerdote comprar um escravo, ou se um escravo nascer em sua casa, esse escravo poderá comer do seu alimento."),  (1849, 3, 22, 12, "Se a filha de um sacerdote se casar com alguém que não seja sacerdote, não poderá comer das ofertas sagradas."),  (1850, 3, 22, 13, "Mas, se a filha de um sacerdote ficar viúva ou se divorciar, e não tiver filhos, e voltar a viver na casa do pai como na sua juventude, poderá comer do alimento do pai, mas dele não poderá comer ninguém que não seja da família do sacerdote."),  (1851, 3, 22, 14, "Se alguém, sem intenção, comer uma oferta sagrada, fará restituição da oferta ao sacerdote e lhe acrescentará um quinto do seu valor."),  (1852, 3, 22, 15, "Os sacerdotes não profanarão as ofertas sagradas que os israelitas apresentam ao Senhor,"),  (1853, 3, 22, 16, "permitindo-lhes comê-las e trazendo assim sobre eles culpa que exige reparação. Eu sou o Senhor que os santifico."),  (1854, 3, 22, 17, "Disse o Senhor a Moisés:"),  (1855, 3, 22, 18, "Diga o seguinte a Arão e a seus filhos e a todos os israelitas: Se algum de vocês, seja israelita, seja estrangeiro residente em Israel, apresentar uma oferta como holocausto ao Senhor, quer para cumprir voto, quer como oferta voluntária,"),  (1856, 3, 22, 19, "apresentará um macho sem defeito do rebanho, boi, carneiro ou bode, a fim de que seja aceita em seu favor."),  (1857, 3, 22, 20, "Não tragam nenhum animal defeituoso, porque não será aceito em favor de vocês."),  (1858, 3, 22, 21, "Quando alguém trouxer um animal do gado ou do rebanho de ovelhas como oferta de comunhão para o Senhor, em cumprimento de voto, ou como oferta voluntária, para ser aceitável o animal terá que ser sem defeito e sem mácula."),  (1859, 3, 22, 22, "Não ofereçam ao Senhor animal cego, aleijado, mutilado, ulceroso, cheio de feridas purulentas ou com fluxo. Não coloquem nenhum desses animais sobre o altar como oferta ao Senhor, preparada no fogo."),  (1860, 3, 22, 23, "Todavia, poderão apresentar como oferta voluntária um boi ou um carneiro ou um cabrito deformados ou atrofiados, mas no caso do cumprimento de voto não serão aceitos."),  (1861, 3, 22, 24, "Não poderão oferecer ao Senhor um animal cujos testículos estejam machucados, esmagados, despedaçados ou cortados. Não façam isso em sua própria terra,"),  (1862, 3, 22, 25, "nem aceitem animais como esses das mãos de um estrangeiro para oferecê-los como alimento do seu Deus. Não serão aceitos em favor de vocês, pois são deformados e apresentam defeitos."),  (1863, 3, 22, 26, "Disse ainda o Senhor a Moisés:"),  (1864, 3, 22, 27, "Quando nascer um bezerro, um cordeiro ou um cabrito, ficará sete dias com sua mãe. Do oitavo dia em diante será aceito como oferta ao Senhor preparada no fogo."),  (1865, 3, 22, 28, "Não matem uma vaca ou uma ovelha ou uma cabra e sua cria no mesmo dia."),  (1866, 3, 22, 29, "Quando vocês oferecerem um sacrifício de gratidão ao Senhor, ofereçam-no de maneira que seja aceito em favor de vocês."),  (1867, 3, 22, 30, "Será comido naquele mesmo dia; não deixem nada até a manhã seguinte. Eu sou o Senhor."),  (1868, 3, 22, 31, "Obedeçam aos meus mandamentos e os coloquem em prática. Eu sou o Senhor."),  (1869, 3, 22, 32, "Não profanem o meu santo nome. Eu serei reconhecido como santo pelos israelitas. Eu sou o Senhor que os santifico"),  (1870, 3, 22, 33, "e que os tirou do Egito para ser o Deus de vocês. Eu sou o Senhor."),  (1871, 3, 23, 1, "Disse o Senhor a Moisés:"),  (1872, 3, 23, 2, "Diga o seguinte aos israelitas: Estas são as minhas festas, as festas fixas do Senhor, que vocês proclamarão como reuniões sagradas:"),  (1873, 3, 23, 3, "Em seis dias realize os seus trabalhos, mas o sétimo dia é sábado, dia de descanso e de reunião sagrada. Não realizem trabalho algum; onde quer que morarem, será sábado dedicado ao Senhor."),  (1874, 3, 23, 4, "Estas são as festas fixas do Senhor, as reuniões sagradas que vocês proclamarão no tempo devido:"),  (1875, 3, 23, 5, "A páscoa do Senhor começa no entardecer do décimo quarto dia do primeiro mês."),  (1876, 3, 23, 6, "No décimo quinto dia daquele mês começa a festa do Senhor, a festa dos pães sem fermento; durante sete dias vocês comerão pães sem fermento."),  (1877, 3, 23, 7, "No primeiro dia façam uma reunião sagrada e não realizem trabalho algum."),  (1878, 3, 23, 8, "Durante sete dias apresentem ao Senhor ofertas preparadas no fogo. E no sétimo dia façam uma reunião sagrada e não realizem trabalho algum."),  (1879, 3, 23, 9, "Disse o Senhor a Moisés:"),  (1880, 3, 23, 10, "Diga o seguinte aos israelitas: Quando vocês entrarem na terra que lhes dou e fizerem colheita, tragam ao sacerdote um feixe do primeiro cereal que colherem."),  (1881, 3, 23, 11, "O sacerdote moverá ritualmente o feixe perante o Senhor para que seja aceito em favor de vocês; ele o moverá no dia seguinte ao sábado."),  (1882, 3, 23, 12, "No dia em que moverem o feixe, vocês oferecerão em holocausto ao Senhor um cordeiro de um ano de idade e sem defeito."),  (1883, 3, 23, 13, "Apresentem também uma oferta de cereal de dois jarros da melhor farinha amassada com óleo, oferta ao Senhor preparada no fogo, de aroma agradável, e uma oferta derramada de um litro de vinho."),  (1884, 3, 23, 14, "Vocês não poderão comer pão algum, nem cereal tostado, nem cereal novo, até o dia em que trouxerem essa oferta ao Deus de vocês. Este é um decreto perpétuo para as suas gerações, onde quer que morarem."),  (1885, 3, 23, 15, "A partir do dia seguinte ao sábado, o dia em que vocês trarão o feixe da oferta ritualmente movida, contem sete semanas completas."),  (1886, 3, 23, 16, "Contem cinqüenta dias, até um dia depois do sétimo sábado, e então apresentem uma oferta de cereal novo ao Senhor."),  (1887, 3, 23, 17, "Onde quer que morarem, tragam de casa dois pães feitos com dois jarros da melhor farinha, cozidos com fermento, como oferta movida dos primeiros frutos ao Senhor."),  (1888, 3, 23, 18, "Junto com os pães apresentem sete cordeiros, cada um com um ano de idade e sem defeito, um novilho e dois carneiros. Eles serão holocausto ao Senhor, juntamente com as suas ofertas de cereal e ofertas derramadas; é oferta preparada no fogo, de aroma agradável ao Senhor."),  (1889, 3, 23, 19, "Depois sacrifiquem um bode como oferta pelo pecado e dois cordeiros, cada um com um ano de idade, como oferta de comunhão."),  (1890, 3, 23, 20, "O sacerdote moverá os dois cordeiros perante o Senhor como gesto ritual de apresentação, juntamente com o pão dos primeiros frutos. São uma oferta sagrada ao Senhor que pertencem ao sacerdote."),  (1891, 3, 23, 21, "Naquele mesmo dia vocês proclamarão uma reunião sagrada e não realizarão trabalho algum. Este é um decreto perpétuo para as suas gerações, onde quer que vocês morarem."),  (1892, 3, 23, 22, "Quando fizerem a colheita da sua terra, não colham até às extremidades da sua lavoura, nem ajuntem as espigas caídas da sua colheita. Deixem-nas para o necessitado e para o estrangeiro. Eu sou o Senhor, o Deus de vocês."),  (1893, 3, 23, 23, "Disse o Senhor a Moisés:"),  (1894, 3, 23, 24, "Diga também aos israelitas: No dia primeiro do sétimo mês vocês terão um dia de descanso, uma reunião sagrada, comemorada com toques de trombeta."),  (1895, 3, 23, 25, "Não realizem trabalho algum, mas apresentem ao Senhor uma oferta preparada no fogo."),  (1896, 3, 23, 26, "Disse o Senhor a Moisés:"),  (1897, 3, 23, 27, "O décimo dia deste sétimo mês é o Dia da Expiação. Façam uma reunião sagrada e humilhem-se, e apresentem ao Senhor uma oferta preparada no fogo."),  (1898, 3, 23, 28, "Não realizem trabalho algum nesse dia, porque é o Dia da Expiação, quando se faz propiciação por vocês perante o Senhor, o Deus de vocês."),  (1899, 3, 23, 29, "Quem não se humilhar nesse dia será eliminado do seu povo."),  (1900, 3, 23, 30, "Eu destruirei do meio do seu povo todo aquele que realizar algum trabalho nesse dia."),  (1901, 3, 23, 31, "Vocês não realizarão trabalho algum. Este é um decreto perpétuo para as suas gerações, onde quer que vocês morarem."),  (1902, 3, 23, 32, "É um sábado de descanso para vocês, e vocês se humilharão. Desde o entardecer do nono dia do mês até ao entardecer do dia seguinte vocês guardarão esse sábado."),  (1903, 3, 23, 33, "Disse o Senhor a Moisés:"),  (1904, 3, 23, 34, "Diga ainda aos israelitas: No décimo quinto dia deste sétimo mês começa a Festa das Cabanas do Senhor, que dura sete dias."),  (1905, 3, 23, 35, "No primeiro dia haverá reunião sagrada; não realizem trabalho algum."),  (1906, 3, 23, 36, "Durante sete dias apresentem ao Senhor ofertas preparadas no fogo, e no oitavo dia façam outra reunião sagrada, e também apresentem ao Senhor uma oferta preparada no fogo. É reunião solene; não realizem trabalho algum."),  (1907, 3, 23, 37, "( Estas são as festas fixas do Senhor, que vocês proclamarão como reuniões sagradas para trazerem ao Senhor ofertas preparadas no fogo, holocaustos e ofertas de cereal, sacrifícios e ofertas derramadas exigidas para cada dia."),  (1908, 3, 23, 38, "Isso fora as do sábado do Senhor e fora as dádivas e votos de vocês, e todas as ofertas voluntárias que vocês derem ao Senhor. )"),  (1909, 3, 23, 39, "Assim, começando no décimo quinto dia do sétimo mês, depois de terem colhido o que a terra produziu, comemorem a festa do Senhor durante sete dias; o primeiro dia e também o oitavo serão dias de descanso."),  (1910, 3, 23, 40, "No primeiro dia vocês apanharão os melhores frutos das árvores, folhagem de tamareira, galhos frondosos e salgueiros, e se alegrarão perante o Senhor, o Deus de vocês, durante sete dias."),  (1911, 3, 23, 41, "Comemorem essa festa do Senhor durante sete dias todos os anos. Este é um decreto perpétuo para as suas gerações; comemorem-na no sétimo mês."),  (1912, 3, 23, 42, "Morem em tendas durante sete dias; todos os israelitas de nascimento morarão em tendas,"),  (1913, 3, 23, 43, "para que os descendentes de vocês saibam que eu fiz os israelitas morarem em tendas quando os tirei da terra do Egito. Eu sou o Senhor, o Deus de vocês."),  (1914, 3, 23, 44, "Assim anunciou Moisés aos israelitas as festas fixas do Senhor."),  (1915, 3, 24, 1, "Disse o Senhor a Moisés:"),  (1916, 3, 24, 2, "Ordene aos israelitas que lhe tragam azeite puro de oliva batida para as lâmpadas, para que fiquem sempre acesas."),  (1917, 3, 24, 3, "Na Tenda do Encontro, do lado de fora do véu que esconde as tábuas da aliança, Arão manterá as lâmpadas continuamente acesas diante do Senhor, desde o entardecer até a manhã seguinte. Este é um decreto perpétuo para as suas gerações."),  (1918, 3, 24, 4, "Mantenha sempre em ordem as lâmpadas no candelabro de ouro puro perante o Senhor."),  (1919, 3, 24, 5, "Apanhe da melhor farinha e asse doze pães, usando dois jarros para cada pão."),  (1920, 3, 24, 6, "Coloque-os em duas fileiras, com seis pães em cada uma, sobre a mesa de ouro puro perante o Senhor."),  (1921, 3, 24, 7, "Junto a cada fileira coloque um pouco de incenso puro como porção memorial para representar o pão e ser uma oferta ao Senhor preparada no fogo."),  (1922, 3, 24, 8, "Esses pães serão colocados regularmente perante o Senhor, cada sábado, em nome dos israelitas, como aliança perpétua."),  (1923, 3, 24, 9, "Pertencem a Arão e a seus descendentes, que os comerão num lugar sagrado, porque é parte santíssima de sua porção regular das ofertas dedicadas ao Senhor, preparadas no fogo. É decreto perpétuo."),  (1924, 3, 24, 10, "Aconteceu que o filho de uma israelita e de um egípcio saiu e foi para o meio dos israelitas. No acampamento houve uma briga entre ele e um israelita."),  (1925, 3, 24, 11, "O filho da israelita blasfemou o Nome com uma maldição; então o levaram a Moisés. O nome de sua mãe era Selomite, filha de Dibri, da tribo de Dã."),  (1926, 3, 24, 12, "Deixaram-no preso até que a vontade do Senhor lhes fosse declarada."),  (1927, 3, 24, 13, "Então o Senhor disse a Moisés:"),  (1928, 3, 24, 14, "Leve o que blasfemou para fora do acampamento. Todos aqueles que o ouviram colocarão as mãos sobre a cabeça dele, e a comunidade toda o apedrejará."),  (1929, 3, 24, 15, "Diga aos israelitas: Se alguém amaldiçoar seu Deus, será responsável pelo seu pecado;"),  (1930, 3, 24, 16, "quem blasfemar o nome do Senhor terá que ser executado. A comunidade toda o apedrejará. Seja estrangeiro, seja natural da terra, se blasfemar o Nome, terá que ser morto."),  (1931, 3, 24, 17, "Se alguém ferir uma pessoa a ponto de matá-la, terá que ser executado."),  (1932, 3, 24, 18, "Quem matar um animal fará restituição: vida por vida."),  (1933, 3, 24, 19, "Se alguém ferir seu próximo, deixando-o defeituoso, assim como fez lhe será feito:"),  (1934, 3, 24, 20, "fratura por fratura, olho por olho, dente por dente. Assim como feriu o outro, deixando-o defeituoso, assim também será ferido."),  (1935, 3, 24, 21, "Quem matar um animal fará restituição, mas quem matar um homem será morto."),  (1936, 3, 24, 22, "Vocês terão a mesma lei para o estrangeiro e para o natural. Eu sou o Senhor, o Deus de vocês."),  (1937, 3, 24, 23, "Depois que Moisés falou aos israelitas, levaram o que blasfemou para fora do acampamento e o apedrejaram. Os israelitas fizeram conforme o Senhor tinha ordenado a Moisés."),  (1938, 3, 25, 1, "Então disse o Senhor a Moisés no monte Sinai:"),  (1939, 3, 25, 2, "Diga o seguinte aos israelitas: Quando vocês entrarem na terra que lhes dou, a própria terra guardará um sábado para o Senhor."),  (1940, 3, 25, 3, "Durante seis anos semeiem as suas lavouras, aparem as suas vinhas e façam a colheita de suas plantações."),  (1941, 3, 25, 4, "Mas no sétimo ano a terra terá um sábado de descanso, um sábado dedicado ao Senhor. Não semeiem as suas lavouras, nem aparem as suas vinhas."),  (1942, 3, 25, 5, "Não colham o que crescer por si, nem colham as uvas das suas vinhas que não serão podadas. A terra terá um ano de descanso."),  (1943, 3, 25, 6, "Vocês se sustentarão do que a terra produzir no ano de descanso, você, o seu escravo, a sua escrava, o trabalhador contratado e o residente temporário que vive entre vocês,"),  (1944, 3, 25, 7, "bem como os seus rebanhos e os animais selvagens de sua terra. Tudo o que a terra produzir poderá ser comido."),  (1945, 3, 25, 8, "Contem sete semanas de anos, sete vezes sete anos; essas sete semanas de anos totalizam quarenta e nove anos."),  (1946, 3, 25, 9, "Então façam soar a trombeta no décimo dia do sétimo mês; no Dia da Expiação façam soar a trombeta por toda a terra de vocês."),  (1947, 3, 25, 10, "Consagrem o qüinquagésimo ano e proclamem libertação por toda a terra a todos os seus moradores. Este lhes será um ano de jubileu, quando cada um de vocês voltará para a propriedade da sua família e para o seu próprio clã."),  (1948, 3, 25, 11, "O quinquagésimo ano lhes será jubileu; não semeiem e não ceifem o que cresce por si mesmo nem colham das vinhas não podadas."),  (1949, 3, 25, 12, "É jubileu, e lhes será santo; comam apenas o que a terra produzir."),  (1950, 3, 25, 13, "Nesse ano do jubileu cada um de vocês voltará para a sua propriedade."),  (1951, 3, 25, 14, "Se vocês venderem alguma propriedade ao seu próximo ou se comprarem alguma propriedade dele, não explore o seu irmão."),  (1952, 3, 25, 15, "O que comprarem do seu próximo será avaliado com base no número de anos desde o Jubileu. E fará a venda com base no número de anos que restam de colheitas."),  (1953, 3, 25, 16, "Quando os anos forem muitos, vocês deverão aumentar o preço, mas quando forem poucos, deverão diminuir o preço, pois o que ele está lhes vendendo é o número de colheitas."),  (1954, 3, 25, 17, "Não explorem um ao outro, mas temam ao Deus de vocês. Eu sou o Senhor, o Deus de vocês."),  (1955, 3, 25, 18, "Pratiquem os meus decretos e obedeçam às minhas ordenanças, e vocês viverão com segurança na terra."),  (1956, 3, 25, 19, "Então a terra dará o seu fruto, e vocês comerão até fartar-se e ali viverão em segurança."),  (1957, 3, 25, 20, "Vocês poderão perguntar: ‘Que iremos comer no sétimo ano, se não plantarmos nem fizermos a colheita? ’"),  (1958, 3, 25, 21, "Saibam que eu lhes enviarei a minha bênção no sexto ano, e a terra produzirá o suficiente para três anos."),  (1959, 3, 25, 22, "Quando vocês estiverem plantando no oitavo ano, comerão ainda da colheita anterior e dela continuarão a comer até a colheita do nono ano."),  (1960, 3, 25, 23, "A terra não poderá ser vendida definitivamente, porque ela é minha, e vocês são apenas estrangeiros e imigrantes."),  (1961, 3, 25, 24, "Em toda terra em que tiverem propriedade, concedam o direito de resgate da terra."),  (1962, 3, 25, 25, "Se alguém do seu povo empobrecer e vender parte da sua propriedade, seu parente mais próximo virá e resgatará aquilo que o seu compatriota vendeu."),  (1963, 3, 25, 26, "Se, contudo, um homem não tiver quem lhe resgate a terra, mas ele mesmo prosperar e adquirir recursos para resgatá-la,"),  (1964, 3, 25, 27, "calculará os anos desde que a vendeu e devolverá a diferença àquele a quem a vendeu; então poderá voltar para a sua propriedade."),  (1965, 3, 25, 28, "Mas, se não adquirir recursos para devolver-lhe o valor, a propriedade que vendeu permanecerá em posse do comprador até o ano do jubileu. Será devolvida no Jubileu, e ele então poderá voltar para a sua propriedade."),  (1966, 3, 25, 29, "Se um homem vender uma casa numa cidade murada, terá o direito de resgate até que se complete um ano após a venda. Nesse período poderá resgatá-la."),  (1967, 3, 25, 30, "Se não for resgatada antes de se completar um ano, a casa da cidade murada pertencerá definitivamente ao comprador e aos seus descendentes; não será devolvida no Jubileu."),  (1968, 3, 25, 31, "Mas as casas dos povoados sem muros ao redor serão consideradas campo aberto. Poderão ser resgatadas e serão devolvidas no Jubileu."),  (1969, 3, 25, 32, "No caso das cidades dos levitas, eles sempre terão direito de resgatar suas casas nas cidades que lhes pertencem."),  (1970, 3, 25, 33, "Assim, a propriedade dos levitas, isto é, uma casa vendida em qualquer cidade deles, é resgatável e deverá ser devolvida no Jubileu, porque as casas das cidades dos levitas são propriedade deles entre os israelitas."),  (1971, 3, 25, 34, "Mas as pastagens pertencentes às suas cidades não serão vendidas; são propriedade permanente deles."),  (1972, 3, 25, 35, "Se alguém do seu povo empobrecer e não puder sustentar-se, ajudem-no como se faz ao estrangeiro e ao residente temporário, para que possa continuar a viver entre vocês."),  (1973, 3, 25, 36, "Não cobrem dele juro algum, mas temam o seu Deus, para que o seu próximo continue a viver entre vocês."),  (1974, 3, 25, 37, "Vocês não poderão exigir dele juros nem emprestar-lhe mantimento visando lucro."),  (1975, 3, 25, 38, "Eu sou o Senhor, o Deus de vocês, que os tirou da terra do Egito para dar-lhes a terra de Canaã e para ser o seu Deus."),  (1976, 3, 25, 39, "Se alguém do seu povo empobrecer e se vender a algum de vocês, não o façam trabalhar como escravo."),  (1977, 3, 25, 40, "Ele deverá ser tratado como trabalhador contratado ou como residente temporário; trabalhará para quem o comprou até o ano do jubileu."),  (1978, 3, 25, 41, "Então ele e os seus filhos estarão livres, e ele poderá voltar para o seu próprio clã e para a propriedade dos seus antepassados."),  (1979, 3, 25, 42, "Pois os israelitas são meus servos, a quem tirei da terra do Egito; não poderão ser vendidos como escravos."),  (1980, 3, 25, 43, "Não dominem impiedosamente sobre eles, mas temam o seu Deus."),  (1981, 3, 25, 44, "Os seus escravos e as suas escravas deverão vir dos povos que vivem ao redor de vocês; deles vocês poderão comprar escravos e escravas."),  (1982, 3, 25, 45, "Também poderão comprá-los entre os filhos dos residentes temporários que vivem entre vocês e entre os que pertencem aos clãs deles, ainda que nascidos na terra de vocês; eles se tornarão propriedade de vocês."),  (1983, 3, 25, 46, "Vocês poderão deixá-los como herança para os seus filhos e poderão fazê-los escravos para sempre, mas sobre os seus irmãos israelitas vocês não poderão dominar impiedosamente."),  (1984, 3, 25, 47, "Se um estrangeiro ou um residente temporário entre vocês enriquecer e alguém do seu povo empobrecer e se vender a esse estrangeiro ou a alguém que pertence ao clã desse estrangeiro,"),  (1985, 3, 25, 48, "manterá o direito de resgate mesmo depois de vender a si mesmo. Um dos seus parentes poderá resgatá-lo:"),  (1986, 3, 25, 49, "ou tio, ou primo, ou qualquer parente próximo poderá resgatá-lo. Se, todavia, prosperar, poderá resgatar a si mesmo."),  (1987, 3, 25, 50, "Ele e o seu comprador contarão o tempo desde o ano em que vendeu a si mesmo até o ano do jubileu. O preço do resgate se baseará no salário de um empregado contratado por aquele número de anos."),  (1988, 3, 25, 51, "Se restarem muitos anos, pagará o seu resgate proporcionalmente ao preço de compra."),  (1989, 3, 25, 52, "Se restarem apenas poucos anos até o ano do jubileu, fará o cálculo, e pagará o seu resgate proporcionalmente aos anos."),  (1990, 3, 25, 53, "Ele deverá ser tratado como um empregado contratado anualmente; não permitam que o seu senhor domine impiedosamente sobre ele."),  (1991, 3, 25, 54, "Se não for resgatado por nenhuma dessas maneiras, ele e os seus filhos estarão livres no ano do jubileu,"),  (1992, 3, 25, 55, "porque os israelitas são meus servos, os quais tirei da terra do Egito. Eu sou o Senhor, o Deus de vocês."),  (1993, 3, 26, 1, "Não façam ídolos, nem imagens, nem colunas sagradas para vocês, e não coloquem nenhuma pedra esculpida em sua terra para curvar-se diante dela. Eu sou o Senhor, o Deus de vocês."),  (1994, 3, 26, 2, "Guardem os meus sábados e reverenciem o meu santuário. Eu sou o Senhor."),  (1995, 3, 26, 3, "Se vocês seguirem os meus decretos e obedecerem aos meus mandamentos, e os colocarem em prática,"),  (1996, 3, 26, 4, "eu lhes mandarei chuva na estação certa, e a terra dará a sua colheita e as árvores do campo darão o seu fruto."),  (1997, 3, 26, 5, "A debulha prosseguirá até a colheita das uvas, e a colheita das uvas prosseguirá até a época da plantação, e vocês comerão até ficarem satisfeitos e viverão em segurança na terra de vocês."),  (1998, 3, 26, 6, "Estabelecerei paz na terra, e vocês se deitarão, e ninguém os amedrontará. Farei desaparecer da terra os animais selvagens, e a espada não passará pela terra de vocês."),  (1999, 3, 26, 7, "Vocês perseguirão os seus inimigos, e estes cairão à espada diante de vocês."),  (2000, 3, 26, 8, "Cinco de vocês perseguirão cem, cem de vocês perseguirão dez mil, e os seus inimigos cairão à espada diante de vocês."),  (2001, 3, 26, 9, "Eu me voltarei para vocês e os farei prolíferos; e os multiplicarei e guardarei a minha aliança com vocês."),  (2002, 3, 26, 10, "Vocês ainda estarão comendo da colheita armazenada no ano anterior, quando terão que se livrar dela para dar espaço para a nova colheita."),  (2003, 3, 26, 11, "Estabelecerei a minha habitação entre vocês e não os rejeitarei."),  (2004, 3, 26, 12, "Andarei entre vocês e serei o seu Deus, e vocês serão o meu povo."),  (2005, 3, 26, 13, "Eu sou o Senhor, o Deus de vocês, que os tirou da terra do Egito para que não mais fossem escravos deles; quebrei as traves do jugo que os prendia e os fiz andar de cabeça erguida. "),  (2006, 3, 26, 14, "Mas, se vocês não me ouvirem e não colocarem em prática todos esses mandamentos,"),  (2007, 3, 26, 15, "e desprezarem os meus decretos, rejeitarem as minhas ordenanças, deixarem de colocar em prática todos os meus mandamentos e forem infiéis à minha aliança,"),  (2008, 3, 26, 16, "então assim os tratarei: eu lhes trarei pavor repentino, doenças e febre que tirarão a visão e lhes definharão a vida. Vocês semearão inutilmente, porque os seus inimigos comerão as suas sementes."),  (2009, 3, 26, 17, "O meu rosto estará contra vocês, e vocês serão derrotados pelos inimigos; os seus adversários os dominarão, e vocês fugirão mesmo quando ninguém os estiver perseguindo."),  (2010, 3, 26, 18, "Se depois disso tudo vocês não me ouvirem, eu os castigarei sete vezes mais pelos seus pecados."),  (2011, 3, 26, 19, "Eu lhes quebrarei o orgulho rebelde e farei que o céu sobre vocês fique como ferro e a terra de vocês fique como bronze."),  (2012, 3, 26, 20, "A força de vocês será gasta em vão, porque a terra não lhes dará colheita, nem as árvores da terra lhes darão fruto."),  (2013, 3, 26, 21, "Se continuarem se opondo a mim e recusarem ouvir-me, eu os castigarei sete vezes mais, conforme os seus pecados."),  (2014, 3, 26, 22, "Mandarei contra vocês animais selvagens que matarão os seus filhos, acabarei com os seus rebanhos e reduzirei vocês a tão poucos que os seus caminhos ficarão desertos."),  (2015, 3, 26, 23, "Se apesar disso vocês não aceitarem a minha disciplina, mas continuarem a opor-se a mim,"),  (2016, 3, 26, 24, "eu mesmo me oporei a vocês e os castigarei sete vezes mais por causa dos seus pecados."),  (2017, 3, 26, 25, "E trarei a espada contra vocês para vingar a aliança. Quando se refugiarem em suas cidades, eu lhes mandarei uma praga, e vocês serão entregues em mãos inimigas."),  (2018, 3, 26, 26, "Quando eu lhes cortar o suprimento de pão, dez mulheres assarão o pão num único forno e repartirão o pão a peso. Vocês comerão, mas não ficarão satisfeitos."),  (2019, 3, 26, 27, "Se apesar disso tudo vocês ainda não me ouvirem, mas continuarem a opor-se a mim,"),  (2020, 3, 26, 28, "então com furor me oporei a vocês, e eu mesmo os castigarei sete vezes mais por causa dos seus pecados."),  (2021, 3, 26, 29, "Vocês comerão a carne dos seus filhos e das suas filhas."),  (2022, 3, 26, 30, "Destruirei os seus altares idólatras, despedaçarei os seus altares de incenso e empilharei os seus cadáveres sobre os seus ídolos mortos, e rejeitarei vocês."),  (2023, 3, 26, 31, "Deixarei as cidades de vocês em ruínas e arrasarei os seus santuários, e não terei prazer no aroma das suas ofertas."),  (2024, 3, 26, 32, "Desolarei a terra a ponto de ficarem perplexos os seus inimigos que vierem ocupá-la."),  (2025, 3, 26, 33, "Espalharei vocês entre as nações e desembainharei a espada contra vocês. Sua terra ficará desolada, e as suas cidades, em ruínas."),  (2026, 3, 26, 34, "Então a terra desfrutará os seus anos sabáticos enquanto estiver desolada e enquanto vocês estiverem na terra dos seus inimigos; e a terra descansará e desfrutará os seus sábados."),  (2027, 3, 26, 35, "Enquanto estiver desolada, a terra terá o descanso sabático que não teve quando vocês a habitaram."),  (2028, 3, 26, 36, "Quanto aos que sobreviverem, eu lhes encherei o coração de tanto medo na terra do inimigo, que o som de uma folha levada pelo vento os porá em fuga. Correrão como quem foge da espada, e cairão, sem que ninguém os persiga."),  (2029, 3, 26, 37, "Tropeçarão uns nos outros, como que fugindo da espada, sem que ninguém os esteja perseguindo. Assim vocês não poderão subsistir diante dos inimigos."),  (2030, 3, 26, 38, "Vocês perecerão entre as nações, e a terra dos seus inimigos os devorará."),  (2031, 3, 26, 39, "Os que sobreviverem apodrecerão na terra do inimigo por causa dos seus pecados, e também por causa dos pecados dos seus antepassados."),  (2032, 3, 26, 40, "Mas, se confessarem os seus pecados e os pecados dos seus antepassados, sua infidelidade e oposição a mim,"),  (2033, 3, 26, 41, "que me levaram a opor-me a eles e a enviá-los para a terra dos seus inimigos; se o seu coração obstinado se humilhar, e eles aceitarem o castigo do seu pecado,"),  (2034, 3, 26, 42, "eu me lembrarei da minha aliança com Jacó e da minha aliança com Isaque e da minha aliança com Abraão, e também me lembrarei da terra,"),  (2035, 3, 26, 43, "que por eles será abandonada e desfrutará os seus sábados enquanto permanecer desolada. Receberão o castigo pelos seus pecados porque desprezaram as minhas ordenanças e rejeitaram os meus decretos."),  (2036, 3, 26, 44, "Apesar disso, quando estiverem na terra do inimigo, não os desprezarei, nem os rejeitarei, para destruí-los totalmente, quebrando a minha aliança com eles, pois eu sou o Senhor, o Deus deles."),  (2037, 3, 26, 45, "Mas por amor deles eu me lembrarei da aliança com os seus antepassados que tirei da terra do Egito à vista das nações, para ser o Deus deles. Eu sou o Senhor. "),  (2038, 3, 26, 46, "São esses os decretos, as ordenanças e as leis que o Senhor estabeleceu no monte Sinai entre ele próprio e os israelitas, por intermédio de Moisés."),  (2039, 3, 27, 1, "Disse também o SENHOR a Moisés:"),  (2040, 3, 27, 2, "Diga o seguinte aos israelitas: Se alguém fizer um voto especial, dedicando pessoas ao Senhor, faça-o conforme o devido valor;"),  (2041, 3, 27, 3, "atribua aos homens entre vinte e sessenta anos o valor de seiscentos gramas de prata, com base no peso padrão do santuário;"),  (2042, 3, 27, 4, "e, se for mulher, atribua-lhe o valor de trezentos e sessenta gramas."),  (2043, 3, 27, 5, "Se for alguém que tenha entre cinco e vinte anos, atribua aos homens o valor de duzentos e quarenta gramas e às mulheres o valor de cento e vinte gramas."),  (2044, 3, 27, 6, "Se for alguém que tenha entre um mês e cinco anos de idade, atribua aos meninos o valor de sessenta gramas de prata e às meninas o valor de trinta e seis gramas de prata."),  (2045, 3, 27, 7, "Se for alguém que tenha de sessenta anos para cima, atribua aos homens o valor de cento e oitenta gramas e às mulheres o valor de cento e vinte gramas."),  (2046, 3, 27, 8, "Se quem fizer o voto for pobre demais para pagar o valor especificado, apresentará a pessoa ao sacerdote, que estabelecerá o valor de acordo com as possibilidades do homem que fez o voto."),  (2047, 3, 27, 9, "Se o que ele prometeu mediante voto for um animal aceitável como oferta ao Senhor, um animal assim dado ao Senhor torna-se santo."),  (2048, 3, 27, 10, "Ele não poderá trocá-lo nem substituir um animal ruim por um bom, nem um animal bom por um ruim; caso troque um animal por outro, tanto o substituto quanto o substituído se tornarão santos."),  (2049, 3, 27, 11, "Se o que ele prometeu mediante voto for um animal impuro, não aceitável como oferta ao Senhor, o animal será apresentado ao sacerdote,"),  (2050, 3, 27, 12, "que o avaliará por suas qualidades. A avaliação do sacerdote determinará o valor do animal."),  (2051, 3, 27, 13, "Se o dono desejar resgatar o animal, terá que acrescentar um quinto ao seu valor."),  (2052, 3, 27, 14, "Se um homem consagrar a sua casa ao Senhor, o sacerdote avaliará a casa por suas qualidades. A avaliação do sacerdote determinará o valor da casa."),  (2053, 3, 27, 15, "Se o homem que consagrar a sua casa quiser resgatá-la, terá que acrescentar um quinto ao seu valor, e a casa voltará a ser sua."),  (2054, 3, 27, 16, "Se um homem consagrar ao Senhor parte das terras da sua família, sua avaliação será de acordo com a semeadura: seiscentos gramas de prata para cada barril de semente de cevada."),  (2055, 3, 27, 17, "Se consagrar a sua terra durante o ano do jubileu, o valor será integral."),  (2056, 3, 27, 18, "Mas, se a consagrar depois do Jubileu, o sacerdote calculará o valor de acordo com o número de anos que faltarem para o próximo ano do jubileu, e o valor será reduzido."),  (2057, 3, 27, 19, "Se o homem que consagrar a sua terra desejar resgatá-la, terá que acrescentar um quinto ao seu valor, e a terra voltará a ser sua."),  (2058, 3, 27, 20, "Mas se não a resgatar, ou se a tiver vendido, não poderá mais ser resgatada;"),  (2059, 3, 27, 21, "quando a terra for liberada no Jubileu, será santa, consagrada ao Senhor, e se tornará propriedade dos sacerdotes."),  (2060, 3, 27, 22, "Se um homem consagrar ao Senhor terras que tenha comprado, terras que não fazem parte da propriedade da sua família,"),  (2061, 3, 27, 23, "o sacerdote determinará o valor de acordo com o tempo que falta para o ano do jubileu; o homem pagará o valor no mesmo dia, consagrando-o ao Senhor."),  (2062, 3, 27, 24, "No ano do jubileu as terras serão devolvidas àquele de quem ele as comprou."),  (2063, 3, 27, 25, "Todos os valores serão calculados com base no peso padrão do santuário, que são doze gramas."),  (2064, 3, 27, 26, "Ninguém poderá consagrar a primeira cria de um animal, pois já pertence ao Senhor; seja cria de vaca, seja de cabra, seja de ovelha, pertence ao Senhor."),  (2065, 3, 27, 27, "Mas se for a cria de um animal impuro, poderá resgatá-la pelo valor estabelecido, acrescentando um quinto a esse valor. Se não for resgatada, será vendida pelo valor estabelecido."),  (2066, 3, 27, 28, "Todavia, nada que um homem possua e consagre ao Senhor, seja homem, seja animal, sejam terras de sua propriedade, poderá ser vendido ou resgatado; todas as coisas assim consagradas são santíssimas ao Senhor."),  (2067, 3, 27, 29, "Nenhuma pessoa consagrada para a destruição poderá ser resgatada; terá que ser executada."),  (2068, 3, 27, 30, "Todos os dízimos da terra, seja dos cereais, seja das frutas das árvores, pertencem ao Senhor; são consagrados ao Senhor."),  (2069, 3, 27, 31, "Se um homem desejar resgatar parte do seu dízimo, terá que acrescentar um quinto ao seu valor."),  (2070, 3, 27, 32, "O dízimo dos seus rebanhos, um de cada dez animais que passem debaixo da vara do pastor, será consagrado ao Senhor."),  (2071, 3, 27, 33, "O dono não poderá retirar os bons dentre os ruins, nem fazer qualquer troca. Se fizer alguma troca, tanto o animal quanto o substituto se tornarão consagrados e não poderão ser resgatados."),  (2072, 3, 27, 34, "São esses os mandamentos que o Senhor ordenou a Moisés no monte Sinai para os israelitas."),  (2073, 9, 9, 3, "E aconteceu que jumentas de Quis, pai de Saul, extraviaram-se. E ele disse a Saul: Chame um dos servos e vá procurar as jumentas."),  (2074, 9, 31, 1, "E aconteceu que, em combate com os filisteus, os israelitas foram postos em fuga e muitos caíram mortos no monte Gilboa."),  (2075, 13, 1, 1, "Adão, Sete, Enos,"),  (2076, 13, 1, 2, "Cainã, Malaleel, Jarede,"),  (2077, 13, 1, 3, "Enoque, Matusalém, Lameque, Noé."),  (2078, 13, 1, 4, "Estes foram os filhos de Noé: Sem, Cam e Jafé."),  (2079, 13, 1, 5, "Estes foram os filhos de Jafé: Gômer, Magogue, Madai, Javã, Tubal, Meseque e Tirás."),  (2080, 13, 1, 6, "Estes foram os filhos de Gômer: Asquenaz, Rifate e Togarma."),  (2081, 13, 1, 7, "Estes foram os filhos de Javã: Elisá, Társis, Quitim e Rodanim."),  (2082, 13, 1, 8, "Estes foram os filhos de Cam: Cuxe, Mizraim, Fute e Canaã."),  (2083, 13, 1, 9, "Estes foram os filhos de Cuxe: Sebá, Havilá, Sabtá, Raamá e Sabtecá. Estes foram os filhos de Raamá: Sabá e Dedã."),  (2084, 13, 1, 10, "Cuxe gerou Ninrode, o primeiro homem poderoso na terra."),  (2085, 13, 1, 11, "Mizraim gerou os luditas, os anamitas, os leabitas, os naftuítas,"),  (2086, 13, 1, 12, "os patrusitas, os casluítas, dos quais se originaram os filisteus, e os caftoritas."),  (2087, 13, 1, 13, "Canaã gerou Sidom, seu filho mais velho, e Hete,"),  (2088, 13, 1, 14, "como também os jebuseus, os amorreus, os girgaseus,"),  (2089, 13, 1, 15, "os heveus, os arqueus, os sineus,"),  (2090, 13, 1, 16, "os arvadeus, os zemareus e os hamateus."),  (2091, 13, 1, 17, "Estes foram os filhos de Sem: Elão, Assur, Arfaxade, Lude e Arã. Estes foram os filhos de Arã: Uz, Hul, Géter e Meseque."),  (2092, 13, 1, 18, "Arfaxade gerou Salá, e este gerou Héber."),  (2093, 13, 1, 19, "A Héber nasceram dois filhos: Um deles se chamou Pelegue, porque em sua época a terra foi dividida; seu irmão chamou-se Joctã."),  (2094, 13, 1, 20, "Joctã gerou Almodá, Salefe, Hazarmavé, Jerá,"),  (2095, 13, 1, 21, "Hadorão, Uzal, Dicla,"),  (2096, 13, 1, 22, "Obal, Abimael, Sabá,"),  (2097, 13, 1, 23, "Ofir, Havilá e Jobabe. Todos esses foram filhos de Joctã."),  (2098, 13, 1, 24, "Sem, Arfaxade, Salá,"),  (2099, 13, 1, 25, "Héber, Pelegue, Reú,"),  (2100, 13, 1, 26, "Serugue, Naor, Terá"),  (2101, 13, 1, 27, "e Abrão, que é Abraão."),  (2102, 13, 1, 28, "Estes foram os filhos de Abraão: Isaque e Ismael."),  (2103, 13, 1, 29, "Foram estes os seus descendentes: Nebaiote, o filho mais velho de Ismael, Quedar, Adbeel, Mibsão,"),  (2104, 13, 1, 30, "Misma, Dumá, Massá, Hadade, Temá,"),  (2105, 13, 1, 31, "Jetur, Nafis e Quedemá. Esses foram os filhos de Ismael."),  (2106, 13, 1, 32, "Estes foram os filhos de Abraão com sua concubina Quetura: Zinrã, Jocsã, Medã, Midiã, Isbaque e Suá. Foram estes os filhos de Jocsã: Sabá e Dedã."),  (2107, 13, 1, 33, "Foram estes os filhos de Midiã: Efá, Éfer, Enoque, Abida e Elda. Todos esses foram descendentes de Quetura."),  (2108, 13, 1, 34, "Abraão gerou Isaque. Estes foram os filhos de Isaque: Esaú e Israel."),  (2109, 13, 1, 35, "Estes foram os filhos de Esaú: Elifaz, Reuel, Jeús, Jalão e Corá."),  (2110, 13, 1, 36, "Estes foram os filhos de Elifaz: Temã, Omar, Zefô, Gaetã e Quenaz; e Amaleque, de Timna, sua concumbina."),  (2111, 13, 1, 37, "Estes foram os filhos de Reuel: Naate, Zerá, Samá e Mizá."),  (2112, 13, 1, 38, "Estes foram os filhos de Seir: Lotã, Sobal, Zibeão, Aná, Disom, Eser e Disã. Lotã tinha uma irmã chamada Timna."),  (2113, 13, 1, 39, "Estes foram os filhos de Lotã: Hori e Homã."),  (2114, 13, 1, 40, "Estes foram os filhos de Sobal: Alvã, Manaate, Ebal, Sefô e Onã. Estes foram os filhos de Zibeão: Aiá e Aná."),  (2115, 13, 1, 41, "Este foi o filho de Aná: Disom. Estes foram os filhos de Disom: Hendã, Esbã, Itrã e Querã."),  (2116, 13, 1, 42, "Estes foram os filhos de Eser: Bilã, Zaavã e Acã. Estes foram os filhos de Disã: Uz e Arã."),  (2117, 13, 1, 43, "Estes foram os reis que reinaram no território de Edom antes que os israelitas tivessem um rei: Belá, filho de Beor. Sua cidade chamava-se Dinabá."),  (2118, 13, 1, 44, "Belá morreu, e Jobabe, filho de Zerá, de Bozra, foi o seu sucessor."),  (2119, 13, 1, 45, "Jobabe morreu, e Husã, da terra dos temanitas, foi o seu sucessor."),  (2120, 13, 1, 46, "Husã morreu, e Hadade, filho de Bedade, que tinha derrotado os midianitas na terra de Moabe, foi o seu sucessor. Sua cidade chamava-se Avite."),  (2121, 13, 1, 47, "Hadade morreu, e Samlá de Masreca foi o seu sucessor."),  (2122, 13, 1, 48, "Samlá morreu, e Saul, de Reobote, próxima ao Eufrates, foi o seu sucessor."),  (2123, 13, 1, 49, "Saul morreu, e Baal-Hanã, filho de Acbor, foi o seu sucessor."),  (2124, 13, 1, 50, "Baal-Hanã morreu, e Hadade foi o seu sucessor. Sua cidade chamava-se Paú, e o nome de sua mulher era Meetabel, filha de Matrede e neta de Mezaabe."),  (2125, 13, 1, 51, "Após a morte de Hadade, Edom foi governada pelos seguintes chefes: Timna, Alva, Jetete,"),  (2126, 13, 1, 52, "Oolibama, Elá, Pinom,"),  (2127, 13, 1, 53, "Quenaz, Temã, Mibzar,"),  (2128, 13, 1, 54, "Magdiel e Irã. Foram esses os chefes de Edom."),  (2129, 13, 2, 1, "Estes foram os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar, Zebulom,"),  (2130, 13, 2, 2, "Dã, José, Benjamim, Naftali, Gade e Aser."),  (2131, 13, 2, 3, "Estes foram os filhos de Judá: Er, Onã e Selá. Ele teve esses três filhos com uma mulher cananéia, a filha de Suá. Mas o Senhor reprovou a conduta perversa de Er, filho mais velho de Judá, e por isso o matou."),  (2132, 13, 2, 4, "Tamar, nora de Judá, deu-lhe os filhos Perez e Zerá. A Judá nasceram ao todo cinco filhos."),  (2133, 13, 2, 5, "Estes foram os filhos de Perez: Hezrom e Hamul."),  (2134, 13, 2, 6, "Estes foram os filhos de Zerá: Zinri, Etã, Hemã, Calcol e Darda. Foram cinco ao todo."),  (2135, 13, 2, 7, "O filho de Carmi foi Acar. Ele causou desgraça a Israel ao violar a proibição de se apossar das coisas consagradas."),  (2136, 13, 2, 8, "Este foi o filho de Etã: Azarias."),  (2137, 13, 2, 9, "Os filhos que nasceram a Hezrom foram Jerameel, Rão e Calebe."),  (2138, 13, 2, 10, "Rão gerou Aminadabe, e Aminadabe gerou Naassom, o líder da tribo de Judá."),  (2139, 13, 2, 11, "Naassom gerou Salmom, Salmom gerou Boaz,"),  (2140, 13, 2, 12, "Boaz gerou Obede, e Obede gerou Jessé."),  (2141, 13, 2, 13, "Jessé gerou Eliabe, o seu filho mais velho; o segundo foi Abinadabe, o terceiro Siméia,"),  (2142, 13, 2, 14, "o quarto Natanael, o quinto Radai,"),  (2143, 13, 2, 15, "o sexto Ozém, e o sétimo Davi."),  (2144, 13, 2, 16, "As irmãs deles foram Zeruia e Abigail. Os três filhos de Zeruia foram Abisai, Joabe e Asael."),  (2145, 13, 2, 17, "Abigail deu à luz Amasa, filho do ismaelita Jéter."),  (2146, 13, 2, 18, "Calebe, filho de Hezrom, teve uma filha chamada Jeriote com sua mulher Azuba. Estes foram os filhos de Azuba: Jeser, Sobabe e Ardom."),  (2147, 13, 2, 19, "Quando Azuba morreu, Calebe tomou por mulher a Efrate, com quem teve Hur."),  (2148, 13, 2, 20, "Hur gerou Uri, e Uri gerou Bezalel."),  (2149, 13, 2, 21, "Depois disso, Hezrom, aos sessenta anos, tomou por mulher a filha de Maquir, pai de Gileade e ela deu-lhe um filho chamado Segube."),  (2150, 13, 2, 22, "Segube gerou Jair, que governou vinte e três cidades em Gileade."),  (2151, 13, 2, 23, "Gesur e Arã conquistaram Havote-Jair, bem como Quenate e os povoados ao redor, ao todo sessenta cidades. Todos esses foram descendentes de Maquir, pai de Gileade."),  (2152, 13, 2, 24, "Depois que Hezrom morreu em Calebe-Efrata, Abia, a mulher de Hezrom, deu-lhe Asur, fundador de Tecoa."),  (2153, 13, 2, 25, "Estes foram os filhos de Jerameel, o filho mais velho de Hezrom: Rão, o mais velho, Buna, Orém, Ozém e Aías."),  (2154, 13, 2, 26, "Jerameel teve outra mulher, chamada Atara, que foi a mãe de Onã."),  (2155, 13, 2, 27, "Estes foram os filhos de Rão, o filho mais velho de Jerameel: Maaz, Jamim e Equer."),  (2156, 13, 2, 28, "Estes foram os filhos de Onã: Samai e Jada. Estes foram os filhos de Samai: Nadabe e Abisur."),  (2157, 13, 2, 29, "O nome da mulher de Abisur era Abiail. Ela deu-lhe dois filhos: Abã e Molide."),  (2158, 13, 2, 30, "Estes foram os filhos de Nadabe: Selede e Apaim. Selede morreu sem filhos."),  (2159, 13, 2, 31, "O filho de Apaim foi Isi, pai de Sesã, pai de Alai."),  (2160, 13, 2, 32, "Estes foram os filhos de Jada, irmão de Samai: Jéter e Jônatas. Jéter morreu sem filhos."),  (2161, 13, 2, 33, "Estes foram os filhos de Jônatas: Pelete e Zaza. Foram esses os descendentes de Jera-meel."),  (2162, 13, 2, 34, "Sesã não teve filhos, apenas filhas. Tinha ele um escravo egípcio chamado Jará,"),  (2163, 13, 2, 35, "a quem deu uma de suas filhas por mulher. E ela deu-lhe um filho chamado Atai."),  (2164, 13, 2, 36, "Atai gerou Natã, Natã gerou Zabade,"),  (2165, 13, 2, 37, "Zabade gerou Eflal, Eflal gerou Obede,"),  (2166, 13, 2, 38, "Obede gerou Jeú, Jeú gerou Azarias,"),  (2167, 13, 2, 39, "Azarias gerou Helez, Helez gerou Eleasa,"),  (2168, 13, 2, 40, "Eleasa gerou Sismai, Sismai gerou Salum,"),  (2169, 13, 2, 41, "Salum gerou Jecamias, e Jecamias gerou Elisama."),  (2170, 13, 2, 42, "Estes foram os filhos de Calebe, irmão de Jerameel: Messa, o mais velho, que foi o pai de Zife, e seu filho Maressa, pai de Hebrom."),  (2171, 13, 2, 43, "Estes foram os filhos de Hebrom: Corá, Tapua, Requém e Sema."),  (2172, 13, 2, 44, "Sema gerou Raão, pai de Jorqueão. Requém gerou Samai."),  (2173, 13, 2, 45, "O filho de Samai foi Maom, e Maom foi o pai de Bete-Zur."),  (2174, 13, 2, 46, "A concubina de Calebe, Efá teve três filhos: Harã, Mosa e Gazez. Harã gerou Gazez."),  (2175, 13, 2, 47, "Estes foram os filhos de Jadai: Regém, Jotão, Gesã, Pelete, Efá e Saafe."),  (2176, 13, 2, 48, "A concubina de Calebe, Maaca teve dois filhos: Seber e Tiraná."),  (2177, 13, 2, 49, "Ela também teve Saafe, pai de Madmana, e Seva, pai de Macbena e de Gibeá. A filha de Calebe chamava-se Acsa."),  (2178, 13, 2, 50, "Calebe teve também estes outros descendentes: Os filhos de Hur, o filho mais velho de Efrate: Sobal, fundador de Quiriate-Jearim,"),  (2179, 13, 2, 51, "Salma, fundador de Belém, e Harefe, fundador de Bete-Gader."),  (2180, 13, 2, 52, "Os descendentes de Sobal, fundador de Quiriate-Jearim: O povo de Haroé, metade dos manaatitas,"),  (2181, 13, 2, 53, "e os clãs de Quiriate-Jearim: os itritas, os fateus, os sumateus e os misraeus. Desses descenderam os zoratitas e os estaoleus."),  (2182, 13, 2, 54, "Os descendentes de Salma: O povo de Belém e de Atrote-Bete-Joabe, os netofatitas, metade dos manaatitas, os zoreus,"),  (2183, 13, 2, 55, "e os clãs dos escribas que viviam em Jabez: os tiratitas, os simeatitas e os sucatitas. Esses foram os queneus, descendentes de Hamate, antepassado da família de Recabe."),  (2184, 13, 3, 1, "Estes foram os filhos de Davi nascidos em Hebrom: O seu filho mais velho era Amnom, filho de Ainoã de Jezreel; o segundo, Daniel, de Abigail, de Carmelo;"),  (2185, 13, 3, 2, "o terceiro, Absalão, de Maaca, filha de Talmai, rei de Gesur; o quarto, Adonias, de Hagite;"),  (2186, 13, 3, 3, "o quinto, Sefatias, de Abital; e o sexto, Itreão, de sua mulher Eglá."),  (2187, 13, 3, 4, "São esses os seis filhos de Davi que nasceram em Hebrom, onde ele reinou sete anos e seis meses. E, em Jerusalém,"),  (2188, 13, 3, 5, "onde Davi reinou trinta e três anos, nasceram-lhe os seguintes filhos: Siméia, Sobabe, Natã e Salomão, os quatro filhos que ele teve com Bate-Seba, filha de Amiel."),  (2189, 13, 3, 6, "Davi teve ainda mais nove filhos: Ibar, Elisua, Elpalete,"),  (2190, 13, 3, 7, "Nogá, Nefegue, Jafia,"),  (2191, 13, 3, 8, "Elisama, Eliada e Elifelete."),  (2192, 13, 3, 9, "Todos esses foram filhos de Davi, sem contar os filhos que teve com suas concubinas, e sua filha Tamar, irmã deles."),  (2193, 13, 3, 10, "O filho de Salomão foi Roboão; o filho de Roboão foi Abias; o filho de Abias, Asa; o filho de Asa, Josafá;"),  (2194, 13, 3, 11, "o filho de Josafá, Jeorão; o filho de Jeorão, Acazias; o filho de Acazias, Joás;"),  (2195, 13, 3, 12, "o filho de Joás, Amazias; o filho de Amazias, Azarias; o filho de Azarias, Jotão;"),  (2196, 13, 3, 13, "o filho de Jotão, Acaz; o filho de Acaz, Ezequias; o filho de Ezequias, Manassés;"),  (2197, 13, 3, 14, "o filho de Manassés, Amom; o filho de Amom, Josias."),  (2198, 13, 3, 15, "Os filhos de Josias foram: Joanã, o primeiro, Jeoaquim, o segundo, Zedequias, o terceiro, e Salum, o quarto."),  (2199, 13, 3, 16, "Os sucessores de Jeoaquim foram: Joaquim e Zedequias."),  (2200, 13, 3, 17, "Estes foram os filhos de Joaquim, que foi levado para o cativeiro: Sealtiel,"),  (2201, 13, 3, 18, "Malquirão, Pedaías, Senazar, Jecamias, Hosama e Nedabias."),  (2202, 13, 3, 19, "Estes foram os filhos de Pedaías: Zorobabel e Simei. Estes foram os filhos de Zorobabel: Mesulão, Hananias e Selomite, irmã deles."),  (2203, 13, 3, 20, "Teve ainda mais cinco filhos: Hasubá, Oel, Berequias, Hasadias e Jusabe-Hesede."),  (2204, 13, 3, 21, "Estes foram os descendentes de Hananias: Pelatias e Jesaías, e os filhos de Refaías, de Arnã, de Obadias e de Secanias."),  (2205, 13, 3, 22, "Estes foram os descendentes de Secanias: Semaías e seus filhos Hatus, Igal, Bariá, Nearias e Safate; seis descendentes ao todo."),  (2206, 13, 3, 23, "Estes foram os três filhos de Nearias: Elioenai, Ezequias e Azricão."),  (2207, 13, 3, 24, "Estes foram os sete filhos de Elioenai: Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías e Anani."),  (2208, 13, 4, 1, "Estes foram os descendentes de Judá: Perez, Hezrom, Carmi, Hur e Sobal."),  (2209, 13, 4, 2, "Reaías, filho de Sobal, gerou Jaate, e Jaate gerou Aumai e Laade. Esses foram os clãs dos zoratitas."),  (2210, 13, 4, 3, "Estes foram os filhos de Etã: Jezreel, Isma e Idbás. A irmã deles chamava-se Hazelelponi."),  (2211, 13, 4, 4, "Depois teve Penuel, pai de Gedor, e Ézer, pai de Husá. Esses foram os descendentes de Hur, o filho mais velho de Efrate e pai de Belém."),  (2212, 13, 4, 5, "Asur, fundador de Tecoa, teve duas mulheres: Helá e Naará."),  (2213, 13, 4, 6, "Naará lhe deu Auzã, Héfer, Temeni e Haastari. Esses foram os filhos de Naará."),  (2214, 13, 4, 7, "Estes foram os filhos de Helá: Zerete, Zoar, Etnã"),  (2215, 13, 4, 8, "e Coz, que gerou Anube e Zobeba e os clãs de Aarel, filho de Harum."),  (2216, 13, 4, 9, "Jabez foi o homem mais respeitado de sua família. Sua mãe lhe deu o nome de Jabez, dizendo: Com muitas dores o dei à luz."),  (2217, 13, 4, 10, "Jabez orou ao Deus de Israel: Ah, abençoa-me e aumenta as minhas terras! Que a tua mão esteja comigo, guardando-me de males e livrando-me de dores. E Deus atendeu ao seu pedido."),  (2218, 13, 4, 11, "Quelube, irmão de Suá, gerou Meir, pai de Estom."),  (2219, 13, 4, 12, "Estom gerou Bete-Rafa, Paséia e Teína, fundador de Ir-Naás. Esses habitaram em Reca."),  (2220, 13, 4, 13, "Estes foram os filhos de Quenaz: Otoniel e Seraías. Estes foram os filhos de Otoniel: Hatate e Meonotai."),  (2221, 13, 4, 14, "Meonotai gerou Ofra. Seraías gerou Joabe, fundador de Ge-Harasim que recebeu esse nome porque os seus habitantes eram artesãos."),  (2222, 13, 4, 15, "Estes foram os filhos de Calebe, filho de Jefoné: Iru, Elá e Naã. O filho de Elá foi Quenaz."),  (2223, 13, 4, 16, "Estes foram os filhos de Jealelel: Zife, Zifa, Tiria e Asareel."),  (2224, 13, 4, 17, "Estes foram os filhos de Ezra: Jéter, Merede, Éfer e Jalom. Merede casou-se com Bitia, filha do faraó, e teve os seguintes filhos: Miriã, Samai e Isbá, fundador de Estemoa."),  (2225, 13, 4, 18, "Sua mulher judia deu à luz a Jerede, fundador de Gedor, a Héber, fundador de Socó, e a Jecutiel, fundador de Zanoa."),  (2226, 13, 4, 19, "Estes foram os filhos da mulher de Hodias, irmã de Naã: o pai de Queila, o garmita, e Estemoa, o maacatita."),  (2227, 13, 4, 20, "Estes foram os filhos de Simão: Amnom, Rina, Bene-Hanã e Tilom. Estes foram os filhos de Isi: Zoete e Ben-Zoete."),  (2228, 13, 4, 21, "Estes foram os filhos de Selá, filho de Judá: Er, pai de Leca; Lada, pai de Maressa. Selá também foi antepassado dos clãs dos que trabalhavam com linho em Bete-Asbéia,"),  (2229, 13, 4, 22, "de Joquim, dos homens de Cozeba, de Joás e de Sarafe, que governavam em Moabe e Jasubi-Leém. ( Estes registros são de épocas antigas. )"),  (2230, 13, 4, 23, "Eles eram oleiros e habitavam em Netaim e em Gederá, perto do rei, para quem trabalhavam."),  (2231, 13, 4, 24, "Estes foram os filhos de Simeão: Nemuel, Jamim, Jaribe, Zerá e Saul;"),  (2232, 13, 4, 25, "O filho de Saul era Salum, pai de Mibsão, que foi o pai de Misma."),  (2233, 13, 4, 26, "Estes foram os descendentes de Misma: seu filho Hamuel, pai de Zacur, que foi o pai de Simei."),  (2234, 13, 4, 27, "Simei teve dezesseis filhos e seis filhas, mas seus irmãos não tiveram muitos filhos; por isso todos os seus clãs não se igualam em número à tribo de Judá."),  (2235, 13, 4, 28, "Eles viviam em Berseba, Moladá, Hazar-Sual,"),  (2236, 13, 4, 29, "Bila, Ezém, Tolade,"),  (2237, 13, 4, 30, "Betuel, Hormá, Ziclague,"),  (2238, 13, 4, 31, "Bete-Marcabote, Hazar-Susim, Bete-Biri e Saaraim. Essas foram as suas cidades até o reinado de Davi."),  (2239, 13, 4, 32, "Tinham também as cinco cidades de Etã, Aim, Rimom, Toquém e Asã,"),  (2240, 13, 4, 33, "com todos os povoados ao redor delas até Baalate. Nessas cidades viviam e mantinham um registro genealógico."),  (2241, 13, 4, 34, "Mesobabe, Janleque, Josa, filho de Amazias,"),  (2242, 13, 4, 35, "Joel, Jeú, filho de Josibias, neto de Seraías e bisneto de Asiel;"),  (2243, 13, 4, 36, "também Elioenai, Jaacobá, Jesoaías, Asaías, Adiel, Jesimiel, Benaia,"),  (2244, 13, 4, 37, "e Ziza, filho de Sifi, neto de Alom, bisneto de Jedaías, trineto de Sinri e tetraneto de Semaías."),  (2245, 13, 4, 38, "Essa é a lista dos líderes dos seus clãs. Suas famílias cresceram muito,"),  (2246, 13, 4, 39, "e por isso foram para os arredores de Gedor, a leste do vale, em busca de pastagens para os seus rebanhos."),  (2247, 13, 4, 40, "Encontraram muitas pastagens boas, numa região vasta, pacífica e tranqüila, onde alguns camitas tinham vivido anteriormente."),  (2248, 13, 4, 41, "Durante o reinado de Ezequias, rei de Judá, esses homens aqui alistados chegaram e atacaram os camitas e os meunitas da região e os destruíram totalmente, como até hoje se pode ver. Depois ocuparam o lugar daqueles povos, pois havia pastagens para os seus rebanhos."),  (2249, 13, 4, 42, "E quinhentos desses simeonitas, liderados por Pelatias, Nearias, Refaías e Uziel, filhos de Isi, invadiram as colinas de Seir."),  (2250, 13, 4, 43, "Eles mataram o restante dos amalequitas que tinha escapado, e ali vivem até hoje."),  (2251, 13, 5, 1, "Estes são os filhos de Rúben, o filho mais velho de Israel. ( De fato, ele era o mais velho, mas, por ter desonrado o leito de seu pai, seus direitos de filho mais velho foram dados aos filhos de José, filho de Israel, de modo que não foi alistado nos registros genealógicos como o primeiro filho."),  (2252, 13, 5, 2, "Embora Judá tenha sido o mais poderoso de seus irmãos e dele tenha vindo um líder, os direitos de filho mais velho foram dados a José )."),  (2253, 13, 5, 3, "Os filhos de Rúben, filho mais velho de Israel, foram: Enoque, Palu, Hezrom e Carmi."),  (2254, 13, 5, 4, "Estes foram os descendentes de Joel: Seu filho Semaías, pai de Gogue, que foi o pai de Simei,"),  (2255, 13, 5, 5, "pai de Mica, que foi o pai de Reaías, pai de Baal,"),  (2256, 13, 5, 6, "que foi o pai de Beera, a quem Tiglate-Pileser, rei da Assíria levou para o exílio. Beera era um líder da tribo de Rúben."),  (2257, 13, 5, 7, "Estes foram os parentes dele, de acordo com seus clãs, alistados conforme os seus registros genealógicos: Jeiel, o chefe, Zacarias"),  (2258, 13, 5, 8, "e Belá, filho de Azaz, neto de Sema e bisneto de Joel. Eles foram viver na região que vai desde Aroer até o monte Nebo e Baal-Meom."),  (2259, 13, 5, 9, "A leste ocuparam a terra que vai até o deserto que se estende na direção do rio Eufrates, pois os seus rebanhos tinham aumentado muito em Gileade."),  (2260, 13, 5, 10, "Durante o reinado de Saul eles entraram em guerra contra os hagarenos e os derrotaram, passando a ocupar o acampamento deles por toda a região a leste de Gileade."),  (2261, 13, 5, 11, "Ao lado da tribo de Rúben ficou a tribo de Gade, desde a região de Basã até Salcá."),  (2262, 13, 5, 12, "Joel foi o primeiro chefe de clãs em Basã, Safã, o segundo; os outros foram Janai e Safate."),  (2263, 13, 5, 13, "Estes foram os parentes deles, por famílias: Micael, Mesulão, Seba, Jorai, Jacã, Zia e Héber. Eram sete ao todo."),  (2264, 13, 5, 14, "Eles eram descendentes de Abiail, filho de Huri, neto de Jaroa, bisneto de Gileade e trineto de Micael, que foi filho de Jesisai, neto de Jado e bisneto de Buz."),  (2265, 13, 5, 15, "Aí, filho de Abdiel e neto de Guni, foi o chefe dessas famílias."),  (2266, 13, 5, 16, "A tribo de Gade habitou em Gileade, em Basã e seus povoados, e em toda a extensão das terras de pastagem de Sarom."),  (2267, 13, 5, 17, "Todos esses entraram nos registros genealógicos durante os reinados de Jotão, rei de Judá, e de Jeroboão, rei de Israel."),  (2268, 13, 5, 18, "As tribos de Rúben, Gade e a metade da tribo de Manassés tinham juntas quarenta e quatro mil e setecentos e sessenta homens de combate, capazes de empunhar escudo e espada, de usar o arco, e treinados para a guerra."),  (2269, 13, 5, 19, "Eles entraram em guerra contra os hagarenos e seus aliados Jetur, Nafis e Nodabe."),  (2270, 13, 5, 20, "Durante a batalha clamaram a Deus, que os ajudou, entregando os hagarenos e todos os seus aliados nas suas mãos. Deus os atendeu, porque confiaram nele."),  (2271, 13, 5, 21, "Tomaram dos hagarenos o rebanho de cinqüenta mil camelos, duzentas e cinqüenta mil ovelhas e dois mil jumentos. Também fizeram cem mil prisioneiros."),  (2272, 13, 5, 22, "E muitos foram os inimigos mortos, pois a batalha era de Deus. Eles ocuparam aquela terra até a época do exílio."),  (2273, 13, 5, 23, "A metade da tribo de Manassés era numerosa e se estabeleceu na região que vai de Basã a Baal-Hermom, isto é, até Senir, o monte Hermom."),  (2274, 13, 5, 24, "Estes eram os chefes das famílias dessa tribo: Éfer, Isi, Eliel, Azriel, Jeremias, Hodavias e Jadiel. Eram soldados valentes, homens famosos, e chefes das famílias."),  (2275, 13, 5, 25, "Mas foram infiéis para com o Deus dos seus antepassados e se prostituíram, seguindo os deuses dos povos que Deus tinha destruído diante deles."),  (2276, 13, 5, 26, "Por isso o Deus de Israel incitou Pul, que é Tiglate-Pileser, rei da Assíria, a levar as tribos de Rúben, de Gade e a metade da tribo de Manassés para Hala, para Habor, para Hara e para o rio Gozã, onde estão até hoje."),  (2277, 13, 6, 1, "Estes foram os filhos de Levi: Gérson, Coate e Merari."),  (2278, 13, 6, 2, "Estes foram os filhos de Coate: Anrão, Isar, Hebrom e Uziel."),  (2279, 13, 6, 3, "Estes foram os filhos de Anrão: Arão, Moisés e Miriã. Estes foram os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar."),  (2280, 13, 6, 4, "Eleazar gerou Finéias, Finéias gerou Abisua,"),  (2281, 13, 6, 5, "Abisua gerou Buqui, Buqui gerou Uzi,"),  (2282, 13, 6, 6, "Uzi gerou Zeraías, Zeraías gerou Meraiote,"),  (2283, 13, 6, 7, "Meraiote gerou Amarias, Amarias gerou Aitube,"),  (2284, 13, 6, 8, "Aitube gerou Zadoque, Zadoque gerou Aimaás,"),  (2285, 13, 6, 9, "Aimaás gerou Azarias, Azarias gerou Joanã,"),  (2286, 13, 6, 10, "Joanã gerou Azarias que foi sacerdote no templo construído por Salomão em Jerusalém;"),  (2287, 13, 6, 11, "Azarias gerou Amarias, Amarias gerou Aitube,"),  (2288, 13, 6, 12, "Aitube gerou Zadoque, Zadoque gerou Salum,"),  (2289, 13, 6, 13, "Salum gerou Hilquias, Hilquias gerou Azarias,"),  (2290, 13, 6, 14, "Azarias gerou Seraías, e Seraías gerou Jeozadaque."),  (2291, 13, 6, 15, "Jeozadaque foi levado prisioneiro quando o Senhor enviou Judá e Jerusalém para o exílio por meio de Nabucodonosor."),  (2292, 13, 6, 16, "Estes foram os filhos de Levi: Gérson, Coate e Merari."),  (2293, 13, 6, 17, "Estes são os nomes dos filhos de Gérson: Libni e Simei."),  (2294, 13, 6, 18, "Estes foram os filhos de Coate: Anrão, Isar, Hebrom e Uziel."),  (2295, 13, 6, 19, "Estes foram os filhos de Merari: Mali e Musi. Estes são os clãs dos levitas alistados de acordo com os seus antepassados:"),  (2296, 13, 6, 20, "De Gérson: Seu filho Libni, que foi o pai de Jaate, pai de Zima,"),  (2297, 13, 6, 21, "que foi o pai de Joá, pai de Ido, pai de Zerá, que foi o pai de Jeaterai."),  (2298, 13, 6, 22, "De Coate: Seu filho Aminadabe, pai de Corá, que foi o pai de Assir,"),  (2299, 13, 6, 23, "pai de Elcana, pai de Ebiasafe, que foi o pai de Assir,"),  (2300, 13, 6, 24, "pai de Taate, pai de Uriel, pai de Uzias, que foi o pai de Saul."),  (2301, 13, 6, 25, "De Elcana: Amasai, Aimote"),  (2302, 13, 6, 26, "e Elcana, pai de Zofai, pai de Naate,"),  (2303, 13, 6, 27, "que foi o pai de Eliabe, pai de Jeroão, pai de Elcana, que foi o pai de Samuel."),  (2304, 13, 6, 28, "De Samuel: Joel, o mais velho, e Abias, o segundo."),  (2305, 13, 6, 29, "De Merari: Mali, pai de Libni, pai de Simei, que foi o pai de Uzá,"),  (2306, 13, 6, 30, "pai de Siméia, pai de Hagias, que foi o pai de Asaías."),  (2307, 13, 6, 31, "Estes são os homens a quem Davi encarregou de dirigir os cânticos no templo do Senhor depois que a arca foi levada para lá."),  (2308, 13, 6, 32, "Eles ministravam o louvor diante do tabernáculo, da Tenda do Encontro, até quando Salomão construiu o templo do Senhor em Jerusalém. Eles exerciam suas funções de acordo com as normas estabelecidas."),  (2309, 13, 6, 33, "Estes são os que ministravam, junto com seus filhos: Dentre os coatitas: O músico Hemã, filho de Joel, filho de Samuel,"),  (2310, 13, 6, 34, "filho de Elcana, filho de Jeroão, filho de Eliel, filho de Toá,"),  (2311, 13, 6, 35, "filho de Zufe, filho de Elcana, filho de Maate, filho de Amasai,"),  (2312, 13, 6, 36, "filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias"),  (2313, 13, 6, 37, "filho de Taate, filho de Assir, filho de Ebiasafe, filho de Corá,"),  (2314, 13, 6, 38, "filho de Isar, filho de Coate, filho de Levi, filho de Israel."),  (2315, 13, 6, 39, "À direita de Hemã, ficava seu parente Asafe, filho de Berequias, filho de Siméia,"),  (2316, 13, 6, 40, "filho de Micael, filho de Baaséias, filho de Malquias,"),  (2317, 13, 6, 41, "filho de Etni, filho de Zerá, filho de Adaías,"),  (2318, 13, 6, 42, "filho de Etã, filho de Zima, filho de Simei,"),  (2319, 13, 6, 43, "filho de Jaate, filho de Gérson, filho de Levi."),  (2320, 13, 6, 44, "Dentre os meraritas: À esquerda de Hemã, parente dos meraritas, ficava Etã, filho de Quisi, filho de Abdi, filho de Maluque,"),  (2321, 13, 6, 45, "filho de Hasabias, filho de Amazias, filho de Hilquias,"),  (2322, 13, 6, 46, "filho de Anzi, filho de Bani, filho de Sêmer,"),  (2323, 13, 6, 47, "filho de Mali, filho de Musi, filho de Merari, filho de Levi."),  (2324, 13, 6, 48, "Seus parentes, os outros levitas, foram encarregados de cuidar de todo o serviço do tabernáculo, o templo de Deus."),  (2325, 13, 6, 49, "Mas era Arão e seus descendentes que cuidavam dos sacrifícios no altar do holocausto e das ofertas no altar de incenso e de todo o serviço do Lugar Santíssimo, e dos sacrifícios de propiciação por Israel, conforme tudo o que Moisés, servo de Deus, tinha ordenado."),  (2326, 13, 6, 50, "Estes foram os descendentes de Arão: o seu filho Eleazar, pai de Finéias, que foi o pai de Abisua,"),  (2327, 13, 6, 51, "pai de Buqui, pai de Uzi, que foi o pai de Zeraías,"),  (2328, 13, 6, 52, "pai de Meraiote, pai de Amarias, que foi o pai de Aitube,"),  (2329, 13, 6, 53, "pai de Zadoque, pai de Aimaás."),  (2330, 13, 6, 54, "Estas foram as cidades e as regiões dadas aos levitas para nelas habitarem. Dentre os descendentes de Arão, o clã coatita foi sorteado primeiro;"),  (2331, 13, 6, 55, "foi-lhe dada Hebrom, em Judá, com suas pastagens ao redor."),  (2332, 13, 6, 56, "Mas os campos e os povoados em torno da cidade foram dados a Calebe, filho de Jefoné."),  (2333, 13, 6, 57, "Assim os descendentes de Arão receberam Hebrom, cidade de refúgio, e Libna, Jatir, Estemoa,"),  (2334, 13, 6, 58, "Hilém, Debir,"),  (2335, 13, 6, 59, "Asã, Jutá e Bete-Semes, com suas respectivas pastagens."),  (2336, 13, 6, 60, "E da tribo de Benjamim receberam Gibeão, Geba, Alemete e Anatote, com suas respectivas pastagens. Ao todo treze cidades foram distribuídas entre os seus clãs."),  (2337, 13, 6, 61, "Para os demais descendentes de Coate foram sorteadas dez cidades pertencentes aos clãs da metade da tribo de Manassés."),  (2338, 13, 6, 62, "Para os descendentes de Gérson, clã por clã, foram sorteadas treze cidades das tribos de Issacar, de Aser e de Naftali, e da metade da tribo de Manassés que fica em Basã."),  (2339, 13, 6, 63, "Para os descendentes de Merari, clã por clã, foram sorteadas doze cidades das tribos de Rúben, de Gade e de Zebulom."),  (2340, 13, 6, 64, "Assim os israelitas deram aos levitas essas cidades com suas respectivas pastagens."),  (2341, 13, 6, 65, "As cidades anteriormente mencionadas dos territórios de Judá, de Simeão e de Benjamim também lhes foram dadas por sorteio."),  (2342, 13, 6, 66, "Alguns dos clãs coatitas receberam as seguintes cidades no território da tribo de Efraim:"),  (2343, 13, 6, 67, "Siquém, cidade de refúgio, nos montes de Efraim, e Gezer,"),  (2344, 13, 6, 68, "Jocmeão, Bete-Horom,"),  (2345, 13, 6, 69, "Aijalom e Gate-Rimom, com suas respectivas pastagens."),  (2346, 13, 6, 70, "E da metade da tribo de Manassés o restante dos clãs coatitas recebeu Aner e Bileã, com suas respectivas pastagens."),  (2347, 13, 6, 71, "Os gersonitas receberam as seguintes cidades: Do clã da meia tribo de Manassés, Golã, em Basã, e também Asterote, com suas respectivas pastagens;"),  (2348, 13, 6, 72, "da tribo de Issacar, Quedes, Daberate,"),  (2349, 13, 6, 73, "Ramote e Aném, com suas respectivas pastagens;"),  (2350, 13, 6, 74, "da tribo de Aser, Masal, Abdom,"),  (2351, 13, 6, 75, "Hucoque e Reobe, com suas respectivas pastagens;"),  (2352, 13, 6, 76, "e da tribo de Naftali, Quedes, na Galiléia, Hamom e Quiriataim, com suas respectivas pastagens."),  (2353, 13, 6, 77, "E estas foram as cidades que os outros meraritas receberam: Da tribo de Zebulom, Rimono e Tabor, com suas respectivas pastagens;"),  (2354, 13, 6, 78, "da tribo de Rúben, do outro lado do Jordão, a leste de Jericó, Bezer, no deserto, Jaza,"),  (2355, 13, 6, 79, "Quedemote e Mefaate, com suas respectivas pastagens;"),  (2356, 13, 6, 80, "e da tribo de Gade, Ramote, em Gileade, Maanaim,"),  (2357, 13, 6, 81, "Hesbom e Jazar, com suas respectivas pastagens."),  (2358, 13, 7, 1, "Estes foram os quatro filhos de Issacar: Tolá, Puá, Jasube e Sinrom."),  (2359, 13, 7, 2, "Estes foram os filhos de Tolá: Uzi, Refaías, Jeriel, Jamai, Ibsão e Samuel, chefes dos seus clãs. No reinado de Davi, os descendentes de Tolá alistados em suas genealogias como homens de combate chegavam a 22. 600."),  (2360, 13, 7, 3, "O filho de Uzi foi Israías. Estes foram os filhos de Israías: Micael, Obadias, Joel e Issias. Todos os cinco eram chefes"),  (2361, 13, 7, 4, "que tinham muitas mulheres e filhos. Por isso, conforme a genealogia de sua família, eles contavam com 36. 000 homens prontos para o combate."),  (2362, 13, 7, 5, "Juntamente com seus parentes, os homens de combate de todos os clãs de Issacar, conforme alistados em sua genealogia, chegavam ao todo a 87. 000."),  (2363, 13, 7, 6, "Estes foram os três filhos de Benjamim: Belá, Bequer e Jediael."),  (2364, 13, 7, 7, "Estes foram os filhos de Belá: Esbom, Uzi, Uziel, Jeremote e Iri, cinco chefes de famílias. Seu registro genealógico alistava 22. 034 homens de combate."),  (2365, 13, 7, 8, "Estes foram os filhos de Bequer: Zemira, Joás, Eliézer, Elioenai, Onri, Jeremote, Abias, Anatote e Alemete. Todos esses eram filhos de Bequer."),  (2366, 13, 7, 9, "O registro genealógico deles alistava os chefes de famílias e 20. 200 homens de combate."),  (2367, 13, 7, 10, "O filho de Jediael foi Bilã. Estes foram os filhos de Bilã: Jeús, Benjamim, Eúde, Quenaaná, Zetã, Társis e Aisaar."),  (2368, 13, 7, 11, "Todos esses descendentes de Jediael eram chefes de famílias que contavam com 17. 200 homens de combate prontos para a guerra."),  (2369, 13, 7, 12, "Supim e Hupim eram filhos de Ir; e Husim era filho de Aer."),  (2370, 13, 7, 13, "Estes foram os filhos de Naftali: Jaziel, Guni, Jezer e Silém, netos de Bila."),  (2371, 13, 7, 14, "Estes foram os descendentes de Manassés: Asriel, filho de sua concubina araméia, que também deu à luz Maquir, pai de Gileade."),  (2372, 13, 7, 15, "Maquir casou-se com Maaca, irmã de Hupim e Supim. Outro descendente de Manassés chamava-se Zelofeade, o qual só teve filhas."),  (2373, 13, 7, 16, "Maaca, mulher de Maquir, deu à luz um filho, a quem deu o nome de Perez. O nome de seu irmão era Seres, cujos filhos chamavam-se Ulão e Requém."),  (2374, 13, 7, 17, "O filho de Ulão foi Bedã. Esses foram os descendentes de Gileade, filho de Maquir, e neto de Manassés."),  (2375, 13, 7, 18, "Sua irmã Hamolequete deu à luz Isode, Abiezer e Maalá."),  (2376, 13, 7, 19, "Estes foram os filhos de Semida: Aiã, Siquém, Liqui e Anião."),  (2377, 13, 7, 20, "Estes foram os descendentes de Efraim: Sutela, que foi o pai de Berede, pai de Taate, pai de Eleada, que foi o pai de Taate,"),  (2378, 13, 7, 21, "pai de Zabade, pai de Sutela. Ézer e Eleade, filhos de Efraim, foram mortos por homens da cidade de Gate, quando tentavam roubar os rebanhos deles."),  (2379, 13, 7, 22, "Efraim chorou muitos dias por eles, e seus parentes vieram consolá-lo."),  (2380, 13, 7, 23, "Depois ele se deitou de novo com sua mulher, e ela engravidou e deu à luz um filho. Ele o chamou Berias, pois tinha acontecido uma desgraça em sua família."),  (2381, 13, 7, 24, "Sua filha chamava-se Seerá. Foi ela que fundou Bete-Horom Alta e Bete-Horom Baixa e também Uzém-Seerá."),  (2382, 13, 7, 25, "O filho de Berias foi Refa, pai de Resefe, que foi o pai de Telá, pai de Taã,"),  (2383, 13, 7, 26, "pai de Ladã, pai de Amiúde, que foi o pai de Elisama,"),  (2384, 13, 7, 27, "pai de Num, que foi o pai de Josué."),  (2385, 13, 7, 28, "Suas terras e cidades incluíam Betel e os povoados ao redor, Naarã a leste, Gezer e seus povoados a oeste, e Siquém e Aiá com os seus povoados."),  (2386, 13, 7, 29, "A tribo de Manassés controlava as cidades de Bete-Seã, Taanaque, Megido e Dor, com seus respectivos povoados. Os descendentes de José, filho de Israel, viviam nessas cidades."),  (2387, 13, 7, 30, "Estes foram os filhos de Aser: Imna, Isvá, Isvi e Berias. A irmã deles chamava-se Sera."),  (2388, 13, 7, 31, "Estes foram os filhos de Berias: Héber e Malquiel, que foi o pai de Birzavite."),  (2389, 13, 7, 32, "Héber gerou Jaflete, Somer e Hotão, e da irmã deles, Suá."),  (2390, 13, 7, 33, "Estes foram os filhos de Jaflete: Pasaque, Bimal e Asvate. Esses foram os filhos de Jaflete."),  (2391, 13, 7, 34, "Estes foram os filhos de Somer: Aí, Roga, Jeubá e Arã."),  (2392, 13, 7, 35, "Estes foram os filhos de Helém, irmão de Somer: Zofa, Imna, Seles e Amal."),  (2393, 13, 7, 36, "Estes foram os filhos de Zofa: Suá, Harnefer, Sual, Beri, Inra,"),  (2394, 13, 7, 37, "Bezer, Hode, Samá, Silsa, Itrã e Beera."),  (2395, 13, 7, 38, "Estes foram os filhos de Jéter: Jefoné, Pispa e Ara."),  (2396, 13, 7, 39, "Estes foram os filhos de Ula: Ara, Haniel e Rizia."),  (2397, 13, 7, 40, "Todos esses foram descendentes de Aser. Eram chefes de famílias, homens escolhidos, soldados valentes e líderes de destaque. O número dos alistados para combate no exército deles chegou a 26. 000."),  (2398, 13, 8, 1, "Benjamim gerou Belá, seu filho mais velho; Asbel, seu segundo filho, Aará, o terceiro,"),  (2399, 13, 8, 2, "Noá, o quarto, e Rafa, o quinto."),  (2400, 13, 8, 3, "Estes foram os filhos de Belá: Adar, Gera, pai de Eúde,"),  (2401, 13, 8, 4, "Abisua, Naamã, Aoá,"),  (2402, 13, 8, 5, "Gera, Sefufá e Hurão."),  (2403, 13, 8, 6, "Estes foram os descendentes de Eúde, chefes das famílias dos habitantes de Geba, que foram deportados para Manaate:"),  (2404, 13, 8, 7, "Naamã, Aías e Gera. Esse Gera, pai de Uzá e de Aiúde, foi quem os deportou."),  (2405, 13, 8, 8, "Depois de ter se divorciado de suas mulheres Husim e Baara, Saaraim teve filhos na terra de Moabe."),  (2406, 13, 8, 9, "Com sua mulher Hodes ele gerou Jobabe, Zíbia, Messa, Malcã,"),  (2407, 13, 8, 10, "Jeús, Saquias e Mirma. Esses foram seus filhos, chefes de famílias."),  (2408, 13, 8, 11, "Com Husim ele gerou Abitube e Elpaal."),  (2409, 13, 8, 12, "Estes foram os filhos de Elpaal: Héber, Misã, Semede, que fundou Ono e Lode com seus povoados."),  (2410, 13, 8, 13, "Berias e Sema foram os chefes das famílias dos habitantes de Aijalom, e foram eles que expulsaram os habitantes de Gate."),  (2411, 13, 8, 14, "Aiô, Sasaque, Jeremote,"),  (2412, 13, 8, 15, "Zebadias, Arade, Éder,"),  (2413, 13, 8, 16, "Micael, Ispa e Joá foram descendentes de Berias."),  (2414, 13, 8, 17, "Zebadias, Mesulão, Hizqui, Héber,"),  (2415, 13, 8, 18, "Ismerai, Izlias e Jobabe foram descendentes de Elpaal."),  (2416, 13, 8, 19, "Jaquim, Zicri, Zabdi,"),  (2417, 13, 8, 20, "Elienai, Ziletai, Eliel,"),  (2418, 13, 8, 21, "Adaías, Beraías e Sinrate foram descendentes de Simei."),  (2419, 13, 8, 22, "Ispã, Héber, Eliel,"),  (2420, 13, 8, 23, "Abdom, Zicri, Hanã,"),  (2421, 13, 8, 24, "Hananias, Elão, Antotias,"),  (2422, 13, 8, 25, "Ifdéias e Penuel foram descendentes de Sasaque."),  (2423, 13, 8, 26, "Sanserai, Searias, Atalias,"),  (2424, 13, 8, 27, "Jaaresias, Elias e Zicri foram descendentes de Jeroão."),  (2425, 13, 8, 28, "Todos esses foram chefes de famílias, líderes conforme alistados em suas genealogias, e moravam em Jerusalém."),  (2426, 13, 8, 29, "Jeiel, pai de Gibeom morou na cidade de Gibeom. O nome de sua mulher era Maaca,"),  (2427, 13, 8, 30, "o de seu filho mais velho, Abdom, e o de seus outros filhos, Zur, Quis, Baal, Ner, Nadabe,"),  (2428, 13, 8, 31, "Gedor, Aiô, Zequer"),  (2429, 13, 8, 32, "e Miclote, que gerou Siméia. Eles também moravam perto de seus parentes, em Jerusalém."),  (2430, 13, 8, 33, "Ner gerou Quis, que gerou Saul. Saul gerou Jônatas, Malquisua, Abinadabe e Esbaal."),  (2431, 13, 8, 34, "O filho de Jônatas foi Meribe-Baal, que gerou Mica."),  (2432, 13, 8, 35, "Estes foram os filhos de Mica: Pitom, Meleque, Taréia e Acaz."),  (2433, 13, 8, 36, "Acaz gerou Jeoada, Jeoada gerou Alemete, Azmavete e Zinri, e Zinri gerou Mosa."),  (2434, 13, 8, 37, "Mosa gerou Bineá, pai de Rafa, que foi o pai de Eleasa, pai de Azel."),  (2435, 13, 8, 38, "Azel teve seis filhos chamados Azricão, Bocru, Ismael, Searias, Obadias e Hanã. Todos esses foram filhos de Azel."),  (2436, 13, 8, 39, "Estes foram os filhos de Eseque, seu irmão: Ulão, o mais velho, Jeús, o segundo e Elifelete, o terceiro."),  (2437, 13, 8, 40, "Os filhos de Ulão eram soldados valentes e bons flecheiros. Tiveram muitos filhos e netos; eram cento e cinqüenta ao todo. Todos esses foram descendentes de Benjamim."),  (2438, 13, 9, 1, "Todos os israelitas foram alistados nas genealogias dos registros históricos dos reis de Israel. O povo de Judá foi levado prisioneiro para a Babilônia por sua infidelidade."),  (2439, 13, 9, 2, "Os primeiros a voltarem às suas propriedades e às suas cidades foram algumas pessoas do povo e alguns sacerdotes, levitas e servidores do templo."),  (2440, 13, 9, 3, "Os de Judá, de Benjamim e de Efraim e Manassés que se instalaram em Jerusalém foram:"),  (2441, 13, 9, 4, "Utai, filho de Amiúde, neto de Onri, bisneto de Inri e trineto de Bani, um descendente de Perez, filho de Judá."),  (2442, 13, 9, 5, "Dos descendentes de Selá: O primogênito Asaías com seus filhos."),  (2443, 13, 9, 6, "Dos descendentes de Zerá: Jeuel. Os de Judá chegaram a 690."),  (2444, 13, 9, 7, "Dos benjamitas: Salu, filho de Mesulão, neto de Hodavias e bisneto de Hassenua;"),  (2445, 13, 9, 8, "Ibnéias, filho de Jeroão; Elá, filho de Uzi, filho de Micri; e Mesulão, filho de Sefatias, filho de Reuel, filho de Ibnias."),  (2446, 13, 9, 9, "Da tribo de Benjamim, relacionados em sua genealogia, eram 956. Todos esses homens eram chefes de suas famílias."),  (2447, 13, 9, 10, "Dos sacerdotes: Jedaías, Jeoiaribe, Jaquim;"),  (2448, 13, 9, 11, "Azarias, filho de Hilquias, neto de Mesulão, bisneto de Zadoque, trineto de Meraiote e tetraneto de Aitube, o líder encarregado do templo de Deus;"),  (2449, 13, 9, 12, "Adaías, filho de Jeroão, neto de Pasur e bisneto de Malquias; e Masai, filho de Adiel, neto de Jazera, bisneto de Mesulão, trineto de Mesilemite e tetraneto de Imer."),  (2450, 13, 9, 13, "O número de sacerdotes que eram chefes de famílias era 1. 760. Eram homens capazes, e sua responsabilidade era ministrar no templo de Deus."),  (2451, 13, 9, 14, "Dos levitas: Semaías, filho de Hassube, neto de Azricão e bisneto de Hasabias, um merarita;"),  (2452, 13, 9, 15, "Baquebacar, Heres, Galal e Matanias, filho de Mica, neto de Zicri e bisneto de Asafe;"),  (2453, 13, 9, 16, "Obadias, filho de Semaías, neto de Galal e bisneto de Jedutum; e Berequias, filho de Asa e neto de Elcana, que vivia nos povoados dos netofatitas."),  (2454, 13, 9, 17, "Os guardas das portas eram: Salum, o chefe, Acube, Talmom, Aimã e os irmãos deles, sendo até hoje"),  (2455, 13, 9, 18, "os guardas da porta do Rei, a leste. Salum era o chefe. Esses eram os guardas das portas que pertenciam ao acampamento dos levitas."),  (2456, 13, 9, 19, "Salum, filho de Coré, neto de Ebiasafe e bisneto de Corá, e seus parentes, os coreítas, guardas das portas, responsáveis por guardar as entradas da Tenda, como os seus antepassados tinham sido responsáveis por guardar a entrada da habitação do Senhor."),  (2457, 13, 9, 20, "Naquela época, Finéias, filho de Eleazar, estivera encarregado dos guardas das portas, e o Senhor estava com ele."),  (2458, 13, 9, 21, "Zacarias, filho de Meselemias, era o guarda das portas da entrada da Tenda do Encontro."),  (2459, 13, 9, 22, "A soma total dos escolhidos para serem guardas das portas, registrados nas genealogias dos seus povoados, era de 212. Eles haviam sido designados para esses postos de confiança por Davi e pelo vidente Samuel."),  (2460, 13, 9, 23, "Eles e os seus descendentes foram encarregados de vigiar as portas do templo do Senhor, o templo chamado Tenda."),  (2461, 13, 9, 24, "Os guardas vigiavam as portas nos quatro lados: norte, sul, leste e oeste."),  (2462, 13, 9, 25, "Seus parentes, residentes em seus povoados, tinham que vir de tempos em tempos e trabalhar com eles por períodos de sete dias."),  (2463, 13, 9, 26, "Mas os quatro principais guardas das portas, que eram levitas, receberam a responsabilidade de tomar conta das salas e da tesouraria do templo de Deus."),  (2464, 13, 9, 27, "Eles passavam a noite perto do templo de Deus, pois tinham o dever de vigiá-la e de abrir as portas todas as manhãs."),  (2465, 13, 9, 28, "Alguns levitas estavam encarregados dos utensílios utilizados no culto no templo; eles os contavam quando eram retirados e quando eram devolvidos."),  (2466, 13, 9, 29, "Outros eram responsáveis pelos móveis e por todos os demais utensílios do santuário, bem como pela farinha, pelo vinho, pelo óleo, pelo incenso e pelas especiarias."),  (2467, 13, 9, 30, "E ainda outros cuidavam da manipulação das especiarias."),  (2468, 13, 9, 31, "Um levita chamado Matitias, filho mais velho do coreíta Salum, tinha a responsabilidade de assar os pães para as ofertas."),  (2469, 13, 9, 32, "E dentre os coatitas, seus irmãos, alguns estavam encarregados de preparar os pães que são postos sobre a mesa todo sábado."),  (2470, 13, 9, 33, "Os cantores, chefes de famílias levitas, permaneciam nas salas do templo e estavam isentos de outros deveres, pois dia e noite se dedicavam à sua própria tarefa."),  (2471, 13, 9, 34, "Todos esses eram chefes de famílias levitas, alistados como líderes em suas genealogias, e moravam em Jerusalém."),  (2472, 13, 9, 35, "Jeiel, pai de Gibeom, morava em Gibeom. O nome de sua mulher era Maaca,"),  (2473, 13, 9, 36, "e o de seu filho mais velho, Abdom. Depois nasceram Zur, Quis, Baal, Ner, Nadabe,"),  (2474, 13, 9, 37, "Gedor, Aiô, Zacarias e Miclote."),  (2475, 13, 9, 38, "Miclote gerou Siméia. Eles também moravam perto de seus parentes em Jerusalém."),  (2476, 13, 9, 39, "Ner gerou Quis, Quis gerou Saul, Saul gerou Jônatas, Malquisua, Abinadabe e Esbaal."),  (2477, 13, 9, 40, "Este foi o filho de Jônatas: Meribe-Baal, que gerou Mica."),  (2478, 13, 9, 41, "Estes foram os filhos de Mica: Pitom, Meleque, Taréia e Acaz."),  (2479, 13, 9, 42, "Acaz gerou Jadá, Jadá gerou Alemete, Azmavete e Zinri, e Zinri gerou Mosa."),  (2480, 13, 9, 43, "Mosa gerou Bineá, cujo filho foi Refaías, o filho deste foi Eleasa, pai de Azel."),  (2481, 13, 9, 44, "Azel teve seis filhos, e os nomes deles foram: Azricão, Bocru, Ismael, Searias, Obadias e Hanã. Esses foram os filhos de Azel."),  (2482, 13, 10, 1, "E aconteceu que, em combate com os filisteus, os israelitas foram postos em fuga, e muitos caíram mortos no monte Gilboa."),  (2483, 13, 10, 2, "Os filisteus perseguiram Saul e seus filhos, e mataram Jônatas, Abinadabe e Malquisua, filhos de Saul."),  (2484, 13, 10, 3, "O combate foi se tornando cada vez mais violento em torno de Saul, até que os flecheiros o alcançaram e o feriram gravemente."),  (2485, 13, 10, 4, "Então Saul ordenou ao seu escudeiro: Tire sua espada e mate-me com ela, senão sofrerei a vergonha de cair nas mãos desses incircuncisos. Mas o seu escudeiro estava apavorado e não quis fazê-lo. Saul, então, apanhou a própria espada e jogou-se sobre ela."),  (2486, 13, 10, 5, "Quando o escudeiro viu que Saul estava morto, jogou-se também sobre sua espada e morreu."),  (2487, 13, 10, 6, "Dessa maneira Saul e seus três filhos morreram, e, assim, toda a descendência real."),  (2488, 13, 10, 7, "Quando os israelitas que habitavam no vale viram que o exército tinha fugido e que Saul e seus filhos estavam mortos, fugiram abandonando suas cidades. Depois os filisteus foram ocupá-las."),  (2489, 13, 10, 8, "No dia seguinte, quando os filisteus foram saquear os mortos, encontraram Saul e seus filhos caídos no monte Gilboa."),  (2490, 13, 10, 9, "Cortaram a cabeça de Saul, pegaram suas armas e enviaram mensageiros por toda a terra dos filisteus proclamando a notícia entre os seus ídolos e o seu povo."),  (2491, 13, 10, 10, "Expuseram suas armas num dos templos dos seus deuses e penduraram sua cabeça no templo de Dagom."),  (2492, 13, 10, 11, "Quando os habitantes de Jabes-Gileade ficaram sabendo o que os filisteus haviam feito com Saul,"),  (2493, 13, 10, 12, "os mais corajosos dentre eles foram e apanharam os corpos de Saul e de seus filhos e os levaram a Jabes. Lá sepultaram seus ossos sob a Grande Árvore, e jejuaram por sete dias."),  (2494, 13, 10, 13, "Saul morreu porque foi infiel ao Senhor; não guardou a palavra do Senhor e chegou a consultar uma médiun em busca de orientação,"),  (2495, 13, 10, 14, "em vez de consultar o Senhor. Por isso o Senhor o entregou à morte e deu o reino a Davi, filho de Jessé."),  (2496, 13, 11, 1, "Todo o Israel reuniu-se com Davi em Hebrom e disse: Somos sangue do teu sangue."),  (2497, 13, 11, 2, "No passado, mesmo quando Saul era rei, eras tu quem liderava Israel em suas batalhas. E o Senhor, o teu Deus, te disse: ‘Você pastoreará o meu povo Israel, e será o seu governante’ ."),  (2498, 13, 11, 3, "Então todas as autoridades de Israel foram ao encontro do rei Davi em Hebrom, e ele fez um acordo com eles em Hebrom perante o Senhor, e eles ungiram Davi rei de Israel, conforme o Senhor havia anunciado por meio de Samuel."),  (2499, 13, 11, 4, "Davi e todos os israelitas marcharam para Jerusalém, que é Jebus. Os jebuseus, habitantes da cidade,"),  (2500, 13, 11, 5, "disseram a Davi: Você não entrará aqui. No entanto, Davi conquistou a fortaleza de Sião, a cidade de Davi."),  (2501, 13, 11, 6, "Naquele dia Davi tinha dito: O primeiro que atacar os jebuseus se tornará o comandante do exército. Joabe, filho de Zeruia, foi o primeiro, e por isso recebeu o comando do exército."),  (2502, 13, 11, 7, "Davi passou a morar na fortaleza, e por isso ela foi chamada cidade de Davi."),  (2503, 13, 11, 8, "Ele reconstruiu a cidade ao redor da fortaleza, desde os muros de arrimo até os muros ao redor, e Joabe restaurou o restante da cidade."),  (2504, 13, 11, 9, "E Davi foi se tornando cada vez mais poderoso, pois o Senhor dos Exércitos estava com ele."),  (2505, 13, 11, 10, "Estes foram os chefes dos principais guerreiros de Davi, que junto com todo Israel, deram um grande apoio para estender o seu reinado a todo o país, conforme o Senhor havia prometido."),  (2506, 13, 11, 11, "Esta é a lista deles: Jasobeão, um hacmonita, era o chefe dos oficiais; foi ele que, empunhando sua lança, matou trezentos homens numa mesma batalha."),  (2507, 13, 11, 12, "Depois, Eleazar, filho de Dodô, de Aoí, um dos três principais guerreiros."),  (2508, 13, 11, 13, "Ele estava com Davi na plantação de cevada de Pas-Damim, onde os filisteus se reuniram para a guerra. As tropas israelitas fugiram dos filisteus,"),  (2509, 13, 11, 14, "mas eles mantiveram sua posição no meio da plantação. Eles o defenderam e feriram os filisteus, e o Senhor lhes deu uma grande vitória."),  (2510, 13, 11, 15, "Quando um grupo de filisteus estava acampado no vale de Refaim, três chefes do pelotão dos trinta foram encontrar Davi na rocha que há perto da caverna de Adulão."),  (2511, 13, 11, 16, "Estando Davi nessa fortaleza, e o destacamento filisteu em Belém,"),  (2512, 13, 11, 17, "Davi expressou seu desejo: Quem me dera me trouxessem água da cisterna que fica junto à porta de Belém! "),  (2513, 13, 11, 18, "Então aqueles três infiltraram-se no acampamento filisteu, tiraram água daquela cisterna e a trouxeram a Davi. Mas ele se recusou a beber; em vez disso, derramou-a como uma oferta ao Senhor."),  (2514, 13, 11, 19, "Longe de mim fazer isso, ó meu Deus! , disse Davi. Esta água representa o sangue desses homens que arriscaram a própria vida!  Eles arriscaram a vida para trazê-la. E não quis bebê-la. Foram essas as proezas dos três principais guerreiros."),  (2515, 13, 11, 20, "Abisai, o irmão de Joabe, era o chefe do batalhão dos trinta. Com uma lança enfrentou trezentos homens e os matou, tornando-se tão famoso quanto os três."),  (2516, 13, 11, 21, "Foi honrado duas vezes mais do que o batalhão dos trinta, e se tornou chefe deles, mas nunca igualou-se aos três principais guerreiros."),  (2517, 13, 11, 22, "Benaia, filho de Joiada, era um corajoso soldado de Cabzeel, e realizou grandes feitos. Matou dois dos melhores guerreiros de Moabe e, num dia de neve, desceu em uma cova e matou um leão."),  (2518, 13, 11, 23, "Também matou um egípcio de dois metros e vinte e cinco centímetros de altura. Embora o egípcio tivesse na mão uma lança parecida com uma lançadeira de tecelão, Benaia o enfrentou com um cajado. Arrancou a lança da mão do egípcio e com ela o matou."),  (2519, 13, 11, 24, "Esses foram os grandes feitos de Benaia, filho de Joiada, que também foi tão famoso quanto os três principais guerreiros de Davi."),  (2520, 13, 11, 25, "Foi mais honrado do que qualquer dos trinta, mas nunca igualou-se aos três. E Davi lhe deu o comando da sua guarda pessoal."),  (2521, 13, 11, 26, "Os outros guerreiros foram: Asael, irmão de Joabe; Elanã, filho de Dodô, de Belém;"),  (2522, 13, 11, 27, "Samote, de Haror; Helez, de Pelom;"),  (2523, 13, 11, 28, "Ira, filho de Iques, de Tecoa; Abiezer, de Anatote;"),  (2524, 13, 11, 29, "Sibecai, de Husate; Ilai, de Aoí;"),  (2525, 13, 11, 30, "Maarai, de Netofate; Helede, filho de Baaná, de Netofate;"),  (2526, 13, 11, 31, "Itai, filho de Ribai, de Gibeá de Benjamim; Benaia, de Piratom;"),  (2527, 13, 11, 32, "Hurai, dos riachos de Gaás; Abiel, de Arbate;"),  (2528, 13, 11, 33, "Azmavete, de Baarum; Eliaba, de Saalbom;"),  (2529, 13, 11, 34, "os filhos de Hasém, de Gizom; Jônatas, filho de Sage, de Harar;"),  (2530, 13, 11, 35, "Aião, filho de Sacar, de Harar; Elifal, filho de Ur;"),  (2531, 13, 11, 36, "Héfer, de Mequerate; Aías, de Pelom;"),  (2532, 13, 11, 37, "Hezro, de Carmelo; Naarai, filho de Ezbai;"),  (2533, 13, 11, 38, "Joel, irmão de Natã; Mibar, filho de Hagri;"),  (2534, 13, 11, 39, "o amonita Zeleque; Naarai, de Beerote, escudeiro de Joabe, filho de Zeruia;"),  (2535, 13, 11, 40, "Ira e Garebe, de Jatir;"),  (2536, 13, 11, 41, "Urias, o hitita; Zabade, filho de Alai;"),  (2537, 13, 11, 42, "Adina, filho de Siza, de Rúben, chefe dos rubenitas e do grupo dos trinta;"),  (2538, 13, 11, 43, "Hanã, filho de Maaca; Josafá, de Mitene;"),  (2539, 13, 11, 44, "Uzia, de Asterate; Sama e Jeiel, filhos de Hotão, de Aroer;"),  (2540, 13, 11, 45, "Jediael, filho de Sinri; seu irmão, Joá, de Tiz;"),  (2541, 13, 11, 46, "Eliel, de Maave; Jeribai e Josavias, filhos de Elnaão; Itma, um moabita,"),  (2542, 13, 11, 47, "e Eliel, Obede e Jaasiel, de Mezoba."),  (2543, 13, 12, 1, "Estes são os que se juntaram a Davi em Ziclague, onde se escondia de Saul, filho de Quis. Eles estavam entre os combatentes que o ajudaram na guerra;"),  (2544, 13, 12, 2, "utilizavam arco e flecha e a funda para atirar pedras tanto com a mão direita como com a esquerda; pertenciam à tribo de Benjamim e eram parentes de Saul:"),  (2545, 13, 12, 3, "Aiezer, o chefe deles, e Joás, filhos de Semaá, de Gibeate; Jeziel e Pelete, filhos de Azmavete; Beraca, Jeú, de Anatote,"),  (2546, 13, 12, 4, "e Ismaías, de Gibeom, um grande guerreiro do pelotão dos trinta, e chefe deles; Jeremias, Jaaziel, Joanã, Jozabade, de Gederate,"),  (2547, 13, 12, 5, "Eluzai, Jeremote, Bealías, Semarias e Sefatias, de Harufe;"),  (2548, 13, 12, 6, "os coreítas Elcana, Issias, Azareel, Joezer e Jasobeão;"),  (2549, 13, 12, 7, "e Joela e Zebadias, filhos de Jeroão de Gedor."),  (2550, 13, 12, 8, "Da tribo de Gade alguns aliaram-se a Davi em sua fortaleza no deserto. Eram guerreiros corajosos, prontos para o combate, e sabiam lutar com escudo e com lança. Tinham a bravura de um leão, e eram ágeis como gazelas nos montes."),  (2551, 13, 12, 9, "Ézer era o primeiro; Obadias, o segundo; Eliabe, o terceiro;"),  (2552, 13, 12, 10, "Mismana, o quarto; Jeremias, o quinto;"),  (2553, 13, 12, 11, "Atai, o sexto; Eliel, o sétimo;"),  (2554, 13, 12, 12, "Joanã, o oitavo; Elzabade, o nono;"),  (2555, 13, 12, 13, "Jeremias, o décimo; e Macbanai era o décimo primeiro."),  (2556, 13, 12, 14, "Todos esses de Gade eram chefes de exército; o menor valia por cem, e o maior enfrentava mil."),  (2557, 13, 12, 15, "Foram eles que atravessaram o Jordão no primeiro mês do ano, quando o rio transborda em todas as suas margens, e puseram em fuga todos os que moravam nos vales, a leste e a oeste."),  (2558, 13, 12, 16, "Alguns outros benjamitas e certos homens de Judá também vieram a Davi em sua fortaleza."),  (2559, 13, 12, 17, "Davi saiu ao encontro deles e lhes disse: Se vocês vieram em paz, para me ajudarem, estou pronto para recebê-los. Mas, se querem trair-me e entregar-me aos meus inimigos quando minhas mãos não cometeram violência, que o Deus de nossos antepassados veja isso e julgue vocês."),  (2560, 13, 12, 18, "Então o Espírito veio sobre Amasai, chefe do pelotão dos trinta, e ele disse: Somos teus, ó Davi! Estamos contigo, ó filho de Jessé! Paz, paz seja contigo, e aos teus aliados, pois o teu Deus te ajudará. Davi os recebeu e os nomeou chefes de seus grupos de ataque."),  (2561, 13, 12, 19, "Alguns soldados de Manassés desertaram para Davi quando ele foi com os filisteus guerrear contra Saul. Mas eles não ajudaram os filisteus, porque os seus chefes os aconselharam e os mandaram embora, dizendo: Pagaremos com a vida, caso Davi deserte e passe para Saul, seu senhor."),  (2562, 13, 12, 20, "Estes foram os homens de Manassés que desertaram para Davi quando ele foi a Ziclague: Adna, Jozabade, Jediael, Micael, Jozabade, Eliú e Ziletai, chefes de batalhões de mil em Manassés."),  (2563, 13, 12, 21, "Eles ajudaram Davi contra grupos de ataque, pois todos eles eram guerreiros valentes, e eram líderes no exército dele."),  (2564, 13, 12, 22, "De fato, diariamente chegavam soldados para ajudar Davi, até que seu exército tornou-se tão grande como o exército de Deus."),  (2565, 13, 12, 23, "Este é o número dos soldados armados para a guerra que vieram a Davi em Hebrom para entregar a ele o reino de Saul, conforme o Senhor tinha dito:"),  (2566, 13, 12, 24, "Da tribo de Judá, 6. 800 armados para a guerra, com escudo e lança;"),  (2567, 13, 12, 25, "Da tribo de Simeão, 7. 100 guerreiros prontos para o combate;"),  (2568, 13, 12, 26, "Da tribo de Levi, 4. 600,"),  (2569, 13, 12, 27, "inclusive Joiada, líder da família de Arão, com 3. 700 homens,"),  (2570, 13, 12, 28, "e Zadoque, um jovem e valente guerreiro, com 22 oficiais de sua família;"),  (2571, 13, 12, 29, "Da tribo de Benjamim, parentes de Saul, 3. 000, a maioria dos quais era até então fiel à família de Saul;"),  (2572, 13, 12, 30, "Da tribo de Efraim, 20. 800 soldados valentes, famosos em seus próprios clãs;"),  (2573, 13, 12, 31, "Da metade da tribo de Manassés, 18. 000, indicados por nome para fazerem Davi rei;"),  (2574, 13, 12, 32, "Da tribo de Issacar, 200 chefes que sabiam como Israel devia agir em qualquer circunstância. Comandavam todos os seus parentes;"),  (2575, 13, 12, 33, "Da tribo de Zebulom, 50. 000 soldados experientes, preparados para guerrear com qualquer tipo de arma, totalmente decididos a ajudar Davi;"),  (2576, 13, 12, 34, "Da tribo de Naftali, 1. 000 líderes com 37. 000 homens armados de escudos e lanças;"),  (2577, 13, 12, 35, "Da tribo de Dã, 28. 600 prontos para o combate;"),  (2578, 13, 12, 36, "Da tribo de Aser, 40. 000 soldados experientes, preparados para o combate;"),  (2579, 13, 12, 37, "e do leste do Jordão, das tribos de Rúben e de Gade, e da metade da tribo de Manassés, 120. 000 completamente armados."),  (2580, 13, 12, 38, "Todos esses eram homens de combate que se apresentaram voluntariamente para servirem nas fileiras. Foram a Hebrom totalmente decididos a fazerem de Davi rei sobre todo o Israel. E todos os outros israelitas tinham esse mesmo propósito."),  (2581, 13, 12, 39, "Ficaram com Davi três dias, comendo e bebendo, pois as suas famílias haviam fornecido provisões para eles."),  (2582, 13, 12, 40, "Os habitantes das tribos vizinhas e também de lugares distantes como Issacar, Zebulom e Naftali, trouxeram-lhes muitas provisões em jumentos, camelos, mulas e bois: farinha, bolos de figo, bolos de uvas passas, vinho, azeite, bois e ovelhas, pois havia grande alegria em Israel."),  (2583, 13, 13, 1, "Depois de consultar todos os seus oficiais, os comandantes de mil e de cem,"),  (2584, 13, 13, 2, "Davi disse a toda a assembléia de Israel: Se vocês estão de acordo e se esta é a vontade do Senhor nosso Deus, enviemos uma mensagem a nossos irmãos em todo o território de Israel, e também aos sacerdotes e aos levitas que estão com eles em suas cidades, para virem unir-se a nós."),  (2585, 13, 13, 3, "Vamos trazer de volta a arca de nosso Deus, pois não nos importamos com ela durante o reinado de Saul."),  (2586, 13, 13, 4, "Toda a assembléia concordou, pois isso pareceu bem a todo o povo."),  (2587, 13, 13, 5, "Então Davi reuniu todos os israelitas, desde o rio Sior, no Egito, até Lebo-Hamate, para trazerem de Quiriate-Jearim a arca de Deus."),  (2588, 13, 13, 6, "Davi e todos os israelitas foram a Baalá, que é Quiriate-Jearim, em Judá, para buscar a arca de Deus, o Senhor, entronizado entre os querubins; a arca sobre a qual seu nome é invocado."),  (2589, 13, 13, 7, "Da casa de Abinadabe levaram a arca de Deus num carroção novo, conduzido por Uzá e Aiô."),  (2590, 13, 13, 8, "Davi e todos os israelitas iam dançando e cantando com todo o vigor diante de Deus, ao som de harpas, liras, tamborins, címbalos e cornetas."),  (2591, 13, 13, 9, "Quando chegaram à eira de Quidom, Uzá esticou o braço e segurou a arca, porque os bois haviam tropeçado."),  (2592, 13, 13, 10, "A ira do Senhor acendeu-se contra Uzá, e ele o feriu por ter tocado na arca. Uzá morreu ali mesmo, diante de Deus."),  (2593, 13, 13, 11, "Davi ficou contrariado porque o Senhor, em sua ira, havia fulminado Uzá. Até hoje aquele lugar é chamado Perez-Uzá."),  (2594, 13, 13, 12, "Naquele dia, Davi teve medo de Deus e se perguntou: Como vou conseguir levar a arca de Deus? "),  (2595, 13, 13, 13, "Por isso desistiu de levar a arca para a cidade de Davi. Em vez disso, levou-a para a casa de Obede-Edom, de Gate."),  (2596, 13, 13, 14, "A arca de Deus ficou na casa dele por três meses, e o Senhor abençoou sua família e tudo o que possuía."),  (2597, 13, 14, 1, "Hirão, rei de Tiro, enviou a Davi uma delegação, que lhe trouxe toras de cedro, e também pedreiros e carpinteiros, para lhe construírem um palácio."),  (2598, 13, 14, 2, "Então Davi teve certeza de que o Senhor o confirmara como rei de Israel e que seu reino estava prosperando por amor de seu povo Israel."),  (2599, 13, 14, 3, "Em Jerusalém Davi tomou para si mais mulheres e gerou mais filhos e filhas."),  (2600, 13, 14, 4, "Estes são os nomes dos que lhe nasceram ali: Samua, Sobabe, Natã, Salomão,"),  (2601, 13, 14, 5, "Ibar, Elisua, Elpelete,"),  (2602, 13, 14, 6, "Nogá, Nefegue, Jafia,"),  (2603, 13, 14, 7, "Elisama, Beeliada e Elifelete."),  (2604, 13, 14, 8, "Quando os filisteus ficaram sabendo que Davi tinha sido ungido rei de todo o Israel, foram com todo o exército prendê-lo, mas Davi soube disso e saiu para enfrentá-los."),  (2605, 13, 14, 9, "Tendo os filisteus invadido o vale de Refaim,"),  (2606, 13, 14, 10, "Davi perguntou a Deus: Devo atacar os filisteus? Tu os entregarás nas minhas mãos?  O Senhor lhe respondeu: Vá, eu os entregarei nas suas mãos."),  (2607, 13, 14, 11, "Então Davi e seus soldados foram a Baal-Perazim, e Davi os derrotou e disse: Assim como as águas de uma enchente causam destruição, pelas minhas mãos Deus destruiu os meus inimigos. Então, aquele lugar passou a ser chamado Baal-Perazim."),  (2608, 13, 14, 12, "Como os filisteus haviam abandonado os seus ídolos ali, Davi ordenou que fossem queimados."),  (2609, 13, 14, 13, "Os filisteus voltaram a atacar o vale;"),  (2610, 13, 14, 14, "então Davi consultou Deus de novo, que lhe respondeu: Não ataque pela frente, mas dê a volta por trás deles e ataque-os em frente das amoreiras."),  (2611, 13, 14, 15, "Assim que você ouvir um som de passos por cima das amoreiras, saia para o combate, pois este é o sinal de que Deus saiu à sua frente para ferir o exército filisteu."),  (2612, 13, 14, 16, "E Davi fez como Deus lhe tinha ordenado, e eles derrotaram o exército filisteu, por todo o caminho, desde Gibeom até Gezer."),  (2613, 13, 14, 17, "Assim, a fama de Davi espalhou-se por todas as terras, e o Senhor fez com que todas as nações o temessem."),  (2614, 13, 15, 1, "Depois de Davi ter construído casas para si na cidade de Davi, ele preparou um lugar para a arca de Deus e armou uma tenda para ela."),  (2615, 13, 15, 2, "Então Davi disse: Somente os levitas poderão carregar a arca de Deus, pois o Senhor os escolheu para transportarem a arca do Senhor e para ficarem sempre ao seu serviço."),  (2616, 13, 15, 3, "Davi reuniu todo o Israel em Jerusalém para levar a arca do Senhor para o lugar que ele lhe havia preparado."),  (2617, 13, 15, 4, "Reuniu também os descendentes de Arão e os levitas:"),  (2618, 13, 15, 5, "Dos descendentes de Coate, Uriel, liderando outros 120;"),  (2619, 13, 15, 6, "dos descendentes de Merari, Asaías, liderando outros 220;"),  (2620, 13, 15, 7, "dos descendentes de Gérson, Joel, liderando outros 130;"),  (2621, 13, 15, 8, "dos descendentes de Elisafã, Semaías, liderando outros 200;"),  (2622, 13, 15, 9, "dos descendentes de Hebrom, Eliel, liderando outros 80;"),  (2623, 13, 15, 10, "dos descendentes de Uziel, Aminadabe, liderando outros 112."),  (2624, 13, 15, 11, "Então Davi convocou os sacerdotes Zadoque e Abiatar, e os levitas Uriel, Asaías, Joel, Semaías, Eliel e Aminadabe, e"),  (2625, 13, 15, 12, "lhes disse: Vocês são os chefes das famílias levitas; vocês e seus companheiros levitas deverão consagrar-se e levar a arca do Senhor, o Deus de Israel, para o local que preparei para ela."),  (2626, 13, 15, 13, "Pelo fato de vocês não terem carregado a arca na primeira vez, a ira do Senhor nosso Deus causou destruição entre nós. Nós não o tínhamos consultado sobre como proceder."),  (2627, 13, 15, 14, "Então os sacerdotes e os levitas se consagraram para transportar a arca do Senhor, o Deus de Israel."),  (2628, 13, 15, 15, "E os levitas carregaram a arca de Deus apoiando as varas da arca sobre os ombros, conforme Moisés tinha ordenado, de acordo com a palavra do Senhor."),  (2629, 13, 15, 16, "Davi também ordenou aos líderes dos levitas que encarregassem os músicos que havia entre eles de cantar músicas alegres, acompanhados por instrumentos musicais: liras, harpas e címbalos sonoros."),  (2630, 13, 15, 17, "Assim, os levitas escolheram Hemã, filho de Joel, e Asafe, um parente dele; e dentre os meraritas, seus parentes, escolheram Etã, filho de Cuxaías;"),  (2631, 13, 15, 18, "e com eles seus parentes que estavam no segundo escalão: Zacarias, Jaaziel, Semiramote, Jeiel, Uni, Eliabe, Benaia, Maaséias, Matitias, Elifeleu, Micnéias, Obede-Edom e Jeiel, os porteiros."),  (2632, 13, 15, 19, "Os músicos Hemã, Asafe e Etã deviam tocar os címbalos de bronze;"),  (2633, 13, 15, 20, "Zacarias, Aziel, Semiramote, Jeiel, Uni, Eliabe, Maaséias e Benaia deviam tocar as liras, acompanhando o soprano,"),  (2634, 13, 15, 21, "e Matitias, Elifeleu, Micnéias, Obede-Edom, Jeiel e Azazias deviam tocar as harpas em oitava, marcando o ritmo."),  (2635, 13, 15, 22, "Quenanias, o chefe dos levitas, ficou encarregado dos cânticos; essa era sua responsabilidade, pois ele era capaz nisso."),  (2636, 13, 15, 23, "Berequias e Elcana seriam porteiros. Eles deveriam proteger a arca."),  (2637, 13, 15, 24, "Os sacerdotes Sebanias, Josafá, Natanael, Amasai, Zacarias, Benaia e Eliézer deviam tocar as cornetas diante da arca de Deus. Obede-Edom e Jeías também deviam ser porteiros, para vigiar a arca."),  (2638, 13, 15, 25, "Assim, com grande festa, foram Davi, as autoridades de Israel e os líderes de batalhões de mil buscar a arca da aliança do Senhor na casa de Obede-Edom."),  (2639, 13, 15, 26, "Como Deus havia poupado os levitas que carregavam a arca da aliança do Senhor, sete novilhos e sete carneiros foram sacrificados."),  (2640, 13, 15, 27, "E Davi vestia um manto de linho fino, assim como também todos os levitas que carregavam a arca, os músicos e Quenanias, chefe dos músicos. E Davi vestia também o colete sacerdotal de linho."),  (2641, 13, 15, 28, "E todo Israel acompanhou a arca da aliança do Senhor alegremente, ao som de trombetas, cornetas e címbalos, ao toque de liras e de harpas."),  (2642, 13, 15, 29, "Aconteceu que, entrando a arca da aliança do Senhor na cidade de Davi, Mical, filha de Saul, observava de uma janela. E, ao ver o rei Davi dançando e comemorando, ela o desprezou em seu coração."),  (2643, 13, 16, 1, "Eles trouxeram a arca de Deus e a colocaram na tenda que Davi lhe havia preparado, e ofereceram holocaustos e sacrifícios de comunhão diante de Deus."),  (2644, 13, 16, 2, "Após oferecer os holocaustos e os sacrifícios de comunhão, Davi abençoou o povo em nome do Senhor,"),  (2645, 13, 16, 3, "e deu um pão, um bolo de tâmaras e um bolo de uvas passas a cada homem e a cada mulher israelita."),  (2646, 13, 16, 4, "Davi nomeou alguns dos levitas para ministrarem diante da arca do Senhor, fazendo petições, dando graças, e louvando o Senhor, o Deus de Israel."),  (2647, 13, 16, 5, "Desses, Asafe era o chefe, Zacarias vinha em seguida, e depois Jeiel, Semiramote, Jeiel, Matitias, Eliabe, Benaia, Obede-Edom e Jeiel. Eles deviam tocar lira e harpa, enquanto Asafe tocava os címbalos."),  (2648, 13, 16, 6, "Os sacerdotes Benaia e Jaaziel deviam tocar diariamente as trombetas diante da arca da aliança de Deus."),  (2649, 13, 16, 7, "Foi naquele dia que pela primeira vez Davi encarregou a Asafe e seus parentes de louvar ao Senhor com salmos de gratidão:"),  (2650, 13, 16, 8, "Dêem graças ao Senhor, clamem pelo seu nome, divulguem entre as nações o que ele tem feito."),  (2651, 13, 16, 9, "Cantem para ele, louvem-no; contem todos os seus atos maravilhosos."),  (2652, 13, 16, 10, "Gloriem-se no seu santo nome; alegrem-se os corações dos que buscam o Senhor."),  (2653, 13, 16, 11, "Olhem para o Senhor e para a sua força; busquem sempre a sua face."),  (2654, 13, 16, 12, "Lembrem-se das maravilhas que ele fez, dos seus prodígios e das ordenanças que pronunciou,"),  (2655, 13, 16, 13, "ó descendentes de Israel, seu servo, ó filhos de Jacó, seus escolhidos."),  (2656, 13, 16, 14, "Ele é o Senhor, o nosso Deus; seus domínio alcança toda a terra."),  (2657, 13, 16, 15, "Para sempre se lembra da sua aliança, da palavra que ordenou para mil gerações,"),  (2658, 13, 16, 16, "da aliança que fez com Abraão, do juramento que fez a Isaque,"),  (2659, 13, 16, 17, "que confirmou para Jacó como um decreto, e para Israel como uma aliança eterna, dizendo:"),  (2660, 13, 16, 18, "A vocês darei a terra de Canaã, a herança que possuirão."),  (2661, 13, 16, 19, "Quando eles ainda eram poucos, muito poucos, e estrangeiros nela,"),  (2662, 13, 16, 20, "e vagueavam de nação em nação, de um reino a outro,"),  (2663, 13, 16, 21, "ele não permitiu que ninguém os oprimisse; por causa deles repreendeu reis, ordenando:"),  (2664, 13, 16, 22, "Não maltratem os meus ungidos; não façam mal aos meus profetas."),  (2665, 13, 16, 23, "Cantem ao Senhor, todas as terras! Proclamem a sua salvação dia após dia!"),  (2666, 13, 16, 24, "Anunciem a sua glória entre as nações, seus feitos maravilhosos entre todos os povos!"),  (2667, 13, 16, 25, "Pois o Senhor é grande e muitíssimo digno de louvor; ele deve ser mais temido que todos os deuses."),  (2668, 13, 16, 26, "Pois todos os deuses das nações não passam de ídolos, mas o Senhor fez os céus."),  (2669, 13, 16, 27, "O esplendor e a majestade estão diante dele; força e alegria na sua habitação."),  (2670, 13, 16, 28, "Dêem ao Senhor, ó famílias das nações, dêem ao Senhor glória e força."),  (2671, 13, 16, 29, "Dêem ao Senhor a glória devida ao seu nome. Tragam ofertas e venham à sua presença. Adorem o Senhor no esplendor da sua santidade,"),  (2672, 13, 16, 30, "tremam diante dele, todas as nações! Firmou o mundo, que não se abalará!"),  (2673, 13, 16, 31, "Que os céus se alegrem e a terra exulte, e diga-se entre as nações: O Senhor reina! "),  (2674, 13, 16, 32, "Ressoe o mar, e tudo o que nele existe; exultem os campos, e tudo o que neles há!"),  (2675, 13, 16, 33, "Então as árvores da floresta cantarão de alegria, cantarão diante do Senhor, pois ele vem julgar a terra."),  (2676, 13, 16, 34, "Rendam graças ao Senhor, pois ele é bom; o seu amor dura para sempre."),  (2677, 13, 16, 35, "Clamem: Salva-nos, ó Deus, nosso Salvador! Reúne-nos e livra-nos das nações, para que demos graças ao teu santo nome e façamos do teu louvor a nossa glória."),  (2678, 13, 16, 36, "Bendito seja o Senhor, o Deus de Israel, de eternidade a eternidade. Então todo o povo exclamou: Amém!  e Louvado seja o Senhor! "),  (2679, 13, 16, 37, "Então Davi deixou Asafe e seus parentes diante da arca da aliança do Senhor para ali ministrarem regularmente, de acordo com as prescrições para cada dia."),  (2680, 13, 16, 38, "Também deixou Obede-Edom e seus sessenta e oito parentes para ministrarem com eles. Obede-Edom, filho de Jedutum, e também Hosa foram porteiros."),  (2681, 13, 16, 39, "Davi deixou o sacerdote Zadoque e seus parentes sacerdotes diante do tabernáculo do Senhor em Gibeom"),  (2682, 13, 16, 40, "para regularmente, de manhã e à tarde, apresentarem holocaustos no altar de holocaustos, de acordo com tudo o que está escrito na Lei do Senhor, que ele deu a Israel."),  (2683, 13, 16, 41, "Com eles estavam Hemã e Jedutum e os outros designados para darem graças ao Senhor, exclamando: O seu amor dura para sempre."),  (2684, 13, 16, 42, "Hemã e Jedutum eram responsáveis pelas trombetas, pelos címbalos e pelos outros instrumentos musicais para o culto. Os filhos de Jedutum foram designados como porteiros."),  (2685, 13, 16, 43, "Então todo o povo partiu, cada um para a sua casa, e Davi voltou para casa para abençoar sua família."),  (2686, 13, 17, 1, "O rei Davi já morava em seu palácio quando, certo dia disse ao profeta Natã: Aqui estou eu, morando num palácio de cedro, enquanto a arca da aliança do Senhor permanece numa simples tenda."),  (2687, 13, 17, 2, "Natã respondeu a Davi: Faze o que tiveres em mente, pois Deus está contigo."),  (2688, 13, 17, 3, "E naquela mesma noite Deus falou a Natã:"),  (2689, 13, 17, 4, "Vá dizer ao meu servo Davi que assim diz o Senhor: Não será você quem vai construir uma casa para eu morar."),  (2690, 13, 17, 5, "Não tenho morado em nenhuma casa, desde o dia em que tirei Israel do Egito, mas fui de uma tenda para outra, e de um tabernáculo para outro."),  (2691, 13, 17, 6, "Por onde tenho acompanhado todo o Israel, alguma vez perguntei a algum líder deles, a quem ordenei que pastoreasse o meu povo: Por que você não me construiu um templo de cedro? "),  (2692, 13, 17, 7, "Agora pois, diga ao meu servo Davi: ‘Assim diz o Senhor dos Exércitos: Eu o tirei das pastagens, onde cuidava dos rebanhos, para ser o soberano do meu povo Israel."),  (2693, 13, 17, 8, "Sempre estive com você por onde você andou, e eliminei todos os seus inimigos. Agora eu o farei tão famoso quanto os homens mais importantes da terra."),  (2694, 13, 17, 9, "E providenciarei um lugar para o meu povo Israel e os plantarei lá, para que tenham o seu próprio lar; e não mais sejam incomodados. Povos ímpios não mais os oprimirão, como fizeram no início"),  (2695, 13, 17, 10, "e têm feito desde a época em que nomeei juízes sobre meu povo Israel. Também subjugarei todos os seus inimigos. Saiba também que eu, o Senhor, lhe estabelecerei uma dinastia."),  (2696, 13, 17, 11, "Quando a sua vida chegar ao fim e você se juntar aos seus antepassados, escolherei um dos seus filhos para sucedê-lo, e eu estabelecerei o reino dele."),  (2697, 13, 17, 12, "Será ele quem construirá um templo para mim, e eu firmarei o trono dele para sempre."),  (2698, 13, 17, 13, "Eu serei seu pai, e ele será meu filho. Nunca retirarei dele o meu amor, como retirei de Saul."),  (2699, 13, 17, 14, "Eu o farei líder do meu povo e do meu reino para sempre; seu reinado será estabelecido para sempre’. "),  (2700, 13, 17, 15, "E Natã transmitiu a Davi tudo o que o Senhor lhe tinha falado e revelado."),  (2701, 13, 17, 16, "Então o rei Davi entrou no tabernáculo, assentou-se diante do Senhor, e orou: Quem sou eu, ó Senhor Deus, e o que é a minha família, para que me trouxesses a este ponto?"),  (2702, 13, 17, 17, "E, como se isso não bastasse para ti, ó Deus, tu falaste sobre o futuro da família deste teu servo. Tens me tratado como um homem de grande importância, ó Senhor Deus."),  (2703, 13, 17, 18, "O que mais Davi poderá dizer-te por honrares o teu servo? Tu conheces o teu servo,"),  (2704, 13, 17, 19, "ó Senhor. Por amor do teu servo e de acordo com tua vontade, realizaste este feito grandioso e tornaste conhecidas todas essas grandes promessas."),  (2705, 13, 17, 20, "Não há ninguém como tu, ó Senhor, nem há outro Deus além de ti, conforme tudo o que sabemos."),  (2706, 13, 17, 21, "E quem é como o teu povo Israel, a única nação da terra que tu, ó Deus, resgataste para ti mesmo, e assim tornaste o teu nome famoso, realizaste grandes e impressionantes maravilhas ao expulsar nações de diante do povo que libertaste do Egito?"),  (2707, 13, 17, 22, "Tu fizeste do teu povo Israel o teu povo particular para sempre, e tu, ó Senhor, te tornaste o seu Deus."),  (2708, 13, 17, 23, "Agora, Senhor, que a promessa que fizeste a respeito de teu servo e de sua descendência se confirme para sempre. Faze conforme prometeste,"),  (2709, 13, 17, 24, "para que tudo se confirme, para que o teu nome seja engrandecido para sempre e os homens digam: ‘O Senhor dos Exércitos, o Deus de Israel, é Deus para Israel! ’ E a descendência de teu servo Davi se manterá firme diante de ti."),  (2710, 13, 17, 25, "Tu, meu Deus, revelaste a teu servo que formarás uma dinastia para ele. Por isso teu servo achou coragem para orar a ti."),  (2711, 13, 17, 26, "Ó Senhor, tu és Deus! Tu fizeste essa boa promessa a teu servo."),  (2712, 13, 17, 27, "Agora, por tua bondade, abençoa a família de teu servo, para que ela continue para sempre na tua presença; pois o que tu, Senhor, abençoas, abençoado está para sempre."),  (2713, 13, 18, 1, "Depois disso, Davi derrotou os filisteus e os subjugou, e tirou do controle deles a cidade de Gate e seus povoados."),  (2714, 13, 18, 2, "Davi derrotou também os moabitas, que ficaram sujeitos a ele, pagando-lhe impostos."),  (2715, 13, 18, 3, "Além disso, Davi derrotou Hadadezer, rei de Zobá, nas proximidades de Hamate, quando Hadadezer tentava obter o controle na região do rio Eufrates."),  (2716, 13, 18, 4, "Davi se apossou de mil dos seus carros de guerra, sete mil cavaleiros e vinte mil soldados de infantaria. Ainda levou cem cavalos de carros de guerra, e aleijou todos os outros."),  (2717, 13, 18, 5, "Quando os arameus de Damasco vieram ajudar Hadadezer, rei de Zobá, Davi matou vinte e dois mil deles."),  (2718, 13, 18, 6, "Em seguida estabeleceu guarnições militares no reino dos arameus de Damasco, sujeitando-os a lhe pagarem impostos. E o Senhor dava vitórias a Davi aonde quer que ele fosse."),  (2719, 13, 18, 7, "Davi também levou para Jerusalém os escudos de ouro usados pelos oficiais de Hadadezer."),  (2720, 13, 18, 8, "De Tebá e Cum, cidades que pertenciam a Hadadezer, o rei Davi levou grande quantidade de bronze, que Salomão utilizou para fazer o tanque de bronze, as colunas e vários utensílios."),  (2721, 13, 18, 9, "Quando Toú, rei de Hamate, soube que Davi tinha derrotado todo o exército de Hadadezer, rei de Zobá,"),  (2722, 13, 18, 10, "enviou seu filho Hadorão ao rei Davi para saudá-lo e parabenizá-lo por sua vitória na batalha contra Hadadezer, que tinha estado em guerra com Toú. E, com Hadorão, mandou todo tipo de utensílios de ouro, de prata e de bronze."),  (2723, 13, 18, 11, "O rei Davi consagrou esses utensílios ao Senhor, como fizera com a prata e o ouro tomados de todas estas nações: Edom e Moabe, os amonitas e os filisteus, e Amaleque."),  (2724, 13, 18, 12, "Abisai, filho de Zeruia, derrotou dezoito mil edomitas no vale do Sal."),  (2725, 13, 18, 13, "Depois colocou guarnições militares em Edom, sujeitando todos os edomitas a Davi. O Senhor dava vitórias a Davi aonde quer que ele fosse."),  (2726, 13, 18, 14, "Davi reinou sobre todo o Israel, administrando o direito e a justiça a todo o seu povo."),  (2727, 13, 18, 15, "Joabe, filho de Zeruia, era comandante do exército; Josafá, filho de Ailude, era o arquivista real;"),  (2728, 13, 18, 16, "Zadoque, filho de Aitube, e Aimeleque, filho de Abiatar, eram sacerdotes; Sausa era secretário;"),  (2729, 13, 18, 17, "Benaia, filho de Joiada, comandava os queretitas e os peletitas; e os filhos do rei Davi eram seus principais oficiais."),  (2730, 13, 19, 1, "Algum tempo depois, Naás, rei dos amonitas, morreu, e seu filho foi o seu sucessor."),  (2731, 13, 19, 2, "Davi pensou: Serei bondoso com Hanum, filho de Naás, porque seu pai foi bondoso comigo. Então Davi enviou uma delegação para transmitir a Hanum seu pesar pela morte do pai. Mas, quando os mensageiros de Davi chegaram à terra dos amonitas para expressar condolências a Hanum,"),  (2732, 13, 19, 3, "os líderes amonitas lhe disseram: Achas que Davi está honrando teu pai ao enviar mensageiros para expressar condolências? Não é nada disso! Davi os enviou como espiões para examinar o país e destruí-lo."),  (2733, 13, 19, 4, "Então Hanum prendeu os mensageiros de Davi, rapou-lhes a barba, cortou metade de suas roupas até as nádegas, e os mandou embora."),  (2734, 13, 19, 5, "Quando Davi soube disso, enviou mensageiros ao encontro deles, pois haviam sido profundamente humilhados, e lhes mandou dizer: Fiquem em Jericó até que a barba cresça, e então voltem para casa."),  (2735, 13, 19, 6, "Vendo Hanum e os amonitas que tinham atraído sobre si o ódio de Davi, alugaram da Mesopotâmia, de Arã Maaca e de Zobá, carros de guerra e condutores de carros, por trinta e cinco toneladas de prata."),  (2736, 13, 19, 7, "Alugaram trinta e dois mil carros e seus condutores, e contrataram o rei de Maaca com suas tropas, o qual veio e acampou perto de Medeba, e os amonitas foram convocados de suas cidades e partiram para a batalha."),  (2737, 13, 19, 8, "Ao saber disso, Davi ordenou a Joabe que marchasse com todo o exército."),  (2738, 13, 19, 9, "Os amonitas saíram e se puseram em posição de combate na entrada da cidade, e os reis que tinham vindo posicionaram-se em campo aberto."),  (2739, 13, 19, 10, "Vendo Joabe que estava cercado pelas linhas de combate, escolheu alguns dos melhores soldados de Israel e os posicionou contra os arameus."),  (2740, 13, 19, 11, "Pôs o restante dos homens sob o comando de seu irmão Abisai e os posicionou contra os amonitas."),  (2741, 13, 19, 12, "E Joabe disse a Abisai: Se os arameus forem fortes demais para mim, venha me ajudar; mas, se os amonitas forem fortes demais para você, eu irei ajudá-lo."),  (2742, 13, 19, 13, "Seja forte e lutemos com bravura pelo nosso povo e pelas cidades do nosso Deus. E que o Senhor faça o que for de sua vontade."),  (2743, 13, 19, 14, "Então Joabe e seus soldados avançaram contra os arameus, que fugiram dele."),  (2744, 13, 19, 15, "Quando os amonitas viram que os arameus estavam fugindo de Joabe, também fugiram de seu irmão Abisai e entraram na cidade. Assim, Joabe voltou para Jerusalém."),  (2745, 13, 19, 16, "Ao perceberem os arameus que haviam sido derrotados por Israel, enviaram mensageiros para trazer arameus que viviam do outro lado do Eufrates, e Sofaque, o comandante do exército de Hadadezer, veio à frente deles."),  (2746, 13, 19, 17, "Informado disso, Davi reuniu todo o Israel e atravessou o Jordão; avançou contra eles e formou linhas de combate defronte deles. Mas, começado o combate,"),  (2747, 13, 19, 18, "eles fugiram de diante de Israel, e Davi matou sete mil dos seus condutores de carros de guerra e quarenta mil dos seus soldados de infantaria. Também matou Sofaque, o comandante do exército deles."),  (2748, 13, 19, 19, "Quando os vassalos de Hadadezer viram que tinham sido derrotados por Israel, fizeram a paz com Davi e se sujeitaram a ele. E os arameus não quiseram mais ajudar os amonitas."),  (2749, 13, 20, 1, "Na primavera seguinte, na época em que os reis saem à guerra, Joabe conduziu o seu exército até a terra dos amonitas e a arrasou. Enquanto Davi ainda estava em Jerusalém, Joabe cercou Rabá, a capital, atacou-a e deixou-a em ruínas."),  (2750, 13, 20, 2, "Davi tirou a coroa da cabeça de Milcon, uma coroa de ouro de trinta e cinco quilos, ornamentada com pedras preciosas. E ela foi colocada na cabeça de Davi. Ele levou uma grande quantidade de bens da cidade,"),  (2751, 13, 20, 3, "e levou também os seus habitantes, designando-lhes trabalhos com serras, picaretas de ferro e machados. Davi fez assim com todas as cidades amonitas. Depois voltou com todo seu exército para Jerusalém."),  (2752, 13, 20, 4, "E houve depois disso uma guerra com os filisteus, em Gezer. Naquela época, Sibecai, de Husate, matou Sipai, um dos descendentes dos refains, e os filisteus foram subjugados."),  (2753, 13, 20, 5, "Noutra batalha contra os filisteus, Elanã, filho de Jair, matou Lami, irmão de Golias, de Gate, que possuía uma lança cuja haste parecia uma lançadeira de tecelão."),  (2754, 13, 20, 6, "Noutra batalha, em Gate, havia um homem de grande estatura e que tinha seis dedos em cada mão e seis dedos em cada pé; vinte e quatro dedos ao todo. Ele também era descendente de Rafa,"),  (2755, 13, 20, 7, "e ele desafiou Israel, mas Jônatas, filho de Siméia, irmão de Davi, o matou."),  (2756, 13, 20, 8, "Esses eram descendentes de Rafa, em Gate, e foram mortos por Davi e seus soldados."),  (2757, 13, 21, 1, "Satanás levantou-se contra Israel e levou Davi a fazer um recenseamento do povo."),  (2758, 13, 21, 2, "Davi disse a Joabe e aos outros comandantes do exército: Vão e contem os israelitas desde Berseba até Dã e tragam-me um relatório para que eu saiba quantos são."),  (2759, 13, 21, 3, "Joabe, porém, respondeu: Que o Senhor multiplique o povo dele por cem. Ó rei, meu senhor, não são, porventura, todos eles súditos do meu senhor? Por que o meu senhor deseja fazer isso? Por que deveria trazer culpa sobre Israel? "),  (2760, 13, 21, 4, "Mas a palavra do rei prevaleceu, de modo que Joabe partiu, percorreu todo o Israel e então voltou a Jerusalém."),  (2761, 13, 21, 5, "Joabe apresentou a Davi o relatório com o número dos homens de combate: Em todo o Israel havia um milhão e cem mil homens habilitados para o serviço militar, sendo quatrocentos e setenta mil de Judá."),  (2762, 13, 21, 6, "Mas Joabe não incluiu as tribos de Levi e de Benjamim na contagem, pois a ordem do rei lhe parecera absurda."),  (2763, 13, 21, 7, "Essa ordem foi reprovada por Deus, e por isso ele puniu Israel."),  (2764, 13, 21, 8, "Então Davi disse a Deus: Pequei gravemente com o que fiz. Agora eu te imploro que perdoes o pecado do teu servo, porque cometi uma grande loucura! "),  (2765, 13, 21, 9, "O Senhor disse a Gade, o vidente de Davi:"),  (2766, 13, 21, 10, "Vá dizer a Davi: ‘Assim diz o Senhor: Estou lhe dando três opções. Escolha uma delas, e eu a executarei contra você’ ."),  (2767, 13, 21, 11, "Então Gade foi a Davi e lhe disse: Assim diz o Senhor: ‘Escolha:"),  (2768, 13, 21, 12, "três anos de fome, três meses fugindo de seus adversários, perseguido pela espada deles, ou três dias da espada do Senhor, isto é, três dias de praga, com o anjo do Senhor assolando todas as regiões de Israel’. Decida agora como devo responder àquele que me enviou."),  (2769, 13, 21, 13, "Davi respondeu: É grande a minha angustia! Prefiro cair nas mãos do Senhor, pois é grande a sua misericórdia, e não nas mãos dos homens."),  (2770, 13, 21, 14, "Então o Senhor enviou uma praga sobre Israel, e setenta mil homens de Israel morreram."),  (2771, 13, 21, 15, "E Deus enviou um anjo para destruir Jerusalém. Mas, quando o anjo ia fazê-lo, o Senhor olhou e arrependeu-se de trazer a catástrofe, e ele disse ao anjo destruidor: Pare! Já basta!  Naquele momento o anjo do Senhor estava perto da eira de Araúna, o jebuseu."),  (2772, 13, 21, 16, "Davi olhou para cima e viu o anjo do Senhor entre o céu e a terra, com uma espada na mão erguida sobre Jerusalém. Então Davi e as autoridades de Israel, vestidos de luto, prostraram-se, rosto em terra."),  (2773, 13, 21, 17, "Davi disse a Deus: Não fui eu que ordenei contar o povo? Fui eu que pequei e fiz o mal. Estes não passam de ovelhas. O que eles fizeram? Ó Senhor meu Deus, que o teu castigo caia sobre mim e sobre a minha família, mas não sobre o teu povo! "),  (2774, 13, 21, 18, "Então o anjo do Senhor mandou Gade dizer a Davi que construísse um altar na eira de Araúna, o jebuseu."),  (2775, 13, 21, 19, "Davi foi para lá, em obediência à palavra que Gade havia falado em nome do Senhor."),  (2776, 13, 21, 20, "Araúna estava debulhando o trigo; virando-se, viu o anjo, e ele e seus quatro filhos que estavam com ele se esconderam."),  (2777, 13, 21, 21, "Nisso chegou Davi e, quando Araúna o viu, saiu da eira e prostrou-se diante de Davi, rosto em terra."),  (2778, 13, 21, 22, "E Davi lhe pediu: Ceda-me o terreno da sua eira para eu construir um altar em honra do Senhor, para que cesse a praga sobre o povo. Venda-me o terreno pelo preço justo."),  (2779, 13, 21, 23, "Mas Araúna disse a Davi: Considera-o teu! Que o meu rei e senhor faça dele o que desejar. Eu darei os bois para os holocaustos, o debulhador para servir de lenha, e o trigo para a oferta de cereal. Tudo isso eu dou a ti."),  (2780, 13, 21, 24, "O rei Davi, porém, respondeu a Araúna: Não! Faço questão de pagar o preço justo. Não darei ao Senhor aquilo que pertence a você, nem oferecerei um holocausto que não me custe nada."),  (2781, 13, 21, 25, "Então Davi pagou a Araúna sete quilos e duzentos gramas de ouro pelo terreno."),  (2782, 13, 21, 26, "E Davi edificou ali um altar ao Senhor e ofereceu holocaustos e sacrifícios de comunhão. Davi invocou o Senhor, e o Senhor lhe respondeu com fogo que veio do céu sobre o altar de holocaustos."),  (2783, 13, 21, 27, "E o Senhor ordenou ao anjo que pusesse a espada na bainha."),  (2784, 13, 21, 28, "Nessa ocasião viu Davi que o Senhor lhe havia respondido na eira de Araúna, o jebuseu, e passou a oferecer sacrifícios ali."),  (2785, 13, 21, 29, "Naquela época, o tabernáculo do Senhor que Moisés fizera no deserto, e o altar de holocaustos, estavam em Gibeom."),  (2786, 13, 21, 30, "Mas Davi não podia consultar a Deus lá, pois tinha medo da espada do anjo do Senhor."),  (2787, 13, 22, 1, "Então disse Davi: Este é o lugar para o templo de Deus, o Senhor, e do altar de holocaustos para Israel."),  (2788, 13, 22, 2, "Então Davi deu ordens para que se reunissem os estrangeiros que viviam em Israel, e dentre eles designou cortadores de pedra para prepararem pedras lavradas para a construção do templo de Deus."),  (2789, 13, 22, 3, "Ele providenciou grande quantidade de ferro para a fabricação de pregos e dobradiças para as portas, e mais bronze do que se podia pesar."),  (2790, 13, 22, 4, "Também providenciou mais toras de cedro do que se podia contar, pois os sidônios e os tírios haviam trazido muito cedro para Davi."),  (2791, 13, 22, 5, "Davi pensava: Meu filho Salomão é jovem e inexperiente, e o templo que será construído para o Senhor deve ser extraordinariamente magnífico, famoso e cheio de esplendor à vista de todas as nações. Por isso deixarei tudo preparado para a construção. Assim, Davi deixou tudo preparado antes de morrer."),  (2792, 13, 22, 6, "Davi mandou chamar seu filho Salomão e ordenou que ele construísse um templo para o Senhor, o Deus de Israel,"),  (2793, 13, 22, 7, "dizendo: Meu filho, eu tinha no coração o propósito de construir um templo em honra do nome do Senhor, o meu Deus."),  (2794, 13, 22, 8, "Mas veio a mim esta palavra do Senhor: ‘Você matou muita gente e empreendeu muitas guerras. Por isso você não construirá um templo em honra do meu nome, pois derramou muito sangue na terra, diante de mim."),  (2795, 13, 22, 9, "Mas você terá um filho que será um homem de paz, e eu farei com que ele tenha paz com todos os inimigos ao redor dele. Seu nome será Salomão, e eu darei paz e tranqüilidade a Israel durante o reinado dele."),  (2796, 13, 22, 10, "É ele que vai construir um templo em honra do meu nome. Eu serei seu pai e ele será meu filho. E eu firmarei para sempre o trono do reinado dele sobre Israel’."),  (2797, 13, 22, 11, "Agora, meu filho, que o Senhor seja com você, para que você consiga construir o templo do Senhor, o seu Deus, conforme ele disse que você faria."),  (2798, 13, 22, 12, "Que o Senhor lhe dê prudência e entendimento para que você obedeça à lei do Senhor, o seu Deus, quando ele o puser como líder de Israel."),  (2799, 13, 22, 13, "E você prosperará se for cuidadoso em obedecer aos decretos e às leis que o Senhor deu a Israel por meio de Moisés. Seja forte e corajoso! Não tenha medo nem se desanime!"),  (2800, 13, 22, 14, "Com muito esforço providenciei para o templo do Senhor três mil e quinhentas toneladas de ouro, trinta e cinco mil toneladas de prata, e tanto bronze e ferro que nem dá para calcular, além de madeira e pedra. E você ainda poderá aumentar a quantidade desse material."),  (2801, 13, 22, 15, "Você tem muitos trabalhadores: cortadores de pedras, pedreiros e carpinteiros, bem como especialistas em todo tipo de trabalho"),  (2802, 13, 22, 16, "em ouro, prata, bronze e ferro. Agora comece o trabalho, e que o Senhor esteja com você."),  (2803, 13, 22, 17, "Então Davi ordenou a todos os líderes de Israel que ajudassem seu filho Salomão."),  (2804, 13, 22, 18, "Disse ele: Certamente o Senhor, o seu Deus, está com vocês, e lhes concedeu paz. Pois ele entregou os habitantes dessa terra em minhas mãos, e ela foi submetida ao Senhor e ao seu povo."),  (2805, 13, 22, 19, "Agora consagrem o coração e a alma para buscarem o Senhor, o seu Deus. Comecem a construir o santuário de Deus, o Senhor, para que vocês possam trazer a arca da aliança do Senhor e os utensílios sagrados que pertencem a Deus para dentro do templo que será construído em honra do nome do Senhor."),  (2806, 13, 23, 1, "Já envelhecido e de idade avançada, Davi fez do seu filho Salomão rei sobre Israel."),  (2807, 13, 23, 2, "Ele reuniu todos os líderes de Israel, bem como os sacerdotes e os levitas."),  (2808, 13, 23, 3, "Os levitas de trinta anos para cima foram contados, e o número total deles chegou a trinta e oito mil."),  (2809, 13, 23, 4, "Davi escolheu vinte e quatro mil desses para supervisionarem o trabalho do templo do Senhor e seis mil para serem oficiais e juízes;"),  (2810, 13, 23, 5, "quatro mil para serem guardas das portas e quatro mil para louvarem o Senhor com os instrumentos musicais que Davi preparou com esse propósito."),  (2811, 13, 23, 6, "Davi repartiu os levitas em grupos que descendiam dos filhos de Levi, Gérson, Coate e Merari."),  (2812, 13, 23, 7, "Dos filhos de Gérson: Ladã e Simei."),  (2813, 13, 23, 8, "Estes foram os filhos de Ladã: Jeiel, o primeiro, Zetã e Joel, três ao todo."),  (2814, 13, 23, 9, "Estes foram os filhos de Simei: Selomote, Haziel e Harã, três ao todo. Esses foram os chefes das famílias de Ladã."),  (2815, 13, 23, 10, "E os filhos de Simei foram: Jaate, Ziza, Jeús e Berias. Esses foram os filhos de Simei, quatro ao todo."),  (2816, 13, 23, 11, "Jaate foi o primeiro e Ziza, o segundo, mas Jeús e Berias não tiveram muitos descendentes, por isso foram contados como uma única família."),  (2817, 13, 23, 12, "Dos filhos de Coate: Anrão, Isar, Hebrom e Uziel, quatro ao todo."),  (2818, 13, 23, 13, "Estes foram os filhos de Anrão: Arão e Moisés. Arão foi separado, ele e seus descendentes para sempre, para consagrar as coisas santíssimas, oferecer sacrifícios ao Senhor, ministrar diante dele e pronunciar bênçãos em seu nome, para sempre."),  (2819, 13, 23, 14, "Os filhos de Moisés, homem de Deus, foram contados como parte da tribo de Levi."),  (2820, 13, 23, 15, "Estes foram os filhos de Moisés: Gérson e Eliézer."),  (2821, 13, 23, 16, "Sebuel foi o chefe dos descendentes de Gérson."),  (2822, 13, 23, 17, "Reabias foi o chefe dos descendentes de Eliézer. Eliézer não teve nenhum outro filho, mas Reabias teve muitos filhos."),  (2823, 13, 23, 18, "Selomite foi o chefe dos filhos de Isar."),  (2824, 13, 23, 19, "Estes foram os filhos de Hebrom: Jerias foi o primeiro, Amarias, o segundo, Jaaziel, o terceiro, e Jecameão foi o quarto."),  (2825, 13, 23, 20, "Estes foram os filhos de Uziel: Mica, o primeiro, e Issias, o segundo."),  (2826, 13, 23, 21, "Dos filhos de Merari: Mali e Musi. Estes foram os filhos de Mali: Eleazar e Quis."),  (2827, 13, 23, 22, "Eleazar morreu sem ter filhos, pois teve apenas filhas. Os primos delas, os filhos de Quis, casaram-se com elas."),  (2828, 13, 23, 23, "Estes foram os filhos de Musi: Mali, Éder e Jeremote, três ao todo."),  (2829, 13, 23, 24, "Esses foram os descendentes de Levi pelas suas famílias: os chefes de famílias conforme registrados por seus nomes e contados individualmente, ou seja, os de vinte anos para cima, que serviam no templo do Senhor."),  (2830, 13, 23, 25, "Pois Davi dissera: Uma vez que o Senhor, o Deus de Israel, concedeu descanso ao seu povo e veio habitar para sempre em Jerusalém,"),  (2831, 13, 23, 26, "os levitas não mais precisam carregar o tabernáculo nem os utensílios usados em seu serviço."),  (2832, 13, 23, 27, "De acordo com as instruções finais de Davi, foram contados os levitas de vinte anos para cima."),  (2833, 13, 23, 28, "O dever dos levitas era ajudar os descendentes de Arão no serviço do templo do Senhor. Encarregavam-se dos pátios, das salas laterais, da purificação de todas as coisas sagradas e dos outros deveres na casa de Deus."),  (2834, 13, 23, 29, "Estavam encarregados do pão consagrado, da farinha para as ofertas de cereal, dos bolos sem fermento, de assar o pão e misturar a massa, e de todos os pesos e medidas."),  (2835, 13, 23, 30, "Além disso, deviam se apresentar todas as manhãs e todas as tardes para agradecer e louvar ao Senhor, e fazer o mesmo"),  (2836, 13, 23, 31, "sempre que holocaustos fossem apresentados ao Senhor nos sábados, nas festas da lua nova e nas festas fixas. Deviam servir regularmente diante do Senhor, conforme o número prescrito para eles."),  (2837, 13, 23, 32, "Dessa maneira os levitas ficaram responsáveis pela Tenda do Encontro, pelo Lugar Santo e, pela assistência aos seus irmãos, os descendentes de Arão, e pelo serviço do templo do Senhor."),  (2838, 13, 24, 1, "Os filhos de Arão foram assim agrupados: Os filhos de Arão foram Nadabe, Abiú, Eleazar e Itamar."),  (2839, 13, 24, 2, "Mas Nadabe e Abiú morreram antes de seu pai e não tiveram filhos; apenas Eleazar e Itamar serviram como sacerdotes."),  (2840, 13, 24, 3, "Com a ajuda de Zadoque, descendente de Eleazar, e de Aimeleque, descendente de Itamar, Davi os dividiu em grupos para que cumprissem as suas responsabilidades."),  (2841, 13, 24, 4, "Havia um número maior de chefes de família entre os descendentes de Eleazar do que entre os de Itamar, e por isso eles foram assim divididos: dezesseis chefes de famílias dentre os descendentes de Eleazar e oito, dentre os descendentes de Itamar."),  (2842, 13, 24, 5, "Eles foram divididos de maneira imparcial mediante sorteio, pois havia líderes do santuário e líderes de Deus tanto entre os descendentes de Eleazar como entre os de Itamar."),  (2843, 13, 24, 6, "O escriba Semaías, filho do levita Natanael, registrou os nomes deles na presença do rei, dos líderes, dos sacerdotes Zadoque e Aimeleque, filho de Abiatar, e dos chefes de famílias dos sacerdotes e dos levitas; as famílias de Eleazar e de Itamar foram sorteadas alternadamente."),  (2844, 13, 24, 7, "A primeira sorte caiu para Jeoiaribe, a segunda para Jedaías,"),  (2845, 13, 24, 8, "a terceira para Harim, a quarta para Seorim,"),  (2846, 13, 24, 9, "a quinta para Malquias, a sexta para Miamim,"),  (2847, 13, 24, 10, "a sétima para Hacoz, a oitava para Abias,"),  (2848, 13, 24, 11, "a nona para Jesua, a décima para Secanias,"),  (2849, 13, 24, 12, "a décima primeira para Eliasibe, a décima segunda para Jaquim,"),  (2850, 13, 24, 13, "a décima terceira para Hupá, a décima quarta para Jesebeabe,"),  (2851, 13, 24, 14, "a décima quinta para Bilga, a décima sexta para Imer,"),  (2852, 13, 24, 15, "a décima sétima para Hezir, a décima oitava para Hapises,"),  (2853, 13, 24, 16, "a décima nona para Petaías, a vigésima para Jeezquel,"),  (2854, 13, 24, 17, "a vigésima primeira para Jaquim, a vigésima segunda para Gamul,"),  (2855, 13, 24, 18, "a vigésima terceira para Delaías, e a vigésima quarta para Maazias."),  (2856, 13, 24, 19, "Conforme essa ordem eles deveriam ministrar quando entrassem no templo do Senhor, de acordo com as prescrições que Arão, antepassado deles, lhes deixou, conforme o Senhor, o Deus de Israel, havia lhe ordenado."),  (2857, 13, 24, 20, "Estes foram os chefes dos outros levitas: dos descendentes de Anrão: Subael; dos descendentes de Subael: Jedias."),  (2858, 13, 24, 21, "Quanto a Reabias, Issias foi o chefe dos seus filhos."),  (2859, 13, 24, 22, "Dos descendentes de Isar: Selomote; dos filhos de Selomote: Jaate."),  (2860, 13, 24, 23, "Dos descendentes de Hebrom: Jerias, o primeiro, Amarias, o segundo, Jaaziel, o terceiro, e Jecameão, o quarto."),  (2861, 13, 24, 24, "Dos descendentes de Uziel: Mica; dos filhos de Mica: Samir."),  (2862, 13, 24, 25, "Dos descendentes de Issias, irmão de Mica, Zacarias."),  (2863, 13, 24, 26, "Dos filhos de Merari: Mali e Musi. Dos filhos de Jaazias: Beno."),  (2864, 13, 24, 27, "Os descendentes de Merari por Jaazias: Beno, Soão, Zacur e Ibri."),  (2865, 13, 24, 28, "De Mali: Eleazar, que não teve filhos."),  (2866, 13, 24, 29, "De Quis: Jerameel."),  (2867, 13, 24, 30, "E foram estes os filhos de Musi: Mali, Éder e Jeremote. Esses foram os levitas, de acordo com as suas famílias."),  (2868, 13, 24, 31, "Eles também tiraram sortes na presença do rei Davi e de Zadoque, de Aimeleque, e dos chefes de famílias dos sacerdotes e dos levitas, assim como fizeram seus irmãos, os descendentes de Arão. As famílias dos irmãos mais velhos foram tratadas da mesma maneira que as dos mais novos."),  (2869, 13, 25, 1, "Davi, junto com os comandantes do exército, separou alguns dos filhos de Asafe, de Hemã e de Jedutum para o ministério de profetizar ao som de harpas, liras e címbalos. Esta é a lista dos escolhidos para essa função:"),  (2870, 13, 25, 2, "Dos filhos de Asafe: Zacur, José, Netanias e Asarela. Os filhos de Asafe estavam sob a sua supervisão que, por sua vez, profetizava sob a supervisão do rei."),  (2871, 13, 25, 3, "Dos filhos de Jedutum: Gedalias, Zeri, Jesaías, Simei, Hasabias e Matitias, seis ao todo, sob a supervisão de seu pai, Jedutum, que profetizava ao som da harpa para agradecer e louvar ao Senhor."),  (2872, 13, 25, 4, "Dos filhos de Hemã: Buquias, Matanias, Uziel, Sebuel, Jeremote, Hananias, Hanani, Eliata, Gidalti, Romanti-Ézer, Josbecasa, Maloti, Hotir e Maaziote."),  (2873, 13, 25, 5, "Todos esses eram filhos de Hemã, o vidente do rei. Esses lhe nasceram conforme as promessas de que Deus haveria de torná-lo poderoso. E Deus deu a Hemã catorze filhos e três filhas."),  (2874, 13, 25, 6, "Todos esses homens estavam sob a supervisão de seus pais quando ministravam a música do templo do Senhor, com címbalos, liras e harpas, na casa de Deus. Asafe, Jedutum e Hemã estavam sob a supervisão do rei."),  (2875, 13, 25, 7, "Junto com seus parentes, todos capazes e preparados para o ministério do louvor do Senhor, totalizavam 288."),  (2876, 13, 25, 8, "Então tiraram sortes entre jovens e velhos, mestres e discípulos para designar-lhes suas responsabilidades."),  (2877, 13, 25, 9, "A primeira sorte, caiu para José, filho de Asafe, com seus filhos e parentes; eram ao todo 12; a segunda, para Gedalias, com seus filhos e parentes, eram ao todo 12;"),  (2878, 13, 25, 10, "a terceira, para Zacur, com seus filhos e parentes, eram ao todo 12;"),  (2879, 13, 25, 11, "a quarta, para Izri, com seus filhos e parentes, eram ao todo 12;"),  (2880, 13, 25, 12, "a quinta, para Netanias, com seus filhos e parentes, eram ao todo 12;"),  (2881, 13, 25, 13, "a sexta, para Buquias, com seus filhos e parentes, eram ao todo 12;"),  (2882, 13, 25, 14, "a sétima, para Jesarela, com seus filhos e parentes, eram ao todo 12;"),  (2883, 13, 25, 15, "a oitava, para Jesaías, com seus filhos e parentes, eram ao todo 12;"),  (2884, 13, 25, 16, "a nona, para Matanias, com seus filhos e parentes, eram ao todo 12;"),  (2885, 13, 25, 17, "a décima, para Simei, com seus filhos e parentes, eram ao todo 12;"),  (2886, 13, 25, 18, "a décima primeira, para Azareel, com seus filhos e parentes, eram ao todo 12;"),  (2887, 13, 25, 19, "a décima segunda, para Hasabias, com seus filhos e parentes, eram ao todo 12;"),  (2888, 13, 25, 20, "a décima terceira, para Subael, com seus filhos e parentes, eram ao todo 12;"),  (2889, 13, 25, 21, "a décima quarta, para Matitias, com seus filhos e parentes, eram ao todo 12;"),  (2890, 13, 25, 22, "a décima quinta, para Jeremote, com seus filhos e parentes, eram ao todo 12;"),  (2891, 13, 25, 23, "a décima sexta, para Hananias, com seus filhos e parentes, eram ao todo 12;"),  (2892, 13, 25, 24, "a décima sétima, para Josbecasa, com seus filhos e parentes, eram ao todo 12;"),  (2893, 13, 25, 25, "a décima oitava, para Hanani, com seus filhos e parentes, eram ao todo 12;"),  (2894, 13, 25, 26, "a décima nona, para Maloti, com seus filhos e parentes, eram ao todo 12;"),  (2895, 13, 25, 27, "a vigésima, para Eliata, com seus filhos e parentes, eram ao todo 12;"),  (2896, 13, 25, 28, "a vigésima primeira, para Hotir, com seus filhos e parentes, eram ao todo 12;"),  (2897, 13, 25, 29, "a vigésima segunda, para Gidalti, com seus filhos e parentes, eram ao todo 12;"),  (2898, 13, 25, 30, "a vigésima terceira, para Maaziote, com seus filhos e parentes, eram ao todo 12;"),  (2899, 13, 25, 31, "a vigésima quarta, para Romanti-Ézer, com seus filhos e parentes, eram ao todo 12."),  (2900, 13, 26, 1, "Esta é a relação dos grupos dos porteiros: Dos coreítas, Meselemias, filho de Coré, da família de Asafe."),  (2901, 13, 26, 2, "Foram estes os filhos de Meselemias: Zacarias, o primeiro, Jediael, o segundo, Zebadias, o terceiro, Jatniel, o quarto,"),  (2902, 13, 26, 3, "Elão, o quinto, Joanã, o sexto, e Elioenai, o sétimo."),  (2903, 13, 26, 4, "Foram estes os filhos de Obede-Edom: Semaías, o primeiro, Jeozabade, o segundo, Joá, o terceiro, Sacar, o quarto, Natanael, o quinto,"),  (2904, 13, 26, 5, "Amiel, o sexto, Issacar, o sétimo, e Peuletai, o oitavo. Pois Deus havia abençoado Obede-Edom."),  (2905, 13, 26, 6, "Seu filho Semaías também teve filhos, que foram líderes na família do seu pai, pois eram homens capazes."),  (2906, 13, 26, 7, "Foram estes os filhos de Semaías: Otni, Rafael, Obede e Elzabade. Os parentes dele, Eliú e Semaquias, também foram homens capazes."),  (2907, 13, 26, 8, "Todos esses foram descendentes de Obede-Edom; eles e os seus filhos e parentes eram capazes e aptos para a obra. Eram ao todo 62 descendentes de Obede-Edom."),  (2908, 13, 26, 9, "Meselemias teve 18 filhos e parentes chegados, todos eles homens capazes."),  (2909, 13, 26, 10, "Foram estes os filhos de Hosa, o merarita: Sinri, que foi nomeado chefe por seu pai, mesmo não sendo o mais velho,"),  (2910, 13, 26, 11, "Hilquias, o segundo, Tebalias, o terceiro, e Zacarias, o quarto. Os filhos e parentes de Hosa foram 13 ao todo."),  (2911, 13, 26, 12, "Essas divisões dos porteiros, feitas pelos chefes deles; eles cumpriam tarefas no serviço do templo do Senhor, assim como seus parentes."),  (2912, 13, 26, 13, "Tiraram sortes entre as famílias, incluindo jovens e velhos, para que cuidassem de cada porta."),  (2913, 13, 26, 14, "E a porta leste coube a Selemias. Então tiraram sortes para seu filho Zacarias, sábio conselheiro, e a porta norte foi sorteada para ele."),  (2914, 13, 26, 15, "A sorte da porta sul saiu para Obede-Edom, e a do depósito, para seus filhos."),  (2915, 13, 26, 16, "A sorte da porta oeste e da porta Salequete, na rua de cima, saíram para Supim e Hosa. Os guardas ficavam um ao lado do outro:"),  (2916, 13, 26, 17, "Havia seis levitas por dia no leste, quatro no norte, quatro no sul e dois de cada vez no depósito."),  (2917, 13, 26, 18, "Quanto ao pátio a oeste, havia quatro na rua e dois no próprio pátio."),  (2918, 13, 26, 19, "Foram essas as divisões dos porteiros, descendentes de Coré e Merari."),  (2919, 13, 26, 20, "Outros dos seus irmãos levitas estavam encarregados dos depósitos dos tesouros do templo de Deus e do depósito das dádivas sagradas."),  (2920, 13, 26, 21, "Os gersonitas, descendentes de Ladã, que eram chefes de famílias pertencentes a Ladã, foram Jeieli"),  (2921, 13, 26, 22, "e seus filhos Zetã e seu irmão Joel. Estavam encarregados da tesouraria do templo do Senhor."),  (2922, 13, 26, 23, "Dos filhos de Anrão, de Isar, de Hebrom e de Uziel:"),  (2923, 13, 26, 24, "Sebuel, um descendente de Gérson, filho de Moisés, era o oficial encarregado dos depósitos dos tesouros."),  (2924, 13, 26, 25, "Seus parentes por parte de Eliézer foram seu filho Reabias, que foi o pai de Jesaías, o avô de Jorão, o bisavô de Zicri, o tataravô de Selomote."),  (2925, 13, 26, 26, "Selomote e seus parentes estavam encarregados de todos os tesouros consagrados pelo rei Davi, pelos chefes de famílias que eram os comandantes de mil e de cem, e pelos outros líderes do exército."),  (2926, 13, 26, 27, "Eles consagravam parte dos despojos tomados em combate para a manutenção do templo do Senhor."),  (2927, 13, 26, 28, "E todas as dádivas consagradas pelo vidente Samuel e por Saul, filho de Quis, por Abner, filho de Ner, e por Joabe, filho de Zeruia, e todas as demais dádivas sagradas estavam sob os cuidados de Selomote e seus parentes."),  (2928, 13, 26, 29, "Dos filhos de Isar, Quenanias e seus filhos ficaram responsáveis pelos negócios públicos de Israel, atuando como oficiais e juízes."),  (2929, 13, 26, 30, "Dos filhos de Hebrom, Hasabias e seus parentes, que ficaram responsáveis em Israel, a oeste do Jordão, por todo o trabalho do Senhor e pelo serviço do rei; ao todo eram mil e setecentos homens capazes."),  (2930, 13, 26, 31, "De acordo com os registros genealógicos das famílias hebronitas, Jerias foi o chefe delas. No ano quarenta do reinado de Davi fez-se uma busca nos registros, e entre os descendentes de Hebrom encontraram-se homens capazes, em Jazar de Gileade."),  (2931, 13, 26, 32, "Jerias tinha dois mil e setecentos parentes, homens capazes e chefes de famílias, que o rei Davi encarregou de todas as questões pertinentes a Deus e aos negócios do rei nas tribos de Rúben e de Gade, e da metade da tribo de Manassés."),  (2932, 13, 27, 1, "Esta é a lista dos israelitas, chefes de famílias, comandantes de mil e comandantes de cem; oficiais que serviam o rei na supervisão das divisões do exército que estavam de serviço mês a mês, durante o ano. Cada divisão era constituída por 24. 000 homens."),  (2933, 13, 27, 2, "Encarregado da primeira divisão de 24. 000 homens, para o primeiro mês, estava Jasobeão, filho de Zabdiel."),  (2934, 13, 27, 3, "Ele era descendente de Perez e chefe de todos os oficiais do exército para o primeiro mês."),  (2935, 13, 27, 4, "Encarregado da divisão para o segundo mês estava Dodai, descendente de Aoí; Miclote era o líder da sua divisão que contava 24. 000 homens."),  (2936, 13, 27, 5, "O terceiro comandante do exército, para o terceiro mês, foi Benaia, filho do sacerdote Joiada. Ele era chefe da sua divisão de 24. 000 homens."),  (2937, 13, 27, 6, "Esse Benaia foi guerreiro, chefe dos Trinta. Seu filho Amizabade estava encarregado da sua divisão."),  (2938, 13, 27, 7, "O quarto, para o quarto mês, foi Asael, irmão de Joabe; seu filho Zebadias foi seu sucessor. Havia 24. 000 homens em sua divisão."),  (2939, 13, 27, 8, "O quinto, para o quinto mês, foi o comandante Samute, o izraíta. Havia 24. 000 homens em sua divisão."),  (2940, 13, 27, 9, "O sexto, para o sexto mês, foi Ira, filho de Iques, de Tecoa. Havia 24. 000 homens em sua divisão."),  (2941, 13, 27, 10, "O sétimo, para o sétimo mês, foi Helez, de Pelom, descendente de Efraim. Havia 24. 000 homens em sua divisão."),  (2942, 13, 27, 11, "O oitavo, para o oitavo mês, foi Sibecai, de Husate, da família de Zerá. Havia 24. 000 homens em sua divisão."),  (2943, 13, 27, 12, "O nono, para o nono mês, foi Abiezer, de Anatote, da tribo de Benjamim. Havia 24. 000 homens em sua divisão."),  (2944, 13, 27, 13, "O décimo, para o décimo mês, foi Maarai, de Netofate, da família de Zerá. Havia 24. 000 homens em sua divisão."),  (2945, 13, 27, 14, "O décimo primeiro, para o décimo primeiro mês, foi Benaia, de Piratom, descendente de Efraim. Havia 24. 000 homens em sua divisão."),  (2946, 13, 27, 15, "O décimo segundo, para o décimo segundo mês, foi Heldai, de Netofate, da família de Otoniel. Havia 24. 000 homens em sua divisão."),  (2947, 13, 27, 16, "Estes foram os líderes das tribos de Israel: de Rúben: Eliézer, filho de Zicri; de Simeão: Sefatias, filho de Maaca;"),  (2948, 13, 27, 17, "de Levi: Hasabias, filho de Quemuel; de Arão: Zadoque;"),  (2949, 13, 27, 18, "de Judá: Eliú, irmão de Davi; de Issacar: Onri, filho de Micael;"),  (2950, 13, 27, 19, "de Zebulom: Ismaías, filho de Obadias; de Naftali: Jeremote, filho de Azriel;"),  (2951, 13, 27, 20, "dos descendentes de Efraim: Oséias, filho de Azazias; da metade da tribo de Manassés: Joel, filho de Pedaías;"),  (2952, 13, 27, 21, "da outra metade da tribo de Manassés, em Gileade: Ido, filho de Zacarias; de Benjamim: Jaasiel, filho de Abner;"),  (2953, 13, 27, 22, "de Dã: Azareel, filho de Jeroão. Foram esses os líderes das tribos de Israel."),  (2954, 13, 27, 23, "Davi não contou os homens com menos de vinte anos, pois o Senhor havia prometido tornar Israel tão numeroso quanto as estrelas do céu."),  (2955, 13, 27, 24, "Joabe, filho de Zeruia, começou a contar os homens, mas não pôde terminar. A ira divina caiu sobre Israel por causa desse recenseamento, e o resultado não entrou nos registros históricos do rei Davi."),  (2956, 13, 27, 25, "Azmavete, filho de Adiel, estava encarregado dos tesouros do palácio. Jônatas, filho de Uzias, estava encarregado dos depósitos do rei nos distritos distantes, nas cidades, nos povoados e nas torres de sentinela."),  (2957, 13, 27, 26, "Ezri, filho de Quelube, estava encarregado dos trabalhadores rurais, que cultivavam a terra."),  (2958, 13, 27, 27, "Simei, de Ramá, estava encarregado das vinhas. Zabdi, de Sifá, estava encarregado do vinho que era armazenado em tonéis."),  (2959, 13, 27, 28, "Baal-Hanã, de Gederá, estava encarregado das oliveiras e das figueiras bravas, na Sefelá. Joás estava encarregado do fornecimento de azeite."),  (2960, 13, 27, 29, "Sitrai, de Sarom, estava encarregado dos rebanhos que pastavam em Sarom. Safate, filho de Adlai, estava encarregado dos rebanhos nos vales."),  (2961, 13, 27, 30, "O ismaelita Obil estava encarregado dos camelos. Jedias, de Meronote, estava encarregado dos jumentos."),  (2962, 13, 27, 31, "O hagareno Jaziz estava encarregado das ovelhas. Todos esses eram encarregados de cuidar dos bens do rei Davi."),  (2963, 13, 27, 32, "Jônatas, tio de Davi, era conselheiro; homem sábio e também escriba. Jeiel, filho de Hacmoni, cuidava dos filhos do rei."),  (2964, 13, 27, 33, "Aitofel era conselheiro do rei. Husai, o arquita, era amigo do rei."),  (2965, 13, 27, 34, "Aitofel foi sucedido por Joiada, filho de Benaia, e por Abiatar. Joabe era o comandante do exército real."),  (2966, 13, 28, 1, "Davi reuniu em Jerusalém todos os líderes de Israel: os líderes das tribos, os líderes das divisões a serviço do rei, os comandantes de mil e de cem, e os líderes encarregados de todos os bens e rebanhos que pertenciam ao rei e a seus filhos, juntamente com os funcionários do palácio, os principais guerreiros e todos os soldados valentes."),  (2967, 13, 28, 2, "O rei Davi se pôs de pé e disse: Escutem-me, meus irmãos e meu povo. Eu tinha no coração o propósito de construir um templo para nele colocar a arca da aliança do Senhor, o estrado dos pés de nosso Deus; fiz planos para construí-lo,"),  (2968, 13, 28, 3, "mas Deus me disse: ‘Você não construirá um templo em honra do meu nome, pois você é um guerreiro e matou muita gente’."),  (2969, 13, 28, 4, "No entanto, o Senhor, o Deus de Israel, escolheu-me dentre toda a minha família para ser rei em Israel, para sempre. Ele escolheu Judá como líder, e da tribo de Judá escolheu minha família, e entre os filhos de meu pai ele quis fazer-me rei de todo o Israel."),  (2970, 13, 28, 5, "E, dentre todos os muitos filhos que me deu, ele escolheu Salomão para sentar-se no trono de Israel, o reino do Senhor."),  (2971, 13, 28, 6, "Ele me disse: ‘Seu filho Salomão é quem construirá o meu templo e os meus pátios, pois eu o escolhi para ser meu filho, e eu serei o pai dele."),  (2972, 13, 28, 7, "Firmarei para sempre o reino dele, se ele continuar a obedecer os meus mandamentos e as minhas ordenanças, como faz agora’."),  (2973, 13, 28, 8, "Por isso agora declaro-lhes perante todo o Israel e a assembléia do Senhor, e diante dos ouvidos de nosso Deus: Tenham o cuidado de obedecer a todos os mandamentos do Senhor, do seu Deus, para que mantenham a posse dessa boa terra e a dêem por herança aos seus descendentes para sempre."),  (2974, 13, 28, 9, "E você, meu filho Salomão, reconheça o Deus de seu pai, e sirva-o de todo o coração e espontaneamente, pois o Senhor sonda todos os corações e conhece a motivação dos pensamentos. Se você o buscar, o encontrará, mas, se você o abandonar, ele o rejeitará para sempre."),  (2975, 13, 28, 10, "Veja que o Senhor o escolheu para construir um templo que me sirva de santuário. Seja forte e mãos ao trabalho! "),  (2976, 13, 28, 11, "Então Davi deu a seu filho Salomão a planta do pórtico do templo, para os seus edifícios, para os seus depósitos, para os andares superiores e suas salas, e para o lugar do propiciatório."),  (2977, 13, 28, 12, "Entregou-lhe também as plantas de tudo o que o Espírito havia posto em seu coração acerca dos pátios do templo do Senhor e de todas as salas ao redor, para os depósitos dos tesouros do templo de Deus e para os depósitos das dádivas sagradas."),  (2978, 13, 28, 13, "Deu-lhe instruções sobre as divisões dos sacerdotes e dos levitas, e sobre à execução de todas as tarefas no templo do Senhor, e os utensílios que seriam utilizados."),  (2979, 13, 28, 14, "Determinou o peso do ouro para todos os utensílios de ouro e o peso da prata para todos os utensílios de prata que seriam utilizados nas diferentes tarefas:"),  (2980, 13, 28, 15, "o peso de ouro para cada candelabro e suas lâmpadas; e o peso de prata para cada candelabro de prata e suas lâmpadas, de acordo com a finalidade de cada um;"),  (2981, 13, 28, 16, "o peso de ouro para cada mesa de pães consagrados; o peso de prata para as mesas de prata;"),  (2982, 13, 28, 17, "o peso de ouro puro para os garfos, para as bacias de aspersão e para os jarros; o peso de ouro para cada tigela de ouro; o peso de prata para cada tigela de prata;"),  (2983, 13, 28, 18, "e o peso de ouro refinado para o altar de incenso. Também lhe deu o desenho do carro dos querubins de ouro que, com suas asas estendidas, abrigam a arca da aliança do Senhor."),  (2984, 13, 28, 19, "Tudo isso, disse Davi a Salomão, foi me dado por escrito pela mão do Senhor, e ele me deu entendimento para executar todos esses projetos. "),  (2985, 13, 28, 20, "E acrescentou: Seja forte e corajoso! Mãos ao trabalho! Não tenha medo nem se desanime, pois Deus, o Senhor, o meu Deus, está com você. Ele não o deixará nem o abandonará até que se termine toda a construção do templo do Senhor."),  (2986, 13, 28, 21, "As divisões dos sacerdotes e dos levitas estão definidas para todas as tarefas que se farão no templo de Deus, e você receberá ajuda de homens peritos em todo tipo de serviço. Os líderes e todo o povo obedecerão a todas as suas ordens."),  (2987, 13, 29, 1, "Então o rei Davi disse a toda a assembléia: Meu filho Salomão, e só ele, foi quem Deus escolheu. Mas ele é jovem e inexperiente e a tarefa é grande, pois o palácio não será feito para homens, mas para o Senhor Deus."),  (2988, 13, 29, 2, "Forneci grande quantidade de recursos para o trabalho do templo do meu Deus: ouro, prata, bronze, ferro e madeira, bem como ônix para os engastes, e ainda turquesas, pedras de várias cores e todo tipo de pedras preciosas, e mármore."),  (2989, 13, 29, 3, "Além disso, pelo meu amor ao templo do meu Deus, agora entrego das minhas próprias riquezas, ouro e prata para o templo do meu Deus, além de tudo o que já tenho dado para este santo templo."),  (2990, 13, 29, 4, "Ofereço, pois, cento e cinco toneladas de ouro puro de Ofir e duzentos e quarenta e cinco toneladas de prata refinada, para o revestimento das paredes do templo,"),  (2991, 13, 29, 5, "para o trabalho em ouro e em prata, e para todo o trabalho dos artesãos. Agora, quem hoje está disposto a ofertar dádivas ao Senhor? "),  (2992, 13, 29, 6, "Então os chefes das famílias, os líderes das tribos de Israel, os comandantes de mil e de cem, e os oficiais encarregados do trabalho do rei ofertaram espontaneamente."),  (2993, 13, 29, 7, "Para a obra do templo de Deus eles deram cento e setenta e cinco toneladas de ouro e dez mil moedas de ouro, trezentas e cinqüenta toneladas de prata, seiscentas e trinta toneladas de bronze e três mil e quinhentas toneladas de ferro."),  (2994, 13, 29, 8, "Quem tinha pedras preciosas deu-as para o depósito dos tesouros do templo do Senhor, cujo responsável era Jeiel, o gersonita."),  (2995, 13, 29, 9, "O povo alegrou-se diante da atitude de seus líderes, pois fizeram essas ofertas voluntariamente e de coração íntegro ao Senhor. E o rei Davi também encheu-se de alegria."),  (2996, 13, 29, 10, "Davi louvou o Senhor na presença de toda a assembléia, dizendo: Bendito sejas, ó Senhor, Deus de Israel, nosso pai, de eternidade a eternidade."),  (2997, 13, 29, 11, "Teus, ó Senhor, são a grandeza, o poder, a glória, a majestade e o esplendor, pois tudo o que há nos céus e na terra é teu. Teu, ó Senhor, é o reino; tu estás acima de tudo."),  (2998, 13, 29, 12, "A riqueza e a honra vêm de ti; tu dominas sobre todas as coisas. Nas tuas mãos estão a força e o poder para exaltar e dar força a todos."),  (2999, 13, 29, 13, "Agora, nosso Deus, damos-te graças, e louvamos o teu glorioso nome."),  (3000, 13, 29, 14, "Mas quem sou eu, e quem é o meu povo para que pudéssemos contribuir tão generosamente como fizemos? Tudo vem de ti, e nós apenas te demos o que vem das tuas mãos."),  (3001, 13, 29, 15, "Diante de ti somos estrangeiros e forasteiros, como os nossos antepassados. Os nossos dias na terra são como uma sombra, sem esperança."),  (3002, 13, 29, 16, "Ó Senhor, nosso Deus, toda essa riqueza que ofertamos para construir um templo em honra do teu santo nome vem das tuas mãos, e toda ela pertence a ti."),  (3003, 13, 29, 17, "Sei, ó meu Deus, que sondas o coração e que te agradas com a integridade. Tudo o que dei foi espontaneamente e com integridade de coração. E agora vi com alegria com quanta disposição o teu povo, que aqui está, tem contribuído."),  (3004, 13, 29, 18, "Ó Senhor, Deus de nossos antepassados Abraão, Isaque e Israel, conserva para sempre este desejo no coração de teu povo, e mantém o coração deles leal a ti."),  (3005, 13, 29, 19, "E dá ao meu filho Salomão um coração íntegro para obedecer aos teus mandamentos, aos teus preceitos e aos teus decretos, a fim de construir este templo para o qual fiz os preparativos necessários."),  (3006, 13, 29, 20, "Então Davi disse a toda a assembléia: Louvem o Senhor, o seu Deus. E todos eles louvaram o Senhor, o Deus dos seus antepassados, inclinando-se e prostrando-se diante do Senhor e diante do rei."),  (3007, 13, 29, 21, "No dia seguinte fizeram sacrifícios ao Senhor e lhe apresentaram holocaustos: mil novilhos, mil carneiros e mil cordeiros, acompanhados de ofertas derramadas, e muitos outros sacrifícios, em favor de todo o Israel."),  (3008, 13, 29, 22, "Naquele dia, comeram e beberam com grande alegria na presença do Senhor. Então pela segunda vez proclamaram Salomão, filho de Davi, como rei, ungindo-o diante do Senhor como soberano, e Zadoque como sacerdote."),  (3009, 13, 29, 23, "De maneira que Salomão assentou-se como rei no trono do Senhor, em lugar de Davi, seu pai. Ele prosperou, e todo o Israel lhe obedecia."),  (3010, 13, 29, 24, "Todos os líderes e principais guerreiros, bem como todos os filhos do rei Davi prometeram submissão ao rei Salomão."),  (3011, 13, 29, 25, "O Senhor exaltou muitíssimo Salomão em todo o Israel e concedeu-lhe tal esplendor em seu reinado como nenhum rei de Israel jamais tivera."),  (3012, 13, 29, 26, "Davi, filho de Jessé, reinou sobre todo Israel."),  (3013, 13, 29, 27, "Ele reinou quarenta anos em Israel: sete anos em Hebrom e trinta e três em Jerusalém."),  (3014, 13, 29, 28, "Morreu em boa velhice, tendo desfrutado vida longa, riqueza e honra. Seu filho Salomão foi o seu sucessor."),  (3015, 13, 29, 29, "Os feitos do rei Davi, desde o início até o fim do seu reinado, estão escritos nos registros do vidente Samuel, do profeta Natã e do vidente Gade,"),  (3016, 13, 29, 30, "incluindo os detalhes do seu reinado e do seu poder, e os acontecimentos relacionados a ele, com Israel e com os reinos das outras terras."),  (3017, 14, 1, 1, "Salomão, filho de Davi, estabeleceu-se com firmeza sobre o seu reino, pois o Senhor, o seu Deus, estava com ele e tornou-o muito poderoso."),  (3018, 14, 1, 2, "Salomão reuniu todo o Israel: os líderes de mil e de cem, os juízes, todos os líderes de Israel e os chefes de famílias."),  (3019, 14, 1, 3, "E foi com toda a assembléia ao lugar sagrado, no alto de Gibeom, pois ali estava a Tenda do Encontro que Moisés, servo do Senhor, havia feito no deserto."),  (3020, 14, 1, 4, "Davi tinha transportado a arca de Deus de Quiriate-Jearim para a tenda que ele tinha armado para ela em Jerusalém."),  (3021, 14, 1, 5, "O altar de bronze que Bezalel, filho de Uri e neto de Hur, fizera, estava em Gibeom, em frente do tabernáculo do Senhor; ali Salomão e a assembléia consultaram o Senhor."),  (3022, 14, 1, 6, "Salomão ofereceu ao Senhor mil holocaustos sobre o altar de bronze, na Tenda do Encontro."),  (3023, 14, 1, 7, "Naquela noite Deus apareceu a Salomão e lhe disse: Peça-me o que quiser, e eu lhe darei."),  (3024, 14, 1, 8, "Salomão respondeu: Tu foste muito bondoso para com meu pai Davi e me fizeste rei em seu lugar."),  (3025, 14, 1, 9, "Agora, Senhor Deus, que se confirme a tua promessa a meu pai Davi, pois me fizeste rei sobre um povo tão numeroso quanto o pó da terra."),  (3026, 14, 1, 10, "Dá-me sabedoria e conhecimento, para que eu possa liderar esta nação, pois, quem pode governar este teu grande povo? "),  (3027, 14, 1, 11, "Deus disse a Salomão: Já que este é o desejo de seu coração e você não pediu riquezas, nem bens, nem honra, nem a morte dos seus inimigos, nem vida longa, mas sabedoria e conhecimento para governar o meu povo, sobre o qual o fiz rei,"),  (3028, 14, 1, 12, "você receberá o que pediu, mas também lhe darei riquezas, bens e honra, como nenhum rei antes de você teve e nenhum depois de você terá."),  (3029, 14, 1, 13, "Então Salomão voltou de Gibeom, de diante da Tenda do Encontro, para Jerusalém. E reinou sobre Israel."),  (3030, 14, 1, 14, "Salomão juntou carros e cavalos; possuía mil e quatrocentos carros e doze mil cavalos, dos quais mantinha uma parte nas guarnições de algumas cidades e a outra perto dele, em Jerusalém."),  (3031, 14, 1, 15, "O rei tornou tão comuns a prata e o ouro em Jerusalém quanto as pedras, e o cedro tão numeroso quanto as figueiras bravas da Sefelá."),  (3032, 14, 1, 16, "Os cavalos de Salomão eram importados do Egito e da Cilícia, onde os fornecedores do rei os compravam."),  (3033, 14, 1, 17, "Importavam do Egito um carro por sete quilos e duzentos gramas de prata, e um cavalo por um quilo e oitocentos gramas, e os exportavam para todos os reis dos hititas e dos arameus."),  (3034, 14, 2, 1, "Salomão deu ordens para a construção de um templo em honra do nome do Senhor e de um palácio para si mesmo."),  (3035, 14, 2, 2, "Ele designou setenta mil homens como carregadores, oitenta mil como cortadores de pedras nas colinas e três mil e seiscentos como capatazes."),  (3036, 14, 2, 3, "Depois Salomão enviou esta mensagem a Hirão, rei de Tiro: Envia-me cedros como fizeste para meu pai Davi, quando da construção do palácio dele."),  (3037, 14, 2, 4, "Agora estou para construir um templo em honra do nome do Senhor, o meu Deus, e dedicá-lo a ele, para queimar incenso aromático diante dele, apresentar regularmente o pão consagrado e fazer holocaustos todas as manhãs e todas as tardes, nos sábados, nas luas novas e nas festas fixas do Senhor, o nosso Deus. Esse é um decreto perpétuo para Israel."),  (3038, 14, 2, 5, "O templo que vou construir será grande, pois o nosso Deus é maior do que todos os outros deuses."),  (3039, 14, 2, 6, "Mas quem é capaz de construir um templo para ele, visto que os céus não podem contê-lo, nem mesmo os mais altos céus? Quem sou eu, então, para lhe construir um templo, a não ser como um lugar para queimar sacrifícios perante ele?"),  (3040, 14, 2, 7, "Por isso, manda-me um homem competente no trabalho com ouro, com prata, com bronze, com ferro e com tecido roxo, vermelho e azul, e experiente em esculturas, para trabalhar em Judá e em Jerusalém com os meus hábeis artesãos, preparados por meu pai Davi."),  (3041, 14, 2, 8, "Também envia-me do Líbano madeira de cedro, de pinho e de junípero, pois eu sei que os teus servos são hábeis em cortar a madeira de lá. Os meus servos trabalharão com os teus"),  (3042, 14, 2, 9, "para me fornecerem madeira em grande quantidade, pois é preciso que o templo que vou edificar seja grande e imponente."),  (3043, 14, 2, 10, "E eu darei como sustento a teus servos, os lenhadores, vinte mil tonéis de trigo, vinte mil tonéis de cevada, dois mil barris de vinho e dois mil barris de azeite."),  (3044, 14, 2, 11, "Hirão, rei de Tiro, respondeu por carta a Salomão: O Senhor ama o seu povo, e por isso te fez rei sobre ele."),  (3045, 14, 2, 12, "E acrescentou: Bendito seja o Senhor, o Deus de Israel, que fez os céus e a terra, pois deu ao rei Davi um filho sábio, que tem inteligência e discernimento, e que vai construir um templo para o Senhor e um palácio para si."),  (3046, 14, 2, 13, "Estou te enviando Hirão-Abi, homem de grande habilidade."),  (3047, 14, 2, 14, "Sua mãe era de Dã e seu pai, de Tiro. Ele foi treinado para trabalhar com ouro e prata, bronze e ferro, pedra e madeira, e em tecido roxo, azul e vermelho, e em linho fino e em todo tipo de entalhe. Ele pode executar qualquer projeto que lhe for dado. Trabalhará com os teus artesãos e com os de meu senhor Davi, teu pai."),  (3048, 14, 2, 15, "Agora, envie meu senhor a seus servos o trigo, a cevada, o azeite e o vinho que prometeste,"),  (3049, 14, 2, 16, "e cortaremos toda a madeira do Líbano necessária, e a faremos flutuar em jangadas pelo mar, descendo até Jope. De lá poderás levá-la a Jerusalém."),  (3050, 14, 2, 17, "Salomão fez um recenseamento de todos os estrangeiros que viviam em Israel, como o que fizera seu pai Davi; e descobriu-se que eram cento e cinqüenta e três mil e seiscentos."),  (3051, 14, 2, 18, "Ele designou setenta mil deles para serem carregadores e oitenta mil para serem cortadores de pedras nas colinas, com três mil e seiscentos capatazes para manter o povo trabalhando."),  (3052, 14, 3, 1, "Então Salomão começou a construir o templo do Senhor em Jerusalém, no monte Moriá, onde o Senhor havia aparecido a seu pai Davi, na eira de Araúna, o jebuseu. Local providenciado por Davi."),  (3053, 14, 3, 2, "Ele começou a construir no segundo dia do segundo mês do quarto ano de seu reinado."),  (3054, 14, 3, 3, "Os alicerces que Salomão lançou para o templo de Deus tinham vinte e sete metros de comprimento e nove metros de largura, pela medida antiga."),  (3055, 14, 3, 4, "O pórtico da entrada do templo tinha nove metros de largura e nove metros de altura. Ele revestiu de ouro puro o seu interior."),  (3056, 14, 3, 5, "Recobriu de pinho o átrio principal, revestiu-o de ouro puro e o decorou com desenhos de tamareiras e correntes."),  (3057, 14, 3, 6, "Ornamentou o templo com pedras preciosas. O ouro utilizado era de Parvaim."),  (3058, 14, 3, 7, "Também revestiu de ouro as vigas do forro, os batentes, as paredes e as portas do templo, e esculpiu querubins nas paredes."),  (3059, 14, 3, 8, "Fez o Lugar Santíssimo, com nove metros de comprimento e nove metros de largura, igual à largura do templo. Revestiu de vinte e uma toneladas de ouro puro o seu interior."),  (3060, 14, 3, 9, "Os pregos de ouro pesavam seiscentos gramas. Também revestiu de ouro as salas superiores."),  (3061, 14, 3, 10, "No Lugar Santíssimo esculpiu e revestiu de ouro dois querubins,"),  (3062, 14, 3, 11, "os quais, de asas abertas, mediam juntos nove metros. Cada asa, de dois metros e vinte e cinco centímetros, tocava, de um lado, na parede do templo,"),  (3063, 14, 3, 12, "e do outro lado, na asa do outro querubim."),  (3064, 14, 3, 13, "Assim os querubins, com asas que se estendiam por nove metros, estavam de pé, de frente para o átrio principal."),  (3065, 14, 3, 14, "Ele fez o véu de tecido azul, roxo, vermelho e linho fino com querubins desenhados nele."),  (3066, 14, 3, 15, "Fez na frente do templo duas colunas, que juntas tinham dezesseis metros, cada uma tendo em cima um capitel com dois metros e vinte e cinco centímetros."),  (3067, 14, 3, 16, "E fez correntes entrelaçadas e colocou-as no alto das colunas. Fez também cem romãs, colocando-as nas correntes."),  (3068, 14, 3, 17, "Então levantou as colunas na frente do templo, uma ao sul, outra ao norte; à que ficava ao sul deu o nome de Jaquim, e à que ficava ao norte, Boaz."),  (3069, 14, 4, 1, "Salomão também mandou fazer um altar de bronze de nove metros de comprimento, nove metros de largura e quatro metros e meio de altura."),  (3070, 14, 4, 2, "Fez o tanque de metal fundido, redondo, medindo quatro metros e meio de diâmetro e dois metros e vinte e cinco centímetros de altura. Era preciso um fio de treze metros e meio para medir a sua circunferência."),  (3071, 14, 4, 3, "Abaixo da borda e ao seu redor havia figuras de touro, de cinco em cinco centímetros. Os touros foram fundidos em duas fileiras numa só peça com o tanque."),  (3072, 14, 4, 4, "O tanque ficava sobre doze touros, três voltados para o norte, três para o oeste, três para o sul e três para o leste. Ficava em cima deles, e as pernas traseiras dos touros eram voltadas para o centro."),  (3073, 14, 4, 5, "A espessura do tanque era de quatro dedos, e sua borda era como a borda de um cálice, como uma flor de lírio. Tinha capacidade de sessenta e seis mil litros."),  (3074, 14, 4, 6, "Fez dez pias, colocando cinco no lado sul e cinco no lado norte. Nelas tudo o que era usado nos holocaustos era lavado, enquanto que o tanque servia para os sacerdotes se lavarem."),  (3075, 14, 4, 7, "Fez dez candelabros de ouro, de acordo com as especificações, e colocou-os no templo, cinco no lado sul e cinco no lado norte."),  (3076, 14, 4, 8, "Fez dez mesas e colocou-as no templo, cinco no lado sul e cinco no lado norte. Também fez cem bacias de ouro para aspersão."),  (3077, 14, 4, 9, "E fez o pátio dos sacerdotes e o pátio principal com suas portas, e revestiu de bronze as suas portas."),  (3078, 14, 4, 10, "Pôs o tanque no lado sul, no canto sudeste do templo."),  (3079, 14, 4, 11, "Também fez os jarros, as pás e as bacias para aspersão. Assim, Hirão terminou o trabalho de que fora encarregado pelo rei Salomão, no templo de Deus:"),  (3080, 14, 4, 12, "as duas colunas; os dois capitéis em forma de taça no alto das colunas; os dois conjuntos de correntes que decoravam os dois capitéis;"),  (3081, 14, 4, 13, "as quatrocentas romãs para os dois conjuntos de correntes, sendo duas fileiras de romãs para cada conjunto;"),  (3082, 14, 4, 14, "os dez carrinhos com as suas dez pias;"),  (3083, 14, 4, 15, "o tanque e os doze touros debaixo dele;"),  (3084, 14, 4, 16, "e os jarros, as pás, os garfos de carne e todos os utensílios afins. Todos esses utensílios que Hirão-Abi fez a pedido do rei Salomão, para o templo do Senhor, eram de bronze polido."),  (3085, 14, 4, 17, "Foi na planície do Jordão, entre Sucote e Zeredá, que o rei os mandou fundir, em moldes de barro."),  (3086, 14, 4, 18, "Salomão os fez em tão grande quantidade, a ponto de não se poder determinar o peso do bronze utilizado."),  (3087, 14, 4, 19, "Além desses, Salomão mandou fazer também todos estes outros utensílios para o templo de Deus: o altar de ouro; as mesas sobre as quais ficavam os pães da Presença;"),  (3088, 14, 4, 20, "os candelabros de ouro puro com suas lâmpadas, para iluminarem diante do santuário interno, conforme determinado;"),  (3089, 14, 4, 21, "as flores, as lâmpadas e as tenazes de ouro maciço;"),  (3090, 14, 4, 22, "os cortadores de pavio, as bacias para aspersão, as tigelas, os incensários de ouro puro e as portas de ouro do templo: tanto as portas da sala interna, o Lugar Santíssimo, quanto as portas do átrio principal."),  (3091, 14, 5, 1, "Terminada toda a obra que Salomão havia realizado para o templo do Senhor, ele trouxe as coisas que seu pai Davi tinha consagrado e colocou junto com os tesouros do templo de Deus: a prata, o ouro e todos os utensílios."),  (3092, 14, 5, 2, "Então Salomão reuniu em Jerusalém as autoridades de Israel e todos os líderes das tribos e os chefes das famílias israelitas, para levarem de Sião, a cidade de Davi, a arca da aliança do Senhor."),  (3093, 14, 5, 3, "E todos os homens de Israel uniram-se ao rei por ocasião da festa, no sétimo mês."),  (3094, 14, 5, 4, "Quando todas as autoridades de Israel chegaram, os levitas pegaram a arca"),  (3095, 14, 5, 5, "e a levaram, com a Tenda do Encontro e com todos os seus utensílios sagrados. Foram os sacerdotes levitas que levaram tudo."),  (3096, 14, 5, 6, "O rei Salomão e toda a comunidade de Israel que se havia reunido a ele diante da arca, sacrificaram tantas ovelhas e bois que nem era possível contar."),  (3097, 14, 5, 7, "Os sacerdotes levaram a arca da aliança do Senhor para o seu lugar no santuário interno do templo, no Lugar Santíssimo, e a colocaram debaixo das asas dos querubins."),  (3098, 14, 5, 8, "Os querubins tinham suas asas estendidas sobre o lugar da arca e cobriam a arca e as varas utilizadas para o transporte."),  (3099, 14, 5, 9, "Essas varas eram tão compridas que as suas pontas, que se estendiam para fora da arca, podiam ser vistas da frente do santuário interno, mas não de fora dele; e elas estão lá até hoje."),  (3100, 14, 5, 10, "Na arca havia só as duas tábuas que Moisés tinha colocado quando estava em Horebe, onde o Senhor fez uma aliança com os israelitas depois que saíram do Egito."),  (3101, 14, 5, 11, "Então os sacerdotes saíram do Lugar Santo. Todos eles haviam se consagrado, não importando a divisão a que pertenciam."),  (3102, 14, 5, 12, "E, todos os levitas que eram músicos — Asafe, Hemã, Jedutum e os filhos e parentes deles — ficaram a leste do altar, vestidos de linho fino, tocando címbalos, harpas e liras, e os acompanhavam cento e vinte sacerdotes tocando cornetas."),  (3103, 14, 5, 13, "Os que tocavam cornetas e os cantores, em uníssono, louvaram e agradeceram ao Senhor. Ao som de cornetas, címbalos e outros instrumentos, levantaram suas vozes em louvor ao Senhor e cantaram: Ele é bom; o seu amor dura para sempre. Então uma nuvem encheu o templo do Senhor,"),  (3104, 14, 5, 14, "de forma que os sacerdotes não podiam desempenhar o seu serviço, pois a glória do Senhor encheu o templo de Deus."),  (3105, 14, 6, 1, "E Salomão exclamou: O Senhor disse que habitaria numa nuvem escura!"),  (3106, 14, 6, 2, "Na realidade construí para ti um templo magnífico, um lugar para nele habitares para sempre! "),  (3107, 14, 6, 3, "Depois o rei virou-se e abençoou toda a assembléia de Israel, que estava ali de pé."),  (3108, 14, 6, 4, "E disse: Bendito seja o Senhor, o Deus de Israel, que por suas mãos cumpriu o que prometeu com sua própria boca a meu pai Davi, quando lhe disse:"),  (3109, 14, 6, 5, "‘Desde o dia em que tirei meu povo do Egito, não escolhi nenhuma cidade das tribos de Israel para nela construir um templo em honra do meu nome, nem escolhi ninguém para ser o líder do meu povo Israel."),  (3110, 14, 6, 6, "Mas, agora, escolhi Jerusalém para o meu nome ali estar e escolhi Davi para governar Israel, o meu povo’."),  (3111, 14, 6, 7, "Meu pai Davi tinha no coração o propósito de construir um templo em honra do nome do Senhor, o Deus de Israel."),  (3112, 14, 6, 8, "Mas o Senhor lhe disse: ‘Você fez bem em ter no coração o plano de construir um templo em honra do meu nome;"),  (3113, 14, 6, 9, "no entanto, não será você que o construirá, mas o seu filho, que procederá de você; ele construirá o templo em honra do meu nome’."),  (3114, 14, 6, 10, "E o Senhor cumpriu a sua promessa. Sou o sucessor de meu pai Davi, e agora ocupo o trono de Israel, como o Senhor tinha prometido, e construí o templo em honra do nome do Senhor, o Deus de Israel."),  (3115, 14, 6, 11, "Coloquei nele a arca, na qual estão as tábuas da aliança do Senhor, aliança que ele fez com os israelitas."),  (3116, 14, 6, 12, "Depois Salomão colocou-se diante do altar do Senhor, diante de toda a assembléia de Israel, e levantou as mãos para orar."),  (3117, 14, 6, 13, "Ele havia mandado fazer uma plataforma de bronze com dois metros e vinte e cinco centímetros de comprimento e de largura, e um metro e trinta e cinco centímetros de altura, no centro do pátio externo. Ele ficou de pé na plataforma, depois ajoelhou-se diante de toda a assembléia de Israel, levantou as mãos para o céu,"),  (3118, 14, 6, 14, "e orou: Senhor, Deus de Israel, não há Deus como tu nos céus e na terra! Tu que guardas a tua aliança de amor com os teus servos que, de todo o coração, andam segundo a tua vontade."),  (3119, 14, 6, 15, "Cumpriste a tua promessa a teu servo Davi, meu pai; com tua boca prometeste e com tua mão a cumpriste, conforme hoje se vê."),  (3120, 14, 6, 16, "Agora, Senhor, Deus de Israel, cumpre a outra promessa que fizeste a teu servo Davi, meu pai, quando disseste: ‘Você nunca deixará de ter, diante de mim, um descendente que se assente no trono de Israel, se tão-somente os seus descendentes tiverem o cuidado de, em tudo, andarem segundo a minha lei, como você tem feito’."),  (3121, 14, 6, 17, "Agora, ó Senhor, Deus de Israel, que se confirme a palavra que falaste a teu servo Davi."),  (3122, 14, 6, 18, "Mas será possível que Deus habite na terra com os homens? Os céus, mesmo os mais altos céus, não podem conter-te. Muito menos este templo que construí!"),  (3123, 14, 6, 19, "Ainda assim, atende à oração do teu servo e ao seu pedido de misericórdia, ó Senhor, meu Deus. Ouve o clamor e a oração que teu servo faz hoje na tua presença."),  (3124, 14, 6, 20, "Estejam os teus olhos voltados dia e noite para este templo, lugar do qual disseste que nele porias o teu nome, para que ouças a oração que o teu servo fizer voltado para este lugar."),  (3125, 14, 6, 21, "Ouve as súplicas do teu servo e de Israel, teu povo, quando orarem voltados para este lugar. Ouve desde os céus, lugar da tua habitação, e quando ouvires, dá-lhes o teu perdão."),  (3126, 14, 6, 22, "Quando um homem pecar contra seu próximo e tiver que fazer um juramento, e vier jurar diante do teu altar neste templo,"),  (3127, 14, 6, 23, "ouve dos céus e age. Julga os teus servos; retribui ao culpado, fazendo recair sobre a sua própria cabeça o resultado da sua conduta, e declara sem culpa o inocente, dando-lhe o que a sua inocência merece."),  (3128, 14, 6, 24, "Quando Israel, o teu povo, for derrotado por um inimigo por ter pecado contra ti, e voltar-se para ti e invocar o teu nome, orando e suplicando a ti neste templo,"),  (3129, 14, 6, 25, "ouve dos céus e perdoa o pecado de Israel, teu povo, e traze-o de volta à terra que deste a ele e aos seus antepassados."),  (3130, 14, 6, 26, "Quando fechar-se o céu, e não houver chuva por haver o teu povo pecado contra ti, e, se o teu povo, voltado para este lugar, invocar o teu nome e afastar-se do seu pecado por o haveres castigado,"),  (3131, 14, 6, 27, "ouve dos céus e perdoa o pecado dos teus servos, do teu povo Israel. Ensina-lhes o caminho certo e envia chuva sobre a tua terra, que deste por herança ao teu povo."),  (3132, 14, 6, 28, "Quando houver fome ou praga no país, ferrugem e mofo, gafanhotos peregrinos e gafanhotos devastadores, ou quando inimigos sitiarem suas cidades, quando, em meio a qualquer praga ou epidemia,"),  (3133, 14, 6, 29, "uma oração ou uma súplica por misericórdia for feita por um israelita ou por todo o teu povo Israel, cada um sentindo as suas próprias aflições e dores, estendendo as mãos na direção deste templo,"),  (3134, 14, 6, 30, "ouve dos céus, o lugar da tua habitação. Perdoa e trata cada um de acordo com o que merece, visto que conheces o seu coração. Sim, só tu conheces o coração do homem."),  (3135, 14, 6, 31, "Assim eles te temerão, e andarão segundo a tua vontade durante todo o tempo em que viverem na terra que deste aos nossos antepassados."),  (3136, 14, 6, 32, "Quanto ao estrangeiro, que não pertence a teu povo Israel, e que veio de uma terra distante por causa do teu grande nome, da tua mão poderosa e do teu braço forte; quando ele vier e orar voltado para este templo,"),  (3137, 14, 6, 33, "ouve dos céus, lugar da tua habitação, e atende o pedido do estrangeiro, a fim de que todos os povos da terra conheçam o teu nome e te temam, como faz Israel, teu povo, e saibam que este templo que construí traz o teu nome."),  (3138, 14, 6, 34, "Quando o teu povo for à guerra contra os seus inimigos, por onde quer que tu o enviares, e orar a ti, voltado para a cidade que escolheste e para o templo que construí em honra do teu nome,"),  (3139, 14, 6, 35, "então ouve dos céus a sua oração e a sua súplica, e defende a sua causa."),  (3140, 14, 6, 36, "Quando pecarem contra ti, pois não há ninguém que não peque, e ficares irado com eles e os entregares ao inimigo, que os leve prisioneiros para uma terra distante ou próxima;"),  (3141, 14, 6, 37, "se eles caírem em si, na terra para a qual foram deportados, e se arrependerem e lá orarem: ‘Pecamos, praticamos o mal e fomos rebeldes’;"),  (3142, 14, 6, 38, "e se lá eles se voltarem para ti de todo o coração e de toda a sua alma, na terra de seu cativeiro para onde foram levados, e orarem voltados para a terra que deste aos seus antepassados, para a cidade que escolheste e para o templo que construí em honra do teu nome,"),  (3143, 14, 6, 39, "então, dos céus, lugar da tua habitação, ouve a sua oração e a sua súplica, e defende a sua causa. Perdoa o teu povo, que pecou contra ti."),  (3144, 14, 6, 40, "Assim, meu Deus, que os teus olhos estejam abertos e teus ouvidos atentos às orações feitas neste lugar."),  (3145, 14, 6, 41, "Agora, levanta-te, ó Senhor, ó Deus, e vem para o teu lugar de descanso, tu e a arca do teu poder. Estejam os teus sacerdotes vestidos de salvação, ó Senhor, ó Deus; que os teus santos se regozijem em tua bondade."),  (3146, 14, 6, 42, "Ó Senhor, ó Deus, não rejeites o teu ungido. Lembra-te da fidelidade prometida a teu servo Davi."),  (3147, 14, 7, 1, "Assim que Salomão acabou de orar, desceu fogo do céu e consumiu o holocausto e os sacrifícios, e a glória do Senhor encheu o templo."),  (3148, 14, 7, 2, "Os sacerdotes não conseguiam entrar no templo do Senhor, porque a glória do Senhor o enchia."),  (3149, 14, 7, 3, "Quando todos os israelitas viram o fogo descendo e a glória do Senhor sobre o templo, ajoelharam-se no pavimento, chegando o rosto ao chão, adoraram e deram graças ao Senhor, dizendo: Ele é bom; o seu amor dura para sempre."),  (3150, 14, 7, 4, "Então o rei e todo o Israel ofereceram sacrifícios ao Senhor."),  (3151, 14, 7, 5, "O rei Salomão ofereceu em sacrifício vinte e dois mil bois e cento e vinte mil ovelhas. Assim o rei e todo o povo fizeram a dedicação do templo de Deus."),  (3152, 14, 7, 6, "Os sacerdotes tomaram seus lugares, bem como os levitas, com os instrumentos musicais do Senhor feitos pelo rei Davi para louvar o Senhor cantando: O seu amor dura para sempre. No outro lado, de frente para os levitas, os sacerdotes tocavam suas cornetas. Todo o povo estava de pé."),  (3153, 14, 7, 7, "Salomão consagrou a parte central do pátio, que ficava na frente do templo do Senhor, e ali ofereceu holocaustos e a gordura das ofertas de comunhão, pois o altar de bronze que Salomão tinha construído não comportava os holocaustos, as ofertas de cereal e as porções de gordura."),  (3154, 14, 7, 8, "Durante sete dias, Salomão, juntamente com todo o Israel, celebrou a festa; era uma grande multidão, gente vinda desde Lebo-Hamate até o ribeiro do Egito."),  (3155, 14, 7, 9, "No oitavo dia realizaram uma assembléia solene. Levaram sete dias para a dedicação do altar, e a festa se prolongou por mais sete dias."),  (3156, 14, 7, 10, "No dia vinte e três do sétimo mês, ele mandou o povo para as suas casas. E todos se foram, jubilosos e de coração alegre pelas coisas boas que o Senhor havia feito por Davi e Salomão e por seu povo Israel."),  (3157, 14, 7, 11, "Quando Salomão acabou de construir o templo do Senhor e o palácio real, executando bem tudo o que tinha em mente realizar no templo do Senhor e em seu próprio palácio,"),  (3158, 14, 7, 12, "o Senhor lhe apareceu de noite e disse: Ouvi sua oração, e escolhi este lugar para mim, como um templo para sacrifícios."),  (3159, 14, 7, 13, "Se eu fechar o céu para que não chova ou mandar que os gafanhotos devorem o país ou sobre o meu povo enviar uma praga,"),  (3160, 14, 7, 14, "se o meu povo, que se chama pelo meu nome, se humilhar e orar, buscar a minha face e se afastar dos seus maus caminhos, dos céus o ouvirei, perdoarei o seu pecado e curarei a sua terra."),  (3161, 14, 7, 15, "De hoje em diante os meus olhos estarão abertos e os meus ouvidos atentos às orações feitas neste lugar."),  (3162, 14, 7, 16, "Escolhi e consagrei este templo para que o meu nome esteja nele para sempre. Meus olhos e meu coração nele sempre estarão."),  (3163, 14, 7, 17, "E se você andar segundo a minha vontade como fez seu pai Davi e fizer tudo o que eu lhe ordeno, obedecendo aos meus decretos e às minhas leis,"),  (3164, 14, 7, 18, "firmarei o seu trono, conforme a aliança que fiz com Davi, seu pai, quando lhe disse: ‘Você nunca deixará de ter um descendente para governar Israel’."),  (3165, 14, 7, 19, "Mas, se vocês se afastarem de mim e abandonarem os decretos e os mandamentos que lhes dei, e prestarem culto a outros deuses e adorá-los,"),  (3166, 14, 7, 20, "desarraigarei Israel da minha terra, que lhes dei, e lançarei para longe da minha presença este templo que consagrei ao meu nome. Farei que ele se torne motivo de zombaria entre todos os povos."),  (3167, 14, 7, 21, "E embora agora este templo seja imponente, todos os que passarem por ele ficarão espantados e perguntarão: ‘Por que o Senhor fez uma coisa dessas a esta terra e a este templo? ’"),  (3168, 14, 7, 22, "E a resposta será: ‘Porque abandonaram o Senhor, o Deus dos seus antepassados, que os tirou do Egito, e se apegaram a outros deuses, adorando-os e prestando-lhes culto; por isso ele trouxe sobre eles toda esta desgraça’ ."),  (3169, 14, 8, 1, "Depois de vinte anos, durante os quais Salomão construiu o templo do Senhor e o seu próprio palácio,"),  (3170, 14, 8, 2, "ele reconstruiu as cidades que Hirão lhe tinha dado, e nelas estabeleceu israelitas."),  (3171, 14, 8, 3, "Depois atacou Hamate-Zobá e a conquistou."),  (3172, 14, 8, 4, "Também reconstruiu Tadmor, no deserto, e todas as cidades-armazéns que havia construído em Hamate."),  (3173, 14, 8, 5, "Reconstruiu Bete-Horom Alta e Bete-Horom Baixa, cidades fortificadas com muros, portas e trancas,"),  (3174, 14, 8, 6, "e também Baalate e todas as cidades-armazéns que possuía, e todas as cidades onde ficavam os seus carros e os seus cavalos. Construiu tudo o que desejou em Jerusalém, no Líbano e em todo o território que governou."),  (3175, 14, 8, 7, "Todos os não israelitas, descendentes dos hititas, dos amorreus, dos ferezeus, dos heveus e dos jebuseus,"),  (3176, 14, 8, 8, "que não tinham sido mortos pelos israelitas, Salomão recrutou para o trabalho forçado, como continuam até hoje."),  (3177, 14, 8, 9, "Mas Salomão não obrigou nenhum israelita a trabalhos forçados; eles eram seus homens de guerra, chefes de seus capitães, comandantes dos seus carros e condutores de carros."),  (3178, 14, 8, 10, "Também eram israelitas os principais funcionários do rei Salomão, duzentos e cinqüenta funcionários que supervisionavam os trabalhadores."),  (3179, 14, 8, 11, "Salomão levou a filha do faraó da cidade de Davi para o palácio que ele havia construído para ela, pois dissera: Minha mulher não deve morar no palácio de Davi, rei de Israel, pois os lugares onde entrou a arca do Senhor são sagrados."),  (3180, 14, 8, 12, "Sobre o altar do Senhor, que havia construído diante do pórtico, Salomão passou a sacrificar holocaustos ao Senhor,"),  (3181, 14, 8, 13, "conforme as determinações de Moisés acerca das ofertas diárias e dos sábados, das luas novas e das três festas anuais: a festa dos pães sem fermento, a festa das semanas e a festa das cabanas."),  (3182, 14, 8, 14, "De acordo com a ordem de seu pai Davi, designou os grupos dos sacerdotes para as suas tarefas, e os levitas para conduzirem o louvor e ajudarem os sacerdotes, conforme as determinações diárias. Também designou, por divisões, os porteiros das várias portas, conforme o que Davi, homem de Deus, tinha ordenado."),  (3183, 14, 8, 15, "Todas as ordens dadas pelo rei aos sacerdotes e aos levitas, inclusive as ordens relativas aos tesouros, foram seguidas à risca."),  (3184, 14, 8, 16, "Todo o trabalho de Salomão foi executado, desde o dia em que foram lançados os alicerces do templo do Senhor até seu término. Assim foi concluído o templo do Senhor."),  (3185, 14, 8, 17, "Depois Salomão foi a Eziom-Geber e a Elate, no litoral de Edom."),  (3186, 14, 8, 18, "E Hirão enviou-lhe navios comandados por seus próprios marinheiros, homens que conheciam o mar. Eles navegavam com os marinheiros de Salomão até Ofir, e de lá trouxeram quinze toneladas e setecentos e cinqüenta quilos de ouro para o rei Salomão."),  (3187, 14, 9, 1, "A rainha de Sabá soube da fama de Salomão, e foi a Jerusalém para pô-lo à prova com perguntas difíceis. Quando chegou, acompanhada de uma enorme caravana, com camelos carregados de especiarias, grande quantidade de ouro e pedras preciosas, foi até Salomão e lhe fez todas as perguntas que tinha em mente."),  (3188, 14, 9, 2, "Salomão respondeu a todas; nenhuma lhe foi tão difícil que não pudesse responder."),  (3189, 14, 9, 3, "Vendo a sabedoria de Salomão, bem como o palácio que ele havia construído,"),  (3190, 14, 9, 4, "o que era servido em sua mesa, o lugar de seus oficiais, os criados e copeiros, todos uniformizados, e os holocaustos que ele fazia no templo do Senhor, ela ficou impressionada."),  (3191, 14, 9, 5, "Disse ela então ao rei: Tudo o que ouvi em meu país acerca de tuas realizações e de tua sabedoria era verdade."),  (3192, 14, 9, 6, "Mas eu não acreditava no que diziam, até ver com os meus próprios olhos. Na realidade, não me contaram nem a metade da grandeza de tua sabedoria; tu ultrapassas em muito o que ouvi."),  (3193, 14, 9, 7, "Como devem ser felizes os homens da tua corte, que continuamente estão diante de ti e ouvem a tua sabedoria!"),  (3194, 14, 9, 8, "Bendito seja o Senhor, o teu Deus, que se agradou de ti e te colocou no trono dele para reinar pelo Senhor, pelo teu Deus. Por causa do amor de teu Deus para com Israel e do seu desejo de preservá-lo para sempre, ele te fez rei, para manter a justiça e a retidão."),  (3195, 14, 9, 9, "E ela deu ao rei quatro toneladas e duzentos quilos de ouro e grande quantidade de especiarias e de pedras preciosas. Nunca se viu tantas especiarias tais como aquelas que a rainha de Sabá deu ao rei Salomão."),  (3196, 14, 9, 10, "( Os marinheiros de Hirão e de Salomão trouxeram ouro de Ofir, e também madeira de junípero e pedras preciosas."),  (3197, 14, 9, 11, "O rei utilizou a madeira para fazer a escadaria do templo do Senhor e a do palácio real, além de harpas e liras para os músicos. Nunca se havia visto algo semelhante em Judá. )"),  (3198, 14, 9, 12, "O rei Salomão deu à rainha de Sabá tudo o que ela desejou e pediu; muito mais do que ela lhe tinha trazido. Então ela e seus servos voltaram para o seu país."),  (3199, 14, 9, 13, "O peso do ouro que Salomão recebia anualmente era de vinte e três toneladas e trezentos quilos,"),  (3200, 14, 9, 14, "fora o que os mercadores e os comerciantes traziam. Também todos os reis da Arábia e os governadores do país traziam ouro e prata para Salomão."),  (3201, 14, 9, 15, "O rei Salomão fez duzentos escudos grandes de ouro batido, utilizando três quilos e seiscentos gramas de ouro em cada um."),  (3202, 14, 9, 16, "Também fez trezentos escudos pequenos de ouro batido, com um quilo e oitocentos gramas de ouro em cada um. O rei os colocou no Palácio da Floresta do Líbano."),  (3203, 14, 9, 17, "O rei mandou fazer ainda um grande trono de marfim revestido de ouro puro."),  (3204, 14, 9, 18, "O trono tinha seis degraus, e um estrado de ouro fixo nele. Nos dois lados do assento havia braços, com um leão junto a cada braço."),  (3205, 14, 9, 19, "Doze leões ficavam nos seis degraus, um de cada lado. Nada igual havia sido feito em nenhum outro reino."),  (3206, 14, 9, 20, "Todas as taças do rei Salomão eram de ouro, bem como todos os utensílios do Palácio da Floresta do Líbano. Não havia nada de prata, pois a prata quase não tinha valor nos dias de Salomão."),  (3207, 14, 9, 21, "O rei tinha uma frota de navios mercantes tripulados por marinheiros do rei Hirão. Cada três anos a frota voltava, trazendo ouro, prata, marfim, macacos e pavões."),  (3208, 14, 9, 22, "O rei Salomão era o mais rico e o mais sábio de todos os reis da terra."),  (3209, 14, 9, 23, "Esses pediam audiência a Salomão, para ouvirem a sabedoria que Deus lhe tinha dado."),  (3210, 14, 9, 24, "Ano após ano, todos os que vinham traziam algum presente: utensílios de prata e de ouro, mantos, armas e especiarias, cavalos e mulas."),  (3211, 14, 9, 25, "Salomão possuía quatro mil estábulos para cavalos e carros, e doze mil cavalos, dos quais mantinha uma parte nas guarnições de algumas cidades e a outra perto dele, em Jerusalém."),  (3212, 14, 9, 26, "Ele dominava sobre todos os reis desde o Eufrates até a terra dos filisteus, junto à fronteira do Egito."),  (3213, 14, 9, 27, "O rei tornou a prata tão comum em Jerusalém quanto as pedras, e o cedro tão numeroso quanto as figueiras bravas da Sefelá."),  (3214, 14, 9, 28, "Os cavalos de Salomão eram importados do Egito e de todos os outros países."),  (3215, 14, 9, 29, "Os demais acontecimentos do reinado de Salomão, desde o início até o fim, estão escritos nos relatos do profeta Natã, nas profecias do silonita Aías e nas visões do vidente Ido acerca de Jeroboão, filho de Nebate."),  (3216, 14, 9, 30, "Salomão reinou quarenta anos em Jerusalém, sobre todo o Israel."),  (3217, 14, 9, 31, "Então descansou com os seus antepassados e foi sepultado na cidade de Davi, seu pai. E o seu filho Roboão foi o seu sucessor."),  (3218, 14, 10, 1, "Roboão foi a Siquém, onde todos os israelitas tinham se reunido para proclamá-lo rei."),  (3219, 14, 10, 2, "Assim que Jeroboão, filho de Nebate, que estava no Egito fugindo do rei Salomão, soube disso, voltou de lá."),  (3220, 14, 10, 3, "E mandaram chamá-lo. Então ele e todo o Israel foram ao encontro de Roboão e disseram:"),  (3221, 14, 10, 4, "Teu pai colocou sobre nós um jugo pesado, mas agora diminui o trabalho árduo e este jugo pesado, e nós te serviremos."),  (3222, 14, 10, 5, "Roboão respondeu: Voltem a mim daqui a três dias. Então o povo foi embora."),  (3223, 14, 10, 6, "O rei Roboão perguntou às autoridades que haviam servido ao seu pai Salomão durante a vida dele: Como vocês me aconselham a responder a este povo? "),  (3224, 14, 10, 7, "Eles responderam: Se hoje fores bom para esse povo, se o agradares e lhe deres resposta favorável, eles sempre serão teus servos."),  (3225, 14, 10, 8, "Roboão, contudo, rejeitou o conselho que as autoridades de Israel lhe tinham dado e consultou os jovens que haviam crescido com ele e o estavam servindo."),  (3226, 14, 10, 9, "Perguntou-lhes: Qual é o conselho de vocês? Como devemos responder a este povo que me diz: ‘Diminui o jugo que teu pai colocou sobre nós’? "),  (3227, 14, 10, 10, "Os jovens que haviam crescido com ele responderam: A este povo que te disse: ‘Teu pai colocou sobre nós um jugo pesado; torna-o mais leve’ — dize: ‘Meu dedo mínimo é mais grosso do que a cintura do meu pai."),  (3228, 14, 10, 11, "Pois bem, meu pai lhes impôs um jugo pesado; eu o tornarei ainda mais pesado. Meu pai os castigou com simples chicotes; eu os castigarei com chicotes pontiagudos’ ."),  (3229, 14, 10, 12, "Três dias depois, Jeroboão e todo o povo voltaram a Roboão, segundo a orientação dada pelo rei: Voltem a mim daqui a três dias."),  (3230, 14, 10, 13, "Mas o rei lhes respondeu asperamente. Rejeitando o conselho das autoridades de Israel,"),  (3231, 14, 10, 14, "seguiu o conselho dos jovens e disse: Meu pai lhes tornou pesado o jugo; eu o tornarei ainda mais pesado. Meu pai os castigou com simples chicotes; eu os castigarei com chicotes pontiagudos."),  (3232, 14, 10, 15, "E o rei não ouviu o povo, pois esta mudança nos acontecimentos vinha da parte de Deus, para que se cumprisse a palavra que o Senhor havia falado a Jeroboão, filho de Nebate, por meio do silonita Aías."),  (3233, 14, 10, 16, "Quando todo o Israel viu que o rei se recusava a ouvi-los, responderam ao rei: Que temos em comum com Davi? Que temos em comum com o filho de Jessé? Para as suas tendas, ó Israel! Cuide da sua própria casa, ó Davi!  E assim os israelitas foram para as suas casas."),  (3234, 14, 10, 17, "Quanto, porém, aos israelitas que moravam nas cidades de Judá, Roboão continuou como rei deles."),  (3235, 14, 10, 18, "O rei Roboão enviou Adonirão, chefe de trabalhos forçados, mas todo o Israel o apedrejou até à morte. O rei, contudo, conseguiu subir em sua carruagem e fugir para Jerusalém."),  (3236, 14, 10, 19, "Desta forma Israel se rebelou contra a dinastia de Davi, e assim permanece até hoje."),  (3237, 14, 11, 1, "Quando Roboão chegou em Jerusalém, convocou cento e oitenta mil homens de combate, das tribos de Judá e de Benjamim, para guerrearem contra Israel e recuperarem o reino para Roboão."),  (3238, 14, 11, 2, "Entretanto, veio esta palavra do Senhor a Semaías, homem de Deus:"),  (3239, 14, 11, 3, "Diga a Roboão, filho de Salomão, rei de Judá, e a todos os israelitas de Judá e de Benjamim:"),  (3240, 14, 11, 4, "‘Assim diz o Senhor: Não saiam à guerra contra os seus irmãos. Voltem para casa, todos vocês, pois fui eu que fiz isso’ . E eles obedeceram à palavra do Senhor e desistiram de marchar contra Jeroboão."),  (3241, 14, 11, 5, "Roboão morou em Jerusalém e reconstruiu algumas cidades para a defesa de Judá. Foram elas:"),  (3242, 14, 11, 6, "Belém, Etã, Tecoa,"),  (3243, 14, 11, 7, "Bete-Zur, Socó, Adulão,"),  (3244, 14, 11, 8, "Gate, Maressa, Zife,"),  (3245, 14, 11, 9, "Adoraim, Láquis, Azeca,"),  (3246, 14, 11, 10, "Zorá, Aijalom e Hebrom. Essas cidades foram fortificadas em Judá e em Benjamim."),  (3247, 14, 11, 11, "Ele fortaleceu as suas defesas e nelas colocou comandantes, com suprimentos de alimentos, azeite e vinho."),  (3248, 14, 11, 12, "Armazenou escudos grandes e lanças em todas as cidades, tornando-as muito fortes. Assim, Judá e Benjamim continuaram sob o seu domínio."),  (3249, 14, 11, 13, "Os sacerdotes e os levitas de todos os distritos de Israel o apoiaram."),  (3250, 14, 11, 14, "Os levitas chegaram até a abandonar as suas pastagens e os seus bens, e foram para Judá e para Jerusalém, porque Jeroboão e seus filhos os haviam rejeitado como sacerdotes do Senhor,"),  (3251, 14, 11, 15, "nomeando seus próprios sacerdotes para os altares idólatras e para os ídolos que haviam feito em forma de bodes e de bezerros."),  (3252, 14, 11, 16, "De todas as tribos de Israel aqueles que estavam realmente dispostos a buscar o Senhor, o Deus de Israel, seguiram os levitas até Jerusalém para oferecerem sacrifícios ao Senhor, ao Deus dos seus antepassados."),  (3253, 14, 11, 17, "Eles fortaleceram o reino de Judá e durante três anos apoiaram Roboão, filho de Salomão, andando nos caminhos de Davi e de Salomão durante esse tempo."),  (3254, 14, 11, 18, "Roboão casou-se com Maalate, filha de Jeremote e neta de Davi. A mãe de Maalate era Abiail, filha de Eliabe e neta de Jessé."),  (3255, 14, 11, 19, "Ela deu-lhe três filhos: Jeús, Semarias e Zaão."),  (3256, 14, 11, 20, "Depois ele casou-se com Maaca, filha de Absalão, a qual lhe deu os filhos Abias, Atai, Ziza e Selomite."),  (3257, 14, 11, 21, "Roboão amava Maaca, filha de Absalão, mais do que a qualquer outra de suas esposas e concubinas. Ao todo ele teve dezoito esposas e sessenta concubinas, vinte e oito filhos e sessenta filhas."),  (3258, 14, 11, 22, "Roboão nomeou Abias, filho de Maaca, o chefe entre os seus irmãos, com o intuito de fazê-lo rei."),  (3259, 14, 11, 23, "Ele agiu com sabedoria, dispersando seus filhos pelos distritos de Judá e de Benjamim, e pelas cidades fortificadas. Garantiu-lhes fartas provisões e lhes conseguiu muitas mulheres."),  (3260, 14, 12, 1, "Depois que Roboão se fortaleceu, firmou-se como rei, ele e todo o Israel abandonaram a lei do Senhor."),  (3261, 14, 12, 2, "Por terem sido infiéis ao Senhor, Sisaque, rei do Egito, atacou Jerusalém no quinto ano do reinado de Roboão."),  (3262, 14, 12, 3, "Com mil e duzentos carros de guerra, sessenta mil cavaleiros e um exército incontável de líbios, suquitas e etíopes, que vieram do Egito com ele,"),  (3263, 14, 12, 4, "conquistou as cidades fortificadas de Judá e chegou até Jerusalém."),  (3264, 14, 12, 5, "Então o profeta Semaías apresentou-se a Roboão e aos líderes de Judá que se haviam reunido em Jerusalém, fugindo de Sisaque, e lhes disse: Assim diz o Senhor: ‘Vocês me abandonaram; por isso eu agora os abandono, entregando-os a Sisaque’ ."),  (3265, 14, 12, 6, "Os líderes de Israel e o rei se humilharam e disseram: O Senhor é justo."),  (3266, 14, 12, 7, "Quando o Senhor viu que eles se humilharam, veio a Semaías esta palavra do Senhor: Visto que eles se humilharam, não os destruirei, mas em breve lhes darei livramento. Minha ira não será derramada sobre Jerusalém por meio de Sisaque."),  (3267, 14, 12, 8, "Eles, contudo, ficarão sujeitos a ele, para que aprendam a diferença entre servir a mim e servir aos reis de outras terras."),  (3268, 14, 12, 9, "Quando Sisaque, rei do Egito, atacou Jerusalém, levou todos os tesouros do templo do Senhor e do palácio real, inclusive os escudos de ouro que Salomão havia feito."),  (3269, 14, 12, 10, "Por isso o rei Roboão mandou fazer escudos de bronze para substituí-los, e os entregou aos chefes da guarda da entrada do palácio real."),  (3270, 14, 12, 11, "Sempre que o rei ia ao templo do Senhor, os guardas empunhavam os escudos, e, em seguida, os devolviam à sala da guarda."),  (3271, 14, 12, 12, "Como Roboão se humilhou, a ira do Senhor afastou-se dele, e ele não foi totalmente destruído. Aliás, ainda havia algo de bom em Judá."),  (3272, 14, 12, 13, "O rei Roboão firmou-se no poder em Jerusalém e continuou a reinar. Tinha quarenta e um anos de idade quando começou a reinar, e reinou dezessete anos em Jerusalém, cidade que o Senhor havia escolhido dentre todas as tribos de Israel para nela pôr o seu nome. Sua mãe, uma amonita, chamava-se Naamá."),  (3273, 14, 12, 14, "Ele agiu mal porque não dispôs o seu coração para buscar o Senhor."),  (3274, 14, 12, 15, "Os demais acontecimentos do reinado de Roboão, do início ao fim, estão escritos nos relatos do profeta Semaías e do vidente Ido, que tratam de genealogias. Houve guerra constante entre Roboão e Jeroboão."),  (3275, 14, 12, 16, "Roboão descansou com os seus antepassados e foi sepultado na cidade de Davi; seu filho Abias foi o seu sucessor."),  (3276, 14, 13, 1, "No décimo oitavo ano do reinado de Jeroboão, Abias tornou-se rei de Judá,"),  (3277, 14, 13, 2, "e reinou três anos em Jerusalém. O nome de sua mãe era Maaca, filha de Uriel, de Gibeá. E houve guerra entre Abias e Jeroboão."),  (3278, 14, 13, 3, "Abias entrou em combate levando uma força de quatrocentos mil excelentes guerreiros, e Jeroboão foi enfrentá-lo com oitocentos mil excelentes guerreiros."),  (3279, 14, 13, 4, "Abias subiu o monte Zemaraim, nos montes de Efraim, e gritou: Jeroboão e todo o Israel, ouçam-me!"),  (3280, 14, 13, 5, "Vocês não sabem que o Senhor, o Deus de Israel, deu para sempre o reino de Israel a Davi e a seus descendentes mediante uma aliança irrevogável?"),  (3281, 14, 13, 6, "Mesmo assim, Jeroboão, filho de Nebate, servo de Salomão, filho de Davi, rebelou-se contra o seu senhor."),  (3282, 14, 13, 7, "Alguns homens vadios e imprestáveis juntaram-se a ele e se opuseram a Roboão, filho de Salomão, quando ainda era jovem, indeciso e incapaz de oferecer-lhes resistência."),  (3283, 14, 13, 8, "E agora vocês pretendem resistir ao reino do Senhor, que está nas mãos dos descendentes de Davi. Vocês são de fato uma multidão imensa e têm os bezerros de ouro que Jeroboão fez para serem os seus deuses."),  (3284, 14, 13, 9, "Mas, não foram vocês que expulsaram os sacerdotes do Senhor, os descendentes de Arão, e os levitas, e escolheram os seus próprios sacerdotes, como fazem os outros povos? Quem quer que se consagre com um novilho e sete carneiros pode tornar-se sacerdote daqueles que não são deuses."),  (3285, 14, 13, 10, "Quanto a nós, o Senhor é o nosso Deus, e não o abandonamos. Os nossos sacerdotes, que servem ao Senhor auxiliados pelos levitas, são descendentes de Arão."),  (3286, 14, 13, 11, "Todas as manhãs e todas as tardes eles apresentam holocaustos e incenso aromático ao Senhor, arrumam os pães sobre a mesa cerimonialmente pura e todas as tardes acendem as lâmpadas do candelabro de ouro. Pois nós observamos as exigências do Senhor, o nosso Deus, enquanto que vocês o abandonaram."),  (3287, 14, 13, 12, "E vejam bem! Deus está conosco; ele é o nosso chefe. Os sacerdotes dele, com suas cornetas, farão soar o grito de guerra contra vocês. Israelitas, não lutem contra o Senhor, o Deus dos seus antepassados, pois vocês não terão êxito! "),  (3288, 14, 13, 13, "Enquanto isso, Jeroboão tinha mandado tropas para a retaguarda do exército de Judá, de forma que ele estava em frente de Judá e a emboscada estava atrás."),  (3289, 14, 13, 14, "Quando o exército de Judá virou-se e viu que estava sendo atacado pela frente e pela retaguarda, clamou ao Senhor. Os sacerdotes tocaram suas cornetas,"),  (3290, 14, 13, 15, "e os homens de Judá deram o grito de guerra. Ao som do grito de guerra, Deus derrotou Jeroboão e todo o Israel diante de Abias e de Judá."),  (3291, 14, 13, 16, "Os israelitas fugiram dos soldados de Judá, e Deus os entregou nas mãos deles."),  (3292, 14, 13, 17, "Abias e os seus soldados lhes infligiram grande derrota; quinhentos mil excelentes guerreiros de Israel foram mortos."),  (3293, 14, 13, 18, "Os israelitas foram subjugados naquela ocasião, e os homens de Judá tiveram força para vencer, pois confiaram no Senhor, o Deus dos seus antepassados."),  (3294, 14, 13, 19, "Abias perseguiu Jeroboão e tomou-lhe as cidades de Betel, Jesana e Efrom, com os seus povoados ao redor."),  (3295, 14, 13, 20, "Durante o reinado de Abias, Jeroboão não recuperou o seu poder; até que o Senhor o feriu, e ele morreu."),  (3296, 14, 13, 21, "Abias, ao contrário, fortaleceu-se. Ele se casou com catorze mulheres e teve vinte e dois filhos e dezesseis filhas."),  (3297, 14, 13, 22, "Os demais acontecimentos do reinado de Abias, o que ele fez e o que disse, estão escritos nos relatos do profeta Ido."),  (3298, 14, 14, 1, "Abias descansou com os seus antepassados e foi sepultado na cidade de Davi. E o seu filho Asa foi o seu sucessor, e em seu reinado o país esteve em paz durante dez anos."),  (3299, 14, 14, 2, "Asa fez o que o Senhor, o seu Deus, aprova."),  (3300, 14, 14, 3, "Retirou os altares dos deuses estrangeiros e os altares idólatras que havia nos montes, despedaçou as colunas sagradas e derrubou os postes sagrados."),  (3301, 14, 14, 4, "Ordenou ao povo de Judá que buscasse o Senhor, o Deus dos seus antepassados, e que obedecesse às leis e aos mandamentos dele."),  (3302, 14, 14, 5, "Retirou os altares idólatras e os altares de incenso de todas as cidades de Judá, e o reino esteve em paz durante o seu governo."),  (3303, 14, 14, 6, "Também construiu cidades fortificadas em Judá, aproveitando esse período de paz. Ninguém entrou em guerra com ele durante aqueles anos, pois o Senhor lhe deu descanso."),  (3304, 14, 14, 7, "Disse ele ao povo de Judá: Vamos construir estas cidades com muros ao redor, fortificadas com torres, portas e trancas. A terra ainda é nossa, porque temos buscado o Senhor, o nosso Deus; nós o buscamos, e ele nos tem concedido paz em nossas fronteiras. Eles então as construíram e prosperaram."),  (3305, 14, 14, 8, "Asa tinha um exército de trezentos mil homens de Judá, equipados com escudos grandes e lanças, e duzentos e oitenta mil de Benjamim, armados com escudos pequenos e arcos. Todos eram valentes homens de combate."),  (3306, 14, 14, 9, "O etíope Zerá marchou contra eles com um exército de um milhão de soldados e trezentos carros de guerra, e chegou a Maressa."),  (3307, 14, 14, 10, "Asa saiu para enfrentá-lo, e eles se puseram em posição de combate no vale de Zefatá, perto de Maressa."),  (3308, 14, 14, 11, "Então Asa clamou ao Senhor, o seu Deus: Senhor, não há ninguém como tu para ajudar os fracos contra os poderosos. Ajuda-nos, ó Senhor, ó nosso Deus, pois em ti pomos a nossa confiança, e em teu nome viemos contra este imenso exército. Ó Senhor, tu és o nosso Deus; não deixes o homem prevalecer contra ti."),  (3309, 14, 14, 12, "O Senhor derrotou os etíopes diante de Asa e de Judá. Os etíopes fugiram,"),  (3310, 14, 14, 13, "e Asa e seu exército os perseguiram até Gerar. E caíram tantos deles que o exército não conseguiu recuperar-se; foram destruídos perante o Senhor e suas forças. E os homens de Judá saquearam muitos bens."),  (3311, 14, 14, 14, "Destruíram todas as cidades ao redor de Gerar, pois o terror do Senhor havia caído sobre elas. Saquearam todas essas cidades, pois havia nelas muitos despojos."),  (3312, 14, 14, 15, "Também atacaram os acampamentos onde havia gado e se apoderaram de muitas ovelhas, cabras e camelos. E então voltaram para Jerusalém."),  (3313, 14, 15, 1, "O Espírito de Deus veio sobre Azarias, filho de Odede."),  (3314, 14, 15, 2, "Ele saiu para encontrar-se com Asa e lhe disse: Escutem-me, Asa e todo o povo de Judá e de Benjamim. O Senhor está com vocês quando vocês estão com ele. Se o buscarem, ele deixará que o encontrem, mas, se o abandonarem, ele os abandonará."),  (3315, 14, 15, 3, "Durante muito tempo Israel esteve sem o verdadeiro Deus, sem sacerdote para ensiná-lo e sem a Lei."),  (3316, 14, 15, 4, "Mas em sua angústia eles se voltaram para o Senhor, o Deus de Israel; buscaram-no, e ele deixou que o encontrassem."),  (3317, 14, 15, 5, "Naqueles dias não era seguro viajar, pois muitos distúrbios afligiam a todos os habitantes do território."),  (3318, 14, 15, 6, "Nações e cidades se destruíam umas às outras, pois Deus as estava afligindo com toda espécie de desgraças."),  (3319, 14, 15, 7, "Mas, vocês devem ser fortes e não se desanimar, pois o trabalho de vocês será recompensado."),  (3320, 14, 15, 8, "Assim que ouviu as palavras e a profecia do profeta Azarias, filho de Odede, o rei Asa encheu-se de coragem. Retirou os ídolos repugnantes de toda a terra de Judá e de Benjamim, e das cidades que havia conquistado nos montes de Efraim, e restaurou o altar do Senhor que estava em frente do pórtico do templo do Senhor."),  (3321, 14, 15, 9, "Depois reuniu todo o povo de Judá e de Benjamim; convocou também os que pertenciam a Efraim, a Manassés e a Simeão que viviam entre eles, pois muitos de Israel tinham passado para o lado do rei Asa, ao verem que o Senhor, o seu Deus, estava com ele."),  (3322, 14, 15, 10, "Eles se reuniram em Jerusalém no terceiro mês do décimo quinto ano do reinado de Asa."),  (3323, 14, 15, 11, "Naquela ocasião sacrificaram ao Senhor setecentos bois e sete mil ovelhas e cabras, do saque que haviam feito."),  (3324, 14, 15, 12, "Fizeram um acordo de todo o coração e de toda a alma de buscar o Senhor, o Deus dos seus antepassados."),  (3325, 14, 15, 13, "Todo aquele que não buscasse o Senhor, o Deus de Israel, deveria ser morto, gente simples ou importante, homem ou mulher."),  (3326, 14, 15, 14, "Fizeram esse juramento ao Senhor em voz alta, bradando ao som de cornetas e trombetas."),  (3327, 14, 15, 15, "Todo o povo de Judá alegrou-se com o juramento, pois o havia feito de todo o coração. Eles buscaram a Deus com toda disposição; então ele deixou que o encontrassem e lhes concedeu paz em suas fronteiras."),  (3328, 14, 15, 16, "O rei Asa chegou até a depor sua avó Maaca da posição de rainha-mãe, pois ela havia feito um poste sagrado repugnante. Asa derrubou o poste, despedaçou-o e queimou-o no vale do Cedrom."),  (3329, 14, 15, 17, "Embora os altares idólatras não tenham sido eliminados de Israel, o coração de Asa foi totalmente dedicado ao Senhor durante toda a sua vida."),  (3330, 14, 15, 18, "Ele trouxe para o templo de Deus a prata, o ouro e os utensílios que ele e seu pai haviam consagrado."),  (3331, 14, 15, 19, "E não houve mais nenhuma guerra até o trigésimo quinto ano do seu reinado."),  (3332, 14, 16, 1, "No trigésimo sexto ano do reinado de Asa, Baasa, rei de Israel, invadiu Judá e fortificou Ramá, para que ninguém pudesse entrar nem sair do território de Asa, rei de Judá."),  (3333, 14, 16, 2, "Então Asa ajuntou a prata e o ouro do tesouro do templo do Senhor e do seu próprio palácio e os enviou a Ben-Hadade, rei da Síria, que governava em Damasco, com uma mensagem que dizia:"),  (3334, 14, 16, 3, "Façamos um tratado, como fizeram meu pai e o teu. Estou te enviando prata e ouro. Agora, rompe o tratado que tens com Baasa, rei de Israel, para que ele saia do meu país."),  (3335, 14, 16, 4, "Ben-Hadade aceitou a proposta do rei Asa e ordenou aos comandantes das suas forças que atacassem as cidades de Israel. Eles conquistaram Ijom, Dã, Abel-Maim e todas as cidades-armazéns de Naftali."),  (3336, 14, 16, 5, "Quando Baasa soube disso, abandonou a construção dos muros de Ramá."),  (3337, 14, 16, 6, "Então o rei Asa reuniu todos os homens de Judá, e eles retiraram de Ramá as pedras e a madeira que Baasa estivera usando. Com esse material Asa fortificou Geba e Mispá."),  (3338, 14, 16, 7, "Naquela época, o vidente Hanani foi dizer a Asa, rei de Judá: Por você ter pedido ajuda ao rei da Síria e não ao Senhor, ao seu Deus, o exército do rei da Síria escapou de suas mãos."),  (3339, 14, 16, 8, "Por acaso os etíopes e os líbios não eram um exército poderoso, com uma grande multidão de carros e cavalos? Contudo, quando você pediu ajuda ao Senhor, ele os entregou em suas mãos."),  (3340, 14, 16, 9, "Pois os olhos do Senhor estão atentos sobre toda a terra para fortalecer aqueles que lhe dedicam totalmente o coração. Nisso você cometeu uma loucura. De agora em diante terás que enfrentar guerras."),  (3341, 14, 16, 10, "Asa irritou-se contra o vidente por causa disso; ficou tão indignado que mandou prendê-lo. Nessa época Asa oprimiu brutalmente alguns do povo."),  (3342, 14, 16, 11, "Os demais acontecimentos do reinado de Asa, do início ao fim, estão escritos nos registros históricos dos reis de Judá e de Israel."),  (3343, 14, 16, 12, "No trigésimo nono ano de seu reinado, Asa foi atacado por uma doença nos pés. Embora a sua doença fosse grave, não buscou ajuda do Senhor, mas só dos médicos."),  (3344, 14, 16, 13, "Então, no quadragésimo primeiro ano do seu reinado, Asa morreu e descansou com os seus antepassados."),  (3345, 14, 16, 14, "Sepultaram-no no túmulo que ele havia mandado cavar para si na cidade de Davi. Deitaram-no num leito coberto de especiarias e de vários perfumes de fina mistura, e fizeram uma imensa fogueira em sua honra."),  (3346, 14, 17, 1, "Josafá, filho de Asa, foi o seu sucessor e fortaleceu-se contra Israel."),  (3347, 14, 17, 2, "Posicionou tropas em todas as cidades fortificadas de Judá e pôs guarnições em Judá e nas cidades de Efraim que seu pai, Asa, tinha conquistado."),  (3348, 14, 17, 3, "O Senhor esteve com Josafá porque, em seus primeiros anos, ele andou nos caminhos que seu pai Davi tinha seguido. Não consultou os baalins,"),  (3349, 14, 17, 4, "mas buscou o Deus de seu pai e obedeceu aos seus mandamentos, e não imitou as práticas de Israel."),  (3350, 14, 17, 5, "O Senhor firmou o reino de Josafá, e todo o Judá lhe trazia presentes, de maneira que teve grande riqueza e honra."),  (3351, 14, 17, 6, "Ele seguiu corajosamente os caminhos do Senhor; além disso, retirou de Judá os altares idólatras e os postes sagrados."),  (3352, 14, 17, 7, "No terceiro ano de seu reinado, ele enviou seus oficiais Bene-Hail, Obadias, Zacarias, Natanael e Micaías para ensinarem nas cidades de Judá."),  (3353, 14, 17, 8, "Com eles foram os levitas Semaías, Netanias, Zebadias, Asael, Semiramote, Jônatas, Adonias, Tobias, Tobe-Adonias e os sacerdotes Elisama e Jeorão."),  (3354, 14, 17, 9, "Eles percorreram todas as cidades do reino de Judá, levando consigo o Livro da Lei do Senhor e ensinando o povo."),  (3355, 14, 17, 10, "O temor do Senhor caiu sobre todos os reinos ao redor de Judá, de forma que não entraram em guerra contra Josafá."),  (3356, 14, 17, 11, "Alguns filisteus levaram presentes a Josafá, além da prata que lhe deram como tributo, e os árabes levaram-lhe rebanhos: sete mil e setecentos carneiros e sete mil e setecentos bodes."),  (3357, 14, 17, 12, "Josafá foi se tornando cada vez mais poderoso; construiu fortalezas e cidades-armazéns em Judá,"),  (3358, 14, 17, 13, "onde guardava enorme quantidade de suprimentos. Também mantinha em Jerusalém homens de combate experientes."),  (3359, 14, 17, 14, "A lista desses homens, por famílias, era a seguinte: De Judá, líderes de batalhões de 1. 000: o líder Adna, com 300. 000 homens de combate;"),  (3360, 14, 17, 15, "em seguida, o líder Joanã, com 280. 000;"),  (3361, 14, 17, 16, "depois, Amasias, filho de Zicri, que se apresentou voluntariamente para o serviço do Senhor, com 200. 000."),  (3362, 14, 17, 17, "De Benjamim: Eliada, um guerreiro valente, com 200. 000 homens armados com arcos e escudos;"),  (3363, 14, 17, 18, "Jeozabade, com 180. 000 homens armados para a batalha."),  (3364, 14, 17, 19, "Esses eram os homens que serviam o rei, além dos que estavam posicionados nas cidades fortificadas em todo o Judá."),  (3365, 14, 18, 1, "Josafá tinha grande riqueza e honra, e aliou-se a Acabe mediante casamento."),  (3366, 14, 18, 2, "Alguns anos depois, ele foi visitar Acabe em Samaria. Acabe abateu muitas ovelhas e bois para receber a ele e à sua comitiva, e insistiu que atacasse Ramote-Gileade."),  (3367, 14, 18, 3, "Acabe, rei de Israel, perguntou a Josafá, rei de Judá: Irás comigo lutar contra Ramote-Gileade?  Josafá respondeu: Sou como tu, e meu povo é como o teu povo; estaremos contigo na guerra."),  (3368, 14, 18, 4, "Mas acrescentou: Peço-te que busques primeiro o conselho do Senhor."),  (3369, 14, 18, 5, "Então o rei de Israel reuniu quatrocentos profetas, e lhes perguntou: Devemos ir à guerra contra Ramote-Gileade, ou não?  Eles responderam: Sim, pois Deus a entregará nas mãos do rei."),  (3370, 14, 18, 6, "Josafá, porém, perguntou: Não existe aqui mais nenhum profeta do Senhor, a quem possamos consultar? "),  (3371, 14, 18, 7, "O rei de Israel respondeu a Josafá: Ainda há um homem por meio de quem podemos consultar o Senhor, mas eu o odeio, porque nunca profetiza coisas boas a meu respeito, mas sempre coisas ruins. É Micaías, filho de Inlá. O rei não deveria dizer isso, Josafá respondeu."),  (3372, 14, 18, 8, "Então o rei de Israel chamou um dos seus oficiais e disse: Traga Micaías, filho de Inlá, imediatamente."),  (3373, 14, 18, 9, "Usando vestes reais, o rei de Israel e Josafá, rei de Judá, estavam sentados em seus tronos, na eira, junto à porta de Samaria, e todos os profetas estavam profetizando em transe diante deles."),  (3374, 14, 18, 10, "E Zedequias, filho de Quenaaná, tinha feito chifres de ferro, e declarou: Assim diz o Senhor: ‘Com estes chifres tu ferirás os arameus até que sejam destruídos’ ."),  (3375, 14, 18, 11, "Todos os outros profetas estavam profetizando a mesma coisa, dizendo: Ataca Ramote-Gileade, e serás vitorioso, pois o Senhor a entregará nas mãos do rei."),  (3376, 14, 18, 12, "O mensageiro que tinha ido chamar Micaías lhe disse: Veja, todos os outros profetas estão predizendo que o rei terá sucesso. Sua palavra também deve ser favorável."),  (3377, 14, 18, 13, "Micaías, porém, disse: Juro pelo nome do Senhor, que direi o que o meu Deus mandar."),  (3378, 14, 18, 14, "Quando ele chegou, o rei lhe perguntou: Micaías, devemos ir à guerra contra Ramote-Gileade, ou não?  Ele respondeu: Atacai, e sereis vitoriosos, pois eles serão entregues em vossas mãos."),  (3379, 14, 18, 15, "O rei lhe disse: Quantas vezes devo fazer você jurar que me irá dizer somente a verdade em nome do Senhor? "),  (3380, 14, 18, 16, "Então Micaías respondeu: Vi todo o Israel espalhado pelas colinas, como ovelhas sem pastor, e o Senhor dizer: ‘Estes não têm dono. Cada um volte para casa em paz’ ."),  (3381, 14, 18, 17, "O rei de Israel disse a Josafá: Não lhe disse que ele nunca profetiza nada de bom a meu respeito, mas apenas coisas ruins? "),  (3382, 14, 18, 18, "Micaías prosseguiu: Ouçam a palavra do Senhor: Vi o Senhor assentado em seu trono, com todo o exército dos céus à sua direita e à sua esquerda."),  (3383, 14, 18, 19, "E o Senhor disse: ‘Quem enganará Acabe, rei de Israel, para que ataque Ramote-Gileade e morra lá? ’ E um sugeria uma coisa, outro sugeria outra, até que,"),  (3384, 14, 18, 20, "finalmente, um espírito colocou-se diante do Senhor e disse: ‘Eu o enganarei’.  ‘De que maneira? ’, perguntou o Senhor."),  (3385, 14, 18, 21, "Ele respondeu: ‘Irei e serei um espírito mentiroso na boca de todos os profetas do rei’. Disse o Senhor: ‘Você conseguirá enganá-lo; vá e engane-o’."),  (3386, 14, 18, 22, "E o Senhor pôs um espírito mentiroso na boca destes seus profetas. O Senhor decretou a sua desgraça."),  (3387, 14, 18, 23, "Então Zedequias, filho de Quenaaná, aproximou-se, deu um tapa no rosto de Micaías e perguntou: Por qual caminho foi o espírito da parte do Senhor, quando saiu de mim para falar a você? "),  (3388, 14, 18, 24, "Micaías respondeu: Você descobrirá no dia em que estiver se escondendo de quarto em quarto."),  (3389, 14, 18, 25, "O rei de Israel então ordenou: Enviem Micaías de volta a Amom, o governador da cidade, e a Joás, filho do rei,"),  (3390, 14, 18, 26, "e digam: Assim diz o rei: Ponham este homem na prisão a pão e água, até que eu volte em segurança."),  (3391, 14, 18, 27, "Micaías declarou: Se você de fato voltar em segurança, o Senhor não falou por meu intermédio. E acrescentou: Ouçam o que estou dizendo, todos vocês! "),  (3392, 14, 18, 28, "Então o rei de Israel e Josafá, rei de Judá, foram atacar Ramote-Gileade."),  (3393, 14, 18, 29, "E o rei de Israel disse a Josafá: Entrarei disfarçado em combate, mas tu, usa as tuas vestes reais. O rei de Israel disfarçou-se, e ambos foram para o combate."),  (3394, 14, 18, 30, "O rei da Síria havia ordenado a seus chefes dos carros de guerra: Não lutem contra ninguém, seja soldado seja oficial, senão contra o rei de Israel."),  (3395, 14, 18, 31, "Quando os chefes dos carros viram Josafá, pensaram: É o rei de Israel, e o cercaram para atacá-lo, mas Josafá clamou, e o Senhor o ajudou. Deus os afastou dele,"),  (3396, 14, 18, 32, "pois, quando os comandantes dos carros viram que não era o rei de Israel, deixaram de persegui-lo."),  (3397, 14, 18, 33, "De repente, um soldado disparou seu arco ao acaso, e atingiu o rei de Israel entre os encaixes da sua armadura. Então o rei disse ao condutor do seu carro: Tire-me do combate. Fui ferido! "),  (3398, 14, 18, 34, "A batalha foi violenta durante todo o dia, e assim, o rei de Israel teve que enfrentar os arameus em pé no seu carro, até à tarde. E, ao pôr-do-sol, ele morreu."),  (3399, 14, 19, 1, "Quando Josafá, rei de Judá, voltou em segurança ao seu palácio em Jerusalém,"),  (3400, 14, 19, 2, "o vidente Jeú, filho de Hanani, saiu ao seu encontro e lhe disse: Será que você devia ajudar os ímpios e amar aqueles que odeiam o Senhor? Por causa disso, a ira do Senhor está sobre você."),  (3401, 14, 19, 3, "Contudo, existe em você algo de bom, pois você livrou a terra dos postes sagrados e buscou a Deus de todo o seu coração."),  (3402, 14, 19, 4, "Josafá morava em Jerusalém; e saiu de novo entre o povo, desde Berseba até os montes de Efraim, fazendo-o voltar para o Senhor, o Deus dos seus antepassados."),  (3403, 14, 19, 5, "Ele nomeou juízes, em cada uma das cidades fortificadas de Judá,"),  (3404, 14, 19, 6, "dizendo-lhes: Considerem atentamente aquilo que fazem, pois vocês não estão julgando para o homem, mas para o Senhor, que estará com vocês sempre que derem um veredicto."),  (3405, 14, 19, 7, "Agora, que o temor do Senhor esteja sobre vocês. Julguem com cuidado, pois com o Senhor, o nosso Deus, não há injustiça nem parcialidade nem suborno."),  (3406, 14, 19, 8, "Também em Jerusalém nomeou Josafá alguns dos levitas, dos sacerdotes e dos chefes de famílias israelitas para julgarem questões da lei do Senhor e resolverem pendências dos habitantes."),  (3407, 14, 19, 9, "Deu-lhes as seguintes ordens: Vocês devem servir com fidelidade e com coração íntegro, no temor do Senhor."),  (3408, 14, 19, 10, "Em cada caso que chegar a vocês da parte dos seus irmãos israelitas das outras cidades, seja caso de derramamento de sangue sejam questões referentes à lei, aos mandamentos, aos decretos ou às ordenanças, vocês deverão adverti-los de que não pequem contra o Senhor; caso contrário a ira dele virá sobre vocês e sobre eles. Façam assim, e vocês não pecarão."),  (3409, 14, 19, 11, "Amarias, o sumo sacerdote, estará com vocês para decidir qualquer questão referente à lei do Senhor; Zebadias, filho de Ismael, líder da tribo de Judá, estará com vocês para decidir qualquer questão civil; e os levitas atuarão como oficiais diante de vocês. Cumpram seus deveres com coragem, e esteja o Senhor com aqueles que agirem corretamente."),  (3410, 14, 20, 1, "Depois disso, os moabitas e os amonitas, com alguns dos meunitas, entraram em guerra contra Josafá."),  (3411, 14, 20, 2, "Então informaram a Josafá: Um exército enorme vem contra ti de Edom, do outro lado do mar Morto. Já está em Hazazom-Tamar, isto é, En-Gedi."),  (3412, 14, 20, 3, "Alarmado, Josafá decidiu consultar o Senhor e proclamou um jejum em todo o reino de Judá."),  (3413, 14, 20, 4, "Reuniu-se, pois, o povo, vindo de todas as cidades de Judá para buscar a ajuda do Senhor."),  (3414, 14, 20, 5, "Então Josafá levantou-se na assembléia de Judá e de Jerusalém, no templo do Senhor, na frente do pátio novo,"),  (3415, 14, 20, 6, "e orou: Senhor, Deus dos nossos antepassados, não és tu o Deus que está nos céus? Tu governas sobre todos os reinos do mundo. Força e poder estão em tuas mãos, e ninguém pode opor-se a ti."),  (3416, 14, 20, 7, "Não és tu o nosso Deus, que expulsaste os habitantes desta terra perante Israel, teu povo, e a deste para sempre aos descendentes de teu amigo Abraão?"),  (3417, 14, 20, 8, "Eles a têm habitado e nela construíram um santuário em honra do teu nome, dizendo:"),  (3418, 14, 20, 9, "‘Se alguma desgraça nos atingir, seja o castigo da espada, seja a peste, seja a fome, nós nos colocaremos em tua presença diante deste templo, pois ele leva o teu nome, e clamaremos a ti em nossa angústia, e tu nos ouvirás e nos salvarás’."),  (3419, 14, 20, 10, "Mas agora, aí estão amonitas, moabitas e habitantes dos montes de Seir, cujos territórios não permitiste que Israel invadisse quando vinha do Egito; por isso os israelitas se desviaram deles e não os destruíram."),  (3420, 14, 20, 11, "Vê agora como estão nos retribuindo, ao virem expulsar-nos da terra que nos deste por herança."),  (3421, 14, 20, 12, "Ó nosso Deus, não irás tu julgá-los? Pois não temos força para enfrentar esse exército imenso que está nos atacando. Não sabemos o que fazer, mas os nossos olhos se voltam para ti."),  (3422, 14, 20, 13, "Todos os homens de Judá, com suas mulheres e seus filhos, até os de colo, estavam ali de pé, diante do Senhor."),  (3423, 14, 20, 14, "Então o Espírito do Senhor veio sobre Jaaziel, filho de Zacarias, neto de Benaia, bisneto de Jeiel e trineto de Matanias, levita e descendente de Asafe, no meio da assembléia."),  (3424, 14, 20, 15, "Ele disse: Escutem, todos os que vivem em Judá e em Jerusalém e o rei Josafá! Assim lhes diz o Senhor: ‘Não tenham medo nem fiquem desanimados por causa desse exército enorme. Pois a batalha não é de vocês, mas de Deus."),  (3425, 14, 20, 16, "Amanhã, desçam contra eles. Eles virão pela subida de Ziz, e vocês os encontrarão no fim do vale, em frente do deserto de Jeruel."),  (3426, 14, 20, 17, "Vocês não precisarão lutar nessa batalha. Tomem suas posições; permaneçam firmes e vejam o livramento que o Senhor lhes dará, ó Judá, ó Jerusalém. Não tenham medo nem se desanimem. Saiam para enfrentá-los amanhã, e o Senhor estará com vocês’ ."),  (3427, 14, 20, 18, "Josafá prostrou-se, rosto em terra, e todo o povo de Judá e de Jerusalém prostrou-se em adoração perante o Senhor."),  (3428, 14, 20, 19, "Então os levitas descendentes dos coatitas e dos coreítas levantaram-se e louvaram o Senhor, o Deus de Israel, em alta voz."),  (3429, 14, 20, 20, "De madrugada partiram para o deserto de Tecoa. Quando estavam saindo, Josafá lhes disse: Escutem-me, Judá e povo de Jerusalém! Tenham fé no Senhor, o seu Deus, e vocês serão sustentados; tenham fé nos profetas dele e vocês terão a vitória."),  (3430, 14, 20, 21, "Depois de consultar o povo, Josafá nomeou alguns homens para cantarem ao Senhor e o louvarem pelo esplendor de sua santidade, indo à frente do exército, cantando: Dêem graças ao Senhor, pois o seu amor dura para sempre."),  (3431, 14, 20, 22, "Quando começaram a cantar e a entoar louvores, o Senhor preparou emboscadas contra os homens de Amom, de Moabe e dos montes de Seir que estavam invadindo Judá, e eles foram derrotados."),  (3432, 14, 20, 23, "Os amonitas e os moabitas atacaram os dos montes de Seir para destruí-los e aniquilá-los. Depois de massacrarem os homens de Seir, destruiram-se uns aos outros."),  (3433, 14, 20, 24, "Quando os homens de Judá foram para o lugar de onde se avista o deserto e olharam para o imenso exército, viram somente cadáveres no chão; ninguém havia escapado."),  (3434, 14, 20, 25, "Então, Josafá e os seus soldados foram saquear os cadáveres e encontraram entre eles grande quantidade de equipamentos e roupas, e também objetos de valor; passaram três dias saqueando, mas havia mais do que eram capazes de levar."),  (3435, 14, 20, 26, "No quarto dia eles se reuniram no vale de Beraca, onde louvaram o Senhor. Por isso até hoje ele é chamado vale de Beraca."),  (3436, 14, 20, 27, "Depois sob a liderança de Josafá, todos os homens de Judá e de Jerusalém voltaram alegres para Jerusalém, pois o Senhor lhes enchera de alegria, dando-lhes vitória sobre os seus inimigos."),  (3437, 14, 20, 28, "Entraram em Jerusalém e foram ao templo do Senhor, ao som de liras, harpas e cornetas."),  (3438, 14, 20, 29, "O temor de Deus veio sobre todas as nações, quando souberam como o Senhor havia lutado contra os inimigos de Israel."),  (3439, 14, 20, 30, "E o reino de Josafá manteve-se em paz, pois o seu Deus lhe concedeu paz em todas as suas fronteiras."),  (3440, 14, 20, 31, "Assim Josafá reinou sobre Judá. Ele tinha trinta e cinco anos de idade quando se tornou rei, e reinou vinte e cinco anos em Jerusalém. O nome da sua mãe era Azuba, filha de Sili."),  (3441, 14, 20, 32, "Ele andou nos caminhos de Asa, seu pai, e não se desviou deles; fez o que o Senhor aprova."),  (3442, 14, 20, 33, "Contudo, não acabou com os altares idólatras, e o povo ainda não havia firmado o coração no Deus dos seus antepassados."),  (3443, 14, 20, 34, "Os demais acontecimentos do reinado de Josafá, do início ao fim, estão escritos nos relatos de Jeú, filho de Hanani, e incluídos nos registros históricos dos reis de Israel."),  (3444, 14, 20, 35, "Posteriormente, Josafá, rei de Judá, fez um tratado com Acazias, rei de Israel, que tinha vida ímpia."),  (3445, 14, 20, 36, "Era um tratado para a construção de navios mercantes. Depois de serem construídos os navios em Eziom-Geber,"),  (3446, 14, 20, 37, "Eliézer, filho de Dodava de Maressa, profetizou contra Josafá, dizendo: Por haver feito um tratado com Acazias, o Senhor destruirá o que você fez. Assim, os navios naufragaram e não puderam sair para negociar."),  (3447, 14, 21, 1, "Josafá descansou com seus antepassados e foi sepultado junto deles na cidade de Davi, e seu filho Jeorão foi o seu sucessor."),  (3448, 14, 21, 2, "Os irmãos de Jeorão, filhos de Josafá, foram Azarias, Jeiel, Zacarias, Azarias, Micael e Sefatias. Todos eles foram filhos de Josafá, rei de Israel."),  (3449, 14, 21, 3, "Ele deu-lhes muitos presentes de prata e ouro e objetos de valor, bem como cidades fortificadas em Judá, mas o reino deu a Jeorão, porque este era seu filho mais velho."),  (3450, 14, 21, 4, "Logo Jeorão se fortaleceu no reino de seu pai, e matou à espada todos os seus irmãos, juntamente com alguns dos líderes de Israel."),  (3451, 14, 21, 5, "Ele tinha trinta e dois anos de idade quando começou a reinar, e reinou oito anos em Jerusalém."),  (3452, 14, 21, 6, "Andou nos caminhos dos reis de Israel, como a família de Acabe havia feito, pois se casou com uma filha de Acabe. E fez o que o Senhor reprova."),  (3453, 14, 21, 7, "Entretanto, por causa da aliança que havia feito com Davi, o Senhor não quis destruir a dinastia dele. Ele havia prometido manter para sempre um descendente de Davi no trono."),  (3454, 14, 21, 8, "Nos dias de Jeorão, os edomitas rebelaram-se contra o domínio de Judá, proclamando seu próprio rei."),  (3455, 14, 21, 9, "Por isso, Jeorão foi combatê-los com seus líderes e com todos os seus carros de guerra. Os edomitas cercaram a ele e aos chefes de seus carros de guerra, mas ele os atacou de noite e rompeu o cerco inimigo."),  (3456, 14, 21, 10, "E até hoje Edom continua independente de Judá. Nessa mesma época, a cidade de Libna também tornou-se independente, pois Jeorão havia abandonado o Senhor, o Deus dos seus antepassados."),  (3457, 14, 21, 11, "Ele até construiu altares idólatras nas colinas de Judá, levando o povo de Jerusalém a prostituir-se e Judá a desviar-se."),  (3458, 14, 21, 12, "Então Jeorão recebeu uma carta do profeta Elias, que dizia: Assim diz o Senhor, o Deus de Davi, seu antepassado: ‘Você não tem andado nos caminhos de seu pai Josafá nem de Asa, rei de Judá."),  (3459, 14, 21, 13, "Mas sim nos caminhos dos reis de Israel, e levou Judá e o povo de Jerusalém a se prostituírem na idolatria como a família de Acabe. E ainda assassinou seus próprios irmãos, membros da família de seu pai, homens que eram melhores do que você."),  (3460, 14, 21, 14, "Por isso, o Senhor vai ferir terrivelmente seu povo, seus filhos, suas mulheres e tudo o que é seu."),  (3461, 14, 21, 15, "Você ficará muito doente; terá uma enfermidade no ventre, que irá piorar até que saiam os seus intestinos’ ."),  (3462, 14, 21, 16, "O Senhor despertou contra Jeorão a hostilidade dos filisteus e dos árabes que viviam perto dos etíopes."),  (3463, 14, 21, 17, "Eles atacaram o reino de Judá, invadiram-no e levaram todos os bens que encontraram no palácio do rei, juntamente com suas mulheres e seus filhos. Só ficou Acazias, o filho mais novo."),  (3464, 14, 21, 18, "Depois disso tudo, o Senhor afligiu Jeorão com uma doença incurável nos intestinos."),  (3465, 14, 21, 19, "Algum tempo depois, ao fim do segundo ano, tanto se agravou a doença que os seus intestinos saíram, e ele morreu sofrendo dores horríveis. Seu povo não fez nenhuma fogueira em sua homenagem, como havia feito para os seus antepassados."),  (3466, 14, 21, 20, "Jeorão tinha trinta e dois anos de idade quando começou a reinar, e reinou oito anos em Jerusalém. Morreu sem que ninguém o lamentasse, e foi sepultado na cidade de Davi, mas não nos túmulos dos reis."),  (3467, 14, 22, 1, "O povo de Jerusalém proclamou Acazias, filho mais novo de Jeorão, rei em seu lugar, uma vez que as tropas que vieram com os árabes haviam matado todos os outros filhos dele. Assim começou a reinar Acazias, filho de Jeorão, rei de Judá."),  (3468, 14, 22, 2, "Acazias tinha vinte e dois anos de idade quando começou a reinar, e reinou um ano em Jerusalém. O nome de sua mãe era Atalia, neta de Onri."),  (3469, 14, 22, 3, "Ele também andou nos caminhos da família de Acabe, pois sua mãe lhe dava maus conselhos."),  (3470, 14, 22, 4, "Ele fez o que o Senhor reprova, como a família de Acabe havia feito, pois, depois da morte de seu pai, eles se tornaram seus conselheiros, para sua ruína."),  (3471, 14, 22, 5, "Ele também seguiu o conselho deles quando aliou-se a Jorão, filho de Acabe, rei de Israel, e saiu à guerra contra Hazael, rei da Síria, em Ramote-Gileade. Jorão foi ferido"),  (3472, 14, 22, 6, "e voltou a Jezreel para recuperar-se dos ferimentos sofridos em Ramote, na batalha contra Hazael, rei da Síria. Depois Acazias, rei de Judá, foi a Jezreel visitar Jorão, que se recuperava de seus ferimentos."),  (3473, 14, 22, 7, "Por meio dessa visita, Deus provocou a queda de Acazias. Quando ele chegou, saiu com Jorão ao encontro de Jeú, filho de Ninsi, a quem o Senhor havia ungido para destruir a família de Acabe."),  (3474, 14, 22, 8, "Quando Jeú estava executando juízo sobre a família de Acabe, encontrou os líderes de Judá e os filhos dos parentes de Acazias, que o serviam, e os matou."),  (3475, 14, 22, 9, "Saiu então em busca de Acazias, e seus soldados o capturaram em Samaria, onde estava escondido. Levado a Jeú, Acazias foi morto. Mas não lhe negaram sepultura, pois disseram: Ele era neto de Josafá, que buscou o Senhor de todo o coração. Assim, a família de Acazias não tinha mais ninguém que pudesse ser rei."),  (3476, 14, 22, 10, "Quando Atalia, mãe de Acazias, soube que seu filho estava morto, mandou matar toda a família real de Judá."),  (3477, 14, 22, 11, "Mas Jeoseba, filha do rei Jeorão, pegou Joás, um dos filhos do rei Acazias que iam ser assassinados, e o colocou num quarto, junto com a sua ama. Assim Jeoseba, filha do rei Jeorão, mulher do sacerdote Joiada e irmã de Acazias, escondeu Joás de Atalia, de forma que ela não pôde matá-lo."),  (3478, 14, 22, 12, "Seis anos ele ficou escondido com elas no templo de Deus, enquanto Atalia governava o país."),  (3479, 14, 23, 1, "No sétimo ano Joiada encorajou-se e fez um acordo com os líderes dos batalhões de cem: Azarias, filho de Jeroão, Ismael, filho de Joanã, Azarias, filho de Obede, Maaséias, filho de Adaías, e Elisafate, filho de Zicri."),  (3480, 14, 23, 2, "Eles percorreram todo o Judá e reuniram de todas as cidades, os levitas e os chefes das famílias israelitas. Quando chegaram a Jerusalém,"),  (3481, 14, 23, 3, "toda a assembléia fez um acordo com o rei no templo de Deus. Joiada lhes disse: Reinará o filho do rei, conforme o Senhor prometeu acerca dos descendentes de Davi."),  (3482, 14, 23, 4, "Vocês vão fazer o seguinte: Um terço de vocês, sacerdotes e levitas que entrarão de serviço no sábado, deverá ficar vigiando nas portas do templo;"),  (3483, 14, 23, 5, "um terço, no palácio real; e um terço, na porta do Alicerce; e todo o povo estará nos pátios do templo do Senhor."),  (3484, 14, 23, 6, "Ninguém deverá entrar no templo do Senhor, exceto os sacerdotes e os levitas de serviço; esses podem entrar porque são consagrados, mas o povo deverá observar o que o Senhor lhes determinou."),  (3485, 14, 23, 7, "Os levitas deverão posicionar-se em torno do rei, todos de armas na mão. Matem todo aquele que entrar no templo. Acompanhem o rei aonde quer que ele for."),  (3486, 14, 23, 8, "Os levitas e todos os homens de Judá fizeram como o sacerdote Joiada havia ordenado. Cada um levou seus soldados, tanto os que estavam entrando de serviço no sábado como os que estavam saindo, pois o sacerdote Joiada não havia dispensado nenhuma das divisões."),  (3487, 14, 23, 9, "Então ele deu aos líderes dos batalhões de cem, as lanças e os escudos grandes e pequenos que haviam pertencido ao rei Davi, e que estavam no templo de Deus."),  (3488, 14, 23, 10, "Posicionou todos os homens, todos de arma na mão, em volta do rei, perto do altar e do templo, desde o lado sul até o lado norte do templo."),  (3489, 14, 23, 11, "Joiada e seus filhos trouxeram o filho do rei e o coroaram; entregaram-lhe uma cópia da aliança e o proclamaram rei, ungindo-o e gritando: Viva o rei! "),  (3490, 14, 23, 12, "Quando Atalia ouviu o barulho do povo correndo e aclamando o rei, foi ao templo do Senhor, onde estava o povo."),  (3491, 14, 23, 13, "Lá ela viu o rei à entrada, de pé junto à coluna. Os oficiais e tocadores de cornetas estavam ao lado do rei, e todo o povo se alegrava ao som das cornetas; os músicos com seus instrumentos musicais dirigiam os louvores. Então Atalia rasgou suas vestes e gritou: Traição! Traição! "),  (3492, 14, 23, 14, "O sacerdote Joiada ordenou aos líderes dos batalhões de cem que estavam no comando das tropas: Levem-na para fora por entre as fileiras, e matem à espada todo que a seguir. Pois o sacerdote dissera: Não a matem no templo do Senhor."),  (3493, 14, 23, 15, "Então eles a prenderam e levaram à porta dos Cavalos, no terreno do palácio, e lá a mataram."),  (3494, 14, 23, 16, "E Joiada fez um acordo pelo qual ele, o povo e o rei seriam o povo do Senhor."),  (3495, 14, 23, 17, "Então todo o povo foi ao templo de Baal e o derrubou. Despedaçaram os altares e os ídolos, e mataram Matã, sacerdote de Baal, em frente dos altares."),  (3496, 14, 23, 18, "E Joiada confiou a supervisão do templo do Senhor aos sacerdotes levitas, aos quais Davi tinha atribuído tarefas no templo, para apresentarem os holocaustos ao Senhor, conforme está escrito na lei de Moisés, com júbilo e cânticos, segundo as instruções de Davi."),  (3497, 14, 23, 19, "Também pôs guardas nas portas do templo do Senhor para que não entrasse ninguém que de alguma forma estivesse impuro."),  (3498, 14, 23, 20, "Levou consigo os líderes dos batalhões de cem, os nobres, os governantes do povo e todo o povo e, juntos, conduziram o rei do templo do Senhor ao palácio, passando pela porta superior, e instalaram o rei no trono;"),  (3499, 14, 23, 21, "e todo o povo se alegrou. A cidade acalmou-se depois que Atalia foi morta à espada."),  (3500, 14, 24, 1, "Joás tinha sete anos de idade quando se tornou rei, e reinou quarenta anos em Jerusalém. O nome de sua mãe era Zíbia; ela era de Berseba."),  (3501, 14, 24, 2, "Joás fez o que o Senhor aprova enquanto viveu o sacerdote Joiada."),  (3502, 14, 24, 3, "Joiada escolheu para ele duas mulheres, e ele teve filhos e filhas."),  (3503, 14, 24, 4, "Algum tempo depois Joás decidiu fazer reparos no templo do Senhor."),  (3504, 14, 24, 5, "Ele reuniu os sacerdotes e os levitas e lhes disse: Vão às cidades de Judá e recolham o imposto devido anualmente por todo o Israel, para fazer reparos no templo de seu Deus. Vão agora mesmo!  Os levitas, porém, não agiram imediatamente."),  (3505, 14, 24, 6, "Por isso, o rei convocou Joiada, o sumo sacerdote, e lhe perguntou: Por que você não exigiu que os levitas trouxessem de Judá e de Jerusalém o imposto determinado por Moisés, servo do Senhor, e pela assembléia de Israel para a tenda da arca da aliança? "),  (3506, 14, 24, 7, "De fato, Atalia, aquela mulher ímpia, e os seus filhos tinham arrombado o templo de Deus e tinham até usado os seus objetos sagrados para cultuar os baalins."),  (3507, 14, 24, 8, "Então, por ordem do rei, fizeram uma caixa e a colocaram do lado de fora, à entrada do templo do Senhor."),  (3508, 14, 24, 9, "Fez-se então uma proclamação em Judá e em Jerusalém para que trouxessem ao Senhor o imposto que Moisés, servo do Senhor, havia exigido de Israel no deserto."),  (3509, 14, 24, 10, "Todos os líderes e todo o povo trouxeram com alegria as suas contribuições, colocando-as na caixa até enchê-la."),  (3510, 14, 24, 11, "Sempre que os levitas levavam a caixa até os supervisores do rei, e esses viam que havia muita prata, o secretário real e o oficial do sumo sacerdote esvaziavam-na e a levavam de volta. Fazendo isso regularmente, ajuntaram uma grande quantidade de prata."),  (3511, 14, 24, 12, "O rei e Joiada entregavam essa prata aos homens que executavam os trabalhos necessários no templo do Senhor. Eles contratavam pedreiros, carpinteiros e também operários que trabalham em ferro e em bronze para restaurarem o templo do Senhor."),  (3512, 14, 24, 13, "Os homens encarregados do trabalho eram diligentes, o que garantiu o progresso da obra de reforma. Eles reconstruíram o templo de Deus de acordo com o modelo original e o reforçaram."),  (3513, 14, 24, 14, "Quando terminaram, trouxeram o restante da prata ao rei e a Joiada, e com ela foram feitos utensílios para o templo do Senhor; utensílios para o serviço e para os holocaustos, além de tigelas e outros objetos de ouro e prata. Enquanto Joiada viveu, holocaustos foram apresentados continuamente no templo do Senhor."),  (3514, 14, 24, 15, "Joiada chegou à idade avançada, e morreu com cento e trinta anos."),  (3515, 14, 24, 16, "Ele foi sepultado com os reis na cidade de Davi, em atenção ao bem que havia feito em Israel em favor de Deus e do seu templo."),  (3516, 14, 24, 17, "Depois da morte de Joiada, os líderes de Judá foram falar com o rei e lhe prestaram reverências, e ele aceitou o que disseram."),  (3517, 14, 24, 18, "Então abandonaram o templo do Senhor, o Deus dos seus antepassados, e prestaram culto aos postes sagrados e aos ídolos. Por culpa deles, a ira de Deus veio sobre Judá e Jerusalém."),  (3518, 14, 24, 19, "Embora o Senhor tivesse enviado profetas ao povo para trazê-los de volta para ele e os profetas tivessem testemunhado contra eles, o povo não quis ouvi-los."),  (3519, 14, 24, 20, "Então o Espírito de Deus apoderou-se de Zacarias, filho do sacerdote Joiada. Ele se colocou diante do povo e disse: Isto é o que Deus diz: ‘Por que vocês desobedecem aos mandamentos do Senhor? Vocês não prosperarão. Já que abandonaram o Senhor, ele os abandonará’ ."),  (3520, 14, 24, 21, "Mas, alguns conspiraram contra ele e, por ordem do rei, apedrejaram-no até à morte no pátio do templo do Senhor."),  (3521, 14, 24, 22, "O rei Joás não levou em conta que Joiada, pai de Zacarias, tinha sido bondoso com ele, e matou o seu filho. Este, ao morrer, exclamou: Veja isto o Senhor e faça justiça! "),  (3522, 14, 24, 23, "Na virada do ano, o exército arameu marchou contra Joás; invadiu Judá e Jerusalém, matou todos os líderes do povo, e enviou para Damasco, para o seu rei, tudo o que saqueou."),  (3523, 14, 24, 24, "Embora o exército arameu fosse pequeno, o Senhor entregou nas mãos dele um exército muito maior, por haver Judá abandonado o Senhor, o Deus dos seus antepassados. Assim o juízo foi executado sobre Joás."),  (3524, 14, 24, 25, "Quando os arameus foram embora, deixaram Joás seriamente ferido. Seus oficiais conspiraram contra ele, porque ele tinha assassinado o filho do sacerdote Joiada, e o mataram em sua cama. Assim ele morreu e foi sepultado na cidade de Davi, mas não nos túmulos dos reis."),  (3525, 14, 24, 26, "Os que conspiraram contra ele foram Zabade, filho da amonita Simeate, e Jeozabade, filho da moabita Sinrite."),  (3526, 14, 24, 27, "Quanto a seus filhos, às muitas profecias a seu respeito e ao relato da restauração do templo, tudo está escrito nas anotações dos livros dos reis. E seu filho Amazias foi o seu sucessor."),  (3527, 14, 25, 1, "Amazias tinha vinte e cinco anos de idade quando começou a reinar, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe era Jeoadã; ela era de Jerusalém."),  (3528, 14, 25, 2, "Ele fez o que o Senhor aprova, mas não de todo o coração."),  (3529, 14, 25, 3, "Quando sentiu que tinha o reino sob pleno controle, mandou executar os oficiais que haviam assassinado o rei, seu pai."),  (3530, 14, 25, 4, "Contudo, não matou os filhos dos assassinos, de acordo com o que está escrito na Lei, no livro de Moisés, onde o Senhor ordenou: Os pais não morrerão no lugar dos filhos, nem os filhos no lugar dos pais; cada um morrerá pelo seu próprio pecado."),  (3531, 14, 25, 5, "Amazias reuniu os homens de Judá e, de acordo com as suas respectivas famílias, nomeou chefes de mil e de cem em todo o Judá e Benjamim. Então convocou todos os de vinte anos para cima e constatou que havia trezentos mil homens prontos para o serviço militar, capazes de empunhar a lança e o escudo."),  (3532, 14, 25, 6, "Também contratou em Israel cem mil homens de combate pelo valor de três toneladas e meia de prata."),  (3533, 14, 25, 7, "Entretanto, um homem de Deus foi até ele e lhe disse: Ó, rei, essas tropas de Israel não devem marchar com você, pois o Senhor não está com Israel; não está com ninguém do povo de Efraim."),  (3534, 14, 25, 8, "Mesmo que vá e combata corajosamente, Deus o derrotará diante do inimigo, pois tem poder para dar a vitória e a derrota."),  (3535, 14, 25, 9, "Amazias perguntou ao homem de Deus: Mas, e as três toneladas e meia de prata que paguei a estas tropas israelitas?  Ele respondeu: O Senhor pode dar-lhe muito mais que isso."),  (3536, 14, 25, 10, "Amazias, mandou então de volta os soldados de Efraim. Eles ficaram furiosos com Judá e foram embora indignados."),  (3537, 14, 25, 11, "Amazias encheu-se de coragem e conduziu o seu exército até o vale do Sal, onde matou dez mil homens de Seir."),  (3538, 14, 25, 12, "Também capturou outros dez mil, que levou para o alto de um penhasco e os atirou de lá, e todos eles se espatifaram."),  (3539, 14, 25, 13, "Enquanto isso, as tropas que Amazias havia mandado de volta não lhes permitindo participar da guerra, atacaram cidades de Judá, desde Samaria até Bete-Horom. Mataram três mil pessoas e levaram grande quantidade de despojos."),  (3540, 14, 25, 14, "Amazias voltou da matança dos edomitas trazendo os deuses do povo de Seir, os quais estabeleceu como seus próprios deuses, inclinou-se diante deles e lhes queimou incenso."),  (3541, 14, 25, 15, "Então a ira do Senhor acendeu-se contra Amazias, e ele lhe enviou um profeta, que disse ao rei: Por que você consulta os deuses desse povo, os quais nem o povo deles puderam salvar de suas mãos? "),  (3542, 14, 25, 16, "Enquanto ele ainda falava, o rei o interrompeu: Por acaso nós o nomeamos conselheiro do rei? Pare! Por que você quer ser morto?  O profeta parou, mas disse: Sei que Deus decidiu destruí-lo, porque você fez tudo isso e não deu atenção ao meu conselho."),  (3543, 14, 25, 17, "Depois de consultar os seus conselheiros, Amazias, rei de Judá, enviou mensageiros a Jeoás, filho de Jeoacaz e neto de Jeú, rei de Israel, com este desafio: Venha me enfrentar."),  (3544, 14, 25, 18, "Contudo, Jeoás, respondeu a Amazias: O espinheiro do Líbano enviou uma mensagem ao cedro do Líbano: ‘Dê sua filha em casamento a meu filho’. Mas um animal selvagem do Líbano veio e pisoteou o espinheiro."),  (3545, 14, 25, 19, "Você diz a si mesmo que derrotou Edom, e agora está arrogante e orgulhoso. Mas fique em casa! Por que provocar uma desgraça que levará você e também Judá à ruína? "),  (3546, 14, 25, 20, "Amazias, porém, não quis ouvi-lo, pois Deus mesmo queria entregar Amazias e seu povo a Jeoás, pois pediram conselhos aos deuses de Edom."),  (3547, 14, 25, 21, "Então Jeoás, rei de Israel, o atacou. Ele e Amazias, rei de Judá, enfrentaram-se em Bete-Semes, em Judá."),  (3548, 14, 25, 22, "Judá foi derrotado por Israel, e seus soldados fugiram para as suas casas."),  (3549, 14, 25, 23, "Jeoás capturou Amazias, filho de Joás e neto de Acazias, em Bete-Semes. Então Jeoás levou-o para Jerusalém e derrubou cento e oitenta metros do muro da cidade, desde a porta de Efraim até a porta da Esquina."),  (3550, 14, 25, 24, "Ele se apoderou de todo o ouro, de toda a prata e de todos os utensílios encontrados no templo de Deus, que haviam estado sob a guarda de Obede-Edom, e ainda dos tesouros do palácio real. Também fez reféns e, então, voltou para Samaria."),  (3551, 14, 25, 25, "Amazias, filho de Joás, rei de Judá, viveu ainda mais quinze anos depois da morte de Jeoás, filho de Jeoacaz, rei de Israel."),  (3552, 14, 25, 26, "Os demais acontecimentos do reinado de Amazias, do início ao fim, estão escritos nos registros históricos dos reis de Judá e de Israel."),  (3553, 14, 25, 27, "A partir do momento em que Amazias deixou de seguir o Senhor, conspiraram contra ele em Jerusalém, e ele fugiu para Láquis, mas o perseguiram até lá e o mataram."),  (3554, 14, 25, 28, "Ele foi trazido de volta a cavalo, e sepultado junto aos seus antepassados na cidade de Judá."),  (3555, 14, 26, 1, "Então todo o povo de Judá proclamou rei a Uzias, de dezesseis anos de idade, no lugar de seu pai, Amazias."),  (3556, 14, 26, 2, "Foi ele quem reconquistou e reconstruiu a cidade de Elate para Judá, depois que Amazias descansou com os seus antepassados."),  (3557, 14, 26, 3, "Uzias tinha dezesseis anos de idade quando se tornou rei, e reinou cinqüenta e dois anos em Jerusalém. Sua mãe era de Jerusalém e chamava-se Jecolias."),  (3558, 14, 26, 4, "Ele fez o que o Senhor aprova, tal como o seu pai Amazias;"),  (3559, 14, 26, 5, "e buscou a Deus durante a vida de Zacarias, que o instruiu no temor de Deus. Enquanto buscou o Senhor, Deus o fez prosperar."),  (3560, 14, 26, 6, "Ele saiu à guerra contra os filisteus e derrubou os muros de Gate, de Jabne e de Asdode. Depois reconstruiu cidades próximo a Asdode e em outros lugares do território filisteu."),  (3561, 14, 26, 7, "Deus o ajudou contra os filisteus, contra os árabes que viviam em Gur-Baal e contra os meunitas."),  (3562, 14, 26, 8, "Os amonitas pagavam tributo a Uzias, e sua fama estendeu-se até a fronteira do Egito, pois havia se tornado muito poderoso."),  (3563, 14, 26, 9, "Uzias construiu torres fortificadas em Jerusalém, na porta da Esquina, na porta do Vale e no canto do muro."),  (3564, 14, 26, 10, "Também construiu torres no deserto e cavou muitas cisternas, pois ele possuía muitos rebanhos na Sefelá e na planície. Ele mantinha trabalhadores em seus campos e em suas vinhas, nas colinas e nas terras férteis, pois gostava da agricultura."),  (3565, 14, 26, 11, "Uzias possuía um exército bem preparado, organizado em divisões de acordo com o número dos soldados convocados pelo secretário Jeiel e pelo oficial Maaséias, sob o comando de Hananias, um dos oficiais do rei."),  (3566, 14, 26, 12, "O total de chefes de família no comando dos homens de combate era de dois mil e seiscentos."),  (3567, 14, 26, 13, "Sob o comando deles estava um exército de trezentos e sete mil e quinhentos homens treinados para a guerra, uma força poderosíssima que apoiava o rei contra os seus inimigos."),  (3568, 14, 26, 14, "Uzias providenciou escudos, lanças, capacetes, couraças, arcos e atiradeiras de pedras para todo o exército."),  (3569, 14, 26, 15, "Em Jerusalém, construiu máquinas projetadas por peritos para serem usadas nas torres e nas defesas das esquinas, máquinas que atiravam flechas e grandes pedras. Ele foi extraordinariamente ajudado, e assim tornou-se muito poderoso e a sua fama espalhou-se para longe."),  (3570, 14, 26, 16, "Entretanto, depois que Uzias se tornou poderoso, o seu orgulho provocou a sua queda. Ele foi infiel ao Senhor, ao seu Deus, e entrou no templo do Senhor para queimar incenso no altar de incenso."),  (3571, 14, 26, 17, "O sumo sacerdote Azarias, e outros oitenta corajosos sacerdotes do Senhor, foram atrás dele."),  (3572, 14, 26, 18, "Eles o enfrentaram e disseram: Não é certo que você, Uzias, queime incenso ao Senhor. Isto é tarefa dos sacerdotes, os descendentes de Arão consagrados para queimar incenso. Saia do santuário, pois você foi infiel e não será honrado por Deus, o Senhor."),  (3573, 14, 26, 19, "Uzias, que estava com um incensário na mão, pronto para queimar o incenso, irritou-se e indignou-se contra os sacerdotes; e na mesma hora, na presença deles, diante do altar de incenso no templo do Senhor, surgiu lepra em sua testa."),  (3574, 14, 26, 20, "Quando o sumo sacerdote Azarias e todos os outros sacerdotes viram a lepra, expulsaram-no imediatamente do templo. Na verdade, ele mesmo ficou ansioso para sair, pois o Senhor o havia ferido."),  (3575, 14, 26, 21, "O rei Uzias sofreu de lepra até o dia em que morreu. Durante todo esse tempo morou numa casa separada, leproso e excluído do templo do Senhor. Seu filho Jotão tomava conta do palácio e governava o povo."),  (3576, 14, 26, 22, "Os demais acontecimentos do reinado de Uzias, do início ao fim, foram registrados pelo profeta Isaías, filho de Amoz."),  (3577, 14, 26, 23, "Uzias descansou com os seus antepassados e foi sepultado perto deles, num cemitério que pertencia aos reis, pois o povo dizia: Ele tinha lepra. Seu filho Jotão foi o seu sucessor."),  (3578, 14, 27, 1, "Jotão tinha vinte e cinco anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém. O nome da sua mãe era Jerusa, filha de Zadoque."),  (3579, 14, 27, 2, "Ele fez o que o Senhor aprova, tal como seu pai, mas, ao contrário deste, não entrou no templo do Senhor. O povo, contudo, prosseguiu em suas práticas corruptas."),  (3580, 14, 27, 3, "Jotão reconstruiu a porta superior do templo do Senhor e fez amplos trabalhos no muro, na colina de Ofel."),  (3581, 14, 27, 4, "Construiu cidades nos montes de Judá, bem como fortes e torres nas matas."),  (3582, 14, 27, 5, "Jotão guerreou contra o rei dos amonitas e o derrotou. Então os amonitas pagaram-lhe três toneladas e meia de prata, dez mil barris de trigo e dez mil de cevada durante três anos seguidos."),  (3583, 14, 27, 6, "Jotão tornou-se cada vez mais poderoso, pois andava firmemente segundo a vontade do Senhor, o seu Deus."),  (3584, 14, 27, 7, "Os demais acontecimentos do reinado de Jotão, inclusive todas as suas guerras e as suas outras realizações, estão escritos nos registros históricos dos reis de Israel e de Judá."),  (3585, 14, 27, 8, "Tinha vinte e cinco anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém."),  (3586, 14, 27, 9, "Jotão descansou com os seus antepassados e foi sepultado na cidade de Davi. Seu filho Acaz foi o seu sucessor."),  (3587, 14, 28, 1, "Acaz tinha vinte anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém. Ao contrário de Davi, seu predecessor, não fez o que o Senhor aprova."),  (3588, 14, 28, 2, "Ele andou nos caminhos dos reis de Israel e fez ídolos de metal para adorar os baalins."),  (3589, 14, 28, 3, "Queimou sacrifícios no vale de Ben-Hinom e chegou até a queimar seus filhos em sacrifício, imitando os costumes detestáveis das nações que o Senhor havia expulsado de diante dos israelitas."),  (3590, 14, 28, 4, "Também ofereceu sacrifícios e queimou incenso nos altares idólatras, no alto das colinas e debaixo de toda árvore frondosa."),  (3591, 14, 28, 5, "Por isso o Senhor, o seu Deus, entregou-o nas mãos do rei da Síria. Os arameus o derrotaram, fizeram muitos prisioneiros entre o seu povo e os levaram para Damasco. Israel também lhe infligiu grande derrota."),  (3592, 14, 28, 6, "Num único dia, Peca, filho de Remalias, matou cento e vinte mil soldados corajosos de Judá; pois Judá havia abandonado o Senhor, o Deus dos seus antepassados."),  (3593, 14, 28, 7, "Zicri, guerreiro efraimita, matou Maaséias, filho do rei, Azricão, oficial encarregado do palácio, e Elcana, o braço direito do rei."),  (3594, 14, 28, 8, "Os israelitas levaram para Samaria duzentos mil prisioneiros dentre os seus parentes, incluindo mulheres, meninos e meninas. Também levaram muitos despojos."),  (3595, 14, 28, 9, "Mas um profeta do Senhor, chamado Odede, estava em Samaria e saiu ao encontro do exército. Ele lhes disse: Estando irado contra Judá, o Senhor, o Deus dos seus antepassados, entregou-os nas mãos de vocês. Mas a fúria com que vocês os mataram chegou aos céus."),  (3596, 14, 28, 10, "E agora ainda pretendem escravizar homens e mulheres de Judá e de Jerusalém. Vocês também não são culpados de pecados contra o Senhor, o seu Deus?"),  (3597, 14, 28, 11, "Agora, ouçam-me! Mandem de volta seus irmãos que vocês fizeram prisioneiros, pois o fogo da ira do Senhor está sobre vocês."),  (3598, 14, 28, 12, "Então Azarias, filho de Joanã, Berequias, filho de Mesilemote, Jeizquias, filho de Salum, e Amasa, filho de Hadlai, que eram alguns dos chefes de Efraim, questionaram os que estavam chegando da guerra, dizendo:"),  (3599, 14, 28, 13, "Não tragam os prisioneiros para cá. Caso contrário seremos culpados diante do Senhor. Vocês querem aumentar ainda mais o nosso pecado e a nossa culpa? A nossa culpa já é grande, e o fogo da sua ira está sobre Israel."),  (3600, 14, 28, 14, "Então os soldados libertaram os prisioneiros e colocaram os despojos na presença dos líderes e de toda a assembléia."),  (3601, 14, 28, 15, "Os homens citados nominalmente apanharam os prisioneiros e com as roupas e as sandálias dos despojos vestiram todos os que estavam nus. Deram-lhes comida, bebida, e bálsamo medicinal. Puseram sobre jumentos todos aqueles que estavam fracos. Assim os levaram de volta a seus patrícios residentes em Jericó, a cidade das Palmeiras, e voltaram para Samaria."),  (3602, 14, 28, 16, "Nessa época, o rei Acaz enviou mensageiros ao rei da Assíria para pedir-lhe ajuda."),  (3603, 14, 28, 17, "Os edomitas tinham voltado a atacar Judá fazendo prisioneiros,"),  (3604, 14, 28, 18, "e os filisteus atacaram cidades na Sefelá e no sul de Judá. Conquistaram e ocuparam Bete-Semes, Aijalom e Gederote, bem como Socó, Timna e Ginzo, com os seus povoados ao redor."),  (3605, 14, 28, 19, "O Senhor humilhou Judá por causa de Acaz, rei de Israel, por sua conduta desregrada em Judá, muito infiel ao Senhor."),  (3606, 14, 28, 20, "Quando chegou Tiglate-Pileser, rei da Assíria, causou-lhe problemas em vez de ajudá-lo."),  (3607, 14, 28, 21, "Acaz apanhou algumas coisas do templo do Senhor, do palácio real e dos líderes e ofereceu-as ao rei da Assíria, mas isso não adiantou."),  (3608, 14, 28, 22, "Mesmo nessa época em que passou por tantas dificuldades, o rei Acaz tornou-se ainda mais infiel ao Senhor."),  (3609, 14, 28, 23, "Ele ofereceu sacrifícios aos deuses de Damasco que o haviam derrotado, pois pensava: Já que os deuses da Síria os têm ajudado, oferecerei sacrifícios a eles para que me ajudem também. Mas eles foram a causa da sua ruína e da ruína de todo o Israel."),  (3610, 14, 28, 24, "Acaz juntou os utensílios do templo de Deus e os retirou de lá. Trancou as portas do templo do Senhor e ergueu altares em todas as esquinas de Jerusalém."),  (3611, 14, 28, 25, "Em todas as cidades de Judá construiu altares idólatras para queimar sacrifícios a outros deuses e provocou a ira do Senhor, o Deus dos seus antepassados."),  (3612, 14, 28, 26, "Os demais acontecimentos de seu reinado e todos os seus atos, do início ao fim, estão escritos nos registros históricos dos reis de Judá e de Israel."),  (3613, 14, 28, 27, "Acaz descansou com os seus antepassados e foi sepultado na cidade de Jerusalém, mas não nos túmulos dos reis de Israel. Seu filho Ezequias foi o seu sucessor."),  (3614, 14, 29, 1, "Ezequias tinha vinte e cinco anos de idade quando começou a reinar, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe era Abia, filha de Zacarias."),  (3615, 14, 29, 2, "Ele fez o que o Senhor aprova, tal como tinha feito Davi, seu predecessor."),  (3616, 14, 29, 3, "No primeiro mês do primeiro ano de seu reinado, ele reabriu as portas do templo do Senhor e as consertou."),  (3617, 14, 29, 4, "Convocou os sacerdotes e os levitas, reuniu-os na praça que fica no lado leste"),  (3618, 14, 29, 5, "e disse: Escutem-me, levitas! Consagrem-se agora e consagrem o templo do Senhor, o Deus dos seus antepassados. Retirem tudo o que é impuro do santuário."),  (3619, 14, 29, 6, "Nossos pais foram infiéis; fizeram o que o Senhor, o nosso Deus, reprova e o abandonaram. Desviaram o rosto do local da habitação do Senhor e deram-lhe as costas."),  (3620, 14, 29, 7, "Também fecharam as portas do pórtico e apagaram as lâmpadas. Não queimaram incenso nem apresentaram holocausto no santuário para o Deus de Israel."),  (3621, 14, 29, 8, "Por isso, a ira do Senhor caiu sobre Judá e sobre Jerusalém; e ele fez deles objeto de espanto, horror e zombaria, conforme vocês podem ver com os seus próprios olhos."),  (3622, 14, 29, 9, "Por isso os nossos pais caíram à espada e os nossos filhos, as nossas filhas e as nossas mulheres foram levadas como prisioneiras."),  (3623, 14, 29, 10, "Pretendo, pois, agora fazer uma aliança com o Senhor, o Deus de Israel, para que o fogo da sua ira se afaste de nós."),  (3624, 14, 29, 11, "Meus filhos, não sejam negligentes agora, pois o Senhor os escolheu para estarem diante dele e o servirem, para ministrarem perante ele e queimarem incenso."),  (3625, 14, 29, 12, "Então estes levitas puseram-se a trabalhar: dentre os descendentes de Coate: Maate, filho de Amasai, e Joel, filho de Azarias; dentre os descendentes de Merari: Quis, filho de Abdi, e Azarias, filho de Jealelel; dentre os descendentes de Gérson: Joá, filho de Zima, e Éden, filho de Joá;"),  (3626, 14, 29, 13, "dentre os descendentes de Elisafã: Sinri e Jeuel; dentre os descendentes de Asafe: Zacarias e Matanias;"),  (3627, 14, 29, 14, "dentre os descendentes de Hemã: Jeuel e Simei; dentre os descendentes de Jedutum: Semaías e Uziel."),  (3628, 14, 29, 15, "Tendo reunido e consagrado os seus parentes, os levitas foram purificar o templo do Senhor, conforme o rei havia ordenado em obediência à palavra do Senhor."),  (3629, 14, 29, 16, "Os sacerdotes entraram no santuário do Senhor para purificá-lo e trouxeram para o pátio do templo do Senhor todas as coisas impuras que lá havia, e os levitas as levaram para o vale de Cedrom."),  (3630, 14, 29, 17, "Começaram a consagração no dia primeiro do primeiro mês, e no oitavo dia chegaram ao pórtico do Senhor. Durante mais oito dias consagraram o templo do Senhor propriamente dito, terminando tudo no dia dezesseis."),  (3631, 14, 29, 18, "Depois foram falar com o rei Ezequias e lhe relataram: Purificamos todo o templo do Senhor, o altar dos holocaustos e a mesa do pão consagrado, ambos com todos seus utensílios."),  (3632, 14, 29, 19, "Preparamos e consagramos todos os utensílios que o rei Acaz, em sua infidelidade, retirou durante o seu reinado. Eles estão em frente do altar do Senhor."),  (3633, 14, 29, 20, "Cedo, na manhã seguinte, o rei Ezequias reuniu os líderes da cidade e, juntos, subiram ao templo do Senhor,"),  (3634, 14, 29, 21, "levando sete novilhos, sete carneiros, sete cordeiros e sete bodes como oferta pelo pecado, em favor da realeza, do santuário e de Judá. O rei ordenou que os sacerdotes, descendentes de Arão, sacrificassem os animais no altar do Senhor."),  (3635, 14, 29, 22, "Então os sacerdotes abateram os novilhos e aspergiram o sangue sobre o altar; em seguida fizeram o mesmo com os carneiros e com os cordeiros."),  (3636, 14, 29, 23, "Depois, os bodes para a oferta pelo pecado foram levados para diante do rei e da assembléia, que impuseram as mãos sobre eles."),  (3637, 14, 29, 24, "Os sacerdotes abateram os bodes e apresentaram o sangue sobre o altar como oferta pelo pecado, para fazer propiciação por todo o Israel, pois era em favor de todo o Israel que o rei havia ordenado o holocausto e a oferta pelo pecado."),  (3638, 14, 29, 25, "O rei posicionou os levitas no templo do Senhor, com címbalos, liras e harpas, segundo a prescrição de Davi, de Gade, vidente do rei, e do profeta Natã; isso foi ordenado pelo Senhor, por meio de seus profetas."),  (3639, 14, 29, 26, "Assim os levitas ficaram em pé, preparados com os instrumentos de Davi, e os sacerdotes com as cornetas."),  (3640, 14, 29, 27, "Então Ezequias ordenou que sacrificassem o holocausto sobre o altar. Iniciado o sacrifício, começou também o canto ao Senhor, ao som das cornetas e dos instrumentos de Davi, rei de Israel."),  (3641, 14, 29, 28, "Toda a assembléia prostrou-se em adoração, enquanto os músicos cantavam e os corneteiros tocavam, até que terminou o holocausto."),  (3642, 14, 29, 29, "Então o rei e todos os presentes ajoelharam-se e adoraram."),  (3643, 14, 29, 30, "O rei Ezequias e seus oficiais ordenaram aos levitas que louvassem o Senhor com as palavras de Davi e do vidente Asafe. Eles louvaram com alegria, depois inclinaram suas cabeças e adoraram."),  (3644, 14, 29, 31, "Disse então Ezequias: Agora que vocês se dedicaram ao Senhor, tragam sacrifícios e ofertas de gratidão ao templo do Senhor. Assim, a comunidade levou sacrifícios e ofertas de gratidão, e alguns, espontaneamente, levaram também holocaustos."),  (3645, 14, 29, 32, "Esses holocaustos que a assembléia ofertou ao Senhor foram setenta bois, cem carneiros e duzentos cordeiros."),  (3646, 14, 29, 33, "Os animais consagrados como sacrifícios chegaram a seiscentos bois e três mil ovelhas e bodes."),  (3647, 14, 29, 34, "Como os sacerdotes eram muito poucos para tirar a pele de todos os holocaustos, os seus parentes, os levitas, os ajudaram até o fim da tarefa e até que outros sacerdotes se consagrassem, pois os levitas demoraram menos para se consagrarem do que os sacerdotes."),  (3648, 14, 29, 35, "Houve holocaustos em grande quantidade, oferecidos com a gordura das ofertas de comunhão e com as ofertas derramadas que acompanhavam esses holocaustos. Assim foi restabelecido o culto no templo do Senhor."),  (3649, 14, 29, 36, "Ezequias e todo o povo regozijavam-se com o que Deus havia feito por seu povo, e tudo em tão pouco tempo."),  (3650, 14, 30, 1, "Ezequias enviou uma mensagem a todo o Israel e Judá e também escreveu cartas a Efraim e a Manassés, convidando-os para ir ao templo do Senhor em Jerusalém e celebrar a Páscoa do Senhor, o Deus de Israel."),  (3651, 14, 30, 2, "O rei, seus oficiais e toda a comunidade de Jerusalém decidiram celebrar a Páscoa no segundo mês."),  (3652, 14, 30, 3, "Não tinha sido possível celebrá-la na data prescrita, pois não havia número suficiente de sacerdotes consagrados, e o povo não estava reunido em Jerusalém."),  (3653, 14, 30, 4, "A idéia pareceu boa tanto ao rei quanto a toda a assembléia."),  (3654, 14, 30, 5, "Então decidiram fazer uma proclamação em todo o Israel, desde Berseba até Dã, convocando o povo a Jerusalém para celebrar a Páscoa do Senhor, o Deus de Israel. Pois muitos não a celebravam segundo o que estava escrito."),  (3655, 14, 30, 6, "Por ordem do rei, mensageiros percorreram Israel e Judá com cartas assinadas pelo rei e pelos seus oficiais, com a seguinte mensagem: Israelitas, voltem para o Senhor, o Deus de Abraão, de Isaque e de Israel, para que ele se volte para vocês que restaram e escaparam das mãos dos reis da Assíria."),  (3656, 14, 30, 7, "Não sejam como seus pais e seus irmãos, que foram infiéis ao Senhor, o Deus dos seus antepassados, de maneira que ele os deixou em ruínas, conforme vocês vêem."),  (3657, 14, 30, 8, "Portanto não sejam obstinados como seus antepassados; submetam-se ao Senhor. Venham ao santuário que ele consagrou para sempre. Sirvam ao Senhor, ao seu Deus, para que o fogo da sua ira se desvie de vocês."),  (3658, 14, 30, 9, "Se vocês voltarem para o Senhor, os que capturaram os seus irmãos e os seus filhos terão misericórdia deles, e eles voltarão a esta terra, pois o Senhor, o seu Deus, é bondoso e compassivo. Ele não os rejeitará, se vocês se voltarem para ele."),  (3659, 14, 30, 10, "Os mensageiros foram de cidade em cidade, em Efraim e em Manassés, e até em Zebulom, mas o povo zombou deles e os expôs ao ridículo."),  (3660, 14, 30, 11, "No entanto, alguns homens de Aser, de Manassés e de Zebulom humilharam-se e foram para Jerusalém."),  (3661, 14, 30, 12, "Já em Judá a mão de Deus esteve sobre o povo dando-lhes unidade de pensamento para executarem o que o rei e os seus oficiais haviam ordenado, conforme a palavra do Senhor."),  (3662, 14, 30, 13, "Uma imensa multidão reuniu-se em Jerusalém no segundo mês, para celebrar a festa dos pães sem fermento."),  (3663, 14, 30, 14, "Eles retiraram os altares que havia em Jerusalém e se desfizeram de todos os altares de incenso, atirando-os no vale de Cedrom."),  (3664, 14, 30, 15, "Abateram o cordeiro da Páscoa no dia catorze do segundo mês. Os sacerdotes e os levitas, envergonhados, consagraram-se e levaram holocaustos ao templo do Senhor."),  (3665, 14, 30, 16, "E assumiram seus postos, conforme prescrito na Lei de Moisés, homem de Deus. Os sacerdotes aspergiram o sangue que os levitas lhes entregaram."),  (3666, 14, 30, 17, "Visto que muitos na multidão não haviam se consagrado, os levitas tiveram que matar cordeiros da Páscoa para todos os que não estavam cerimonialmente puros e que por isso não podiam consagrar os seus cordeiros ao Senhor."),  (3667, 14, 30, 18, "Embora muitos dos que vieram de Efraim, de Manassés, de Issacar e de Zebulom não se tivessem purificado, assim mesmo comeram a Páscoa, contrariando o que estava escrito. Mas Ezequias orou por eles, dizendo: Queira o Senhor, que é bondoso, perdoar todo"),  (3668, 14, 30, 19, "aquele que inclina o seu coração para buscar a Deus, o Senhor, o Deus dos seus antepassados, mesmo que não esteja puro de acordo com as regras do santuário."),  (3669, 14, 30, 20, "E o Senhor ouviu a oração de Ezequias e não castigou o povo."),  (3670, 14, 30, 21, "Os israelitas presentes em Jerusalém celebraram com muita alegria a festa dos pães sem fermento durante sete dias. Diariamente os levitas e os sacerdotes cantavam louvores, ao som dos instrumentos ressonantes do Senhor."),  (3671, 14, 30, 22, "Ezequias dirigiu palavras animadoras a todos os levitas, que mostraram boa disposição para com o serviço do Senhor. Durante os sete dias eles comeram suas porções das ofertas, apresentaram sacrifícios de comunhão e louvaram o Senhor, o Deus dos seus antepassados."),  (3672, 14, 30, 23, "E toda a assembléia decidiu prolongar a festa por mais sete dias, e a celebraram com alegria."),  (3673, 14, 30, 24, "Ezequias, rei de Judá, forneceu mil novilhos e sete mil ovelhas e bodes para a assembléia, e os líderes, mil novilhos e dez mil ovelhas e bodes. Muitos sacerdotes se consagraram,"),  (3674, 14, 30, 25, "e toda a assembléia de Judá se regozijava, juntamente com os sacerdotes, com os levitas e com todos os que se haviam reunido, vindos de Israel, inclusive os estrangeiros que viviam em Israel e em Judá."),  (3675, 14, 30, 26, "Houve grande alegria em Jerusalém, pois desde os dias de Salomão, filho de Davi, rei de Israel, não havia acontecido algo assim na cidade."),  (3676, 14, 30, 27, "Os sacerdotes e os levitas levantaram-se para abençoar o povo, e Deus os ouviu; a oração deles chegou aos céus, sua santa habitação."),  (3677, 14, 31, 1, "Quando a festa acabou, os israelitas saíram pelas cidades de Judá e despedaçaram as pedras sagradas e derrubaram os postes sagrados. Eles destruíram os altares idólatras em todo o Judá e Benjamim, e em Efraim e Manassés. Depois de destruírem tudo, voltaram para as suas cidades, cada um para a sua propriedade."),  (3678, 14, 31, 2, "Ezequias designou os sacerdotes e os levitas por turnos, cada um de acordo com os seus deveres, para apresentarem holocaustos e sacrifícios de comunhão, ministrarem, darem graças e cantarem louvores junto às portas da habitação do Senhor."),  (3679, 14, 31, 3, "O rei contribuía com seus próprios bens para os holocaustos da manhã e da tarde e para os holocaustos dos sábados, das Luas Novas e das festas fixas, conforme o que está escrito na Lei do Senhor."),  (3680, 14, 31, 4, "Ele ordenou ao povo de Jerusalém que desse aos sacerdotes e aos levitas a porção que lhes era devida a fim de que pudessem dedicar-se à Lei do Senhor."),  (3681, 14, 31, 5, "Assim que se divulgou essa ordem, os israelitas deram com generosidade o melhor do trigo, do vinho, do óleo, do mel e de tudo o que os campos produziam. Trouxeram o dízimo de tudo. Era uma grande quantidade."),  (3682, 14, 31, 6, "Os habitantes de Israel e de Judá que viviam nas cidades de Judá também levaram o dízimo de todos os seus rebanhos e das coisas sagradas dedicadas ao Senhor, o seu Deus, ajuntando-os em muitas pilhas."),  (3683, 14, 31, 7, "Começaram a fazer isso no terceiro mês e terminaram no sétimo."),  (3684, 14, 31, 8, "Quando Ezequias e os seus oficiais chegaram e viram as pilhas de ofertas, louvaram o Senhor e abençoaram Israel, o seu povo."),  (3685, 14, 31, 9, "Ezequias perguntou aos sacerdotes e aos levitas sobre essas ofertas;"),  (3686, 14, 31, 10, "o sumo sacerdote Azarias, da família de Zadoque, respondeu: Desde que o povo começou a trazer suas contribuições ao templo do Senhor, temos tido o suficiente para comer e ainda tem sobrado muito, pois o Senhor tem abençoado o seu povo, e esta é a grande quantidade que sobra."),  (3687, 14, 31, 11, "Ezequias ordenou que preparassem despensas no templo do Senhor, e assim foi feito."),  (3688, 14, 31, 12, "Então recolheram fielmente as contribuições, os dízimos e os presentes dedicados. O levita Conanias foi encarregado dessas coisas, e seu irmão Simei era o seu auxiliar."),  (3689, 14, 31, 13, "Jeiel, Azazias, Naate, Asael, Jeremote, Jozabade, Eliel, Ismaquias, Maate e Benaia eram supervisores, subordinados a Conanias e ao seu irmão Simei, por nomeação do rei Ezequias e de Azarias, o oficial encarregado do templo de Deus."),  (3690, 14, 31, 14, "Coré, filho do levita Imna, guarda da porta leste, foi encarregado das ofertas voluntárias feitas a Deus, distribuindo as contribuições dedicadas ao Senhor e as ofertas consagradas."),  (3691, 14, 31, 15, "Sob o comando dele estavam Éden, Miniamim, Jesua, Semaías, Amarias e Secanias, que, nas cidades dos sacerdotes, com toda a fidelidade distribuíam ofertas aos seus colegas sacerdotes de acordo com seus turnos, tanto aos idosos quanto aos jovens."),  (3692, 14, 31, 16, "Eles as distribuíram aos homens e aos meninos de três anos para cima, cujos nomes estavam nos registros genealógicos, também a todos os que entravam no templo do Senhor para realizar suas várias tarefas diárias, de acordo com suas responsabilidades e seus turnos."),  (3693, 14, 31, 17, "Os registros genealógicos dos sacerdotes eram feitos segundo suas famílias, o dos levitas de vinte anos para cima, de acordo com suas responsabilidades e seus turnos."),  (3694, 14, 31, 18, "O registro incluía todos os filhos pequenos, as mulheres, e os filhos e filhas de todo o grupo, pois os sacerdotes e os levitas haviam sido fiéis em se consagrarem."),  (3695, 14, 31, 19, "Entre os sacerdotes, descendentes de Arão, que viviam nas terras de pastagem ao redor de suas cidades, foram nomeados alguns deles, de cidade em cidade, para distribuírem as ofertas a todos os sacerdotes e a todos os que estavam registrados nas genealogias dos levitas."),  (3696, 14, 31, 20, "Foi isso que Ezequias fez em todo o reino de Judá. Ele fez o que era bom e certo, e em tudo foi fiel diante do Senhor, do seu Deus."),  (3697, 14, 31, 21, "Em tudo o que ele empreendeu no serviço do templo de Deus e na obediência à lei e aos mandamentos, ele buscou o seu Deus e trabalhou de todo o coração; e por isso prosperou."),  (3698, 14, 32, 1, "Depois de tudo o que Ezequias fez com tanta fidelidade, Senaqueribe, rei da Assíria, invadiu Judá. Ele sitiou as cidades fortificadas para conquistá-las."),  (3699, 14, 32, 2, "Quando Ezequias viu que Senaqueribe pretendia guerrear contra Jerusalém,"),  (3700, 14, 32, 3, "consultou os seus oficiais e os comandantes do exército sobre a idéia de mandar fechar a passagem de água das fontes do lado de fora da cidade; e eles concordaram."),  (3701, 14, 32, 4, "Assim, ajuntaram-se muitos homens, e fecharam todas as fontes e o riacho que atravessava a região. Eles diziam: Por que deixar que os reis da Assíria venham e encontrem toda essa água? "),  (3702, 14, 32, 5, "Depois, com grande empenho consertou todos os trechos quebrados do muro e construiu torres sobre ele. Construiu outro muro do lado de fora do primeiro e reforçou os muros de arrimo da cidade de Davi; e mandou fazer também muitas lanças e muitos escudos."),  (3703, 14, 32, 6, "Nomeou sobre o povo oficiais militares e os reuniu na praça, junto à porta da cidade, animando-os com estas palavras:"),  (3704, 14, 32, 7, "Sejam fortes e corajosos. Não tenham medo nem se desanimem por causa do rei da Assíria e do enorme exército que está com ele, pois conosco está um poder maior do que o que está com ele."),  (3705, 14, 32, 8, "Com ele está somente o poder humano, mas conosco está o Senhor, o nosso Deus, para nos ajudar e para travar as nossas batalhas. E o povo ganhou confiança com o que disse Ezequias, rei de Judá."),  (3706, 14, 32, 9, "Mais tarde, quando Senaqueribe, rei da Assíria, e todas as suas forças estavam sitiando Láquis, mandou oficiais a Jerusalém com a seguinte mensagem a Ezequias e a todo o povo de Judá que morava lá:"),  (3707, 14, 32, 10, "Assim diz Senaqueribe, rei da Assíria: Em que vocês baseiam a sua confiança, para permanecerem cercados em Jerusalém?"),  (3708, 14, 32, 11, "Quando Ezequias diz: ‘O Senhor, o nosso Deus, nos salvará das mãos do rei da Assíria’, ele os está enganando, para deixá-los morrer de fome e de sede."),  (3709, 14, 32, 12, "Mas não foi o próprio Ezequias que retirou os altares desse deus, dizendo a Judá e a Jerusalém: ‘Vocês devem adorar diante de um só altar e sobre ele queimar incenso’? "),  (3710, 14, 32, 13, "Vocês não sabem o que eu e os meus antepassados fizemos a todos os povos das outras terras? Acaso alguma vez os deuses daquelas nações conseguiram livrar das minhas mãos a terra deles?"),  (3711, 14, 32, 14, "De todos os deuses das nações que os meus antepassados destruíram, qual deles conseguiu salvar o seu povo de mim? Como então o deus de vocês poderá livrá-los das minhas mãos?"),  (3712, 14, 32, 15, "Portanto, não deixem Ezequias enganá-los ou iludi-los dessa maneira. Não acreditem nele, pois nenhum deus de qualquer nação ou reino jamais conseguiu livrar o seu povo das minhas mãos ou das mãos de meus antepassados. Muito menos o deus de vocês conseguirá livrá-los das minhas mãos! "),  (3713, 14, 32, 16, "Os oficiais de Senaqueribe desafiaram ainda mais a Deus, ao Senhor, e ao seu servo Ezequias."),  (3714, 14, 32, 17, "Senaqueribe também escreveu cartas insultando o Senhor, o Deus de Israel, e o desafiando: Assim como os deuses dos povos das outras terras não livraram o povo deles das minhas mãos, também o deus de Ezequias não livrará o seu povo das minhas mãos."),  (3715, 14, 32, 18, "Então os oficiais gritaram na língua dos judeus ao povo de Jerusalém que estava sobre o muro, para assustá-lo e amedrontá-lo, com o intuito de conquistarem a cidade."),  (3716, 14, 32, 19, "Referiram-se ao Deus de Jerusalém como falavam dos deuses dos outros povos da terra, que não passam de obra das mãos dos homens."),  (3717, 14, 32, 20, "Por tudo isso o rei Ezequias e o profeta Isaías, filho de Amoz, clamaram em oração aos céus."),  (3718, 14, 32, 21, "E o Senhor enviou um anjo, que matou todos os homens de combate e todos os líderes e oficiais no acampamento do rei assírio, de forma que este se retirou envergonhado para a sua terra. E certo dia, ao adentrar o templo do seu deus, alguns dos seus filhos o mataram à espada."),  (3719, 14, 32, 22, "Assim o Senhor salvou Ezequias e o povo de Jerusalém das mãos de Senaqueribe, rei da Assíria, e das mãos de todos os outros; e cuidou deles em todas as fronteiras."),  (3720, 14, 32, 23, "Muitos levaram a Jerusalém ofertas para o Senhor e presentes valiosos para Ezequias, rei de Judá. Daquela ocasião em diante ele foi muito respeitado por todas as nações."),  (3721, 14, 32, 24, "Naquele tempo Ezequias ficou doente, e quase morreu. Ele orou ao Senhor, que lhe respondeu dando-lhe um sinal miraculoso."),  (3722, 14, 32, 25, "Mas Ezequias tornou-se orgulhoso, e não correspondeu à bondade com que foi tratado; por isso a ira do Senhor veio sobre ele, sobre Judá e sobre Jerusalém."),  (3723, 14, 32, 26, "Então Ezequias humilhou-se reconhecendo o seu orgulho, como também o povo de Jerusalém; por isso a ira do Senhor não veio sobre eles durante o reinado de Ezequias."),  (3724, 14, 32, 27, "Possuía Ezequias muitíssimas riquezas e glória; construiu depósitos para guardar prata, ouro, pedras preciosas, especiarias, escudos e todo tipo de objetos de valor."),  (3725, 14, 32, 28, "Também construiu armazéns para estocar trigo, vinho e azeite; fez ainda estábulos para os seus diversos rebanhos e para as ovelhas."),  (3726, 14, 32, 29, "Construiu cidades e adquiriu muitos rebanhos, pois Deus lhe dera muitas riquezas."),  (3727, 14, 32, 30, "Foi Ezequias que bloqueou o manancial superior da fonte de Giom e, canalizou a água para a parte oeste da cidade de Davi. Ele foi bem sucedido em tudo o que se propôs a fazer."),  (3728, 14, 32, 31, "Mas, quando os governantes da Babilônia enviaram uma delegação para perguntar-lhe acerca do sinal miraculoso que havia ocorrido no país, Deus o deixou, para prová-lo e para saber tudo o que havia em seu coração."),  (3729, 14, 32, 32, "Os demais acontecimentos do reinado de Ezequias e os seus atos piedosos, estão escritos na visão do profeta Isaías, filho de Amoz, no livro dos reis de Judá e de Israel."),  (3730, 14, 32, 33, "Ezequias descansou com os seus antepassados e foi sepultado na colina onde estão os túmulos dos descendentes de Davi. Todo o Judá e o povo de Jerusalém prestaram-lhe homenagens por ocasião da sua morte. E o seu filho Manassés foi o seu sucessor."),  (3731, 14, 33, 1, "Manassés tinha doze anos de idade quando começou a reinar, e reinou cinqüenta e cinco anos em Jerusalém."),  (3732, 14, 33, 2, "Ele fez o que o Senhor reprova, imitando as práticas detestáveis das nações que o Senhor havia expulsado de diante dos israelitas."),  (3733, 14, 33, 3, "Reconstruiu os altares idólatras que seu pai Ezequias havia demolido; também ergueu altares para os baalins e fez postes sagrados. Inclinou-se diante de todos os exércitos celestes e lhes prestou culto."),  (3734, 14, 33, 4, "Construiu altares no templo do Senhor, do qual o Senhor tinha dito: Meu nome permanecerá para sempre em Jerusalém."),  (3735, 14, 33, 5, "Nos dois pátios do templo do Senhor ele construiu altares para todos os exércitos celestes."),  (3736, 14, 33, 6, "Chegou a queimar seus filhos em sacrifício, no vale de Ben-Hinom; praticou feitiçaria, adivinhação e magia, e consultou médiuns e espíritas. Fez o que o Senhor reprova, provocando-o à ira."),  (3737, 14, 33, 7, "Ele tomou a imagem esculpida que havia feito e a colocou no templo, do qual Deus tinha dito a Davi e a seu filho Salomão: Neste templo e em Jerusalém, que escolhi dentre todas as tribos de Israel, porei meu nome para sempre."),  (3738, 14, 33, 8, "Não farei os pés dos israelitas deixarem novamente a terra que dei aos seus antepassados, se tão-somente tiverem o cuidado de fazer tudo o que lhes ordenei em todas as leis, os decretos e as ordenanças dados por meio de Moisés."),  (3739, 14, 33, 9, "Manassés, porém, desencaminhou Judá e o povo de Jerusalém, a ponto de fazerem pior do que as nações que o Senhor havia destruído diante dos israelitas."),  (3740, 14, 33, 10, "O Senhor falou a Manassés e a seu povo, mas não lhe deram atenção."),  (3741, 14, 33, 11, "Por isso o Senhor enviou contra eles os comandantes do exército do rei da Assíria, os quais prenderam Manassés, colocaram-lhe um gancho no nariz e algemas de bronze, e o levaram para a Babilônia."),  (3742, 14, 33, 12, "Em sua angústia, ele buscou o favor do Senhor, o seu Deus, e humilhou-se muito diante do Deus dos seus antepassados."),  (3743, 14, 33, 13, "Quando ele orou, o Senhor o ouviu e atendeu o seu pedido; de forma que o trouxe de volta a Jerusalém e a seu reino. E assim Manassés reconheceu que o Senhor é Deus."),  (3744, 14, 33, 14, "Depois disso ele reconstruiu e aumentou a altura do muro externo da cidade de Davi, a oeste da fonte de Giom, no vale, até a entrada da porta do Peixe, em torno da colina de Ofel. Também pôs comandantes militares em todas as cidades fortificadas de Judá."),  (3745, 14, 33, 15, "Manassés tirou do templo do Senhor os deuses estrangeiros e a imagem que lá havia colocado, bem como todos os altares idólatras que havia construído na colina do templo e em Jerusalém; e jogou-os fora da cidade."),  (3746, 14, 33, 16, "Então restaurou o altar do Senhor e sobre ele ofereceu sacrifícios de comunhão e ofertas de gratidão, ordenando a Judá que servisse o Senhor, o Deus de Israel."),  (3747, 14, 33, 17, "O povo, contudo, continuou a sacrificar nos altares idólatras, mas somente ao Senhor, ao seu Deus."),  (3748, 14, 33, 18, "Os demais acontecimentos do reinado de Manassés, inclusive sua oração a seu Deus e as palavras que os videntes lhe falaram em nome do Senhor, o Deus de Israel, estão escritos nos registros históricos dos reis de Israel."),  (3749, 14, 33, 19, "Sua oração e a resposta de Deus, bem como todos os seus pecados e a sua infidelidade, além dos locais onde construiu altares idólatras e ergueu postes sagrados e ídolos, antes de humilhar-se, tudo está escrito nos registros históricos dos videntes."),  (3750, 14, 33, 20, "Manassés descansou com os seus antepassados e foi sepultado em sua propriedade. E seu filho Amom foi o seu sucessor."),  (3751, 14, 33, 21, "Amom tinha vinte e dois anos de idade quando começou a reinar, e reinou dois anos em Jerusalém."),  (3752, 14, 33, 22, "Ele fez o que o Senhor reprova; à semelhança de seu pai, Amom prestou culto e ofereceu sacrifícios a todos os ídolos que Manassés havia feito."),  (3753, 14, 33, 23, "Mas, ao contrário de seu pai Manassés, não se humilhou diante do Senhor, antes, aumentou a sua culpa."),  (3754, 14, 33, 24, "Os oficiais de Amom conspiraram contra ele e o assassinaram em seu palácio."),  (3755, 14, 33, 25, "Mas o povo matou todos os que haviam conspirado contra o rei Amom, e a seu filho Josias proclamou rei em seu lugar."),  (3756, 14, 34, 1, "Josias tinha oito anos de idade quando começou a reinar, e reinou trinta e um anos em Jerusalém."),  (3757, 14, 34, 2, "Ele fez o que o Senhor aprova e andou nos caminhos de Davi, seu predecessor, sem desviar-se nem para a direita nem para a esquerda."),  (3758, 14, 34, 3, "No oitavo ano do seu reinado, sendo ainda bem jovem, ele começou a buscar o Deus de Davi, seu predecessor. No décimo segundo ano, começou a purificar Judá e Jerusalém dos altares idólatras, dos postes sagrados, das imagens esculpidas e dos ídolos de metal."),  (3759, 14, 34, 4, "Sob as suas ordens foram derrubados os altares dos baalins; além disso, ele despedaçou os altares de incenso que ficavam acima deles. Também despedaçou e reduziu a pó os postes sagrados, as imagens esculpidas e os ídolos de metal, e os espalhou sobre os túmulos daqueles que lhes haviam oferecido sacrifícios."),  (3760, 14, 34, 5, "Depois queimou os ossos dos sacerdotes sobre esses altares, purificando assim Judá e Jerusalém."),  (3761, 14, 34, 6, "Nas cidades das tribos de Manassés, de Efraim e de Simeão, e até mesmo de Naftali, e nas ruínas ao redor delas,"),  (3762, 14, 34, 7, "derrubou os altares e os postes sagrados, esmagou os ídolos, reduzindo-os a pó, e despedaçou todos os altares de incenso espalhados por Israel. Então voltou para Jerusalém."),  (3763, 14, 34, 8, "No décimo oitavo ano do seu reinado, a fim de purificar o país e o templo, ele enviou Safã, filho de Azalias, e Maaséias, governador da cidade, junto com Joá, filho do arquivista real Joacaz, para restaurarem o templo do Senhor, do seu Deus."),  (3764, 14, 34, 9, "Eles foram entregar ao sumo sacerdote Hilquias a prata que havia sido trazida ao templo de Deus e que os porteiros levitas haviam recolhido das ofertas do povo de Manassés e de Efraim, e de todo o remanescente de Israel, e também de todo o povo de Judá e de Benjamim e dos habitantes de Jerusalém."),  (3765, 14, 34, 10, "Então confiaram a prata aos homens nomeados para supervisionarem a reforma no templo do Senhor, que pagavam os trabalhadores que faziam os reparos no templo."),  (3766, 14, 34, 11, "Também deram dessa prata aos carpinteiros e aos construtores para comprarem pedras lavradas, e madeira para as juntas e as vigas dos edifícios que os reis de Judá haviam deixado ficar em ruínas."),  (3767, 14, 34, 12, "Esses homens fizeram o trabalho com fidelidade. Eram dirigidos por Jaate e Obadias, levitas descendentes de Merari, e Zacarias e Mesulão, descendentes de Coate. Todos os levitas que sabiam tocar instrumentos musicais"),  (3768, 14, 34, 13, "estavam encarregados dos operários e supervisionavam todos os trabalhadores em todas as funções. Outros levitas eram secretários, oficiais e porteiros."),  (3769, 14, 34, 14, "Enquanto recolhiam a prata que tinha sido levada para o templo do Senhor, o sacerdote Hilquias encontrou o livro da Lei do Senhor que havia sido dada por meio de Moisés."),  (3770, 14, 34, 15, "Hilquias disse ao secretário Safã: Encontrei o livro da Lei no templo do Senhor. E o entregou a Safã."),  (3771, 14, 34, 16, "Então Safã levou o livro ao rei e lhe informou: Teus servos estão fazendo tudo o que lhes foi ordenado."),  (3772, 14, 34, 17, "Fundiram a prata que estava no templo do Senhor e a confiaram aos supervisores e aos trabalhadores."),  (3773, 14, 34, 18, "E acrescentou: O sacerdote Hilquias entregou-me um livro. E Safã leu trechos do livro para o rei."),  (3774, 14, 34, 19, "Assim que o rei ouviu as palavras da Lei, rasgou suas vestes"),  (3775, 14, 34, 20, "e deu estas ordens a Hilquias, a Aicam, filho de Safã, a Abdom, filho de Mica, ao secretário Safã e ao auxiliar real Asaías:"),  (3776, 14, 34, 21, "Vão consultar o Senhor por mim e pelo remanescente de Israel e de Judá acerca do que está escrito neste livro que foi encontrado. A ira do Senhor contra nós deve ser grande, pois os nossos antepassados não obedeceram à palavra do Senhor e não agiram de acordo com tudo o que está escrito neste livro."),  (3777, 14, 34, 22, "Hilquias e aqueles que o rei tinha enviado com ele foram falar com a profetisa Hulda, mulher de Salum, responsável pelo guarda-roupa do templo, filho de Tocate e neto de Harás. Ela morava no bairro novo de Jerusalém."),  (3778, 14, 34, 23, "Ela lhes disse: Assim diz o Senhor, o Deus de Israel: ‘Digam ao homem que os enviou a mim:"),  (3779, 14, 34, 24, "Assim diz o Senhor: Eu vou trazer uma desgraça sobre este lugar e sobre seus habitantes; todas as maldições escritas no livro que foi lido na presença do rei de Judá."),  (3780, 14, 34, 25, "Porque me abandonaram e queimaram incenso a outros deuses, provocando-me a ira por meio de todos os ídolos que as mãos deles têm feito, minha ira arderá contra este lugar e não será apagada’."),  (3781, 14, 34, 26, "Digam ao rei de Judá, que os enviou para consultar o Senhor: ‘Assim diz o Senhor, o Deus de Israel, acerca das palavras que você ouviu:"),  (3782, 14, 34, 27, "Já que o seu coração se abriu e você se humilhou diante de Deus quando ouviu o que ele falou contra este lugar e contra os seus habitantes, e você se humilhou diante de mim, rasgou as suas vestes e chorou na minha presença, eu o ouvi, declara o Senhor."),  (3783, 14, 34, 28, "Portanto, eu o reunirei aos seus antepassados, e você será sepultado em paz. Seus olhos não verão a desgraça que trarei sobre este lugar e sobre seus habitantes’ . Então eles levaram a resposta ao rei."),  (3784, 14, 34, 29, "Então o rei convocou todas as autoridades de Judá e de Jerusalém."),  (3785, 14, 34, 30, "Depois subiu ao templo do Senhor acompanhado por todos os homens de Judá, todo o povo de Jerusalém, os sacerdotes e os levitas: todo o povo, dos mais simples aos mais importantes. Para todos o rei leu em voz alta todas as palavras do Livro da Aliança, que havia sido encontrado no templo do Senhor."),  (3786, 14, 34, 31, "Ele tomou o seu lugar e, na presença do Senhor, fez uma aliança, comprometendo-se a seguir o Senhor e obedecer de todo o coração e de toda a alma aos seus mandamentos, seus testemunhos e seus decretos, cumprindo as palavras da aliança escritas naquele livro."),  (3787, 14, 34, 32, "Depois fez com que todos em Jerusalém e em Benjamim se comprometessem com a aliança; os habitantes de Jerusalém passaram a cumprir a aliança de Deus, o Deus dos seus antepassados."),  (3788, 14, 34, 33, "Josias retirou todos os ídolos detestáveis de todo o território dos israelitas e obrigou todos os que estavam em Israel a servirem ao Senhor, ao seu Deus. E enquanto ele viveu, o povo não deixou de seguir o Senhor, o Deus dos seus antepassados."),  (3789, 14, 35, 1, "Josias celebrou a Páscoa do Senhor em Jerusalém, e o cordeiro da Páscoa foi abatido no dia catorze do primeiro mês."),  (3790, 14, 35, 2, "Ele nomeou os sacerdotes para as suas responsabilidades e os encorajou a dedicar-se ao serviço no templo do Senhor."),  (3791, 14, 35, 3, "Ele disse aos levitas que instruíam todo Israel e haviam sido consagrados ao Senhor: Ponham a arca sagrada no templo construído por Salomão, filho de Davi, rei de Israel. Vocês não precisam mais levá-la de um lado para outro sobre os ombros. Agora sirvam ao Senhor, ao seu Deus, e ao povo dele, Israel."),  (3792, 14, 35, 4, "Preparem-se por famílias, em suas divisões, de acordo com a orientação escrita por Davi, rei de Israel, e por seu filho Salomão."),  (3793, 14, 35, 5, "Fiquem no lugar santo com um grupo de levitas para cada subdivisão das famílias do povo."),  (3794, 14, 35, 6, "Abatam os cordeiros da Páscoa, consagrem-se e preparem os cordeiros para os seus irmãos israelitas, fazendo o que o Senhor ordenou por meio de Moisés."),  (3795, 14, 35, 7, "Josias deu a todo o povo que ali estava um total de trinta mil ovelhas e cabritos para as ofertas da Páscoa, além de três mil bois; tudo foi tirado dos bens pessoais do rei."),  (3796, 14, 35, 8, "Seus oficiais também contribuíram voluntariamente para o povo, para os sacerdotes e para os levitas. Hilquias, Zacarias e Jeiel, os administradores do templo de Deus, deram aos sacerdotes duas mil e seiscentas ovelhas e cabritos e trezentos bois."),  (3797, 14, 35, 9, "Também Conanias, junto com seus irmãos Semaías, Natanael e com os líderes dos levitas, Hasabias, Jeiel e Jozabade, ofereceram aos levitas cinco mil ovelhas e cabritos e quinhentos bois."),  (3798, 14, 35, 10, "O serviço foi organizado e os sacerdotes assumiram os seus lugares com os levitas em seus turnos, conforme o rei ordenara."),  (3799, 14, 35, 11, "Os cordeiros da Páscoa foram abatidos, e os sacerdotes aspergiram o sangue que lhes fora entregue, enquanto os levitas tiravam a pele dos animais."),  (3800, 14, 35, 12, "Eles separaram também os holocaustos para dá-los aos grupos das famílias do povo, para que essas os oferecessem ao Senhor, conforme está escrito no livro de Moisés; e fizeram o mesmo com os bois."),  (3801, 14, 35, 13, "Assaram os animais da Páscoa sobre o fogo, conforme prescrito, cozinharam as ofertas sagradas em potes, caldeirões e panelas, e serviram rapidamente a todo o povo."),  (3802, 14, 35, 14, "Depois disso, os levitas prepararam a parte deles e a dos sacerdotes, pois estes, descendentes de Arão, ficaram sacrificando os holocaustos e as porções de gordura até o anoitecer. Foi por isso que os levitas prepararam a parte deles e a dos sacerdotes, descendentes de Arão."),  (3803, 14, 35, 15, "Os músicos, descendentes de Asafe, estavam nos locais prescritos por Davi, e por Asafe, Hemã e Jedutum, videntes do rei. Os porteiros que guardavam cada porta não precisaram deixar os seus postos, pois os seus colegas levitas prepararam as ofertas para eles."),  (3804, 14, 35, 16, "Assim, naquele dia, todo o serviço do Senhor foi executado para a celebração da Páscoa e para a apresentação de holocaustos no altar do Senhor, conforme o rei Josias havia ordenado."),  (3805, 14, 35, 17, "Os israelitas que estavam presentes celebraram a Páscoa naquele dia e durante sete dias celebraram a festa dos pães sem fermento."),  (3806, 14, 35, 18, "A Páscoa não havia sido celebrada dessa maneira em Israel desde os dias do profeta Samuel; e nenhum dos reis de Israel havia celebrado uma Páscoa como esta, como o fez Josias, com os sacerdotes, os levitas e todo o Judá e Israel que estavam ali com o povo de Jerusalém."),  (3807, 14, 35, 19, "Esta Páscoa foi celebrada no décimo oitavo ano do reinado de Josias."),  (3808, 14, 35, 20, "Depois de tudo o que Josias fez, e depois de colocar em ordem o templo, Neco, rei do Egito, saiu para lutar em Carquemis, junto ao Eufrates, e Josias marchou para combatê-lo."),  (3809, 14, 35, 21, "Neco, porém, enviou-lhe mensageiros, dizendo: Não interfiras nisso, ó rei de Judá. Desta vez não estou atacando a ti, mas a outro reino com o qual estou em guerra. Deus me disse que me apressasse; por isso pára de opor-se a Deus, que está comigo; caso contrário ele o destruirá."),  (3810, 14, 35, 22, "Josias, contudo, não quis voltar atrás, e disfarçou-se para enfrentá-lo em combate. Ele não quis ouvir o que Neco lhe disse por ordem de Deus, mas foi combatê-lo na planície de Megido."),  (3811, 14, 35, 23, "E na batalha, flecheiros atingiram o rei Josias, pelo que disse aos seus oficiais: Tirem-me daqui. Estou gravemente ferido."),  (3812, 14, 35, 24, "Eles o tiraram do seu carro, colocaram-no em outro e o levaram para Jerusalém, onde morreu. Ele foi sepultado nos túmulos dos seus antepassados, e todos os moradores de Judá e de Jerusalém choraram por ele."),  (3813, 14, 35, 25, "Jeremias compôs um cântico de lamento em homenagem a Josias, e até hoje todos os cantores e cantoras homenageiam Josias com cânticos de lamento. Estes se tornaram uma tradição em Israel e estão escritos na Coletânea das Lamentações."),  (3814, 14, 35, 26, "Os demais acontecimentos do reinado de Josias e os seus atos piedosos, de acordo com o que está escrito na Lei do Senhor,"),  (3815, 14, 35, 27, "todos os acontecimentos, do início ao fim, estão escritos nos registros históricos dos reis de Israel e de Judá."),  (3816, 14, 36, 1, "E o povo tomou Jeoacaz, filho de Josias, e proclamou-o rei em Jerusalém, no lugar de seu pai."),  (3817, 14, 36, 2, "Jeoacaz tinha vinte e três anos de idade quando começou a reinar, e reinou três meses em Jerusalém."),  (3818, 14, 36, 3, "O rei do Egito destronou-o em Jerusalém e impôs a Judá um tributo de três toneladas e meia de prata e trinta e cinco quilos de ouro."),  (3819, 14, 36, 4, "O rei do Egito proclamou Eliaquim, irmão de Jeoacaz, rei sobre Judá e sobre Jerusalém, e mudou-lhe o nome para Jeoaquim. Mas Neco levou Jeoacaz, irmão de Eliaquim, para o Egito."),  (3820, 14, 36, 5, "Jeoaquim tinha vinte e cinco anos de idade quando começou a reinar, e reinou onze anos em Jerusalém. Ele fez o que o Senhor, o seu Deus, reprova."),  (3821, 14, 36, 6, "Nabucodonosor, rei da Babilônia, atacou-o e prendeu-o com algemas de bronze para levá-lo para a Babilônia."),  (3822, 14, 36, 7, "E levou também para a Babilônia objetos do templo do Senhor e os colocou no seu templo."),  (3823, 14, 36, 8, "Os demais acontecimentos do reinado de Jeoaquim, as coisas detestáveis que fez e tudo o que foi achado contra ele, estão escritos nos registros históricos dos reis de Israel e de Judá. Seu filho Joaquim foi o seu sucessor."),  (3824, 14, 36, 9, "Joaquim tinha dezoito anos de idade quando começou a reinar; e reinou três meses e dez dias em Jerusalém. Ele fez o que o Senhor reprova."),  (3825, 14, 36, 10, "Na primavera o rei Nabucodonosor mandou levá-lo para a Babilônia, junto com objetos de valor retirados do templo do Senhor, e proclamou Zedequias, tio de Joaquim, rei sobre Judá e sobre Jerusalém."),  (3826, 14, 36, 11, "Zedequias tinha vinte e um anos de idade quando começou a reinar, e reinou onze anos em Jerusalém."),  (3827, 14, 36, 12, "Ele fez o que o Senhor, o seu Deus, reprova, e não se humilhou diante do profeta Jeremias, que lhe falava como porta-voz do Senhor."),  (3828, 14, 36, 13, "Também se revoltou contra o rei Nabucodonosor, que o havia obrigado a fazer um juramento em nome de Deus. Tornou-se muito obstinado e não quis se voltar para o Senhor, o Deus de Israel."),  (3829, 14, 36, 14, "Além disso, todos os líderes dos sacerdotes e o povo se tornaram cada vez mais infiéis, seguindo todas as práticas detestáveis das outras nações e contaminando o templo do Senhor, consagrado por ele em Jerusalém."),  (3830, 14, 36, 15, "O Senhor, o Deus dos seus antepassados, advertiu-os várias vezes por meio de seus mensageiros, pois ele tinha compaixão de seu povo e do lugar de sua habitação."),  (3831, 14, 36, 16, "Mas eles zombaram dos mensageiros de Deus, desprezaram as palavras dele e expuseram ao ridículo os seus profetas, até que a ira do Senhor se levantou contra o seu povo, e já não houve remédio."),  (3832, 14, 36, 17, "Ele enviou contra eles o rei dos babilônios, que no santuário matou os seus jovens à espada. Não poupou nem rapazes, nem moças, nem adultos, nem velhos. Deus entregou todos eles nas mãos de Nabucodonosor;"),  (3833, 14, 36, 18, "este levou para a Babilônia todos os utensílios do templo de Deus, tanto os pequenos como os grandes, juntamente com os tesouros do templo do Senhor, os do rei e os de seus oficiais."),  (3834, 14, 36, 19, "Os babilônios incendiaram o templo de Deus e derrubaram o muro de Jerusalém; queimaram todos os palácios e destruíram todos os utensílios de valor que havia neles."),  (3835, 14, 36, 20, "Nabucodonosor levou para o exílio, na Babilônia, os remanescentes, que escaparam da espada, para serem seus escravos e dos seus descendentes, até à época do domínio persa."),  (3836, 14, 36, 21, "A terra desfrutou os seus descansos sabáticos; descansou durante todo o tempo de sua desolação, até que os setenta anos se completaram, em cumprimento da palavra do Senhor anunciada por Jeremias."),  (3837, 14, 36, 22, "No primeiro ano do reinado de Ciro, rei da Pérsia, para que se cumprisse a palavra do Senhor anunciada por Jeremias, o Senhor tocou no coração de Ciro, rei da Pérsia, para que fizesse uma proclamação em todo o território de seu domínio e a pusesse por escrito, nestes termos:"),  (3838, 14, 36, 23, "Assim declaro Ciro, rei da Pérsia: ‘O Senhor, o Deus dos céus, deu-me todos os reinos da terra e designou-me para construir-lhe um templo em Jerusalém, na terra de Judá. Quem dentre vocês pertencer ao seu povo vá para Jerusalém, e que o Senhor, o seu Deus, esteja com ele’ ."),  (3839, 40, 1, 1, "Registro da genealogia de Jesus Cristo, filho de Davi, filho de Abraão:"),  (3840, 40, 1, 2, "Abraão gerou Isaque; Isaque gerou Jacó; Jacó gerou Judá e seus irmãos;"),  (3841, 40, 1, 3, "Judá gerou Perez e Zerá, cuja mãe foi Tamar; Perez gerou Esrom; Esrom gerou Arão;"),  (3842, 40, 1, 4, "Arão gerou Aminadabe; Aminadabe gerou Naassom; Naassom gerou Salmom;"),  (3843, 40, 1, 5, "Salmom gerou Boaz, cuja mãe foi Raabe; Boaz gerou Obede, cuja mãe foi Rute; Obede gerou Jessé;"),  (3844, 40, 1, 6, "e Jessé gerou o rei Davi. Davi gerou Salomão, cuja mãe tinha sido mulher de Urias;"),  (3845, 40, 1, 7, "Salomão gerou Roboão; Roboão gerou Abias; Abias gerou Asa;"),  (3846, 40, 1, 8, "Asa gerou Josafá; Josafá gerou Jorão; Jorão gerou Uzias;"),  (3847, 40, 1, 9, "Uzias gerou Jotão; Jotão gerou Acaz; Acaz gerou Ezequias;"),  (3848, 40, 1, 10, "Ezequias gerou Manassés; Manassés gerou Amom; Amom gerou Josias;"),  (3849, 40, 1, 11, "e Josias gerou Jeconias e seus irmãos, no tempo do exílio na Babilônia."),  (3850, 40, 1, 12, "Depois do exílio na Babilônia: Jeconias gerou Salatiel; Salatiel gerou Zorobabel;"),  (3851, 40, 1, 13, "Zorobabel gerou Abiúde; Abiúde gerou Eliaquim; Eliaquim gerou Azor;"),  (3852, 40, 1, 14, "Azor gerou Sadoque; Sadoque gerou Aquim; Aquim gerou Eliúde;"),  (3853, 40, 1, 15, "Eliúde gerou Eleazar; Eleazar gerou Matã; Matã gerou Jacó;"),  (3854, 40, 1, 16, "e Jacó gerou José, marido de Maria, da qual nasceu Jesus, que é chamado Cristo."),  (3855, 40, 1, 17, "Assim, ao todo houve catorze gerações de Abraão a Davi, catorze de Davi até o exílio na Babilônia e catorze do exílio até o Cristo."),  (3856, 40, 1, 18, "Foi assim o nascimento de Jesus Cristo: Maria, sua mãe, estava prometida em casamento a José, mas, antes que se unissem, achou-se grávida pelo Espírito Santo."),  (3857, 40, 1, 19, "Por ser José, seu marido, um homem justo, e não querendo expô-la à desonra pública, pretendia anular o casamento secretamente."),  (3858, 40, 1, 20, "Mas, depois de ter pensado nisso, apareceu-lhe um anjo do Senhor em sonho e disse: José, filho de Davi, não tema receber Maria como sua esposa, pois o que nela foi gerado procede do Espírito Santo."),  (3859, 40, 1, 21, "Ela dará à luz um filho, e você deverá dar-lhe o nome de Jesus, porque ele salvará o seu povo dos seus pecados."),  (3860, 40, 1, 22, "Tudo isso aconteceu para que se cumprisse o que o Senhor dissera pelo profeta:"),  (3861, 40, 1, 23, "A virgem ficará grávida e dará à luz um filho, e lhe chamarão Emanuel que significa Deus conosco."),  (3862, 40, 1, 24, "Ao acordar, José fez o que o anjo do Senhor lhe tinha ordenado e recebeu Maria como sua esposa."),  (3863, 40, 1, 25, "Mas não teve relações com ela enquanto ela não deu à luz um filho. E ele lhe pôs o nome de Jesus."),  (3864, 42, 2, 9, "E aconteceu que um anjo do Senhor apareceu-lhes e a glória do Senhor resplandeceu ao redor deles; e ficaram aterrorizados.");